  const BASEMAP_SESSION_KEY = 'surveyor-operational-basemap-session-v1';
  function savedBaseMapKey() {
    try {
      const key = String(sessionStorage.getItem(BASEMAP_SESSION_KEY) || '').trim();
      return baseLayers[key] ? key : 'osm';
    } catch { return 'osm'; }
  }
  function persistBaseMapKey(key) {
    const normalized = baseLayers[key] ? key : 'osm';
    try { sessionStorage.setItem(BASEMAP_SESSION_KEY, normalized); } catch {}
    return normalized;
  }

  function normalizeLayerText(value) {
    return String(value || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[_:./-]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

