  function officialCatalogSourceCandidate(id, aliases = [], priority = 100) {
    const url = OFFICIAL_LAYER_SOURCE_ENDPOINTS[id];
    if (!url) return null;
    return {
      id,
      url,
      label: OFFICIAL_LAYER_SOURCE_LABELS[id] || id,
      aliases: [...new Set((aliases || []).map((value) => String(value || '').trim()).filter(Boolean))],
      priority
    };
  }

  function officialLayerSourceCandidates(layer) {
    const configured = String(layer?.serviceUrl || layer?.sourceUrl || OFFICIAL_LAYER_SOURCE_ENDPOINTS.inema).trim();
    const shortName = geobahiaWmsShortName(String(layer?.metadata?.layerName || layer?.metadata?.layers || '')).toLowerCase();
    const name = normalizeLayerText(layer?.name || '');
    const candidates = [];
    const add = (id, aliases = [], priority = 100, explicitUrl = '') => {
      const candidate = explicitUrl
        ? { id, url: explicitUrl, label: OFFICIAL_LAYER_SOURCE_LABELS[id] || id, aliases, priority }
        : officialCatalogSourceCandidate(id, aliases, priority);
      if (!candidate?.url) return;
      if (!candidates.some((item) => item.url === candidate.url)) candidates.push(candidate);
    };
    const hints = OFFICIAL_LAYER_ALIAS_HINTS[shortName] || [];

    // A fonte cadastrada da camada é sempre tentada primeiro. Isto evita que uma
    // correção em outro órgão altere a semântica de uma camada que já funciona no
    // GeoBahia. Fontes produtoras externas entram como fallback OFICIAL isolado.
    add(isInemaWmsUrl(configured) ? 'inema' : 'configured', hints, 10, configured);

    if (/^cefir_imovel_rural_(?:app|reserva_legal|vegetacao_nativa)_inema$/.test(shortName)) add('sicar', hints, 20);
    if (/^sitios_arqueologicos_iphan_pt$/.test(shortName)) add('iphan', hints, 20);
    if (/areas_quilombolas/.test(shortName)) add('incra', hints, 20);
    if (/terras_indigenas/.test(shortName)) add('funai', hints, 20);
    if (/^(?:uc_federal|rppn_federal_icmbio|zona_amortecimento_federal)$/.test(shortName) || /plano de acao nacional|plano acao territorial/.test(name)) add('icmbio', hints, 20);
    if (/^(?:biomas_ibge_2019|vegetacao|limite_estadual|sistema_costeiro_marinho)$/.test(shortName)) add('ibge', hints, 20);
    if (/^(?:areas_prioritarias_conservacao|lei_mata_atlantica)$/.test(shortName)) add('mma', hints, 25);
    if (/^faixa_servidao_rodovias$/.test(shortName)) add('dnit', [...hints, 'SNV', 'SNV202407A', 'Subsistema Rodoviário Federal'], 25);
    if (/^(?:bacias_ottocodificadas|bacias_otto_nivel4|trechos_drenagem|massa_dagua|trecho_massa_dagua|rpga|aquiferos|estacoes_fluviometricas|rede_qualidade_agua|estacoes_qualidade_agua_remoto|estacoes_hidrologicas)$/.test(shortName)) add('snirh', hints, 25);

    if (!candidates.some((item) => item.id === 'inema')) add('inema', hints, 80);
    return candidates.sort((a, b) => a.priority - b.priority);
  }

  function isOfficialCatalogProxyUrl(value) {
    const raw = String(value || '').trim();
    if (!raw) return false;
    try {
      const host = new URL(raw, window.location.href).hostname.toLowerCase();
      return [
        'geoserver.inema.ba.gov.br', 'geoserver.car.gov.br', 'geoserver.funai.gov.br',
        'geoservicos.inde.gov.br', 'geoservicos.ibge.gov.br', 'portal.iphan.gov.br',
        'acervofundiario.incra.gov.br', 'www.acervofundiario.incra.gov.br', 'www.snirh.gov.br', 'snirh.gov.br'
      ].includes(host) || host.endsWith('.inema.ba.gov.br');
    } catch {
      return false;
    }
  }

  function geobahiaWmsShortName(value) {
    return String(value || '').trim().split(':').pop();
  }

  function normalizeGeobahiaWmsLayerName(value) {
    const raw = String(value || '').trim();
    if (!raw) return raw;
    if (raw === 'Vetor_Recortes_Tematicos:cefir_imovel_rural_propriedade_inema') {
      return OFFICIAL_GEOBAHIA_WMS_LAYERS.cefir_imovel_rural_propriedade_inema;
    }
    const short = geobahiaWmsShortName(raw);
    return OFFICIAL_GEOBAHIA_WMS_LAYERS[short] || raw;
  }

  function configuredWmsLayerName(layer) {
    const resolved = String(layer?.__georuralResolvedLayerName || '').trim();
    if (resolved) return resolved;
    return normalizeGeobahiaWmsLayerName(String(layer?.metadata?.layerName || layer?.metadata?.layers || '').trim());
  }

  function officialMunicipalBoundaryMatch(layer) {
    const technicalName = normalizeLayerText(configuredWmsLayerName(layer));
    return technicalName === 'vetor bases gerais municip sei 2019'
      || technicalName === 'municip sei 2019';
  }

  function officialTerritoryIdentityMatch(layer) {
    const technicalName = normalizeLayerText(configuredWmsLayerName(layer));
    const identity = normalizeLayerText(`${layer?.name || ''} ${layer?.slug || ''}`);
    return technicalName === 'vetor bases gerais territorio identidade'
      || technicalName === 'territorio identidade'
      || /territorio de identidade/.test(identity);
  }

  function sicarStateCodeForLayer(layer = {}) {
    const metadata = layer?.metadata && typeof layer.metadata === 'object' ? layer.metadata : {};
    const direct = String(metadata.stateCode || (Array.isArray(metadata.coverageStates) ? metadata.coverageStates[0] : '') || '').trim().toUpperCase();
    if (/^[A-Z]{2}$/.test(direct)) return direct;
    const technical = String(metadata.layerName || metadata.layers || '').toLowerCase();
    const match = technical.match(/sicar:sicar_imoveis_([a-z]{2})/i);
    if (match) return match[1].toUpperCase();
    try { return normalizedCatalogState(selectedCatalogState || 'BA'); } catch { return 'BA'; }
  }

  function sicarLayerNameFor(layer = {}) {
    return `sicar:sicar_imoveis_${sicarStateCodeForLayer(layer).toLowerCase()}`;
  }

  function activeSicarCatalogLayer() {
    const active = activePropertyBoundaryCatalogEntry?.();
    return active?.entry?.meta || null;
  }

  function officialPropertyBoundaryMatch(layer) {
    const technicalName = normalizeLayerText(configuredWmsLayerName(layer));
    const officialTechnicalName = normalizeLayerText(OFFICIAL_PROPERTY_BOUNDARY_LAYER);

    // O Nome Técnico informado pelo administrador tem prioridade absoluta.
    // Se ele existe e não descreve o limite do imóvel, a camada jamais pode
    // receber o fallback CAR/CEFIR, mesmo que a URL seja do INEMA/GeoBahia.
    if (technicalName) {
      return technicalName === officialTechnicalName
        || technicalName === 'cefir imovel rural limite inema'
        || technicalName === 'cefir imovel rural limite'
        || /^sicar sicar imoveis [a-z]{2}$/.test(technicalName);
    }

    // Compatibilidade somente com registros antigos realmente identificados
    // como limite de propriedade. Nome do órgão, URL, descrição genérica do
    // CAR, “INEMA” ou “CEFIR” isoladamente não classificam mais uma camada.
    const identity = normalizeLayerText(`${layer?.name || ''} ${layer?.slug || ''}`);
    return /limites? de propriedade/.test(identity)
      || /limites? do imovel/.test(identity)
      || /limite do imovel rural/.test(identity)
      || /perimetro do imovel/.test(identity);
  }


  function geobahiaPropertyBoundaryMatch(layer = {}) {
    if (!officialPropertyBoundaryMatch(layer)) return false;
    const technicalName = normalizeLayerText(configuredWmsLayerName(layer));
    if (technicalName === normalizeLayerText(OFFICIAL_PROPERTY_BOUNDARY_LAYER)
      || technicalName === 'cefir imovel rural limite inema'
      || technicalName === 'cefir imovel rural limite') return true;
    const sourceText = normalizeLayerText(`${layer?.source || ''} ${layer?.sourceName || ''} ${layer?.serviceUrl || ''} ${layer?.sourceUrl || ''}`);
    return /inema|geobahia/.test(sourceText);
  }

  const officialWmsCatalog = [
    {
      matches: officialPropertyBoundaryMatch,
      // O servidor do INEMA não deve ser acessado diretamente pelo navegador.
      // A API do GeoRural recebe a requisição HTTPS do frontend e consulta o
      // upstream HTTP, preservando o Nome Técnico enviado em LAYERS.
      serviceUrls: () => [
        inemaWmsProxyUrl('http://geoserver.inema.ba.gov.br/geoserver/wms')
      ],
      fallbackLayerName: OFFICIAL_PROPERTY_BOUNDARY_LAYER,
      attribution: 'INEMA / GeoBahia'
    }
  ];

  function officialWmsForLayer(layer) {
    if (layer?.metadata?.forceStoredData === true) return null;
    const entry = officialWmsCatalog.find((candidate) => candidate.matches(layer));
    if (!entry) return null;

    const layerName = configuredWmsLayerName(layer) || entry.fallbackLayerName;
    const serviceUrls = typeof entry.serviceUrls === 'function'
      ? entry.serviceUrls(layerName, layer)
      : entry.serviceUrls;
    return { ...entry, layerName, serviceUrls };
  }

  function isArcGisRestServiceUrl(value) {
    const serviceUrl = String(value || '').trim();
    if (!serviceUrl || /\/WMSServer(?:\?|$)/i.test(serviceUrl)) return false;
    return /\/(?:FeatureServer|MapServer)(?:\/\d+)?\/?(?:\?.*)?$/i.test(serviceUrl);
  }

  function hasConfiguredWms(layer) {
    const declared = String(layer?.serviceType || '').trim().toLowerCase();
    const serviceUrl = String(layer?.serviceUrl || layer?.sourceUrl || '').trim();
    const metadata = layer?.metadata || {};
    const layerName = String(metadata.layerName || metadata.layers || '').trim();

    if (!serviceUrl || isArcGisRestServiceUrl(serviceUrl)) return false;
    if (declared === 'wms' || metadata.directWms === true) return true;
    if (!layerName) return false;
    if (declared === 'wfs' || declared === 'xyz' || declared === 'mvt') return false;

    return /(?:service=wms|request=getmap|\/geoserver\/(?:wms|ows)(?:\?|$)|\/wms(?:\?|$)|\/WMSServer(?:\?|$))/i.test(serviceUrl)
      || String(metadata.format || '').toLowerCase() === 'image/png'
      || Boolean(metadata.wmsVersion);
  }

  function resolvedLayerServiceType(layer) {
    const serviceUrl = String(layer?.serviceUrl || layer?.sourceUrl || '').trim();
    if (isArcGisRestServiceUrl(serviceUrl)) return 'arcgis';
    if (hasConfiguredWms(layer)) return 'wms';
    return String(layer?.serviceType || '').trim().toLowerCase();
  }

  const TRANSPARENT_TILE = 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';

  function finiteZoom(value) {
    if (value === null || value === undefined || value === '') return null;
    const zoom = Number(value);
    return Number.isFinite(zoom) ? zoom : null;
  }

  const GEOBAHIA_HEAVY_LAYER_MIN_ZOOM = Object.freeze({
    vegetacao: 12,
    geologia_2004: 12,
    geomorfologia_2004: 12,
    solos: 12,
    bacias_ottocodificadas: 12,
    bacias_otto_nivel4: 12
  });

  function effectiveCatalogMinZoom(layer) {
    const configured = Math.max(0, finiteZoom(layer?.minZoom) ?? 0);
    const shortName = geobahiaWmsShortName?.(configuredWmsLayerName?.(layer) || layer?.metadata?.layerName || layer?.metadata?.layers || '') || '';
    const heavyMin = Number(GEOBAHIA_HEAVY_LAYER_MIN_ZOOM[String(shortName || '').toLowerCase()] || 0);
    return Math.max(configured, heavyMin);
  }

  function tileZoomOptions(layer) {
    const options = {};
    const minZoom = effectiveCatalogMinZoom(layer);
    const maxZoom = finiteZoom(layer?.maxZoom);
    if (minZoom > 0) options.minZoom = minZoom;
    if (maxZoom !== null) options.maxZoom = maxZoom;
    return options;
  }

  function normalizeWmsBaseUrl(rawUrl) {
    const value = String(rawUrl || '').trim();
    if (!value) return '';

    try {
      const parsed = new URL(value, window.location.href);

      // O endereço público do INEMA costuma ser divulgado como /wms ou /ows.
      // Padronizamos apenas o caminho; o protocolo é decidido pelo roteamento.
      if (/^geoserver\.inema\.ba\.gov\.br$/i.test(parsed.hostname)) {
        if (/^\/(?:wms|ows|geoserver\/ows)\/?$/i.test(parsed.pathname)) {
          parsed.pathname = '/geoserver/wms';
        }
      }

      // A URL armazenada deve ser a URL-base. Parâmetros de uma requisição
      // GetMap/GetCapabilities colada pelo administrador são removidos, pois o
      // Leaflet cria esses parâmetros para cada bloco do mapa.
      const dynamicParams = [
        'bbox', 'width', 'height', 'request', 'service', 'layers', 'layer',
        'styles', 'format', 'transparent', 'srs', 'crs', 'version', 'tiled',
        'sld', 'sld_body'
      ];
      for (const name of dynamicParams) {
        parsed.searchParams.delete(name);
        parsed.searchParams.delete(name.toUpperCase());
      }

      return parsed.toString();
    } catch {
      return value;
    }
  }

  function isInemaWmsUrl(value) {
    const raw = String(value || '').trim();
    if (!raw) return false;
    try {
      const hostname = new URL(raw, window.location.href).hostname.toLowerCase();
      return hostname === 'inema.ba.gov.br' || hostname.endsWith('.inema.ba.gov.br');
    } catch {
      return /(?:^|\.)inema\.ba\.gov\.br(?:[/:?#]|$)/i.test(raw);
    }
  }

  function normalizeInemaWmsUpstreamUrl(rawUrl) {
    const normalized = normalizeWmsBaseUrl(rawUrl);
    const parsed = new URL(normalized, window.location.href);

    // O navegador nunca acessa este endereço diretamente. Ele é enviado apenas
    // como parâmetro target para a API. O backend tenta HTTPS primeiro e usa
    // HTTP somente como contingência.
    parsed.protocol = 'https:';
    parsed.username = '';
    parsed.password = '';
    parsed.hash = '';

    if (/^\/(?:wms|ows|geoserver\/ows)\/?$/i.test(parsed.pathname)) {
      parsed.pathname = '/geoserver/wms';
    }
    return parsed.toString();
  }


  function wmsProxyEndpoint(path, explicitBase = '') {
    if (/^https?:\/\//i.test(path)) return path;
    const configuredBase = explicitBase
      || window.GEORURAL_CONFIG?.wmsProxyBaseUrl
      || window.GEORURAL_WMS_PROXY_URL
      || window.GEORURAL_CONFIG?.apiBaseUrl
      || window.GEORURAL_API_URL
      || '';
    const base = String(configuredBase).replace(/\/$/, '');
    const url = `${base}${path.startsWith('/') ? path : `/${path}`}`;
    return typeof window.GEORURAL_SECURE_GEOSERVICES_URL === 'function' ? window.GEORURAL_SECURE_GEOSERVICES_URL(url) : url;
  }

  function geoserviceProxyBaseCandidates() {
    const bases = [];
    const add = (value) => {
      const text = String(value || '').trim().replace(/\/+$/, '');
      if (!text || !/^https?:\/\//i.test(text)) return;
      if (!bases.includes(text)) bases.push(text);
    };

    add(window.GEORURAL_CONFIG?.wmsProxyBaseUrl);
    add(window.GEORURAL_CONFIG?.geoservicesBaseUrl);
    add(window.GEORURAL_WMS_PROXY_URL);
    add(window.GEORURAL_GEOSERVICES_URL);

    // Cloudflare continua sendo a rota primária. A API oficial entra como
    // segunda rota pública e allowlisted para WMS/WFS/GetFeatureInfo; essas
    // rotas geográficas não exigem sessão e evitam que uma indisponibilidade
    // isolada do Worker deixe todas as camadas oficiais invisíveis.
    const allowAppwriteGeoFallback = window.GEORURAL_ALLOW_APPWRITE_GEO_FALLBACK !== false
      && window.GEORURAL_CONFIG?.allowAppwriteGeoFallback !== false;
    if (allowAppwriteGeoFallback) {
      add(window.GEORURAL_CONFIG?.apiBaseUrl);
      add(window.GEORURAL_API_URL);
    }


    return bases;
  }

  function base64UrlEncodeText(value) {
    const text = String(value || '');
    try {
      const bytes = new TextEncoder().encode(text);
      let binary = '';
      bytes.forEach((byte) => { binary += String.fromCharCode(byte); });
      return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
    } catch {
      return btoa(unescape(encodeURIComponent(text))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
    }
  }

  const GEORURAL_PROXY_WMS_PREFIX = 'GEORURAL_PROXY_WMS::';

  function geoserviceEncodedProxyUrlForBase(base, upstreamUrl, kind = 'wms') {
    let safeKind = /^(wms|wfs|wms-info|info)$/i.test(kind) ? String(kind).toLowerCase() : 'wms';
    if (safeKind === 'wms-info') safeKind = 'info';
    return wmsProxyEndpoint(`/${safeKind}-url/${base64UrlEncodeText(upstreamUrl)}`, base);
  }

  function geoserviceEncodedProxyUrls(upstreamUrl, kind = 'wms') {
    const urls = geoserviceProxyBaseCandidates().map((base) => geoserviceEncodedProxyUrlForBase(base, upstreamUrl, kind));
    return [...new Set(urls.filter(Boolean))];
  }

  function geoserviceEncodedProxyUrl(upstreamUrl, kind = 'wms') {
    return geoserviceEncodedProxyUrls(upstreamUrl, kind)[0] || geoserviceEncodedProxyUrlForBase('', upstreamUrl, kind);
  }

  function georuralProxyMarkerUrl(targetUrl) {
    return `${GEORURAL_PROXY_WMS_PREFIX}${targetUrl}`;
  }

  function isGeoruralProxyMarkerUrl(value) {
    return String(value || '').startsWith(GEORURAL_PROXY_WMS_PREFIX);
  }

  function georuralProxyMarkerTarget(value) {
    return String(value || '').slice(GEORURAL_PROXY_WMS_PREFIX.length);
  }

  function genericWmsProxyUrl(targetUrl) {
    return georuralProxyMarkerUrl(targetUrl);
  }

  function inemaWmsProxyUrl(rawUrl) {
    return genericWmsProxyUrl(normalizeInemaWmsUpstreamUrl(rawUrl));
  }

  function secureCloneUrl(url, protocol = 'https:') {
    try {
      const parsed = new URL(url, window.location.href);
      parsed.protocol = protocol;
      parsed.username = '';
      parsed.password = '';
      parsed.hash = '';
      return parsed.toString();
    } catch {
      return String(url || '').replace(/^https?:/i, protocol);
    }
  }

  function resolveInemaDirectWmsCandidates(rawServiceUrl) {
    const normalized = normalizeWmsBaseUrl(rawServiceUrl);
    const candidates = [];
    const add = (value) => {
      const text = String(value || '').trim();
      if (text && !candidates.includes(text)) candidates.push(text);
    };

    // O GeoBahia/INEMA historicamente é mais estável em HTTP. Em ambiente
    // local HTTP nós tentamos HTTP direto primeiro. Em GitHub Pages/HTTPS,
    // o navegador bloquearia mixed content, então tentamos HTTPS e caímos
    // para o proxy Appwrite quando necessário.
    // GeoBahia/INEMA nunca deve ser acessado direto pelo navegador.
    // Mesmo em localhost, usa a Function surveyor-geoservices para evitar SSL/CORS/mixed-content.
    add(genericWmsProxyUrl(normalizeInemaWmsUpstreamUrl(normalized)));
    return candidates;
  }

  function resolveWmsServiceUrl(layer) {
    const rawServiceUrl = String(layer?.__georuralResolvedServiceUrl || layer?.serviceUrl || layer?.sourceUrl || '').trim();
    if (!rawServiceUrl) throw new Error('A camada WMS está sem URL do serviço.');

    const serviceUrl = normalizeWmsBaseUrl(rawServiceUrl);

    if (isInemaWmsUrl(serviceUrl)) {
      return resolveInemaDirectWmsCandidates(serviceUrl)[0] || serviceUrl;
    }

    // Fontes oficiais alternativas também são consumidas pelo Worker quando
    // possível. A URL direta só fica como descrição do upstream.
    if (window.location.protocol === 'https:' && /^http:\/\//i.test(serviceUrl)) {
      return serviceUrl.replace(/^http:/i, 'https:');
    }

    return serviceUrl;
  }

  function resolveConfiguredWmsProxyUrl(layer, rawServiceUrl) {
    const normalizedServiceUrl = normalizeWmsBaseUrl(rawServiceUrl);

    // INEMA sempre usa o proxy genérico para preservar o Nome Técnico dinâmico.
    // A rota fixa /api/geoservices/inema/wms é exclusiva do limite legado.
    if (isInemaWmsUrl(normalizedServiceUrl)) {
      return inemaWmsProxyUrl(normalizedServiceUrl);
    }

    const configuredProxyUrl = String(layer?.metadata?.proxyUrl || '').trim();
    const isLegacyFixedInemaProxy = /\/api\/geoservices\/inema\/wms(?:\?|$)/i.test(configuredProxyUrl);

    if (configuredProxyUrl && !isLegacyFixedInemaProxy) {
      return apiEndpoint(configuredProxyUrl);
    }
    if (isLegacyFixedInemaProxy) {
      console.warn('Proxy INEMA legado ignorado; usando o proxy WMS genérico para preservar o Nome Técnico.');
    }
    return genericWmsProxyUrl(normalizedServiceUrl);
  }

  function escapeWmsXml(value) {
    return String(value || '').replace(/[&<>"']/g, (char) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;'
    }[char]));
  }

  function normalizeWmsHexColor(value, fallback = '#3974D8') {
    const raw = String(value || '').trim().toUpperCase();
    const short = raw.match(/^#?([0-9A-F]{3})$/);
    if (short) return `#${short[1].split('').map((char) => char + char).join('')}`;
    const full = raw.match(/^#?([0-9A-F]{6})$/);
    if (full) return `#${full[1]}`;
    return fallback;
  }

  function darkenWmsColor(color, factor = 0.72) {
    const normalized = normalizeWmsHexColor(color).slice(1);
    const channels = [0, 2, 4].map((index) => Math.max(0, Math.min(255, Math.round(parseInt(normalized.slice(index, index + 2), 16) * factor))));
    return `#${channels.map((channel) => channel.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
  }

  function inferredWmsSymbolizer(layer) {
    const configured = String(layer?.metadata?.wmsSymbolizer || '').toLowerCase();
    if (['polygon', 'line', 'point', 'mixed'].includes(configured)) return configured;
    const text = `${layer?.name || ''} ${layer?.description || ''} ${configuredWmsLayerName(layer) || ''}`.toLowerCase();
    if (/nascente|ponto|point|marco|vértice|vertice/.test(text)) return 'point';
    if (/rio|hidro|linha|line|estrada|rodovia|via|curso d[’']?água|curso d[’']?agua/.test(text)) return 'line';
    return 'polygon';
  }

  function wmsSupportsInlineSld(layer) {
    const url = String(layer?.serviceUrl || layer?.sourceUrl || '');
    return /geoserver|\/ows(?:\?|$)|\/wms(?:\?|$)/i.test(url);
  }

  function shouldForceWmsColor(layer) {
    if (layer?.metadata?.forceWmsColor === false) return false;
    if (layer?.metadata?.forceWmsColor === true) return true;

    const layerName = configuredWmsLayerName(layer);
    const serviceText = `${layer?.sourceName || ''} ${layer?.serviceUrl || ''} ${layer?.sourceUrl || ''} ${layerName}`;
    const isGeoBahiaInema = /geobahia|inema/i.test(serviceText)
      || /^Vetor_/i.test(layerName)
      || /^Raster_/i.test(layerName)
      || Boolean(OFFICIAL_GEOBAHIA_WMS_LAYERS[geobahiaWmsShortName(layerName)]);
    if (isGeoBahiaInema) return false;

    // Compatibilidade: camadas GeoServer já cadastradas passam a respeitar
    // automaticamente a cor que já aparece na legenda do GeoRural, exceto
    // GeoBahia/INEMA, onde o SLD inline pode gerar tiles pretos ou falhas.
    return wmsSupportsInlineSld(layer);
  }

  function wmsSymbolizerXml(kind, fillColor, strokeColor, options = {}) {
    const fillOpacity = Math.max(0, Math.min(1, Number(options.fillOpacity ?? 0.82)));
    const strokeOpacity = Math.max(0, Math.min(1, Number(options.strokeOpacity ?? 1)));
    const strokeWidth = Math.max(0.4, Number(options.strokeWidth ?? 4));
    const lineWidth = Math.max(0.4, Number(options.lineWidth ?? 4.5));
    const polygon = `<sld:PolygonSymbolizer><sld:Fill><sld:CssParameter name="fill">${fillColor}</sld:CssParameter><sld:CssParameter name="fill-opacity">${fillOpacity}</sld:CssParameter></sld:Fill><sld:Stroke><sld:CssParameter name="stroke">${strokeColor}</sld:CssParameter><sld:CssParameter name="stroke-width">${strokeWidth}</sld:CssParameter><sld:CssParameter name="stroke-opacity">${strokeOpacity}</sld:CssParameter></sld:Stroke></sld:PolygonSymbolizer>`;
    const line = `<sld:LineSymbolizer><sld:Stroke><sld:CssParameter name="stroke">${fillColor}</sld:CssParameter><sld:CssParameter name="stroke-width">${lineWidth}</sld:CssParameter><sld:CssParameter name="stroke-opacity">${strokeOpacity}</sld:CssParameter><sld:CssParameter name="stroke-linecap">round</sld:CssParameter><sld:CssParameter name="stroke-linejoin">round</sld:CssParameter></sld:Stroke></sld:LineSymbolizer>`;
    const point = `<sld:PointSymbolizer><sld:Graphic><sld:Mark><sld:WellKnownName>circle</sld:WellKnownName><sld:Fill><sld:CssParameter name="fill">${fillColor}</sld:CssParameter></sld:Fill><sld:Stroke><sld:CssParameter name="stroke">${strokeColor}</sld:CssParameter><sld:CssParameter name="stroke-width">2.2</sld:CssParameter></sld:Stroke></sld:Mark><sld:Size>13</sld:Size></sld:Graphic></sld:PointSymbolizer>`;
    if (kind === 'line') return line;
    if (kind === 'point') return point;
    if (kind === 'mixed') return `${polygon}${line}${point}`;
    return polygon;
  }

  function buildWmsColorSld(layer, requestedLayerName = '') {
    const layerNames = String(requestedLayerName || configuredWmsLayerName(layer) || '').split(',').map((name) => name.trim()).filter(Boolean);
    if (!layerNames.length) return '';
    const color = normalizeWmsHexColor(layer?.style?.color || layer?.style?.fillColor || layer?.color || '#3974D8');
    const strokeColor = normalizeWmsHexColor(layer?.metadata?.wmsStrokeColor || darkenWmsColor(color), darkenWmsColor(color));
    const symbolizer = wmsSymbolizerXml(inferredWmsSymbolizer(layer), color, strokeColor, {
      fillOpacity: layer?.metadata?.wmsFillOpacity,
      strokeOpacity: layer?.metadata?.wmsStrokeOpacity,
      strokeWidth: layer?.metadata?.wmsStrokeWidth,
      lineWidth: layer?.metadata?.wmsLineWidth
    });
    const namedLayers = layerNames.map((name) => `<sld:NamedLayer><sld:Name>${escapeWmsXml(name)}</sld:Name><sld:UserStyle><sld:Title>GeoRural ${color}</sld:Title><sld:FeatureTypeStyle><sld:Rule>${symbolizer}</sld:Rule></sld:FeatureTypeStyle></sld:UserStyle></sld:NamedLayer>`).join('');
    return `<?xml version="1.0" encoding="UTF-8"?><sld:StyledLayerDescriptor version="1.0.0" xmlns:sld="http://www.opengis.net/sld" xmlns:ogc="http://www.opengis.net/ogc" xmlns:gml="http://www.opengis.net/gml">${namedLayers}</sld:StyledLayerDescriptor>`;
  }

  function wmsOptions(layer, pref, attribution = null, requestedLayerName = '') {
    const layers = normalizeGeobahiaWmsLayerName(String(requestedLayerName || configuredWmsLayerName(layer) || layer?.slug || '').trim());
    if (!layers) throw new Error('A camada WMS está sem o Nome Técnico (layers).');

    const forceColor = shouldForceWmsColor(layer);
    const propertyBoundary = officialPropertyBoundaryMatch(layer);
    const options = {
      layers,
      styles: forceColor ? '' : (layer.metadata?.styles || layer.metadata?.officialWmsStyle || ''),
      format: layer.metadata?.format || 'image/png',
      transparent: true,
      version: layer.metadata?.wmsVersion || '1.1.1',
      uppercase: true,
      tiled: true,
      pane: 'catalogPane',
      opacity: Math.min(1, Math.max(0.05, Number(pref.opacity ?? layer?.style?.opacity ?? layer?.style?.fillOpacity ?? 0.55))),
      // Limites cadastrais precisam acompanhar o zoom sem desaparecer. Mantemos
      // mais tiles em memória e iniciamos a nova grade durante a animação; para
      // as demais WMS preservamos o modo conservador usado pelo catálogo.
      updateWhenIdle: false,
      // Em limite cadastral, não trocamos a grade no meio da animação de zoom.
      // O Leaflet mantém os tiles anteriores escalados até a nova grade chegar,
      // evitando o “sumiço” temporário relatado pelos usuários.
      updateWhenZooming: false,
      updateInterval: propertyBoundary ? 180 : 200,
      // Mantemos uma margem maior de tiles para que pequenos pan/zooms não
      // precisem refazer imediatamente as mesmas requisições WMS.
      keepBuffer: propertyBoundary ? 5 : 6,
      tileSize: 256,
      attribution: attribution || layer.source || layer.name,
      ...tileZoomOptions(layer)
    };

    if (forceColor) {
      const sldBody = buildWmsColorSld(layer, layers);
      if (sldBody) options.sld_body = sldBody;
    }
    return options;
  }

  function createWmsLayer(serviceUrl, layerName, layer, pref, attribution = null) {
    const options = wmsOptions(layer, pref, attribution, layerName);
    options.errorTileUrl = TRANSPARENT_TILE;
    const tileLayer = L.tileLayer.wms(serviceUrl, { ...options });
    tileLayer.__georuralWmsLayerName = options.layers;
    tileLayer.__georuralWmsCustomColor = Boolean(options.sld_body);
    tileLayer.__georuralWmsColor = layer?.style?.color || layer?.style?.fillColor || null;
    tileLayer.__georuralWmsInstanceId = L.Util.stamp(tileLayer);
    tileLayer.setZIndex?.(390);
    return tileLayer;
  }


  function mvtStyleFromCatalog(layer, pref) {
    const style = catalogVectorStyle(layer, pref);
    return {
      color: style.color || '#2563eb',
      weight: Math.max(0.4, Number(style.weight || 1.2)),
      opacity: Number(style.opacity ?? 0.9),
      fill: true,
      fillColor: style.fillColor || style.color || '#2563eb',
      fillOpacity: Number(style.fillOpacity ?? 0.28),
      lineCap: 'round',
      lineJoin: 'round'
    };
  }

  function buildMvtCatalogLayer(layer, pref, runtime = {}) {
    if (!L.vectorGrid?.protobuf) {
      throw new Error('O módulo Leaflet.VectorGrid não foi carregado. Atualize mapa.html e limpe o cache.');
    }
    if (!layer.serviceUrl) throw new Error('A camada MVT está sem URL de tiles.');

    const sourceLayerName = layer.metadata?.layerName || layer.slug || 'default';
    const configuredDetailTemplate = layer.metadata?.detailUrl || null;
    const mvtTemplateMatch = String(layer.serviceUrl || '').match(/^(.*)\/api\/gis\/tiles\/([^/]+)\/\{z\}\/\{x\}\/\{y\}\.pbf(?:\?.*)?$/i);
    const detailTemplate = configuredDetailTemplate || (mvtTemplateMatch ? `${mvtTemplateMatch[1]}/api/gis/layers/${mvtTemplateMatch[2]}/features/{id}` : null);
    const vectorStyle = mvtStyleFromCatalog(layer, pref);
    runtime.onProgress?.({ stage: 'mvt', percent: 72, message: 'Ativando tiles vetoriais da área visível...' });

    const tileLayer = L.vectorGrid.protobuf(layer.serviceUrl, {
      pane: 'catalogPane',
      rendererFactory: L.canvas.tile,
      interactive: true,
      keepBuffer: 3,
      updateWhenIdle: false,
      updateWhenZooming: true,
      updateInterval: 120,
      vectorTileLayerStyles: {
        [sourceLayerName]: vectorStyle,
        [layer.slug || sourceLayerName]: vectorStyle,
        default: vectorStyle
      },
      getFeatureId(feature) {
        return feature?.properties?.feature_id ?? feature?.properties?.id ?? feature?.properties?._id ?? feature?.properties?.source_id;
      },
      ...tileZoomOptions(layer)
    });

    tileLayer.__georuralMvt = true;
    tileLayer.__georuralSourceLayerName = sourceLayerName;
    tileLayer.setZIndex?.(395);

    tileLayer.on('click', async (event) => {
      const properties = event?.layer?.properties || {};
      const featureId = properties.feature_id ?? properties.id ?? properties._id;
      const sourceId = properties.source_id || properties._source_id;
      const basicRows = Object.entries(properties)
        .filter(([key]) => !key.startsWith('_'))
        .slice(0, 10)
        .map(([key, value]) => `<tr><th>${escapeHtmlLocal(key)}</th><td>${escapeHtmlLocal(value)}</td></tr>`)
        .join('');
      const popup = L.popup().setLatLng(event.latlng).setContent(
        `<strong>${escapeHtmlLocal(layer.name)}</strong>${basicRows ? `<table>${basicRows}</table>` : '<p>Carregando detalhes...</p>'}`
      ).openOn(map);

      if (!detailTemplate || !featureId) return;
      try {
        const detailUrl = detailTemplate
          .replaceAll('{id}', encodeURIComponent(featureId))
          .replaceAll('{sourceId}', encodeURIComponent(sourceId || ''));
        const response = await fetch(detailUrl, { headers: { Accept: 'application/geo+json,application/json' } });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const feature = await response.json();
        const rows = Object.entries(feature?.properties || {})
          .filter(([key]) => !key.startsWith('_'))
          .slice(0, 24)
          .map(([key, value]) => `<tr><th>${escapeHtmlLocal(key)}</th><td>${escapeHtmlLocal(value)}</td></tr>`)
          .join('');
        popup.setContent(`<strong>${escapeHtmlLocal(layer.name)}</strong><table>${rows}</table>`);
      } catch (error) {
        console.warn('Detalhes MVT indisponíveis:', error);
      }
    });

    return tileLayer;
  }

  function createResilientWmsLayer(serviceUrls, layerName, layer, pref, attribution = null, flags = {}) {
    const urls = [...new Set((serviceUrls || []).filter(Boolean))];
    if (!urls.length) throw new Error('Nenhuma rota WMS foi configurada para a camada.');

    const options = wmsOptions(layer, pref, attribution, layerName);
    options.tileSize = 256;
    options.keepBuffer = Math.max(2, Number(options.keepBuffer || 0));

    const ResilientWmsLayer = L.TileLayer.WMS.extend({
      initialize(urlList, layerOptions) {
        this._serviceUrls = urlList;
        this.__georuralLastError = '';
        const fallbackBoundaryColor = layer?.style?.color || layer?.style?.fillColor || '#FFD400';
        const fallbackBoundaryWeight = Number(layer?.style?.weight ?? 1.8);
        this.__georuralBoundaryColor = /^#[0-9a-f]{6}$/i.test(String(pref?.color || '')) ? String(pref.color).toUpperCase() : String(fallbackBoundaryColor).toUpperCase();
        this.__georuralBoundaryWeight = Math.max(0.6, Math.min(6, Number(pref?.weight ?? fallbackBoundaryWeight)));
        this.__georuralBoundaryStyleMode = layer?.metadata?.boundaryStyleMode === 'official' || layer?.metadata?.clientRasterRecolor === false ? 'official' : 'custom';
        this.__georuralUsesClientBoundaryStyle = flags.propertyBoundary === true && layer?.metadata?.clientRasterRecolor !== false;
        L.TileLayer.WMS.prototype.initialize.call(this, urlList[0], layerOptions);
      },

      createTile(coords, done) {
        // O SICAR ignora SLD inline em alguns nós e devolve o estilo cinza
        // padrão mesmo quando o frontend pede amarelo. Para Limites de
        // Propriedade, mantemos o WMS leve, mas recolorimos o PNG localmente.
        // Assim o servidor continua entregando raster, sem WFS massivo, e o
        // usuário vê o contorno amarelo com preenchimento realmente leve.
        const recolorPropertyBoundary = flags.propertyBoundary === true
          && layer?.metadata?.clientRasterRecolor !== false;
        const tileSize = this.getTileSize();
        const tile = recolorPropertyBoundary
          ? document.createElement('canvas')
          : document.createElement('img');
        const sourceImage = recolorPropertyBoundary ? new Image() : tile;

        if (recolorPropertyBoundary) {
          tile.width = tileSize.x;
          tile.height = tileSize.y;
          tile.style.width = `${tileSize.x}px`;
          tile.style.height = `${tileSize.y}px`;
          sourceImage.crossOrigin = 'anonymous';
        } else {
          tile.alt = '';
        }
        tile.setAttribute('role', 'presentation');

        const paintPropertyBoundaryTile = () => {
          if (!recolorPropertyBoundary) return;
          const ctx = tile.getContext('2d', { willReadFrequently: true });
          if (!ctx) return;
          ctx.clearRect(0, 0, tile.width, tile.height);
          ctx.drawImage(sourceImage, 0, 0, tile.width, tile.height);
          try {
            const image = ctx.getImageData(0, 0, tile.width, tile.height);
            const pixels = image.data;
            const original = new Uint8ClampedArray(pixels);
            const strongBoundary = new Uint8Array(tile.width * tile.height);

            // O WMS oficial nem sempre respeita SLD. Detectamos a borda no
            // raster e a redesenhamos com a cor/espessura escolhida pelo usuário.
            // O preenchimento continua quase transparente para preservar a ortofoto.
            for (let i = 0, pixelIndex = 0; i < pixels.length; i += 4, pixelIndex += 1) {
              const originalAlpha = original[i + 3];
              if (originalAlpha <= 2) continue;
              const luminance = (original[i] * 0.2126) + (original[i + 1] * 0.7152) + (original[i + 2] * 0.0722);
              const darkness = Math.max(0, Math.min(1, 1 - (luminance / 255)));
              strongBoundary[pixelIndex] = darkness >= 0.40 && originalAlpha >= 18 ? 1 : 0;
            }
            const [targetR, targetG, targetB] = hexToRgb(this.__georuralBoundaryColor || GEOBAHIA_BOUNDARY_UI_COLOR);
            const fillAlpha = Math.round(255 * Math.max(0.08, Math.min(0.24, Number(layer?.metadata?.wmsFillOpacity ?? GEOBAHIA_BOUNDARY_FILL_OPACITY))));
            const radius = Math.max(0, Math.min(3, Math.round((Number(this.__georuralBoundaryWeight || GEOBAHIA_BOUNDARY_UI_WEIGHT) - 0.8) / 1.2)));
            const width = tile.width;
            const height = tile.height;
            // Dilatação somente a partir dos pixels de borda. A implementação
            // anterior examinava a vizinhança de todos os 65 mil pixels do tile
            // e causava atraso perceptível depois do zoom.
            const paintedBoundary = radius > 0 ? new Uint8Array(strongBoundary.length) : strongBoundary;
            if (radius > 0) {
              for (let y = 0; y < height; y += 1) {
                for (let x = 0; x < width; x += 1) {
                  const pixelIndex = y * width + x;
                  if (!strongBoundary[pixelIndex]) continue;
                  const minY = Math.max(0, y - radius), maxY = Math.min(height - 1, y + radius);
                  const minX = Math.max(0, x - radius), maxX = Math.min(width - 1, x + radius);
                  for (let yy = minY; yy <= maxY; yy += 1) {
                    const row = yy * width;
                    for (let xx = minX; xx <= maxX; xx += 1) paintedBoundary[row + xx] = 1;
                  }
                }
              }
            }
            for (let pixelIndex = 0, i = 0; pixelIndex < paintedBoundary.length; pixelIndex += 1, i += 4) {
              const originalAlpha = original[i + 3];
              if (paintedBoundary[pixelIndex]) {
                pixels[i] = targetR; pixels[i + 1] = targetG; pixels[i + 2] = targetB;
                pixels[i + 3] = 238;
              } else if (originalAlpha > 2) {
                // A feição permanece legível sobre a ortofoto sem esconder o terreno.
                pixels[i] = targetR; pixels[i + 1] = targetG; pixels[i + 2] = targetB;
                pixels[i + 3] = fillAlpha;
              } else {
                pixels[i + 3] = 0;
              }
            }
            ctx.putImageData(image, 0, 0);
          } catch (error) {
            // O Worker envia CORS *, então isto normalmente não acontece. Se
            // algum navegador impedir leitura de pixels, ao menos preservamos
            // o tile original em vez de quebrar a camada.
            console.warn('Não foi possível recolorir tile SICAR localmente:', error);
          }
        };

        const candidateUrls = [...new Set(this._serviceUrls.flatMap((baseUrl) => {
          const previousUrl = this._url;
          let tileUrls = [];
          if (isGeoruralProxyMarkerUrl(baseUrl) || isInemaWmsUrl(baseUrl)) {
            this._url = isGeoruralProxyMarkerUrl(baseUrl)
              ? georuralProxyMarkerTarget(baseUrl)
              : normalizeInemaWmsUpstreamUrl(baseUrl);
            tileUrls = geoserviceEncodedProxyUrls(this.getTileUrl(coords), 'wms');
          } else {
            this._url = baseUrl;
            tileUrls = [this.getTileUrl(coords)];
          }
          this._url = previousUrl;
          return tileUrls;
        }).filter(Boolean))];

        let candidateIndex = 0;
        let attemptId = 0;
        let completed = false;
        let attemptTimer = null;
        const proxyOnly = flags.proxyOnly === true;
        const sourceTimeouts = candidateUrls.map((_url, index) => {
          if (flags.propertyBoundary === true) return proxyOnly ? (index === 0 ? 30_000 : 45_000) : (index === 0 ? 18_000 : 30_000);
          return proxyOnly ? 90_000 : (index === 0 ? 30_000 : 90_000);
        });

        const clearAttempt = () => {
          if (attemptTimer) clearTimeout(attemptTimer);
          attemptTimer = null;
        };

        const finish = (error = null) => {
          if (completed) return;
          completed = true;
          clearAttempt();
          sourceImage.onload = null;
          sourceImage.onerror = null;
          done(error, tile);
        };

        const tryNextSource = (reason = 'error') => {
          if (completed) return;
          clearAttempt();
          const currentAttempt = ++attemptId;

          if (candidateIndex >= candidateUrls.length) {
            const message = proxyOnly
              ? 'O proxy do GeoRural não recebeu uma imagem válida do WMS. Confira a URL e o Nome Técnico cadastrados.'
              : 'Nenhuma rota WMS entregou imagem. Confira a URL e o Nome Técnico cadastrados.';
            this.__georuralLastError = message;
            sourceImage.onload = null;
            sourceImage.onerror = null;
            if (recolorPropertyBoundary) {
              const ctx = tile.getContext('2d');
              ctx?.clearRect?.(0, 0, tile.width, tile.height);
            } else {
              tile.src = TRANSPARENT_TILE;
            }
            finish(new Error(message));
            return;
          }

          const sourceIndex = candidateIndex;
          const sourceUrl = candidateUrls[candidateIndex++];
          if (sourceIndex > 0) {
            this.fire('georuralfallback', {
              coords,
              reason,
              sourceIndex,
              message: 'Tentando a rota segura da API do GeoRural...'
            });
          }

          sourceImage.onload = () => {
            if (currentAttempt !== attemptId || completed) return;
            paintPropertyBoundaryTile();
            this.__georuralLastError = '';
            this.fire('georuralsourceok', { coords, sourceIndex });
            finish();
          };
          sourceImage.onerror = () => {
            if (currentAttempt !== attemptId || completed) return;
            this.__georuralLastError = proxyOnly
              ? 'A API do GeoRural não recebeu uma imagem válida do WMS.'
              : (sourceIndex === 0
                ? 'A conexão direta com o WMS falhou; tentando a API do GeoRural.'
                : 'A API do GeoRural também não recebeu uma imagem válida do WMS.');
            tryNextSource('error');
          };

          sourceImage.src = sourceUrl;
          attemptTimer = setTimeout(() => {
            if (currentAttempt !== attemptId || completed) return;
            this.__georuralLastError = proxyOnly
              ? 'O WMS do INEMA não respondeu ao proxy no tempo esperado.'
              : (sourceIndex === 0
                ? 'O WMS direto demorou demais; tentando a API do GeoRural.'
                : 'O servidor WMS não respondeu no tempo esperado.');
            tryNextSource('timeout');
          }, sourceTimeouts[sourceIndex] || 30_000);
        };

        tryNextSource('initial');
        return tile;
      }
    });

    // Cada cadastro cria uma instância WMS independente. O parâmetro LAYERS
    // fica preso à própria instância e nunca é reaproveitado entre cards.
    const tileLayer = new ResilientWmsLayer(urls, { ...options });
    tileLayer.__georuralWmsLayerName = options.layers;
    tileLayer.__georuralWmsInstanceId = L.Util.stamp(tileLayer);
    tileLayer.__georuralOfficialWms = flags.official === true;
    tileLayer.__georuralExternalWms = true;
    tileLayer.__georuralConfiguredWms = flags.configured !== false;
    tileLayer.__georuralPropertyBoundary = flags.propertyBoundary === true || officialPropertyBoundaryMatch(layer);
    tileLayer.__georuralProxyWms = flags.proxyOnly === true || urls.length > 1;
    tileLayer.__georuralSourceMode = flags.proxyOnly === true
      ? 'api-proxy-only'
      : (urls.length > 1 ? 'direct-with-api-fallback' : 'direct');
    if (tileLayer.__georuralPropertyBoundary) {
      tileLayer.__georuralBoundaryProvider = geobahiaPropertyBoundaryMatch(layer) ? 'geobahia' : 'sicar';
      tileLayer.setBoundaryStyle = ({ color, weight, opacity, styleMode } = {}) => {
        const clientStyled = tileLayer.__georuralUsesClientBoundaryStyle === true;
        let needsRedraw = false;
        if ((styleMode === 'official' || styleMode === 'custom') && tileLayer.__georuralBoundaryStyleMode !== styleMode) {
          tileLayer.__georuralBoundaryStyleMode = styleMode;
          needsRedraw = clientStyled;
        }
        if (clientStyled && /^#[0-9a-f]{6}$/i.test(String(color || ''))) {
          const nextColor = String(color).toUpperCase();
          if (nextColor !== tileLayer.__georuralBoundaryColor) {
            tileLayer.__georuralBoundaryColor = nextColor;
            needsRedraw = true;
          }
        }
        if (clientStyled && Number.isFinite(Number(weight))) {
          const nextWeight = Math.max(0.6, Math.min(6, Number(weight)));
          if (nextWeight !== tileLayer.__georuralBoundaryWeight) {
            tileLayer.__georuralBoundaryWeight = nextWeight;
            needsRedraw = true;
          }
        }
        // Opacidade é propriedade do próprio TileLayer e não exige baixar os
        // tiles novamente. Isto elimina recargas desnecessárias ao mover/zoomar.
        if (Number.isFinite(Number(opacity))) tileLayer.setOpacity?.(Math.max(0.05, Math.min(1, Number(opacity))));
        if (needsRedraw) tileLayer.redraw?.();
      };
      tileLayer.__georuralRetryBudget = 2;
      tileLayer.on('tileload', () => { tileLayer.__georuralRetryBudget = 2; });
      tileLayer.on('tileerror', () => {
        if (tileLayer.__georuralRetryBudget <= 0 || tileLayer.__georuralRetryTimer) return;
        tileLayer.__georuralRetryBudget -= 1;
        tileLayer.__georuralRetryTimer = setTimeout(() => {
          tileLayer.__georuralRetryTimer = null;
          if (map?.hasLayer?.(tileLayer)) tileLayer.redraw?.();
        }, 1200);
      });
    }
    tileLayer.setZIndex?.(390);
    return tileLayer;
  }

  function createResilientOfficialWmsLayer(serviceUrls, layerName, layer, pref, attribution = null) {
    const proxyOnly = (serviceUrls || []).length > 0
      && serviceUrls.every((url) => isGeoruralProxyMarkerUrl(url) || /\/api\/geoservices\/wms(?:\?|$)/i.test(String(url || '')) || /\/api\/geoservices\/wms-url\//i.test(String(url || '')) || /\/wms-url\//i.test(String(url || '')));
    return createResilientWmsLayer(serviceUrls, layerName, layer, pref, attribution, {
      official: true,
      configured: false,
      proxyOnly
    });
  }


  function geoserverOwsEndpointFromWmsUrl(rawUrl) {
    const normalized = normalizeWmsBaseUrl(rawUrl);
    try {
      const parsed = new URL(normalized, window.location.href);
      parsed.username = '';
      parsed.password = '';
      parsed.hash = '';
      if (/\/geoserver\/(?:wms|ows)\/?$/i.test(parsed.pathname)) {
        parsed.pathname = parsed.pathname.replace(/\/(?:wms|ows)\/?$/i, '/ows');
      } else if (/\/geoserver\/?$/i.test(parsed.pathname)) {
        parsed.pathname = parsed.pathname.replace(/\/?$/i, '/ows');
      }
      if (window.location.protocol === 'https:' && parsed.protocol === 'http:') parsed.protocol = 'https:';
      return parsed.toString();
    } catch {
      return normalized.replace(/\/wms(?:\?.*)?$/i, '/ows');
    }
  }

  function isGeobahiaWmsCatalogLayer(layer) {
    const serviceUrl = String(layer?.serviceUrl || layer?.sourceUrl || '').trim();
    return isInemaWmsUrl(serviceUrl) && Boolean(configuredWmsLayerName(layer));
  }

  function isUsingHuggingFaceGeoServices() {
    const provider = String(window.GEORURAL_CONFIG?.geoservicesProvider || '').toLowerCase();
    const base = String(window.GEORURAL_CONFIG?.geoservicesBaseUrl || window.GEORURAL_GEOSERVICES_URL || window.GEORURAL_WMS_PROXY_URL || '').toLowerCase();
    return provider.includes('huggingface') || /\.hf\.space(?:\/|$)/i.test(base);
  }

  function geobahiaLayerIsRaster(layer) {
    const layerName = String(configuredWmsLayerName(layer) || '');
    const identity = normalizeLayerText(`${layer?.name || ''} ${layer?.slug || ''} ${layerName}`);
    if (String(layer?.__georuralResolvedService || '').toLowerCase() === 'wms-only') return true;
    return /^Raster_/i.test(layerName)
      || /ortofoto|imagem raster|mosaico|imagem de satelite|imagem satelite/.test(identity)
      || layer?.metadata?.raster === true;
  }

  const GEOBAHIA_WFS_MIN_ZOOM = 15;
  const GEOBAHIA_WFS_MAX_FEATURES = 50;

  function geobahiaLayerShouldPreferWfs(layer) {
    if (!isGeobahiaWmsCatalogLayer(layer)) return false;
    if (officialPropertyBoundaryMatch(layer)) return false;
    if (officialMunicipalBoundaryMatch(layer)) return false;
    if (layer?.metadata?.forceWmsOnly === true) return false;
    if (geobahiaLayerIsRaster(layer)) return false;
    if (String(layer?.__georuralResolvedService || '').toLowerCase() === 'wms-only') return false;

    // 2026-08-29 — WMS-first para o catálogo GeoBahia/INEMA.
    // O WFS deixa de ser a renderização padrão: ele só pode ser usado de forma
    // explícita e em zoom próximo, evitando downloads massivos de GeoJSON.
    return layer?.metadata?.preferWfs === true;
  }

  function preferGeobahiaWfsViewport(layer = null) {
    try {
      if (localStorage.getItem('GEORURAL_FORCE_WMS_TILES') === '1') return false;
      if (localStorage.getItem('GEORURAL_FORCE_WFS_GEOBAHIA') === '1') {
        return Number(map?.getZoom?.() ?? 0) >= GEOBAHIA_WFS_MIN_ZOOM;
      }
    } catch {
      // ignora storage indisponível
    }
    if (!geobahiaLayerShouldPreferWfs(layer)) return false;
    if (officialMunicipalBoundaryMatch(layer) || layer?.metadata?.forceWmsOnly === true) return false;

    // Mesmo quando uma camada for marcada manualmente como WFS, nunca pedimos
    // vetores em zoom municipal/estadual. A visualização padrão continua WMS.
    if (Number(map?.getZoom?.() ?? 0) < GEOBAHIA_WFS_MIN_ZOOM) return false;
    if (window.GEORURAL_CONFIG?.enableExplicitGeobahiaWfs !== true) return false;
    return true;
  }

  window.__GEORURAL_DEBUG_GEOSERVICES__ = () => ({
    apiBaseUrl: window.GEORURAL_CONFIG?.apiBaseUrl || window.GEORURAL_API_URL || '',
    geoservicesBaseUrl: window.GEORURAL_CONFIG?.geoservicesBaseUrl || window.GEORURAL_GEOSERVICES_URL || '',
    wmsProxyBaseUrl: window.GEORURAL_CONFIG?.wmsProxyBaseUrl || window.GEORURAL_WMS_PROXY_URL || '',
    provider: window.GEORURAL_CONFIG?.geoservicesProvider || '',
    preferGeobahiaWfs: preferGeobahiaWfsViewport(null),
    build: window.GEORURAL_CONFIG?.appVersion || globalThis.__GEORURAL_BUILD__ || '',
    externalGeoRequests: 'cloudflare-worker-only',
    primaryGeoServices: geoserviceProxyPrimaryBase(),
    sourceMatrixVersion: '2.23.0-wms-first',
    layerSources: (layer) => officialLayerSourceCandidates(layer).map(({ id, url, label, priority }) => ({ id, url, label, priority }))
  });

  function geobahiaWfsUrls(layer) {
    const rawServiceUrl = String(layer?.__georuralResolvedServiceUrl || layer?.serviceUrl || layer?.sourceUrl || '').trim();
    const layerName = configuredWmsLayerName(layer);
    if (!rawServiceUrl || !layerName) throw new Error('Camada GeoBahia sem URL WMS ou nome técnico.');
    const bbox = visibleMapBbox(Number(map?.getZoom?.() ?? 0) >= 17 ? 0.006 : 0.012);
    const variants = [
      { version: '1.0.0', typeKey: 'TYPENAME', output: 'application/json', maxKey: 'MAXFEATURES' },
      { version: '1.0.0', typeKey: 'TYPENAME', output: 'json', maxKey: 'MAXFEATURES' },
      { version: '1.1.0', typeKey: 'TYPENAME', output: 'application/json', maxKey: 'MAXFEATURES' }
    ];
    const urls = [];
    for (const variant of variants) {
      const upstream = new URL(geoserverOwsEndpointFromWmsUrl(rawServiceUrl), window.location.href);
      upstream.searchParams.set('SERVICE', 'WFS');
      upstream.searchParams.set('VERSION', variant.version);
      upstream.searchParams.set('REQUEST', 'GetFeature');
      upstream.searchParams.set(variant.typeKey, layerName);
      upstream.searchParams.set('OUTPUTFORMAT', variant.output);
      upstream.searchParams.set('SRSNAME', 'EPSG:4326');
      upstream.searchParams.set('BBOX', `${bbox[0]},${bbox[1]},${bbox[2]},${bbox[3]},EPSG:4326`);
      upstream.searchParams.set(variant.maxKey, String(GEOBAHIA_WFS_MAX_FEATURES));
      urls.push(...geoserviceEncodedProxyUrls(upstream.toString(), 'wfs'));
    }
    return [...new Set(urls)];
  }

  function geoserviceProxyPrimaryBase() {
    return String(window.GEORURAL_CONFIG?.geoservicesBaseUrl || window.GEORURAL_GEOSERVICES_URL || window.GEORURAL_CONFIG?.wmsProxyBaseUrl || window.GEORURAL_WMS_PROXY_URL || '').replace(/\/+$/, '');
  }


  async function resolveGeobahiaCatalogLayer(layer, runtime = {}) {
    const configuredServiceUrl = String(layer?.serviceUrl || layer?.sourceUrl || '').trim();
    if (!isInemaWmsUrl(configuredServiceUrl)) return null;
    if (layer.__georuralResolutionAttempted && layer.__georuralResolvedLayerName) {
      return {
        layerName: layer.__georuralResolvedLayerName,
        service: layer.__georuralResolvedService || 'wfs',
        title: layer.__georuralResolvedTitle || layer.name || '',
        bbox: layer.__georuralResolvedBbox || null,
        serviceUrl: layer.__georuralResolvedServiceUrl || configuredServiceUrl,
        sourceLabel: layer.__georuralResolvedSourceLabel || 'INEMA / GeoBahia'
      };
    }

    const base = geoserviceProxyPrimaryBase();
    const requestedLayer = normalizeGeobahiaWmsLayerName(String(layer?.metadata?.layerName || layer?.metadata?.layers || '').trim());
    if (!base || !requestedLayer) return null;

    layer.__georuralResolutionAttempted = true;
    const metadataAliases = Array.isArray(layer?.metadata?.legacyLayerNames)
      ? layer.metadata.legacyLayerNames
      : [];
    const shortName = geobahiaWmsShortName(requestedLayer);
    const workspaceAliases = [
      'Vetor_Recortes_Tematicos',
      'Vetor_Bases_Gerais',
      'Vetor_Recursos_Hidricos',
      'Vetor_Recursos_Naturais',
      'Vetor_Recursos_Ambientais',
      'Vetor_Biodiversidade',
      'Raster',
      'Raster_ORTOFOTO'
    ].map((workspace) => `${workspace}:${shortName}`);
    const knownAliases = {
      uc_inema_2025: ['Vetor_Recursos_Ambientais:uc_inema_2024', 'uc_inema_2024', 'Vetor_Recursos_Ambientais:uc_inema_2023', 'uc_inema_2023', 'Vetor_Recursos_Ambientais:uc_inema_2021', 'uc_inema_2021', 'Vetor_Recortes_Tematicos:uc_estadual', 'uc_estadual'],
      uc_inema_2024: ['Vetor_Recursos_Ambientais:uc_inema_2025', 'uc_inema_2025', 'Vetor_Recursos_Ambientais:uc_inema_2023', 'uc_inema_2023', 'Vetor_Recursos_Ambientais:uc_inema_2021', 'uc_inema_2021', 'Vetor_Recortes_Tematicos:uc_estadual', 'uc_estadual'],
      uc_inema_2023: ['Vetor_Recursos_Ambientais:uc_inema_2025', 'uc_inema_2025', 'Vetor_Recursos_Ambientais:uc_inema_2024', 'uc_inema_2024', 'Vetor_Recursos_Ambientais:uc_inema_2021', 'uc_inema_2021', 'Vetor_Recortes_Tematicos:uc_estadual', 'uc_estadual'],
      uc_inema_2021: ['Vetor_Recursos_Ambientais:uc_inema_2025', 'uc_inema_2025', 'Vetor_Recursos_Ambientais:uc_inema_2024', 'uc_inema_2024', 'Vetor_Recursos_Ambientais:uc_inema_2023', 'uc_inema_2023', 'Vetor_Recortes_Tematicos:uc_estadual', 'uc_estadual'],
      uc_estadual: ['Vetor_Recursos_Ambientais:uc_inema_2025', 'uc_inema_2025', 'Vetor_Recursos_Ambientais:uc_inema_2024', 'uc_inema_2024', 'Vetor_Recursos_Ambientais:uc_inema_2023', 'uc_inema_2023', 'Vetor_Recursos_Ambientais:uc_inema_2021', 'uc_inema_2021'],
      faixa_servidao_ferrovias: ['Vetor_Recortes_Tematicos:faixa_dominio_ferrovia', 'faixa_dominio_ferrovia', 'Vetor_Recortes_Tematicos:faixa_dominio_ferrovias', 'faixa_dominio_ferrovias', 'Vetor_Recortes_Tematicos:faixa_dominio_ferroviario', 'faixa_dominio_ferroviario', 'Vetor_Recortes_Tematicos:faixa_servidao_ferrovia', 'faixa_servidao_ferrovia', 'Vetor_Recortes_Tematicos:faixa_servidao_ferroviaria', 'faixa_servidao_ferroviaria', 'Vetor_Recortes_Tematicos:trecho_ferroviario', 'trecho_ferroviario'],
      faixa_dominio_ferrovia: ['Vetor_Recortes_Tematicos:faixa_servidao_ferrovias', 'faixa_servidao_ferrovias'],
      faixa_dominio_ferrovias: ['Vetor_Recortes_Tematicos:faixa_servidao_ferrovias', 'faixa_servidao_ferrovias'],
      faixa_dominio_ferroviario: ['Vetor_Recortes_Tematicos:faixa_servidao_ferrovias', 'faixa_servidao_ferrovias'],
      solos: ['Vetor_Recursos_Ambientais:solos', 'Vetor_Recursos_Naturais:solos'],
      massa_dagua: ['Vetor_Recursos_Hidricos:trecho_massa_dagua_50k_inema', 'trecho_massa_dagua_50k_inema'],
      trecho_massa_dagua: ['Vetor_Recursos_Hidricos:trecho_massa_dagua_50k_inema', 'trecho_massa_dagua_50k_inema']
    };
    const sourceCandidates = officialLayerSourceCandidates(layer);
    const diagnostics = [];

    runtime.onProgress?.({
      stage: 'capabilities',
      percent: 8,
      message: sourceCandidates.length > 1
        ? `Validando ${sourceCandidates.length} fonte(s) oficial(is) para esta camada...`
        : 'Confirmando o nome técnico no catálogo oficial do GeoBahia...'
    });

    for (let index = 0; index < sourceCandidates.length; index += 1) {
      const candidate = sourceCandidates[index];
      const target = geoserverOwsEndpointFromWmsUrl(candidate.url);
      const params = new URLSearchParams({
        target,
        layer: requestedLayer,
        title: String(layer?.name || ''),
        slug: String(layer?.slug || ''),
        minScore: candidate.id === 'inema' || candidate.id === 'configured' ? '0.48' : '0.72'
      });
      [...new Set([
        ...metadataAliases,
        ...workspaceAliases,
        ...(knownAliases[shortName] || []),
        ...(candidate.aliases || [])
      ])]
        .slice(0, 48)
        .forEach((alias) => {
          const clean = String(alias || '').trim();
          if (clean && clean !== requestedLayer) params.append('alias', clean);
        });

      const controller = new AbortController();
      const parentAbort = () => controller.abort();
      const timer = setTimeout(() => controller.abort(), index === 0 ? 32_000 : 26_000);
      runtime.signal?.addEventListener('abort', parentAbort, { once: true });
      try {
        runtime.onProgress?.({
          stage: 'capabilities',
          percent: Math.min(24, 8 + (index * 4)),
          message: `Consultando ${candidate.label}...`
        });
        const resolveUrl = `${base}/resolve?${params.toString()}`;
        const securedResolveUrl = typeof window.GEORURAL_SECURE_GEOSERVICES_URL === 'function' ? window.GEORURAL_SECURE_GEOSERVICES_URL(resolveUrl) : resolveUrl;
        const response = await fetch(securedResolveUrl, {
          signal: controller.signal,
          headers: { Accept: 'application/json' },
          cache: 'no-store'
        });
        const payload = await response.json().catch(() => null);
        diagnostics.push({
          source: candidate.label,
          ok: Boolean(response.ok && payload?.ok),
          resolved: Boolean(payload?.resolved),
          service: payload?.service || null,
          score: Number(payload?.score || 0),
          error: payload?.error || null
        });
        if (!response.ok || !payload?.ok || !payload?.resolved || !payload?.layerName) continue;

        layer.__georuralResolvedLayerName = String(payload.layerName);
        layer.__georuralResolvedService = String(payload.service || 'wfs');
        layer.__georuralResolvedTitle = String(payload.title || layer.name || '');
        layer.__georuralResolvedBbox = Array.isArray(payload.bbox) ? payload.bbox.map(Number) : null;
        layer.__georuralResolutionSource = String(payload.source || 'capabilities');
        layer.__georuralResolvedServiceUrl = String(candidate.url || configuredServiceUrl);
        layer.__georuralResolvedSourceLabel = String(candidate.label || 'Fonte oficial');
        layer.__georuralResolutionDiagnostics = diagnostics;
        runtime.onProgress?.({
          stage: 'source-resolved',
          percent: 28,
          message: `Fonte oficial selecionada: ${layer.__georuralResolvedSourceLabel}.`
        });
        return {
          ...payload,
          serviceUrl: layer.__georuralResolvedServiceUrl,
          sourceLabel: layer.__georuralResolvedSourceLabel
        };
      } catch (error) {
        if (runtime.signal?.aborted) throw new DOMException('Operação cancelada.', 'AbortError');
        diagnostics.push({ source: candidate.label, ok: false, resolved: false, error: error?.message || String(error) });
        console.warn(`Não foi possível validar ${layer.name} em ${candidate.label}:`, error);
      } finally {
        clearTimeout(timer);
        runtime.signal?.removeEventListener('abort', parentAbort);
      }
    }

    // Nenhuma fonte confirmou via GetCapabilities. Preserva o nome cadastrado
    // do INEMA como último fallback, sem trocar silenciosamente por uma camada
    // parecida de outro órgão.
    layer.__georuralResolvedService = /^Raster_/i.test(requestedLayer) ? 'wms-only' : 'unknown';
    layer.__georuralResolvedServiceUrl = configuredServiceUrl;
    layer.__georuralResolvedSourceLabel = 'INEMA / GeoBahia';
    layer.__georuralResolutionDiagnostics = diagnostics;
    return null;
  }

  function geobahiaWfsUrl(layer) {
    return geobahiaWfsUrls(layer)[0];
  }

  async function fetchGeoTextWithTimeout(url, { signal = null, timeoutMs = 90_000 } = {}) {
    const controller = new AbortController();
    const abortFromParent = () => controller.abort();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    if (signal) signal.addEventListener('abort', abortFromParent, { once: true });
    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: { Accept: 'application/geo+json,application/json,text/plain' }
      });
      const text = await response.text().catch(() => '');
      if (!response.ok) {
        const error = new Error(`HTTP ${response.status}${text ? `: ${text.slice(0, 180)}` : ''}`);
        error.status = response.status;
        throw error;
      }
      return { text, response, url };
    } catch (error) {
      if (signal?.aborted) throw new DOMException('Operação cancelada.', 'AbortError');
      if (error?.name === 'AbortError') throw new Error(`Tempo limite de ${Math.round(timeoutMs / 1000)}s excedido.`);
      throw error;
    } finally {
      clearTimeout(timer);
      if (signal) signal.removeEventListener('abort', abortFromParent);
    }
  }

  async function fetchFirstTextCandidate(urls, { signal = null } = {}) {
    const errors = [];
    for (let index = 0; index < urls.length; index += 1) {
      const url = urls[index];
      try {
        return await fetchGeoTextWithTimeout(url, { signal, timeoutMs: 90_000 });
      } catch (error) {
        if (error?.name === 'AbortError') throw error;
        errors.push(`${new URL(url, window.location.href).origin}: ${error?.message || String(error)}`);
      }
    }
    throw new Error(`WFS GeoBahia falhou em todas as rotas do GeoRural. ${errors.slice(0, 3).join(' | ')}`.trim());
  }

  async function buildGeobahiaWfsViewportLayer(layer, pref, runtime = {}) {
    if (Number(map?.getZoom?.() ?? 0) < GEOBAHIA_WFS_MIN_ZOOM) {
      throw new Error(`WFS vetorial disponível somente a partir do zoom ${GEOBAHIA_WFS_MIN_ZOOM}; use WMS para visualização ampla.`);
    }
    const target = L.featureGroup([], { pane: 'catalogPane' });
    target.__georuralWfsFallback = true;
    target.__georuralExternalWms = true;
    target.__georuralSourceMode = 'wfs-visible-fallback';
    target.__georuralWmsLayerName = configuredWmsLayerName(layer);

    const vectorStyle = catalogVectorStyle(layer, pref);
    let disposed = false;
    let reloadTimer = null;
    let requestController = null;

    const loadViewport = async ({ initial = false } = {}) => {
      if (disposed) return { count: 0 };
      requestController?.abort();
      requestController = new AbortController();
      runtime.onProgress?.({
        stage: 'wfs-fallback',
        percent: initial ? 58 : 72,
        message: initial
          ? 'Buscando os vetores GeoBahia/WFS da área visível...'
          : 'Atualizando os vetores GeoBahia/WFS da área visível...'
      });

      const { text } = await fetchFirstTextCandidate(geobahiaWfsUrls(layer), {
        signal: requestController.signal
      });
      const geojson = JSON.parse(text);
      const features = Array.isArray(geojson?.features) ? geojson.features : [];
      target.clearLayers();
      if (features.length) {
        L.geoJSON({ type: 'FeatureCollection', features }, {
          pane: 'catalogPane',
          style: () => vectorStyle,
          pointToLayer: (_feature, latlng) => L.circleMarker(latlng, {
            pane: 'catalogPane',
            radius: 5,
            color: vectorStyle.color,
            weight: 2,
            fillColor: vectorStyle.fillColor,
            fillOpacity: vectorStyle.fillOpacity
          }),
          onEachFeature: (feature, featureLayer) => bindCatalogPopup(feature, featureLayer, layer)
        }).addTo(target);
      }
      target.__georuralFallbackSummary = {
        count: features.length,
        message: features.length
          ? `GeoBahia carregado por vetores WFS na área visível (${features.length} feição(ões)).`
          : 'GeoBahia consultado por WFS; nenhuma feição nesta área visível.'
      };
      runtime.onProgress?.({ stage: 'wfs-fallback', percent: 100, message: target.__georuralFallbackSummary.message });
      return target.__georuralFallbackSummary;
    };

    const scheduleVisibleLoad = () => {
      if (disposed || !map.hasLayer(target)) return;
      clearTimeout(reloadTimer);
      reloadTimer = setTimeout(() => {
        loadViewport({ initial: false }).catch((error) => {
          if (error?.name !== 'AbortError') console.warn(`Falha ao atualizar WFS GeoBahia de ${layer.name}:`, error);
        });
      }, 350);
    };

    await loadViewport({ initial: true });
    map.on('moveend zoomend', scheduleVisibleLoad);
    target.__georuralCleanup = () => {
      disposed = true;
      clearTimeout(reloadTimer);
      requestController?.abort();
      map.off('moveend zoomend', scheduleVisibleLoad);
    };
    return target;
  }


  function visibleWmsIdentifyEntries() {
    const entries = [];
    for (const [layerId, entry] of catalogMapLayers.entries()) {
      const leafletLayer = entry?.leafletLayer;
      if (!leafletLayer || !map.hasLayer(leafletLayer)) continue;
      const isWms = Boolean(leafletLayer.__georuralExternalWms || leafletLayer.__georuralOfficialWms || leafletLayer.__georuralPropertyBoundary || leafletLayer.__georuralWmsLayerName || leafletLayer.wmsParams?.layers);
      if (!isWms) continue;
      entries.push({ layerId, leafletLayer, meta: entry.meta || {} });
    }
    return entries;
  }

  function wmsIdentifyTargetUrl(leafletLayer, meta = {}) {
    return leafletLayer.__georuralOriginalServiceUrl
      || leafletLayer.__georuralResolvedServiceUrl
      || meta.serviceUrl
      || meta.sourceUrl
      || leafletLayer._url
      || '';
  }

  function buildWmsFeatureInfoUpstreamUrl(entry, latlng, infoFormat = 'application/json') {
    const leafletLayer = entry.leafletLayer || {};
    const meta = entry.meta || {};
    const target = wmsIdentifyTargetUrl(leafletLayer, meta) || meta.serviceUrl || meta.sourceUrl || '';
    const layers = leafletLayer.__georuralWmsLayerName || leafletLayer.wmsParams?.layers || meta.layerName || meta.layers || configuredWmsLayerName(meta);
    if (!target || !layers) return '';

    const size = map.getSize();
    const point = map.latLngToContainerPoint(latlng);
    const bounds = map.getBounds();
    let upstream;
    try {
      upstream = new URL(isInemaWmsUrl(target) ? normalizeInemaWmsUpstreamUrl(target) : normalizeWmsBaseUrl(target), window.location.href);
    } catch {
      return '';
    }
    upstream.searchParams.set('SERVICE', 'WMS');
    upstream.searchParams.set('VERSION', '1.1.1');
    upstream.searchParams.set('REQUEST', 'GetFeatureInfo');
    upstream.searchParams.set('LAYERS', layers);
    upstream.searchParams.set('QUERY_LAYERS', layers);
    upstream.searchParams.set('STYLES', leafletLayer.wmsParams?.styles || meta.metadata?.styles || meta.styles || '');
    upstream.searchParams.set('FORMAT', leafletLayer.wmsParams?.format || meta.format || 'image/png');
    upstream.searchParams.set('TRANSPARENT', String(leafletLayer.wmsParams?.transparent ?? meta.transparent ?? true));
    upstream.searchParams.set('SRS', 'EPSG:4326');
    upstream.searchParams.set('BBOX', [bounds.getWest(), bounds.getSouth(), bounds.getEast(), bounds.getNorth()].map((value) => Number(value).toFixed(8)).join(','));
    upstream.searchParams.set('WIDTH', String(Math.max(1, Math.round(size.x))));
    upstream.searchParams.set('HEIGHT', String(Math.max(1, Math.round(size.y))));
    upstream.searchParams.set('X', String(Math.max(0, Math.min(Math.round(size.x) - 1, Math.round(point.x)))));
    upstream.searchParams.set('Y', String(Math.max(0, Math.min(Math.round(size.y) - 1, Math.round(point.y)))));
    upstream.searchParams.set('INFO_FORMAT', infoFormat);
    upstream.searchParams.set('FEATURE_COUNT', String(meta.featureCount || 8));

    return upstream.toString();
  }

  function buildWmsFeatureInfoUrl(entry, latlng, infoFormat = 'application/json') {
    const upstream = buildWmsFeatureInfoUpstreamUrl(entry, latlng, infoFormat);
    return upstream ? geoserviceEncodedProxyUrl(upstream, 'wms-info') : '';
  }

  function buildWmsFeatureInfoProxyUrls(entry, latlng, infoFormat = 'application/json') {
    const upstream = buildWmsFeatureInfoUpstreamUrl(entry, latlng, infoFormat);
    return upstream ? geoserviceEncodedProxyUrls(upstream, 'wms-info') : [];
  }

