  els.generateAppBtn?.addEventListener('click', () => {
    if (!selectedLayer) return toast('Selecione um curso d’água desenhado em linha.', 'error');
    const feature = selectedLayer.toGeoJSON();
    const category = metadata(selectedLayer).category;
    if (!isAppGenerationCategory(category) || !/LineString/.test(feature.geometry?.type || '')) {
      return toast('A APP automática exige uma linha classificada como “APP” ou “Nascente/curso d’água”.', 'error');
    }
    const width = Number(prompt('Informe a largura de cada margem da APP, em metros:', '30'));
    if (!Number.isFinite(width) || width <= 0 || width > 1000) return toast('Largura inválida.', 'error');
    try {
      const buffered = turf.buffer(feature, width, { units: 'meters', steps: 16 });
      if (!buffered) throw new Error('Não foi possível gerar o buffer.');
      buffered.properties = { name: `APP automática — ${metadata(selectedLayer).name || 'curso d’água'}`, category: 'app', bufferMeters: width, automatic: true };
      loadCollection({ type: 'FeatureCollection', features: [buffered] }, false);
      toast(`APP de ${width} m criada. Clique em Salvar para sincronizar no Appwrite.`, 'success');
    } catch (error) {
      console.error(error); toast(error.message || 'Falha ao gerar a APP.', 'error');
    }
  });

