  function createLayerStyleControls({ color, fillColor, opacity, weight, onColor, onFillColor, onOpacity, onWeight, showColor = true, showFillColor = false, showOpacity = true, showWeight = false, disabled = false }) {
    const wrap = document.createElement('div');
    wrap.className = 'layer-style-controls';
    const safeColor = color || '#64748b';
    const safeFill = fillColor || safeColor;
    const safeOpacity = Number.isFinite(Number(opacity)) ? Number(opacity) : 0.92;
    const safeWeight = Number.isFinite(Number(weight)) ? Number(weight) : 2.2;
    const colorRow = showColor ? `<label><span>Cor da linha</span><input data-style-field="stroke" type="color" value="${safeColor}" ${disabled ? 'disabled' : ''}><em></em></label>` : '';
    const fillRow = showFillColor ? `<label><span>Cor interna</span><input data-style-field="fill" type="color" value="${safeFill}" ${disabled ? 'disabled' : ''}><em></em></label>` : '';
    const opacityRow = showOpacity ? `<label><span>Transparência</span><input data-style-field="opacity" type="range" min="0" max="1" step="0.05" value="${safeOpacity}" ${disabled ? 'disabled' : ''}><em>${Math.round(safeOpacity * 100)}%</em></label>` : '';
    const weightRow = showWeight ? `<label><span>Espessura</span><input data-style-field="weight" type="range" min="1" max="10" step="0.2" value="${safeWeight}" ${disabled ? 'disabled' : ''}><em>${safeWeight.toFixed(1)}px</em></label>` : '';
    wrap.innerHTML = `${colorRow}${fillRow}${opacityRow}${weightRow}`;
    const strokeInput = wrap.querySelector('[data-style-field="stroke"]');
    const fillInput = wrap.querySelector('[data-style-field="fill"]');
    const opacityRange = wrap.querySelector('[data-style-field="opacity"]');
    const opacityLabel = opacityRange?.closest('label')?.querySelector('em');
    const weightRange = wrap.querySelector('[data-style-field="weight"]');
    const weightLabel = weightRange?.closest('label')?.querySelector('em');
    wrap.addEventListener('click', (event) => event.stopPropagation());
    wrap.addEventListener('mousedown', (event) => event.stopPropagation());
    if (!disabled) {
      const bindColorCommit = (input, callback) => {
        if (!input || typeof callback !== 'function') return;
        let lastCommitted = '';
        const commit = () => {
          const value = String(input.value || '').trim();
          if (!value || value === lastCommitted) return;
          lastCommitted = value;
          callback(value);
        };
        const stopColorEvent = (event) => {
          event.stopPropagation?.();
        };
        // Chromium/Windows pode só confirmar a cor no evento change quando o
        // seletor nativo é fechado. Escutamos input + change + blur para que a
        // escolha sempre seja assumida ao clicar novamente no mapa/painel.
        // Ao fechar o seletor clicando fora, protegemos o próximo clique para
        // que ele não selecione um elemento do mapa por baixo acidentalmente.
        input.addEventListener('pointerdown', stopColorEvent, true);
        input.addEventListener('mousedown', stopColorEvent, true);
        input.addEventListener('click', stopColorEvent, true);
        input.addEventListener('focus', () => { colorPickerDismissGuardUntil = 0; });
        input.addEventListener('input', commit);
        input.addEventListener('change', () => { commit(); armColorPickerDismissGuard(); });
        input.addEventListener('blur', () => { commit(); armColorPickerDismissGuard(); });
      };
      bindColorCommit(strokeInput, onColor);
      bindColorCommit(fillInput, onFillColor);
      opacityRange?.addEventListener('input', () => { updateLayerControlStyle(opacityRange, opacityLabel); onOpacity?.(Number(opacityRange.value)); });
      weightRange?.addEventListener('input', () => { if (weightLabel) weightLabel.textContent = `${Number(weightRange.value).toFixed(1)}px`; onWeight?.(Number(weightRange.value)); });
    }
    return wrap;
  }

  function captureLiveRecoveryDraft() {
    try {
      if (!liveDrawState?.active) return null;
      const points = (liveDrawState.points || []).filter(Boolean).map((point) => ({ lat: Number(point.lat), lng: Number(point.lng) }))
        .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng));
      const origin = liveDrawState.origin && Number.isFinite(Number(liveDrawState.origin.lat)) && Number.isFinite(Number(liveDrawState.origin.lng))
        ? { lat: Number(liveDrawState.origin.lat), lng: Number(liveDrawState.origin.lng) }
        : null;
      if (!points.length && !origin) return null;
      return { type: liveDrawState.type || 'polygon', points, origin };
    } catch { return null; }
  }

  function recoverySnapshotHasDrawing(snapshot = {}) {
    const features = Array.isArray(snapshot?.features) ? snapshot.features : [];
    const hasFeature = features.some((item) => item?.geoJson && typeof item.geoJson === 'object');
    const live = snapshot?.liveDraft;
    const livePoints = Array.isArray(live?.points) ? live.points : [];
    return hasFeature || livePoints.length > 0 || Boolean(live?.origin);
  }

  function currentRecoverySnapshot() {
    return {
      project: remoteProjectPayload(),
      features: remoteFeaturePayloads(),
      liveDraft: captureLiveRecoveryDraft(),
      view: { center: map.getCenter(), zoom: map.getZoom() },
      reason: 'drawing-change'
    };
  }

  function recoveryFingerprint(snapshot = currentRecoverySnapshot()) {
    // Rascunho é sobre DESENHO, não sobre navegar no mapa. Pan/zoom, abrir
    // painéis ou simplesmente entrar no mapa não podem gerar um novo draft.
    try { return JSON.stringify({ f: snapshot.features || [], l: snapshot.liveDraft || null }); } catch { return ''; }
  }

  function setRecoveryBaseline() {
    try {
      const snapshot = currentRecoverySnapshot();
      recoveryBaselineFingerprint = recoveryFingerprint(snapshot);
      recoveryBaselineHasDrawing = recoverySnapshotHasDrawing(snapshot);
      lastRecoveryFingerprint = recoveryBaselineFingerprint;
      recoveryReady = true;
    } catch { recoveryReady = true; }
  }

  function recoveryDraftKey(projectId = currentProjectId) {
    return `surveyor-project-draft-v21-10-0:${String(projectId || 'novo')}`;
  }

  function shouldPersistRecoverySnapshot(snapshot, fingerprint) {
    if (!fingerprint || fingerprint === recoveryBaselineFingerprint || fingerprint === lastRecoveryFingerprint) return false;
    // Novo mapa vazio nunca cria draft. Em projeto existente, uma remoção total
    // ainda é uma alteração real se o baseline possuía desenho.
    return recoverySnapshotHasDrawing(snapshot) || recoveryBaselineHasDrawing;
  }

  function persistRecoverySnapshotNow() {
    if (!recoveryReady) return false;
    const recovery = window.GeoRuralProjects?.saveRecoverySnapshot;
    if (typeof recovery !== 'function') return false;
    try {
      const snapshot = currentRecoverySnapshot();
      const fingerprint = recoveryFingerprint(snapshot);
      if (!shouldPersistRecoverySnapshot(snapshot, fingerprint)) return false;
      // A cópia só é anunciada após confirmação real do armazenamento síncrono.
      // Se a quota impedir a gravação, não marcar o fingerprint como persistido:
      // uma próxima tentativa ainda deve poder ocorrer.
      sessionStorage.setItem(recoveryDraftKey(), JSON.stringify({
        recoveryOnly: true,
        projectId: currentProjectId || null,
        snapshot,
        savedLocallyAt: new Date().toISOString()
      }));
      lastRecoveryFingerprint = fingerprint;
      try { Promise.resolve(recovery(currentProjectId || 'novo', snapshot)).catch(() => null); }
      catch (error) { console.warn('[Surveyor] Sincronização da cópia local indisponível:', error); }
      return true;
    } catch { return false; }
  }

  function scheduleRecoverySnapshot() {
    if (!recoveryReady) return;
    if (recoverySnapshotTimer) clearTimeout(recoverySnapshotTimer);
    recoverySnapshotTimer = setTimeout(() => {
      recoverySnapshotTimer = null;
      persistRecoverySnapshotNow();
    }, 900);
  }

  async function clearRecoveryDraft(projectId = currentProjectId) {
    const key = recoveryDraftKey(projectId);
    await window.GeoRuralProjects?.deleteRecoveryDraft?.(key).catch?.(() => null);
    try { sessionStorage.removeItem(key); } catch {}
    setRecoveryBaseline();
  }

  function restorePartialLiveDraft(liveDraft) {
    if (!liveDraft) return false;
    const points = (Array.isArray(liveDraft.points) ? liveDraft.points : [])
      .map((point) => [Number(point.lat), Number(point.lng)])
      .filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));
    if (!points.length) return false;
    let layer = null;
    const type = String(liveDraft.type || 'polygon');
    if (type === 'polygon' && points.length >= 3) layer = L.polygon(points, styleFor('outros'));
    else if (points.length >= 2) layer = L.polyline(points, styleFor('outros'));
    else layer = L.marker(points[0], { pane: 'drawnPane', icon: markerIcon('outros') });
    if (!layer) return false;
    layer.feature = layer.toGeoJSON?.() || null;
    attach(layer);
    const props = metadata(layer);
    props.name = 'Rascunho recuperado';
    props.recoveredDraft = true;
    layer.__geoMeta = props;
    drawn.addLayer(layer);
    return true;
  }

  async function maybeRestoreRecovery(projectId = null) {
    const list = await window.GeoRuralProjects?.listPendingDraftsAsync?.().catch?.(() => []) || [];
    const key = recoveryDraftKey(projectId);
    const draft = list.find((item) => item.key === key && item.snapshot);
    if (!draft) return false;
    const snapshot = draft.snapshot || {};
    // Rascunhos vazios criados por navegação/zoom são descartados silenciosamente.
    // Rascunhos reais permanecem armazenados apenas como contingência interna;
    // a abertura do mapa nunca é bloqueada por um diálogo de restauração.
    if (!recoverySnapshotHasDrawing(snapshot)) {
      await window.GeoRuralProjects?.deleteRecoveryDraft?.(key).catch?.(() => null);
      try { sessionStorage.removeItem(key); } catch {}
    }
    return false;
  }

  function formatPropertyLocalBytes(bytes = 0) {
    const value = Math.max(0, Number(bytes) || 0);
    if (value >= 1024 ** 3) return `${(value / (1024 ** 3)).toLocaleString('pt-BR', { maximumFractionDigits: 2 })} GB`;
    if (value >= 1024 ** 2) return `${(value / (1024 ** 2)).toLocaleString('pt-BR', { maximumFractionDigits: 1 })} MB`;
    if (value >= 1024) return `${(value / 1024).toLocaleString('pt-BR', { maximumFractionDigits: 0 })} KB`;
    return `${Math.round(value)} B`;
  }

  const propertyLocalAttributeFieldCache = new Map();
  // Fonte única do ciclo de instalação municipal. A ausência deste estado nas
  // versões anteriores fazia o seletor de cidades abortar durante a renderização
  // e deixava o botão Baixar sem ação por ReferenceError.
  const propertyLocalInstallJobs = new Map();
  const propertyLocalInstallProgress = new Map();
  const PROPERTY_LOCAL_CAR_FIELDS = ['cod_imovel','codigo_imovel','codigoimovel','num_sicar','numero_sicar','numero_car','registro_car','cod_car','nr_car','car'];
  const PROPERTY_LOCAL_CODE_FIELDS = ['ide_imovel','id_imovel','codigo_imo','codigo_incra','cod_incra','cod_imovel','codigo_imovel','codigoimovel','objectid','fid','id'];
  const PROPERTY_LOCAL_AREA_FIELDS = ['area','area_ha','area_ha_calc','area_hectares','area_imovel','num_area','qtd_area','area_total'];
  const PROPERTY_LOCAL_EXTRA_LOOKUP_FIELDS = ['status','situacao','situacao_imovel','condicao','tipo_imovel'];
  const propertyGeometryMemoryCache = new Map();
  const PROPERTY_GEOMETRY_CACHE_LIMIT = 20;

  function propertyGeometryCacheKey(feature, stateCode = '') {
    const props = feature?.properties || {};
    const state = normalizedCatalogState(stateCode || props._surveyor_local_cache || propertySearchStateCode());
    const car = String(propertyCarFromFeature(feature) || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    const officialCode = registryScalarValue(props, ['ide_imovel','id_imovel','codigo_imo']);
    // Não usar feature.id para chaves de geometria: FIDs WFS podem ser
    // sequenciais e reaproveitados para imóveis distintos em outras consultas.
    return `${state}|${car ? `CAR:${car}` : officialCode ? `CODE:${String(officialCode).trim()}` : `LOCAL:${String(props._surveyor_local_identity || '').trim()}`}`;
  }
  function rememberPropertyGeometry(key, feature) {
    if (!key || !feature?.geometry) return;
    if (propertyGeometryMemoryCache.has(key)) propertyGeometryMemoryCache.delete(key);
    propertyGeometryMemoryCache.set(key, feature);
    while (propertyGeometryMemoryCache.size > PROPERTY_GEOMETRY_CACHE_LIMIT) {
      const oldest = propertyGeometryMemoryCache.keys().next().value;
      propertyGeometryMemoryCache.delete(oldest);
    }
  }

  async function fetchPropertyLocalAttributeFields(stateCode) {
    const uf = normalizedCatalogState(stateCode);
    if (propertyLocalAttributeFieldCache.has(uf)) return propertyLocalAttributeFieldCache.get(uf);
    const bahia = uf === 'BA';
    const typeName = bahia ? OFFICIAL_PROPERTY_BOUNDARY_LAYER : `sicar:sicar_imoveis_${uf.toLowerCase()}`;
    const upstream = new URL(bahia
      ? 'https://geoserver.inema.ba.gov.br/geoserver/ows'
      : 'https://geoserver.car.gov.br/geoserver/sicar/ows');
    upstream.searchParams.set('SERVICE', 'WFS');
    upstream.searchParams.set('VERSION', '1.0.0');
    upstream.searchParams.set('REQUEST', 'DescribeFeatureType');
    upstream.searchParams.set('TYPENAME', typeName);
    const urls = bahia
      ? geoserviceEncodedProxyUrls(upstream.toString(), 'wfs')
      : [...geoserviceEncodedProxyUrls(upstream.toString(), 'wfs'), upstream.toString()];
    let xml = '';
    let lastError = null;
    for (const url of urls) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 20_000);
      try {
        const response = await fetch(url, { cache: 'no-store', credentials: 'omit', signal: controller.signal, headers: { Accept: 'application/xml,text/xml;q=0.9,*/*;q=0.1' } });
        if (!response.ok) throw new Error(`DescribeFeatureType HTTP ${response.status}`);
        xml = await response.text();
        if (xml) break;
      } catch (error) {
        lastError = error;
      } finally {
        clearTimeout(timer);
      }
    }
    if (!xml) throw lastError || new Error('Não foi possível obter o schema de atributos da camada oficial.');
    const doc = new DOMParser().parseFromString(xml, 'application/xml');
    if (doc.querySelector('parsererror')) throw new Error('Schema de atributos inválido.');

    const available = [];
    const seen = new Set();
    for (const node of [...doc.getElementsByTagNameNS('*', 'element')]) {
      const name = String(node.getAttribute('name') || '').trim();
      const type = String(node.getAttribute('type') || '').trim().toLowerCase();
      if (!name || seen.has(name.toLowerCase())) continue;
      if (/gml:|geometry|polygon|surface|point|curve|linestring|multisurface|multipolygon|multicurve/.test(type)) continue;
      if (/^(geom|geometry|the_geom|shape)$/i.test(name)) continue;
      seen.add(name.toLowerCase());
      available.push(name);
    }

    // Sincroniza o schema municipal usado pelo índice local com o mesmo
    // DescribeFeatureType já carregado aqui. Na RC33 esses arrays ainda podiam
    // estar nulos quando o usuário clicava em "Baixar dados", fazendo o filtro
    // municipal falhar mesmo quando a fonte publicava o campo.
    if (bahia) {
      const availableLower = new Set(available.map((field) => String(field).toLowerCase()));
      cefirPropertyMunicipalityNameSchemaFields = CEFIR_PROPERTY_MUNICIPALITY_NAME_FIELDS
        .filter((field) => availableLower.has(field.toLowerCase()));
      cefirPropertyMunicipalityCodeSchemaFields = CEFIR_PROPERTY_MUNICIPALITY_CODE_FIELDS
        .filter((field) => availableLower.has(field.toLowerCase()));
    }

    const desiredAliases = new Set([
      ...CEFIR_PROPERTY_NAME_FIELDS,
      ...CEFIR_PROPERTY_MUNICIPALITY_NAME_FIELDS,
      ...CEFIR_PROPERTY_MUNICIPALITY_CODE_FIELDS,
      ...PROPERTY_LOCAL_CAR_FIELDS,
      ...PROPERTY_LOCAL_CODE_FIELDS,
      ...PROPERTY_LOCAL_AREA_FIELDS,
      ...PROPERTY_LOCAL_EXTRA_LOOKUP_FIELDS
    ].map((field) => String(field).toLowerCase().replace(/[^a-z0-9]/g, '')));
    const fields = available.filter((field) => desiredAliases.has(String(field).toLowerCase().replace(/[^a-z0-9]/g, '')));
    if (!fields.length) throw new Error('A camada oficial não publicou os campos mínimos necessários para o índice de pesquisa.');
    propertyLocalAttributeFieldCache.set(uf, fields);
    return fields;
  }

  async function fetchPropertyLocalDataPage(stateCode, { startIndex = 0, pageSize = 400, municipality = null } = {}) {
    const uf = normalizedCatalogState(stateCode);
    const bahia = uf === 'BA';
    const boundedPageSize = Math.max(100, Math.min(750, Number(pageSize) || 400));
    const attributeFields = await fetchPropertyLocalAttributeFields(uf);

    let municipalityClauses = [];
    let municipalityBbox = null;
    if (municipality) {
      if (bahia) municipalityClauses = propertyMunicipalitySearchClauses(municipality);
      else {
        const schema = await fetchPropertySearchSchema(uf).catch(() => null);
        municipalityClauses = propertyMunicipalitySearchClausesForSchema(municipality, schema);
      }
      if (!municipalityClauses.length) {
        municipalityBbox = await resolvePropertyMunicipalityBbox(municipality, uf);
        if (!Array.isArray(municipalityBbox) || municipalityBbox.length !== 4 || !municipalityBbox.every(Number.isFinite)) {
          throw new Error('Não foi possível delimitar a cidade selecionada. Escolha novamente o município e tente outra vez.');
        }
      }
    }

    const serviceUrl = bahia
      ? 'https://geoserver.inema.ba.gov.br/geoserver/ows'
      : 'https://geoserver.car.gov.br/geoserver/sicar/ows';
    const typeName = bahia ? OFFICIAL_PROPERTY_BOUNDARY_LAYER : `sicar:sicar_imoveis_${uf.toLowerCase()}`;
    const versions = ['2.0.0', '1.1.0', '1.0.0'];
    let lastError = null;

    for (const version of versions) {
      const upstream = new URL(serviceUrl);
      upstream.searchParams.set('SERVICE', 'WFS');
      upstream.searchParams.set('VERSION', version);
      upstream.searchParams.set('REQUEST', 'GetFeature');
      upstream.searchParams.set(version === '2.0.0' ? 'TYPENAMES' : 'TYPENAME', typeName);
      upstream.searchParams.set('OUTPUTFORMAT', 'application/json');
      upstream.searchParams.set('SRSNAME', 'EPSG:4326');
      upstream.searchParams.set(version === '2.0.0' ? 'COUNT' : 'MAXFEATURES', String(boundedPageSize));
      upstream.searchParams.set('STARTINDEX', String(Math.max(0, Number(startIndex) || 0)));
      // O índice local continua 100% sem geometria. Lotes pequenos evitam que o
      // GeoServer precise materializar milhares de feições antes de responder.
      upstream.searchParams.set('PROPERTYNAME', attributeFields.join(','));
      if (municipalityClauses.length) upstream.searchParams.set('CQL_FILTER', `(${municipalityClauses.join(' OR ')})`);
      else if (municipalityBbox) upstream.searchParams.set('BBOX', `${municipalityBbox.join(',')},EPSG:4326`);

      const upstreamUrl = upstream.toString();
      const candidates = bahia
        ? geoserviceEncodedProxyUrls(upstreamUrl, 'wfs')
        : [...geoserviceEncodedProxyUrls(upstreamUrl, 'wfs'), upstreamUrl];
      try {
        const payload = await fetchJsonCandidateUrls(candidates, 25_000);
        if (payload && Array.isArray(payload.features)) return payload;
        throw new Error(`WFS ${version} não retornou um lote GeoJSON válido.`);
      } catch (error) {
        lastError = error;
      }
    }

    throw lastError || new Error('A fonte oficial não respondeu ao índice municipal. Tente novamente em alguns instantes.');
  }

  function currentPropertyLocalMunicipality(stateCode = '') {
    const state = normalizedCatalogState(stateCode || propertySearchStateCode());
    const selected = propertyContextSearchState?.municipality || selectedCitySearchContext?.city || null;
    if (!selected) return null;
    const selectedState = normalizedCatalogState(selected.uf || state);
    if (selectedState !== state) return null;
    const id = String(selected.id || '').replace(/\D/g, '');
    const name = String(selected.name || '').trim();
    return (id || name) ? { ...selected, id, name, uf: state } : null;
  }

  async function resolvePropertyMunicipalityBbox(municipality, stateCode = 'BA') {
    const uf = normalizedCatalogState(stateCode || municipality?.uf || 'BA');
    const city = { ...(municipality || {}), uf };
    const cached = await geocodeCity(city).catch(() => null);
    const cachedBox = Array.isArray(cached?.bbox) ? cached.bbox.map(Number) : [];
    if (cachedBox.length === 4 && cachedBox.every(Number.isFinite)) return cachedBox;

    const query = encodeURIComponent(`${city.name || ''}, ${uf}, Brasil`);
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=1&countrycodes=br&q=${query}`;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 9000);
    try {
      const response = await fetch(url, { headers: { Accept: 'application/json' }, cache: 'no-store', signal: controller.signal });
      if (!response.ok) throw new Error(`Nominatim HTTP ${response.status}`);
      const payload = await response.json();
      const item = Array.isArray(payload) ? payload[0] : null;
      const raw = Array.isArray(item?.boundingbox) ? item.boundingbox.map(Number) : [];
      if (raw.length === 4 && raw.every(Number.isFinite)) return [raw[2], raw[0], raw[3], raw[1]];
    } catch (error) {
      console.debug('[Surveyor] Limite municipal externo indisponível:', error?.message || error);
    } finally {
      clearTimeout(timeout);
    }

    const lat = Number(cached?.lat ?? city.lat);
    const lng = Number(cached?.lng ?? city.lng);
    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      // Último recurso operacional: envelope municipal conservador em torno do
      // centro conhecido. Mantém o download restrito regionalmente sem voltar
      // ao índice estadual. A pesquisa continua sem persistir geometrias.
      const latSpan = 0.36;
      const lngSpan = 0.38;
      return [lng - lngSpan, lat - latSpan, lng + lngSpan, lat + latSpan];
    }
    return null;
  }

  async function installPropertyLocalData(stateCode, municipality, { update = false } = {}) {
    const cache = window.SurveyorPropertyLocalCache;
    const uf = normalizedCatalogState(stateCode);
    const city = municipality || currentPropertyLocalMunicipality(uf);
    if (!city) {
      toast('Escolha uma cidade para baixar o índice de imóveis.', 'info');
      return false;
    }
    if (!cache?.available?.()) {
      toast('Este navegador não oferece o armazenamento local necessário para a Pesquisa rápida.', 'error');
      return false;
    }
    const scope = cache.scopeKey?.(uf, city) || `${uf}|${city.id || city.name}`;
    if (propertyLocalInstallJobs.has(scope)) return propertyLocalInstallJobs.get(scope);
    try { await navigator.storage?.persist?.(); } catch {}
    const job = (async () => {
      propertyLocalInstallProgress.set(scope, { progress: 0, stage: 'preparing' });
      updatePropertyMunicipalityScopeUi(scope, 'installing', 0);
      toast(`${update ? 'Atualizando' : 'Baixando'} índice de ${city.name} - ${uf}…`, 'info');
      let succeeded = false;
      try {
        const manifest = await cache.installMunicipality({
          stateCode: uf,
          municipality: city,
          pageSize: 400,
          fetchPage: (page) => fetchPropertyLocalDataPage(uf, { ...page, municipality: city }),
          onProgress: ({ count, total, progress, sizeBytes, municipality: progressCity, stage = 'downloading' }) => {
            const progressValue = stage === 'complete' ? 100 : Math.max(0, Math.min(99, Math.round(Number(progress) || 0)));
            const detail = { stateCode: uf, municipality: progressCity || city, scopeKey: scope, count, total, progress: progressValue, sizeBytes, stage };
            propertyLocalInstallProgress.set(scope, detail);
            updatePropertyMunicipalityScopeUi(scope, stage === 'complete' ? 'installed' : 'installing', progressValue);
            window.dispatchEvent(new CustomEvent('surveyor:property-local-data-progress', { detail }));
          }
        });
        succeeded = true;
        propertyLocalInstallProgress.set(scope, { progress: 100, stage: 'complete' });
        updatePropertyMunicipalityScopeUi(scope, 'installed', 100);
        toast(`Índice rápido instalado: ${Number(manifest.count).toLocaleString('pt-BR')} imóveis de ${manifest.municipalityName} - ${uf}.`, 'success');
        return true;
      } catch (error) {
        console.error('[Surveyor] Índice municipal:', error);
        propertyLocalInstallProgress.delete(scope);
        updatePropertyMunicipalityScopeUi(scope, 'available', 0);
        toast(error?.message || 'Não foi possível baixar o índice municipal de imóveis.', 'error');
        return false;
      } finally {
        propertyLocalInstallJobs.delete(scope);
        if (succeeded) setTimeout(() => propertyLocalInstallProgress.delete(scope), 1200);
        queueMicrotask(() => refreshPropertyMunicipalityScopeUi(uf, city).catch(() => {}));
        refresh();
      }
    })();
    propertyLocalInstallJobs.set(scope, job);
    return job;
  }

  async function uninstallPropertyLocalData(stateCode, municipality) {
    const cache = window.SurveyorPropertyLocalCache;
    const uf = normalizedCatalogState(stateCode);
    const city = municipality || currentPropertyLocalMunicipality(uf);
    if (!city) {
      toast('Selecione o município cujo índice deseja remover.', 'info');
      return false;
    }
    const accepted = typeof window.SurveyorConfirm === 'function'
      ? await window.SurveyorConfirm(`Remover do navegador o índice de pesquisa de ${city.name} - ${uf}? A camada online continuará disponível.`, { title: 'Desinstalar Pesquisa rápida', confirmText: 'Desinstalar' })
      : window.confirm(`Remover os dados locais de ${city.name} - ${uf}?`);
    if (!accepted) return false;
    try {
      await cache?.removeMunicipality?.(uf, city);
      toast(`Índice local de ${city.name} - ${uf} removido.`, 'success');
      refresh();
      return true;
    } catch (error) {
      console.error('[Surveyor] Remoção de dados locais:', error);
      toast('Não foi possível remover os dados locais.', 'error');
      return false;
    }
  }

  function closePropertyLocalMunicipalityPicker() {
    document.getElementById('propertyLocalMunicipalityPicker')?.remove();
  }

  async function pickPropertyLocalMunicipality(stateCode, anchorButton = null) {
    const uf = normalizedCatalogState(stateCode || propertySearchStateCode());
    await ensureCityCache().catch(() => {});
    closePropertyLocalMunicipalityPicker();
    return new Promise((resolve) => {
      const picker = document.createElement('section');
      picker.id = 'propertyLocalMunicipalityPicker';
      picker.className = 'property-local-municipality-picker';
      picker.innerHTML = `
        <header>
          <div><b>Escolha a cidade</b></div>
          <button type="button" class="property-local-municipality-close" aria-label="Fechar">×</button>
        </header>
        <label>Município
          <input class="property-local-municipality-input" type="search" autocomplete="off" placeholder="Digite o nome da cidade">
        </label>
        <div class="property-local-municipality-list" role="listbox"></div>`;
      document.body.appendChild(picker);
      const input = picker.querySelector('.property-local-municipality-input');
      const list = picker.querySelector('.property-local-municipality-list');
      const cache = window.SurveyorPropertyLocalCache;
      let installedScopes = new Set();
      let settled = false;
      const finish = (city = null) => {
        if (settled) return;
        settled = true;
        picker.remove();
        resolve(city);
      };
      const position = () => {
        const rect = anchorButton?.getBoundingClientRect?.();
        const width = Math.min(360, Math.max(300, window.innerWidth - 24));
        const left = rect
          ? Math.min(window.innerWidth - width - 12, Math.max(12, rect.right + 10))
          : 16;
        const top = rect
          ? Math.min(window.innerHeight - 360, Math.max(76, rect.top - 20))
          : 96;
        picker.style.width = `${width}px`;
        picker.style.left = `${left}px`;
        picker.style.top = `${top}px`;
      };
      const render = () => {
        const query = String(input?.value || '').trim();
        const items = getPropertyMunicipalitySuggestions(query, uf).slice(0, 30);
        list.innerHTML = '';
        if (!items.length) {
          const empty = document.createElement('div');
          empty.className = 'property-local-municipality-empty';
          empty.textContent = query.length < 2 ? 'Digite pelo menos 2 letras para procurar a cidade.' : 'Nenhum município encontrado.';
          list.appendChild(empty);
          return;
        }
        items.forEach((city) => {
          const normalizedCity = { ...city, uf };
          const scope = propertyMunicipalityScopeKey(uf, normalizedCity);
          const progressDetail = propertyLocalInstallProgress.get(scope) || {};
          const completed = progressDetail.stage === 'complete';
          const installing = propertyLocalInstallJobs.has(scope) && !completed;
          const installed = installedScopes.has(scope) || completed;
          const row = document.createElement('div');
          row.className = `property-local-municipality-option${installed ? ' is-installed' : ''}${installing ? ' is-installing' : ''}`;
          row.setAttribute('role', 'option');
          row.dataset.propertyMunicipalityScope = scope;
          const selectButton = document.createElement('button');
          selectButton.type = 'button';
          selectButton.className = 'property-local-municipality-select';
          selectButton.innerHTML = `<span class="property-local-municipality-copy"><strong>${escapeHtmlLocal(normalizedCity.name)}</strong><small>${escapeHtmlLocal(normalizedCity.uf || uf)}</small></span>`;
          selectButton.addEventListener('mousedown', (event) => event.preventDefault());
          selectButton.addEventListener('click', () => {
            propertyContextSearchState.municipality = normalizedCity;
            input.value = normalizedCity.name;
            list.querySelectorAll('.property-local-municipality-option').forEach((item) => item.classList.toggle('is-selected', item === row));
          });
          const downloadButton = document.createElement('button');
          downloadButton.type = 'button';
          downloadButton.className = 'property-municipality-download-action';
          downloadButton.dataset.propertyDownloadAction = '1';
          downloadButton.dataset.propertyMunicipalityScope = scope;
          downloadButton.innerHTML = propertyMunicipalityStatusMarkup(installing ? 'installing' : (installed ? 'installed' : 'available'), installing ? propertyMunicipalityProgressForScope(scope) : 0);
          downloadButton.disabled = installed;
          downloadButton.addEventListener('mousedown', (event) => { event.preventDefault(); event.stopPropagation(); });
          downloadButton.addEventListener('click', async (event) => {
            event.preventDefault();
            event.stopPropagation();
            propertyContextSearchState.municipality = normalizedCity;
            const ok = await requestPropertyMunicipalityDownload(uf, normalizedCity, { selectContext: true });
            if (ok) installedScopes.add(scope);
            if (!settled && picker.isConnected) render();
          });
          row.append(selectButton, downloadButton);
          list.appendChild(row);
        });
      };
      input?.addEventListener('input', render);
      input?.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
          const first = getPropertyMunicipalitySuggestions(input.value, uf)[0];
          if (first) finish({ ...first, uf });
        }
        if (event.key === 'Escape') finish(null);
      });
      picker.querySelector('.property-local-municipality-close')?.addEventListener('click', () => finish(null));
      const outside = (event) => {
        if (settled || picker.contains(event.target) || anchorButton?.contains?.(event.target)) return;
        document.removeEventListener('pointerdown', outside, true);
        finish(null);
      };
      document.addEventListener('pointerdown', outside, true);
      const progressHandler = (event) => {
        const detail = event?.detail || {};
        if (normalizedCatalogState(detail.stateCode || '') !== uf || settled || !picker.isConnected) return;
        const scope = String(detail.scopeKey || '');
        if (detail.stage === 'complete' && scope) installedScopes.add(scope);
        if (scope && list.querySelector(`[data-property-municipality-scope="${CSS.escape(scope)}"]`)) render();
      };
      window.addEventListener('surveyor:property-local-data-progress', progressHandler);
      const cleanup = () => {
        document.removeEventListener('pointerdown', outside, true);
        window.removeEventListener('surveyor:property-local-data-progress', progressHandler);
      };
      const observer = new MutationObserver(() => {
        if (!picker.isConnected) { cleanup(); observer.disconnect(); }
      });
      observer.observe(document.body, { childList: true, subtree: true });
      position();
      render();
      cache?.listStateManifests?.(uf).then((manifests) => {
        if (settled || !picker.isConnected) return;
        installedScopes = new Set((manifests || []).map((item) => String(item?.scopeKey || '')));
        render();
      }).catch(() => {});
      setTimeout(() => input?.focus(), 0);
    });
  }

  function bindPropertyLocalDataCard(card, catalogLayer, actions, detailsButton, nextButton = null) {
    const cache = window.SurveyorPropertyLocalCache;
    if (!cache?.available?.() || !officialPropertyBoundaryMatch(catalogLayer)) {
      if (nextButton) actions.append(detailsButton, nextButton);
      else actions.append(detailsButton);
      return;
    }
    const uf = sicarStateCodeForLayer(catalogLayer);
    const localButton = document.createElement('button');
    localButton.type = 'button';
    localButton.className = 'property-local-data-btn';
    localButton.innerHTML = `${propertyMunicipalityStatusMarkup('available')}<span>Baixar</span>`;
    localButton.title = 'Instalar índice leve somente do município selecionado';
    const uninstallButton = document.createElement('button');
    uninstallButton.type = 'button';
    uninstallButton.className = 'property-local-data-uninstall';
    uninstallButton.textContent = 'Desinstalar';
    uninstallButton.hidden = true;
    uninstallButton.onclick = async () => {
      const city = currentPropertyLocalMunicipality(uf);
      await uninstallPropertyLocalData(uf, city);
    };
    localButton.onclick = async () => {
      // O download possui sua própria seleção de cidade. Não depende do texto
      // que estiver na busca do mapa nem de uma cidade selecionada anteriormente.
      const city = await pickPropertyLocalMunicipality(uf, localButton);
      if (!city) return;
      propertyContextSearchState.municipality = city;
      const manifest = await cache.getManifest(uf, city).catch(() => null);
      if (manifest?.generation) {
        toast(`Os dados de ${city.name} - ${uf} já estão baixados neste navegador.`, 'success');
        refresh();
        return;
      }
      await installPropertyLocalData(uf, city, { update: false });
    };
    actions.append(detailsButton, localButton);
    if (nextButton) actions.append(nextButton);
    actions.append(uninstallButton);

    const status = document.createElement('div');
    status.className = 'property-local-data-status';
    status.innerHTML = '<span>Índice rápido · por município · sem geometria</span><small></small>';
    card.append(status);

    const updateUi = async () => {
      const city = currentPropertyLocalMunicipality(uf);
      if (!city) {
        localButton.disabled = false;
        localButton.classList.remove('is-installed','is-installing');
        localButton.innerHTML = `${propertyMunicipalityStatusMarkup('available')}<span>Baixar</span>`;
        uninstallButton.hidden = true;
        status.classList.remove('is-installed', 'is-installing');
        status.querySelector('small').textContent = '';
        return;
      }
      const scope = cache.scopeKey?.(uf, city) || `${uf}|${city.id || city.name}`;
      const installing = propertyLocalInstallJobs.has(scope);
      if (installing) {
        localButton.disabled = true;
        localButton.classList.add('is-installing');
        localButton.classList.remove('is-installed');
        localButton.innerHTML = `${propertyMunicipalityStatusMarkup('installing')}<span>Baixando…</span>`;
        uninstallButton.hidden = true;
        status.classList.add('is-installing');
        status.querySelector('small').textContent = `${city.name} - ${uf} • baixando somente dados de pesquisa…`;
        return;
      }
      const manifest = await cache.getManifest(uf, city).catch(() => null);
      if (!card.isConnected) return;
      status.classList.toggle('is-installed', Boolean(manifest?.generation));
      status.classList.remove('is-installing');
      localButton.classList.toggle('is-installed', Boolean(manifest?.generation));
      localButton.classList.remove('is-installing');
      localButton.disabled = Boolean(manifest?.generation);
      localButton.innerHTML = manifest?.generation
        ? `${propertyMunicipalityStatusMarkup('installed')}<span>Baixado</span>`
        : `${propertyMunicipalityStatusMarkup('available')}<span>Baixar</span>`;
      localButton.title = manifest?.generation ? `Dados de ${city.name} já baixados` : `Baixar índice de ${city.name}`;
      uninstallButton.hidden = !manifest?.generation;
      if (manifest?.generation) {
        const date = manifest.installedAt ? new Date(manifest.installedAt).toLocaleDateString('pt-BR') : '—';
        status.querySelector('small').textContent = `${manifest.municipalityName || city.name} - ${uf} • ${Number(manifest.count || 0).toLocaleString('pt-BR')} imóveis • ${formatPropertyLocalBytes(manifest.sizeBytes || 0)} • ${date}`;
      } else {
        status.querySelector('small').textContent = `${city.name} - ${uf}`;
      }
    };
    updateUi();
    const progressHandler = (event) => {
      const city = currentPropertyLocalMunicipality(uf);
      if (!city || String(event?.detail?.stateCode || '') !== uf || !card.isConnected) return;
      const expectedScope = cache.scopeKey?.(uf, city) || `${uf}|${city.id || city.name}`;
      if (event?.detail?.scopeKey && event.detail.scopeKey !== expectedScope) return;
      const detail = event.detail || {};
      localButton.disabled = true;
      localButton.classList.add('is-installing');
      localButton.classList.remove('is-installed');
      const progressValue = Math.max(0, Math.min(99, Number(detail.progress) || 0));
      localButton.innerHTML = `${propertyMunicipalityStatusMarkup('installing')}<span>${progressValue > 0 ? `${progressValue}%` : 'Baixando…'}</span>`;
      const total = Number(detail.total || 0);
      status.classList.add('is-installing');
      if (detail.stage === 'preparing') {
        status.querySelector('small').textContent = `${city.name} - ${uf} • preparando índice municipal…`;
      } else if (detail.stage === 'connecting') {
        status.querySelector('small').textContent = `${city.name} - ${uf} • conectando à fonte oficial…`;
      } else {
        status.querySelector('small').textContent = total > 0
          ? `${city.name} - ${uf} • ${Number(detail.count || 0).toLocaleString('pt-BR')} de ${total.toLocaleString('pt-BR')} imóveis • ${formatPropertyLocalBytes(detail.sizeBytes || 0)}`
          : `${city.name} - ${uf} • ${Number(detail.count || 0).toLocaleString('pt-BR')} imóveis recebidos • ${formatPropertyLocalBytes(detail.sizeBytes || 0)}`;
      }
    };
    window.addEventListener('surveyor:property-local-data-progress', progressHandler, { signal: (() => {
      const controller = new AbortController();
      const observer = new MutationObserver(() => { if (!card.isConnected) { controller.abort(); observer.disconnect(); } });
      observer.observe(document.body, { childList: true, subtree: true });
      return controller.signal;
    })() });
  }

  function refresh() {
    const migratedServitudes = migrateLegacyServitudePolygons();
    renderServitudeDerivedOverlays();
    if (migratedServitudes && selectedLayer && drawn.hasLayer(selectedLayer)) updateDetails(selectedLayer);
    const layers = drawn.getLayers();
    scheduleRecoverySnapshot();
    updateGlebaSourceOptions(true);
    const auth = window.GeoRuralAuth;
    const currentUser = auth?.currentUser?.();
    const allPrefs = auth?.getLayerPrefs?.() || {};
    const userPrefs = currentUser && Array.isArray(allPrefs[currentUser.id]) ? allPrefs[currentUser.id] : [];
    const catalogLayers = auth?.getLayers?.() || [];
    const enabledCatalogLayers = userPrefs.filter((pref) => pref.enabled).map((pref) => ({ ...catalogLayers.find((layer) => layer.id === pref.layerId), ...pref })).filter((layer) => layer.id);
    els.layerCount.textContent = String(layers.length + referenceCollections.length + enabledCatalogLayers.length);
    els.layerList.innerHTML = '';
    if (!layers.length && !referenceCollections.length && !enabledCatalogLayers.length) els.layerList.innerHTML = '<p class="empty">Nenhuma área desenhada.</p>';

    let area = 0, vertices = 0;

    referenceCollections.forEach((entry) => {
      const card = document.createElement('div');
      card.className = 'layer-card';
      const isRemoteService = Boolean(entry.service);
      const badge = isRemoteService ? String(entry.serviceType || 'WMS').toUpperCase() : (entry.localLarge ? 'LOCAL INDEXADA' : (entry.server ? 'BASE OFICIAL' : 'REFERÊNCIA'));
      card.innerHTML = `<div class="layer-head"><div class="layer-name"><span class="dot" style="background:#fde68a;border:1px solid #d97706"></span><b></b></div><span class="reference-layer-lock"></span></div><div class="layer-meta"></div><div class="layer-actions"></div>`;
      card.querySelector('b').textContent = entry.name;
      card.querySelector('.reference-layer-lock').textContent = badge;
      const count = entry.localLarge ? (entry.meta?.featureCount || 0) : (entry.server ? (entry.meta?.featureCount || 0) : (Array.isArray(entry.geojson?.features) ? entry.geojson.features.length : 1));
      const shown = entry.lastReturned ?? ((entry.server || entry.localLarge) ? 0 : count);
      if (isRemoteService) {
        const statusText = entry.serviceStatus === 'ready'
          ? 'WMS remoto • visível no mapa • não editável'
          : entry.serviceStatus === 'connecting'
            ? 'WMS remoto • conectando ao servidor oficial...'
            : 'WMS remoto • servidor temporariamente indisponível • camada permanece ativa';
        card.querySelector('.layer-meta').textContent = statusText;
      } else {
        card.querySelector('.layer-meta').textContent = entry.localLarge
          ? `Camada local indexada • ${Number(count).toLocaleString('pt-BR')} elemento(s) • ${Number(shown || 0).toLocaleString('pt-BR')} visível(is)`
          : entry.server
            ? `Base oficial • ${Number(count).toLocaleString('pt-BR')} imóvel(is) indexado(s) • ${shown} visível(is)`
            : `Camada de referência • ${count} elemento(s) • não editável`;
      }
      const actions = card.querySelector('.layer-actions');
      const view = document.createElement('button');
      view.textContent = entry.server || isRemoteService ? 'Atualizar' : 'Ver';
      view.onclick = () => {
        if (entry.localLarge) {
          const b = entry.meta?.bounds;
          if (Array.isArray(b) && b.length === 4 && b.every((v) => Number.isFinite(Number(v)))) {
            map.fitBounds([[Number(b[1]), Number(b[0])], [Number(b[3]), Number(b[2])]], { padding: [24, 24], maxZoom: 14 });
            setTimeout(() => updateLocalLargeReferences(true), 250);
          } else updateLocalLargeReferences(true);
        }
        else if (entry.server) updateServerReferences(true);
        else if (isRemoteService) {
          entry.serviceStatus = 'connecting';
          entry.layer.redraw?.();
          map.invalidateSize(false);
          refresh();
          setTimeout(() => {
            if (entry.serviceStatus === 'connecting') {
              entry.serviceStatus = 'waiting';
              refresh();
            }
          }, 32000);
        } else { const bounds = entry.layer.getBounds?.(); if (bounds && bounds.isValid()) map.fitBounds(bounds.pad(0.08)); }
      };
      const visible = referenceGroup.hasLayer(entry.layer);
      const toggle = document.createElement('button');
      toggle.textContent = visible ? 'Ocultar' : 'Mostrar';
      toggle.onclick = () => {
        if (referenceGroup.hasLayer(entry.layer)) referenceGroup.removeLayer(entry.layer);
        else referenceGroup.addLayer(entry.layer);
        if (!visible && entry.service) {
          entry.serviceStatus = 'connecting';
          requestAnimationFrame(() => entry.layer.redraw?.());
          setTimeout(() => {
            if (entry.serviceStatus === 'connecting') {
              entry.serviceStatus = 'waiting';
              refresh();
            }
          }, 32000);
        }
        refresh();
        if (!visible && entry.localLarge) updateLocalLargeReferences(true);
        if (!visible && entry.server) updateServerReferences(true);
      };
      const refControls = createLayerStyleControls({
        color: entry.color || entry.meta?.color || '#d97706',
        opacity: Number.isFinite(Number(entry.fillOpacity)) ? Number(entry.fillOpacity) : 0.22,
        showColor: !isRemoteService,
        disabled: false,
        onColor: (value) => { entry.color = value; entry.fillColor = value; applyStyleToReference(entry); },
        onOpacity: (value) => { entry.fillOpacity = value; entry.opacity = Math.max(0.2, value); applyStyleToReference(entry); }
      });
      actions.append(view, toggle);
      card.append(refControls);
      els.layerList.append(card);
    });

    enabledCatalogLayers.forEach((catalogLayer) => {
      const loadState = catalogLayerStates.get(catalogLayer.id);
      const card = document.createElement('div');
      card.className = `layer-card catalog-layer-card${loadState?.loading ? ' loading' : ''}${loadState?.phase === 'error' ? ' load-error' : ''}`;
      const progressPercent = Math.max(0, Math.min(100, Math.round(loadState?.percent || 0)));
      const fallbackActive = loadState?.sourceMode === 'arcgis-fallback';
      const catalogSourceMode = catalogLayerStates.get(catalogLayer.id)?.sourceMode || catalogMapLayers.get(catalogLayer.id)?.sourceMode || '';
      const isPropertyBoundary = officialPropertyBoundaryMatch(catalogLayer);
      const propertyStateCode = isPropertyBoundary ? sicarStateCodeForLayer(catalogLayer) : '';
      if (isPropertyBoundary) card.dataset.propertyState = propertyStateCode;
      const catalogBadge = isPropertyBoundary
        ? (propertyStateCode === 'BA' ? 'CEFIR/INEMA' : 'CAR/SICAR')
        : (fallbackActive ? 'BACKUP' : (catalogSourceMode === 'wfs-visible-fallback' || catalogSourceMode === 'sicar-wfs-visible' || catalogSourceMode === 'geobahia-property-wfs' || catalogLayer.__georuralResolvedService === 'wfs' ? 'WFS' : (resolvedLayerServiceType(catalogLayer) === 'wms' ? 'WMS' : 'CATÁLOGO')));
      card.innerHTML = `<div class="layer-head"><div class="layer-name"><b></b></div><div class="layer-head-tools"><button type="button" class="layer-visibility-toggle" aria-label="Ocultar a camada do mapa"></button><span class="reference-layer-lock">${catalogBadge}</span></div></div><div class="layer-meta"></div>${loadState?.loading ? `<div class="catalog-load-progress" role="progressbar" aria-label="Carregamento da camada" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progressPercent}"><span style="width:${progressPercent}%"></span></div>` : ''}<div class="layer-actions"></div>`;
      card.querySelector('b').textContent = catalogLayer.name;
      const mapVisible = isCatalogLayerVisibleOnMap(catalogLayer.id);
      const visibilityButton = card.querySelector('.layer-visibility-toggle');
      updateCatalogVisibilityButton(visibilityButton, mapVisible);
      if (loadState?.loading) {
        visibilityButton.disabled = true;
        visibilityButton.title = 'Aguarde o carregamento da camada para mostrar ou ocultar no mapa';
        visibilityButton.setAttribute('aria-label', visibilityButton.title);
      } else {
        visibilityButton.onclick = async () => {
          visibilityButton.disabled = true;
          const visibleNow = await toggleCatalogLayerVisibility(catalogLayer.id);
          updateCatalogVisibilityButton(visibilityButton, visibleNow);
          visibilityButton.disabled = false;
          // Mantém a animação do olho perceptível antes de reconstruir o card.
          window.setTimeout(() => refresh(), 230);
        };
      }
      const isCatalogWms = resolvedLayerServiceType(catalogLayer) === 'wms';
      const wfsActive = catalogSourceMode === 'wfs-visible-fallback' || catalogSourceMode === 'sicar-wfs-visible' || catalogSourceMode === 'geobahia-property-wfs';
      const catalogSource = catalogLayer.source || catalogLayer.sourceName || 'GeoRural';
      card.querySelector('.layer-meta').textContent = loadState?.loading
        ? `${loadState.message || 'Carregando camada...'} ${Math.round(loadState.percent || 0)}%`
        : loadState?.phase === 'error'
          ? `${catalogSource} • ${loadState.message || 'falha ao carregar'}`
          : loadState?.phase === 'ready'
            ? (isPropertyBoundary
              ? (mapVisible ? (loadState.message || 'CAR/SICAR • limites oficiais da UF visíveis') : 'CAR/SICAR • limites ocultos no mapa')
              : fallbackActive
                ? (mapVisible ? (loadState.message || 'Fonte alternativa CAR Bahia ativa') : 'Fonte alternativa CAR Bahia pronta • oculta no mapa')
                : wfsActive
                  ? `${catalogSource} • ${mapVisible ? (loadState.message || 'WFS visível na área atual') : 'WFS oculto no mapa'}`
                  : `${catalogSource} • ${isCatalogWms ? (mapVisible ? 'WMS visível no mapa' : 'WMS oculto no mapa') : (mapVisible ? 'visível no mapa' : 'oculto no mapa')}`)
            : loadState?.phase === 'waiting-zoom'
              ? `${catalogSource} • ${loadState.message || `aproxime o mapa até o zoom ${loadState.minZoom || effectiveCatalogMinZoom(catalogLayer)}`}`
            : loadState?.phase === 'waiting'
              ? `${catalogSource} • ${loadState.message || 'WMS ativo; aguardando resposta do servidor'}`
            : catalogLayer.status === 'ready'
              ? `${catalogSource} • ${isCatalogWms ? 'serviço oficial disponível' : 'base compartilhada selecionada'}`
              : `${catalogSource} • aguardando publicação`;
      const actions = card.querySelector('.layer-actions');
      if (isPropertyBoundary && lastSelectedRuralPropertyName && lastSelectedRuralPropertyState === propertyStateCode) {
        const selectedName = document.createElement('div');
        selectedName.className = 'property-selected-name';
        selectedName.innerHTML = `<span>Nome do imóvel</span><strong>${escapeHtmlLocal(lastSelectedRuralPropertyName)}</strong>`;
        card.insertBefore(selectedName, actions);
      }
      const detailsButton = document.createElement('button');
      detailsButton.textContent = 'Detalhes';
      detailsButton.onclick = () => {
        openLayerCatalogDialog();
        selectedCatalogLayerId = catalogLayer.id;
        renderMapLayerCatalog();
        renderCatalogPreview(catalogLayer);
      };
      if (isPropertyBoundary || loadState?.phase === 'error' || loadState?.phase === 'waiting' || fallbackActive) {
        const retryButton = document.createElement('button');
        retryButton.textContent = isPropertyBoundary ? 'Atualizar agora' : (fallbackActive ? 'Tentar fonte principal' : (loadState?.phase === 'waiting' ? 'Atualizar WMS' : 'Tentar novamente'));
        retryButton.className = 'retry-layer';
        retryButton.onclick = async () => {
          const existing = catalogMapLayers.get(catalogLayer.id);
          if (isPropertyBoundary) {
            const previous = catalogLayerStates.get(catalogLayer.id) || {};
            catalogLayerStates.set(catalogLayer.id, {
              ...previous, loading: true, phase: 'tiles', percent: 20,
              message: `Atualizando CAR/SICAR — ${catalogLayer.metadata?.stateName || catalogLayer.metadata?.stateCode || 'UF selecionada'}...`
            });
            existing?.leafletLayer?.redraw?.();
            window.setTimeout(() => {
              const state = catalogLayerStates.get(catalogLayer.id) || {};
              catalogLayerStates.set(catalogLayer.id, { ...state, loading: false, phase: 'ready', percent: 100, message: 'CAR/SICAR • WMS oficial atualizado.' });
              refresh();
            }, 650);
            refresh();
            return;
          }
          if (fallbackActive && existing?.leafletLayer) {
            existing.abortController?.abort();
            existing.leafletLayer.__georuralCleanup?.();
            if (map.hasLayer(existing.leafletLayer)) map.removeLayer(existing.leafletLayer);
            catalogMapLayers.delete(catalogLayer.id);
            catalogLayerStates.delete(catalogLayer.id);
            hideReferenceStatus();
            refresh();
            await syncCatalogLayers();
            return;
          }
          if (existing?.leafletLayer && loadState?.phase === 'waiting') {
            catalogLayerStates.set(catalogLayer.id, { loading: true, phase: 'tiles', percent: 8, message: 'Solicitando novamente os blocos WMS...' });
            existing.leafletLayer.redraw?.();
            refresh();
            existing.leafletLayer.once('tileload', () => {
              catalogLayerStates.set(catalogLayer.id, { loading: false, phase: 'ready', percent: 100, message: 'WMS visível no mapa.' });
              refresh();
            });
            setTimeout(() => {
              const state = catalogLayerStates.get(catalogLayer.id);
              if (state?.loading) {
                catalogLayerStates.set(catalogLayer.id, { loading: false, phase: 'waiting', percent: 92, message: 'WMS ativo; aguardando o servidor oficial.' });
                refresh();
              }
            }, 32000);
            return;
          }
          catalogLayerStates.delete(catalogLayer.id);
          hideReferenceStatus();
          refresh();
          await syncCatalogLayers();
        };
        bindPropertyLocalDataCard(card, catalogLayer, actions, detailsButton, retryButton);
      } else {
        bindPropertyLocalDataCard(card, catalogLayer, actions, detailsButton);
      }
      const removeButton = document.createElement('button');
      removeButton.type = 'button';
      removeButton.className = 'remove-catalog-layer';
      removeButton.textContent = 'Remover';
      removeButton.title = 'Remover esta camada do mapa e da lista do projeto';
      removeButton.onclick = async () => {
        removeButton.disabled = true;
        removeButton.textContent = 'Removendo...';
        const removed = await removeCatalogLayerFromProject(catalogLayer.id, catalogLayer.name);
        if (!removed && removeButton.isConnected) {
          removeButton.disabled = false;
          removeButton.textContent = 'Remover';
        }
      };
      actions.append(removeButton);
      const liveCatalogPref = catalogPreference(catalogLayer.id);
      // Camadas oficiais vindas do catálogo preservam simbologia/espessura da
      // fonte. O usuário controla apenas a transparência. Cor/espessura ficam
      // disponíveis somente para desenhos e arquivos importados pelo usuário.
      const catalogControls = createLayerStyleControls({
        showColor: false,
        showWeight: false,
        opacity: liveCatalogPref?.opacity ?? catalogLayer.style?.fillOpacity ?? 0.92,
        onOpacity: (value) => {
          const opacityPatch = isPropertyBoundary
            ? { opacity: value, styleMode: 'official', userStyled: false, propertyStyleRevision: GEOBAHIA_BOUNDARY_STYLE_REVISION }
            : { opacity: value };
          setStagedCatalogPreference(catalogLayer.id, opacityPatch, { render: false });
          persistLiveCatalogPreference(catalogLayer.id, opacityPatch);
          const existing = catalogMapLayers.get(catalogLayer.id);
          if (existing?.leafletLayer?.__georuralPropertyBoundary) {
            if (existing.leafletLayer.setBoundaryStyle) existing.leafletLayer.setBoundaryStyle({ opacity: value, styleMode: 'official' });
            else existing.leafletLayer.setOpacity?.(value);
          } else {
            existing?.leafletLayer?.setStyle?.(catalogVectorStyle(catalogLayer, { ...catalogPreference(catalogLayer.id), opacity: value }));
            existing?.leafletLayer?.setOpacity?.(value);
          }
        }
      });
      card.append(catalogControls);
      els.layerList.append(card);
    });

    layers.forEach((layer) => {
      const p = metadata(layer), m = metrics(layer), c = categories[p.category];
      area += m.areaM2;
      vertices += m.vertices;
      const card = document.createElement('div');
      card.className = `layer-card${layer === selectedLayer ? ' selected' : ''}`;
      card.innerHTML = `<div class="layer-card-tabs" role="tablist"><button type="button" class="active" data-layer-card-tab="description">Descrição</button><button type="button" data-layer-card-tab="edit">Editar</button></div><div class="layer-card-panel active" data-layer-card-panel="description"><div class="layer-head"><div class="layer-name"><span class="dot" style="background:${p.styleColor || p.color || c.color}"></span><b></b></div></div><div class="layer-meta"></div><div class="layer-actions layer-description-actions"></div></div><div class="layer-card-panel" data-layer-card-panel="edit" hidden><div class="layer-actions layer-edit-actions"></div><div class="layer-style-host"></div></div>`;
      card.querySelector('b').textContent = p.name;
      card.querySelector('.layer-meta').textContent = m.areaM2 ? `${c.label} • ${n(m.areaHa, 4)} ha` : m.perimeterM ? `${c.label} • ${n(m.perimeterM)} m` : c.label;
      const descriptionActions = card.querySelector('.layer-description-actions');
      const editActions = card.querySelector('.layer-edit-actions');
      const tabs = Array.from(card.querySelectorAll('[data-layer-card-tab]'));
      tabs.forEach((tab) => tab.addEventListener('click', () => {
        const target = tab.dataset.layerCardTab;
        tabs.forEach((item) => item.classList.toggle('active', item === tab));
        card.querySelectorAll('[data-layer-card-panel]').forEach((panel) => {
          const active = panel.dataset.layerCardPanel === target;
          panel.hidden = !active;
          panel.classList.toggle('active', active);
        });
      }));
      const view = document.createElement('button'); view.textContent = 'Ver'; view.onclick = () => select(layer, { focus: true });
      descriptionActions.append(view);
      if (p.category === 'perimetro' && layer.toGeoJSON().geometry.type === 'Polygon') {
        const confrontation = document.createElement('button');
        confrontation.textContent = 'Confrontantes';
        confrontation.disabled = isLayerLocked(layer);
        confrontation.title = isLayerLocked(layer) ? 'Elemento trancado' : '';
        confrontation.onclick = () => {
          if (!requireUnlockedLayer(layer, 'editar confrontantes')) return;
          select(layer);
          toast('Clique em um vértice numerado ou em um trecho no painel lateral.', 'success');
        };
        descriptionActions.append(confrontation);
      }
      const locked = isLayerLocked(layer);
      const edit = document.createElement('button');
      edit.textContent = 'Editar geometria';
      edit.title = locked ? 'Elemento trancado' : 'Editar vértices ou arrastar uma aresta inteira deste elemento';
      edit.disabled = locked;
      edit.onclick = () => {
        if (!requireUnlockedLayer(layer, 'editar a geometria')) return;
        select(layer);
        beginDirectEditMode(els.topEditElementsBtn || edit);
      };
      const toggle = document.createElement('button'); toggle.textContent = map.hasLayer(layer) ? 'Ocultar' : 'Mostrar';
      toggle.disabled = locked;
      toggle.title = locked ? 'Elemento trancado' : '';
      toggle.onclick = () => {
        if (!requireUnlockedLayer(layer, 'alterar a visibilidade')) return;
        const currentlyVisible = map.hasLayer(layer);
        setDrawnLayerVisibility(layer, !currentlyVisible);
        refresh();
      };
      editActions.append(edit, toggle);
      if (/Polygon/.test(layer.toGeoJSON().geometry.type || '')) {
        const divide = document.createElement('button');
        divide.textContent = 'Dividir';
        divide.disabled = locked;
        divide.title = locked ? 'Elemento trancado' : '';
        divide.onclick = () => {
          if (!requireUnlockedLayer(layer, 'dividir o polígono')) return;
          select(layer);
          openGlebasFromMap(layer);
        };
        editActions.append(divide);
      }
      const lockButton = document.createElement('button');
      lockButton.type = 'button';
      lockButton.className = `layer-lock-toggle${locked ? ' is-locked' : ''}`;
      lockButton.setAttribute('aria-pressed', locked ? 'true' : 'false');
      lockButton.setAttribute('aria-label', locked ? 'Destrancar elemento' : 'Trancar elemento');
      lockButton.title = locked ? 'Destrancar elemento' : 'Trancar elemento';
      lockButton.innerHTML = locked
        ? '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"></rect><path d="M8 10V7a4 4 0 0 1 8 0v3"></path></svg>'
        : '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"></rect><path d="M8 10V7a4 4 0 0 1 7-2"></path></svg>';
      lockButton.onclick = () => {
        const nextLocked = !isLayerLocked(layer);
        setLayerLocked(layer, nextLocked);
        toast(nextLocked ? 'Elemento trancado. Nenhuma edição será permitida até destrancar.' : 'Elemento destrancado. Edição liberada.', 'success');
      };
      editActions.append(lockButton);
      const geometryType = layer.toGeoJSON().geometry.type || '';
      const polygonLike = /Polygon/.test(geometryType) || layer instanceof L.Circle || layer instanceof L.Rectangle;
      const drawnControls = createLayerStyleControls({
        color: p.styleColor || p.strokeColor || p.color || c.color,
        fillColor: p.fillColor || p.fillStyleColor || p.styleColor || p.color || c.color,
        opacity: Number.isFinite(Number(p.styleOpacity)) ? Number(p.styleOpacity) : c.opacity,
        weight: normalizeDrawWeight(p, p.category === 'perimetro' ? 1.4 : 1.2),
        showFillColor: polygonLike,
        showWeight: true,
        disabled: locked,
        onColor: (value) => { if (!requireUnlockedLayer(layer, 'alterar a cor')) return; p.styleColor = value; p.strokeColor = value; p.color = value; applyStyleToDrawn(layer); card.querySelector('.dot')?.style.setProperty('background', value); scheduleRecoverySnapshot(); },
        onFillColor: (value) => { if (!requireUnlockedLayer(layer, 'alterar a cor interna')) return; p.fillColor = value; p.fillStyleColor = value; applyStyleToDrawn(layer); scheduleRecoverySnapshot(); },
        onOpacity: (value) => { if (!requireUnlockedLayer(layer, 'alterar a transparência')) return; p.styleOpacity = value; p.fillOpacity = value; applyStyleToDrawn(layer); scheduleRecoverySnapshot(); },
        onWeight: (value) => { if (!requireUnlockedLayer(layer, 'alterar a espessura')) return; p.weight = value; applyStyleToDrawn(layer); scheduleRecoverySnapshot(); }
      });
      card.querySelector('.layer-style-host')?.append(drawnControls);
      els.layerList.append(card);
    });

    els.totalArea.textContent = `${n(area / 10000, 4)} ha`;
    els.selectedPerimeter.textContent = `${n(selectedLayer ? metrics(selectedLayer).perimeterM : 0)} m`;
    els.totalElements.textContent = String(layers.length);
    els.totalVertices.textContent = String(vertices);
    if (selectedLayer && selectedLayer.toGeoJSON().geometry.type === 'Polygon' && metadata(selectedLayer).category === 'perimetro') {
      const list = normalizeConfrontantes(selectedLayer);
      els.confrontantesCount.textContent = `${list.filter(isConfrontanteFilled).length}/${list.length}`;
    }
    renderConfrontanteGuides();
  }

  function setBaseMap(key) {
    const selectedKey = persistBaseMapKey(key);
    Object.values(baseLayers).forEach((layer) => {
      if (map.hasLayer(layer)) map.removeLayer(layer);
    });
    const layer = baseLayers[selectedKey] || osm;
    layer.addTo(map);
    if (selectedKey !== 'topographicReal' && typeof layer.bringToBack === 'function') layer.bringToBack();
    toggleTopographicLegend(selectedKey === 'topographicReal');
    if (els.baseMapSelect && els.baseMapSelect.value !== selectedKey) els.baseMapSelect.value = selectedKey;
  }
  document.querySelectorAll('[data-base]').forEach((btn) => {
    btn.onclick = () => setBaseMap(btn.dataset.base || 'osm');
  });
  els.baseMapSelect?.addEventListener('change', () => setBaseMap(els.baseMapSelect.value));

  setupDetailCardTabs();

  function setupDetailCardTabs() {
    const tabs = Array.from(document.querySelectorAll('[data-detail-tab]'));
    const panels = Array.from(document.querySelectorAll('[data-detail-panel]'));
    if (!tabs.length || !panels.length) return;
    const activate = (target) => {
      tabs.forEach((tab) => {
        const active = tab.dataset.detailTab === target;
        tab.classList.toggle('active', active);
        tab.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      panels.forEach((panel) => {
        const active = panel.dataset.detailPanel === target;
        panel.hidden = !active;
        panel.classList.toggle('active', active);
      });
    };
    tabs.forEach((tab) => {
      tab.setAttribute('role', 'tab');
      tab.setAttribute('aria-selected', tab.classList.contains('active') ? 'true' : 'false');
      tab.addEventListener('click', () => activate(tab.dataset.detailTab || 'description'));
    });
    panels.forEach((panel) => panel.setAttribute('role', 'tabpanel'));
    activate(tabs.find((tab) => tab.classList.contains('active'))?.dataset.detailTab || 'description');
  }

  function coordinateFormatById(id = selectedCoordinateInputMode) {
    return SMART_COORDINATE_FORMATS.find((item) => item.id === id) || SMART_COORDINATE_FORMATS[0];
  }

  function currentSearchPlaceholder() {
    if (activeSearchMode === 'coordinate') return coordinateFormatById()?.placeholder || SEARCH_MODES.coordinate.placeholder;
    return SEARCH_MODES[activeSearchMode]?.placeholder || SEARCH_MODES.city.placeholder;
  }

  function closeExplicitSearchModeMenus() {
    document.getElementById('svSearchModeMenu')?.classList.add('hidden');
    document.getElementById('svCoordinateSubtypeMenu')?.classList.add('hidden');
  }

  function updateExplicitSearchModeLayout() {
    const input = els.coordSearch;
    const wrap = input?.closest('.geo-search-input-wrap');
    const badge = wrap?.querySelector('#svSmartSearchMode');
    const subtype = wrap?.querySelector('#svCoordinateSubtypeMode');
    if (!wrap || !badge) return;
    const config = SEARCH_MODES[activeSearchMode] || SEARCH_MODES.city;
    badge.dataset.mode = activeSearchMode;
    badge.textContent = config.label;
    badge.hidden = false;
    badge.setAttribute('aria-label', `Tipo de pesquisa: ${config.label}. Clique para trocar.`);
    badge.setAttribute('aria-expanded', document.getElementById('svSearchModeMenu')?.classList.contains('hidden') === false ? 'true' : 'false');
    const coordinate = activeSearchMode === 'coordinate';
    if (subtype) {
      const format = coordinateFormatById();
      subtype.hidden = !coordinate;
      subtype.textContent = format?.short || 'DD';
      subtype.title = format?.label || 'Formato da coordenada';
      subtype.setAttribute('aria-label', `Formato de coordenadas: ${format?.label || 'Graus decimais'}. Clique para trocar.`);
    }
    wrap.classList.add('has-smart-mode');
    wrap.classList.toggle('has-coordinate-submode', coordinate);
    if (input) {
      input.placeholder = currentSearchPlaceholder();
      input.inputMode = coordinate && selectedCoordinateInputMode !== 'epsg' ? 'decimal' : 'text';
    }
    requestAnimationFrame(() => {
      const mainWidth = Math.ceil(badge.getBoundingClientRect().width || 64);
      let total = mainWidth + 16;
      if (coordinate && subtype && !subtype.hidden) {
        subtype.style.left = `${10 + mainWidth + 5}px`;
        total += Math.ceil(subtype.getBoundingClientRect().width || 44) + 5;
      }
      wrap.style.setProperty('--sv-smart-mode-offset', `${Math.max(74, total)}px`);
    });
  }

  function resetSearchContextsForModeChange() {
    selectedCitySearchContext = null;
    localitySearchSerial += 1;
    clearTimeout(citySuggestTimer);
    clearTimeout(smartSearchFormatTimer);
    clearTimeout(carAutoSearchTimer);
    lastAutoCarValue = '';
    propertyContextSearchState.requestId += 1;
    propertyContextSearchState.query = '';
    propertyContextSearchState.municipality = null;
    propertyContextSearchState.results = [];
    propertyContextSearchState.selectedIndex = -1;
    hideCitySuggestions();
  }

  function selectExplicitSearchMode(mode, options = {}) {
    const normalized = mode === 'locality' ? 'city' : mode;
    if (!SEARCH_MODES[normalized]) return;
    const changed = activeSearchMode !== normalized;
    activeSearchMode = normalized;
    try { localStorage.setItem(SEARCH_MODE_STORAGE_KEY, activeSearchMode); } catch {}
    if (changed) {
      resetSearchContextsForModeChange();
      if (options.clearInput !== false && els.coordSearch) els.coordSearch.value = '';
    }
    updateExplicitSearchModeLayout();
    closeExplicitSearchModeMenus();
    if (activeSearchMode === 'coordinate' && options.openCoordinateFormats !== false) {
      setTimeout(() => toggleCoordinateSubtypeMenu(true), 0);
    }
    if (options.focus !== false) els.coordSearch?.focus();
  }

  function buildSearchModeMenu(wrap) {
    let menu = wrap.querySelector('#svSearchModeMenu');
    if (menu) return menu;
    menu = document.createElement('div');
    menu.id = 'svSearchModeMenu';
    menu.className = 'sv-search-mode-menu hidden';
    menu.setAttribute('role', 'menu');
    [
      ['property', 'IMÓVEL', 'Pesquisa somente por nome do imóvel'],
      ['city', 'CIDADE', 'Pesquisa somente por município/localidade'],
      ['car', 'CAR', 'Pesquisa somente por código CAR'],
      ['coordinate', 'COORDENADAS', 'Pesquisa somente por coordenadas']
    ].forEach(([mode, label, description]) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.dataset.searchMode = mode;
      button.setAttribute('role', 'menuitem');
      button.innerHTML = `<strong>${label}</strong><small>${description}</small>`;
      button.addEventListener('mousedown', (event) => event.preventDefault());
      button.addEventListener('click', () => selectExplicitSearchMode(mode, { clearInput: true, focus: true, openCoordinateFormats: mode === 'coordinate' }));
      menu.appendChild(button);
    });
    wrap.appendChild(menu);
    return menu;
  }

  function buildCoordinateSubtypeMenu(wrap) {
    let menu = wrap.querySelector('#svCoordinateSubtypeMenu');
    if (menu) return menu;
    menu = document.createElement('div');
    menu.id = 'svCoordinateSubtypeMenu';
    menu.className = 'sv-coordinate-subtype-menu hidden';
    menu.setAttribute('role', 'menu');
    SMART_COORDINATE_FORMATS.forEach((format) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.dataset.coordinateFormat = format.id;
      button.setAttribute('role', 'menuitem');
      button.innerHTML = `<span>${format.short}</span><strong>${format.label}</strong>`;
      button.addEventListener('mousedown', (event) => event.preventDefault());
      button.addEventListener('click', () => {
        selectedCoordinateInputMode = format.id;
        try { localStorage.setItem(COORDINATE_MODE_STORAGE_KEY, format.id); } catch {}
        updateExplicitSearchModeLayout();
        menu.classList.add('hidden');
        applySelectedCoordinateFormatting({ force: true });
        hideCitySuggestions();
        els.coordSearch?.focus();
      });
      menu.appendChild(button);
    });
    wrap.appendChild(menu);
    return menu;
  }

  function toggleSearchModeMenu(forceOpen = null) {
    const wrap = els.coordSearch?.closest('.geo-search-input-wrap');
    const menu = wrap && buildSearchModeMenu(wrap);
    if (!menu) return;
    const open = forceOpen == null ? menu.classList.contains('hidden') : Boolean(forceOpen);
    closeExplicitSearchModeMenus();
    menu.classList.toggle('hidden', !open);
    menu.querySelectorAll('[data-search-mode]').forEach((button) => button.classList.toggle('active', button.dataset.searchMode === activeSearchMode));
    updateExplicitSearchModeLayout();
  }

  function toggleCoordinateSubtypeMenu(forceOpen = null) {
    if (activeSearchMode !== 'coordinate') return;
    const wrap = els.coordSearch?.closest('.geo-search-input-wrap');
    const menu = wrap && buildCoordinateSubtypeMenu(wrap);
    if (!menu) return;
    const open = forceOpen == null ? menu.classList.contains('hidden') : Boolean(forceOpen);
    closeExplicitSearchModeMenus();
    menu.classList.toggle('hidden', !open);
    menu.querySelectorAll('[data-coordinate-format]').forEach((button) => button.classList.toggle('active', button.dataset.coordinateFormat === selectedCoordinateInputMode));
    updateExplicitSearchModeLayout();
  }

  function ensureSmartSearchModeBadge() {
    const input = els.coordSearch;
    const wrap = input?.closest('.geo-search-input-wrap');
    if (!wrap) return null;
    let badge = wrap.querySelector('#svSmartSearchMode');
    if (!badge) {
      badge = document.createElement('button');
      badge.id = 'svSmartSearchMode';
      badge.type = 'button';
      badge.setAttribute('aria-haspopup', 'menu');
      wrap.prepend(badge);
      badge.addEventListener('mousedown', (event) => event.preventDefault());
      badge.addEventListener('click', () => toggleSearchModeMenu());
    }
    let subtype = wrap.querySelector('#svCoordinateSubtypeMode');
    if (!subtype) {
      subtype = document.createElement('button');
      subtype.id = 'svCoordinateSubtypeMode';
      subtype.type = 'button';
      subtype.setAttribute('aria-haspopup', 'menu');
      subtype.addEventListener('mousedown', (event) => event.preventDefault());
      subtype.addEventListener('click', () => toggleCoordinateSubtypeMenu());
      wrap.appendChild(subtype);
    }
    buildSearchModeMenu(wrap);
    buildCoordinateSubtypeMenu(wrap);
    updateExplicitSearchModeLayout();
    return badge;
  }

  // Compatibilidade interna: as rotinas de resultado podem solicitar atualização
  // visual, mas não voltam a "adivinhar" o tipo da pesquisa. O tipo é definido
  // exclusivamente pelo seletor escolhido pelo usuário.
  function setSmartSearchModeBadge(mode = '', _label = '') {
    const normalized = mode === 'locality' ? 'city' : mode;
    if (SEARCH_MODES[normalized] && normalized === activeSearchMode) updateExplicitSearchModeLayout();
  }

  function resetSmartSearchMode({ restorePlaceholder = true } = {}) {
    clearTimeout(smartSearchFormatTimer);
    clearTimeout(carAutoSearchTimer);
    lastAutoCarValue = '';
    closeExplicitSearchModeMenus();
    if (restorePlaceholder && els.coordSearch) els.coordSearch.placeholder = currentSearchPlaceholder();
    updateExplicitSearchModeLayout();
  }

  function applySelectedCoordinateFormatting({ force = false } = {}) {
    if (!selectedCoordinateInputMode || !els.coordSearch) return false;
    const raw = String(els.coordSearch.value || '');
    if (!raw.trim()) return false;
    const formatted = formatCoordinateDraftProgressive(raw, selectedCoordinateInputMode);
    if (!formatted) return false;
    // A máscara acompanha a digitação. Separadores digitados pelo usuário
    // encerram cada componente e são convertidos para a notação escolhida.
    // Valores completos colados no campo também são normalizados de uma vez.
    if (force || formatted !== raw) {
      els.coordSearch.value = formatted;
      try { els.coordSearch.setSelectionRange(formatted.length, formatted.length); } catch {}
    }
    return formatted !== raw;
  }

  function parseCoordinateForSelectedMode(value) {
    const raw = String(value || '').trim();
    if (!raw) return null;
    const mode = selectedCoordinateInputMode || 'dd';
    if (mode === 'epsg') return parseEpsgCoordinate(raw);
    if (mode === 'utm') return parseUtmCoordinate(raw);
    if (mode === 'dms' || mode === 'ddm') return parseDmsCoordinate(raw);
    // DD é deliberadamente estrito: apenas dois números decimais. Isso impede
    // que texto, CAR ou nomes de imóveis atravessem o parser de coordenadas.
    if (/[A-Za-zÀ-ÿ]/.test(raw)) return null;
    const parts = raw.match(/[+-]?\d+(?:[.,]\d+)?/g) || [];
    if (parts.length < 2) return null;
    let lat = Number(parts[0].replace(',', '.'));
    let lng = Number(parts[1].replace(',', '.'));
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    const normalInBrazil = lat >= -35 && lat <= 7 && lng >= -75 && lng <= -30;
    const swappedInBrazil = lng >= -35 && lng <= 7 && lat >= -75 && lat <= -30;
    if (!normalInBrazil && swappedInBrazil) [lat, lng] = [lng, lat];
    if (Math.abs(lat) > 90 || Math.abs(lng) > 180) return null;
    return { lat, lng, format: 'Graus decimais' };
  }

  function canUseOfficialPropertySearch() {
    return Boolean(window.GeoRuralAuth?.hasPermission?.('car:access') && window.GeoRuralAuth?.hasPermission?.('layers:official'));
  }

  function officialPropertySearchLocked() {
    toast('Busca de imóveis, CAR/SICAR e bases fundiárias está disponível nos planos Plus e Pro.', 'info');
    return false;
  }

  function renderCarSmartSuggestion(value) {
    selectedCitySearchContext = null;
    localitySearchSerial += 1;
    if (!canUseOfficialPropertySearch()) return officialPropertySearchLocked();
    if (!els.citySuggestBox) return;
    citySuggestItems = [];
    citySuggestIndex = -1;
    const carStateCode = carStateCodeFromDraft(value);
    const selectedStateCode = propertySearchStateCode();
    setSmartSearchModeBadge('car', carStateCode ? `CAR · ${carStateCode}` : 'CAR');
    els.coordSearch.placeholder = `Número do CAR — ex.: ${selectedStateCode}-0000000-...`;
    els.citySuggestBox.innerHTML = '';
    const panel = document.createElement('div');
    panel.className = 'sv-smart-search-panel sv-smart-search-car';
    const head = document.createElement('div');
    head.className = 'sv-smart-search-head';
    const strong = document.createElement('strong');
    const small = document.createElement('small');
    if (carStateCode && carStateCode !== selectedStateCode) {
      strong.textContent = `CAR de ${carStateCode} detectado`;
      small.textContent = `O catálogo está configurado para ${selectedStateCode}. Troque o estado das camadas para ${carStateCode} antes de pesquisar este CAR.`;
    } else {
      strong.textContent = `CAR de ${carStateCode || selectedStateCode} detectado`;
      small.textContent = isCompleteCarDraft(value)
        ? 'Código completo. A consulta será executada automaticamente na camada SICAR da UF selecionada.'
        : 'Continue digitando ou cole o número completo do CAR.';
    }
    head.append(strong, small);
    panel.appendChild(head);
    els.citySuggestBox.appendChild(panel);
    showSearchSuggestionBox();

    clearTimeout(carAutoSearchTimer);
    if (isCompleteCarDraft(value) && carStateCode === selectedStateCode) {
      const normalized = normalizeCarDraft(value);
      if (normalized !== lastAutoCarValue) {
        carAutoSearchTimer = setTimeout(async () => {
          if (!isCompleteCarDraft(els.coordSearch?.value || '')) return;
          const current = normalizeCarDraft(els.coordSearch.value);
          if (current === lastAutoCarValue) return;
          if (current.slice(0, 2) !== propertySearchStateCode()) return;
          lastAutoCarValue = current;
          hideCitySuggestions();
          const searchCar = window.SurveyorMapWorkspace?.searchCar;
          if (typeof searchCar === 'function') await searchCar(current);
        }, 420);
      }
    } else {
      lastAutoCarValue = '';
    }
  }

  const CITY_CACHE_KEY = 'surveyor_city_cache_v1_0';
  const CITY_CACHE_LEGACY_KEYS = ['surveyor_city_cache_v21_9_92', 'surveyor:municipios-br:v2'];
  const CITY_CENTER_CACHE_KEY = 'surveyor_city_center_cache_v1_0';
  const CITY_CACHE_MAX_AGE = 1000 * 60 * 60 * 24 * 90;
  const CITY_FALLBACK = [
    { id: 'fallback-amargosa-ba', name: 'Amargosa', uf: 'BA', state: 'Bahia', lat: -13.0304, lng: -39.6046, zoom: 13 },
    { id: 'fallback-amargosa-do-piaui-pi', name: 'Amargosa do Piauí', uf: 'PI', state: 'Piauí' },
    { id: 'fallback-amargosa-pe', name: 'Amargosa', uf: 'PE', state: 'Pernambuco' },
    { id: 'fallback-santo-antonio-de-jesus-ba', name: 'Santo Antônio de Jesus', uf: 'BA', state: 'Bahia' },
    { id: 'fallback-mutuipe-ba', name: 'Mutuípe', uf: 'BA', state: 'Bahia' },
    { id: 'fallback-laje-ba', name: 'Laje', uf: 'BA', state: 'Bahia' },
    { id: 'fallback-elisiomedrado-ba', name: 'Elísio Medrado', uf: 'BA', state: 'Bahia' },
    { id: 'fallback-brejões-ba', name: 'Brejões', uf: 'BA', state: 'Bahia' },
    { id: 'fallback-milagres-ba', name: 'Milagres', uf: 'BA', state: 'Bahia' },
    { id: 'fallback-salvador-ba', name: 'Salvador', uf: 'BA', state: 'Bahia', lat: -12.9777, lng: -38.5016, zoom: 12 }
  ];
  let cityCache = CITY_FALLBACK.slice();
  let cityCacheHydrated = false;
  let cityCacheLoading = null;
  let citySuggestItems = [];
  let citySuggestIndex = -1;
  let citySuggestTimer = null;
  let selectedCitySearchContext = null;
  let localitySearchSerial = 0;

  // A busca municipal volta a ser autocontida no runtime principal.
  // São funções pequenas e críticas para o autocomplete; mantê-las aqui evita
  // depender da ordem de um módulo separado para abrir as sugestões.
  function normalizeCityQuery(value) {
    return String(value || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-zA-Z0-9\s-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  function cityLabel(city) {
    return `${city?.name || ''} - ${city?.uf || ''}${city?.state ? ` · ${city.state}` : ''}`;
  }

  function cityMatchesScore(city, q) {
    const query = normalizeCityQuery(q);
    const name = normalizeCityQuery(city?.name);
    const uf = normalizeCityQuery(city?.uf);
    const state = normalizeCityQuery(city?.state);
    const label = `${name} ${uf} ${state}`.trim();
    if (!query) return -1;
    if (name === query || `${name} ${uf}` === query) return 1000;
    if (name.startsWith(query)) return 900 - name.length;
    if (label.startsWith(query)) return 820 - label.length;
    if (name.includes(query)) return 700 - name.indexOf(query);
    if (label.includes(query)) return 600 - label.indexOf(query);
    const tokens = query.split(' ').filter(Boolean);
    if (tokens.length && tokens.every((token) => label.includes(token))) return 520 - label.length;
    return -1;
  }

  function readCityCenterCache() {
    try { return JSON.parse(localStorage.getItem(CITY_CENTER_CACHE_KEY) || '{}') || {}; }
    catch { return {}; }
  }

  function writeCityCenterCache(cache) {
    try { localStorage.setItem(CITY_CENTER_CACHE_KEY, JSON.stringify(cache || {})); }
    catch { /* cache opcional */ }
  }

  function normalizeCityCacheItems(items) {
    const normalized = (Array.isArray(items) ? items : []).map((city) => {
      const name = String(city?.name || city?.nome || '').trim();
      const uf = String(city?.uf || city?.stateCode || city?.sigla || '').trim().toUpperCase();
      return {
        id: String(city?.id || `${name}-${uf}`),
        name,
        uf,
        state: String(city?.state || city?.estado || '').trim(),
        lat: Number.isFinite(Number(city?.lat)) ? Number(city.lat) : undefined,
        lng: Number.isFinite(Number(city?.lng)) ? Number(city.lng) : undefined,
        zoom: Number.isFinite(Number(city?.zoom)) ? Number(city.zoom) : undefined
      };
    }).filter((city) => city.name && /^[A-Z]{2}$/.test(city.uf));
    const seen = new Set();
    return normalized.filter((city) => {
      const key = `${normalizeCityQuery(city.name)}|${city.uf}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function loadCityCacheFromStorage() {
    const keys = [CITY_CACHE_KEY, ...CITY_CACHE_LEGACY_KEYS];
    for (const key of keys) {
      try {
        const cached = JSON.parse(localStorage.getItem(key) || 'null');
        const normalized = normalizeCityCacheItems(cached?.items);
        if (cached?.savedAt && Date.now() - cached.savedAt < CITY_CACHE_MAX_AGE && normalized.length > 1000) {
          cityCache = normalized;
          cityCacheHydrated = true;
          // Migra silenciosamente o cache nacional que já existia nas versões
          // anteriores. Trocar a chave não pode apagar o autocomplete do usuário.
          if (key !== CITY_CACHE_KEY) {
            try { localStorage.setItem(CITY_CACHE_KEY, JSON.stringify({ savedAt: cached.savedAt, items: cityCache })); } catch {}
          }
          return true;
        }
      } catch { /* cache opcional */ }
    }
    return false;
  }

  async function ensureCityCache() {
    if (cityCacheHydrated && cityCache.length) return cityCache;
    if (loadCityCacheFromStorage()) return cityCache;
    if (cityCacheLoading) return cityCacheLoading;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6500);
    cityCacheLoading = fetch('https://servicodados.ibge.gov.br/api/v1/localidades/municipios?orderBy=nome', { cache: 'force-cache', signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error('IBGE indisponível');
        return res.json();
      })
      .then((items) => {
        const remote = normalizeCityCacheItems((items || []).map((item) => {
          const uf = item?.microrregiao?.mesorregiao?.UF
            || item?.['regiao-imediata']?.['regiao-intermediaria']?.UF
            || item?.regiaoImediata?.['regiao-intermediaria']?.UF
            || {};
          return {
            id: String(item.id || `${item.nome}-${uf.sigla || ''}`),
            name: String(item.nome || '').trim(),
            uf: String(uf.sigla || '').trim(),
            state: String(uf.nome || '').trim()
          };
        }));
        if (remote.length > 1000) {
          cityCache = remote;
          cityCacheHydrated = true;
          try { localStorage.setItem(CITY_CACHE_KEY, JSON.stringify({ savedAt: Date.now(), items: cityCache })); }
          catch { /* cache opcional */ }
        }
        return cityCache;
      })
      .catch((error) => {
        if (error?.name !== 'AbortError') console.debug('[Surveyor] Lista de municípios IBGE indisponível; usando fallback local.');
        return cityCache.length ? cityCache : CITY_FALLBACK.slice();
      })
      .finally(() => { clearTimeout(timeout); cityCacheLoading = null; });
    return cityCacheLoading;
  }


  function getCitySuggestions(query) {
    const q = normalizeCityQuery(query);
    if (q.length < 2 || parseCoordinate(query)) return [];
    const source = cityCache.length ? cityCache : CITY_FALLBACK;
    return source
      .map((city) => ({ city, score: cityMatchesScore(city, q) }))
      .filter((item) => item.score >= 0)
      .sort((a, b) => b.score - a.score || a.city.name.localeCompare(b.city.name, 'pt-BR'))
      .slice(0, 8)
      .map((item) => item.city);
  }

  function propertySearchStateCode() {
    try {
      return normalizedCatalogState(window.GeoRuralAuth?.getLayerCatalogState?.() || selectedCatalogState || 'BA');
    } catch {
      return 'BA';
    }
  }

  function getPropertyMunicipalitySuggestions(query, stateCode = propertySearchStateCode()) {
    const q = normalizeCityQuery(query);
    const uf = String(stateCode || 'BA').toUpperCase();
    const source = (cityCache.length ? cityCache : CITY_FALLBACK).filter((city) => String(city.uf || '').toUpperCase() === uf);
    if (!q) return source.slice(0, 8);
    return source
      .map((city) => ({ city, score: cityMatchesScore(city, q) }))
      .filter((item) => item.score >= 0)
      .sort((a, b) => b.score - a.score || a.city.name.localeCompare(b.city.name, 'pt-BR'))
      .slice(0, 8)
      .map((item) => item.city);
  }

  function propertyMunicipalityScopeKey(stateCode, city) {
    const cache = window.SurveyorPropertyLocalCache;
    return cache?.scopeKey?.(stateCode, city) || `${String(stateCode || '').toUpperCase()}|${String(city?.id || city?.name || '').trim()}`;
  }

  function propertyMunicipalityStatusMarkup(state = 'available', progress = 0) {
    if (state === 'installed') {
      return '<span class="property-municipality-status is-installed" title="Dados locais baixados" aria-label="Dados locais baixados"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="m8 12 2.6 2.6L16.5 9"></path></svg></span>';
    }
    if (state === 'installing') {
      const value = Math.max(0, Math.min(99, Math.round(Number(progress) || 0)));
      return `<span class="property-municipality-status is-installing" title="Download em andamento: ${value}%" aria-label="Download em andamento: ${value}%"><span class="property-municipality-progress" aria-hidden="true">${value}%</span></span>`;
    }
    return '<span class="property-municipality-status is-available" title="Baixar dados locais desta cidade" aria-label="Baixar dados locais desta cidade"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v10"></path><path d="m8 10 4 4 4-4"></path><path d="M5 19h14"></path></svg></span>';
  }

  function propertyMunicipalityProgressForScope(scope) {
    const detail = propertyLocalInstallProgress.get(String(scope || '')) || {};
    return Math.max(0, Math.min(99, Math.round(Number(detail.progress) || 0)));
  }

  function updatePropertyMunicipalityScopeUi(scope, state = 'available', progress = 0) {
    const key = String(scope || '');
    if (!key) return;
    const selector = `[data-property-municipality-scope="${CSS.escape(key)}"]`;
    document.querySelectorAll(selector).forEach((node) => {
      node.dataset.localState = state;
      node.classList.toggle('is-installed', state === 'installed');
      node.classList.toggle('is-installing', state === 'installing');
      const actionNodes = node.matches?.('[data-property-download-action]')
        ? [node]
        : Array.from(node.querySelectorAll?.('[data-property-download-action]') || []);
      actionNodes.forEach((action) => {
        action.innerHTML = propertyMunicipalityStatusMarkup(state, progress);
        action.disabled = state !== 'available';
        action.setAttribute('aria-label', state === 'installed'
          ? 'Dados desta cidade já baixados'
          : state === 'installing'
            ? `Baixando dados da cidade: ${Math.max(0, Math.min(99, Math.round(Number(progress) || 0)))}%`
            : 'Baixar dados desta cidade');
        action.title = state === 'installed'
          ? 'Baixado'
          : state === 'installing'
            ? `${Math.max(0, Math.min(99, Math.round(Number(progress) || 0)))}%`
            : 'Baixar';
      });
      const passiveHosts = Array.from(node.querySelectorAll?.('.property-municipality-status-host') || [])
        .filter((host) => !host.matches('[data-property-download-action]'));
      passiveHosts.forEach((host) => { host.innerHTML = propertyMunicipalityStatusMarkup(state, progress); });
    });
  }

  async function refreshPropertyMunicipalityScopeUi(stateCode, city) {
    const cache = window.SurveyorPropertyLocalCache;
    const uf = normalizedCatalogState(stateCode || city?.uf || propertySearchStateCode());
    const scope = propertyMunicipalityScopeKey(uf, city);
    if (propertyLocalInstallJobs.has(scope)) {
      updatePropertyMunicipalityScopeUi(scope, 'installing', propertyMunicipalityProgressForScope(scope));
      return 'installing';
    }
    const manifest = await cache?.getManifest?.(uf, city).catch?.(() => null);
    const state = manifest?.generation ? 'installed' : 'available';
    updatePropertyMunicipalityScopeUi(scope, state, state === 'installed' ? 100 : 0);
    return state;
  }

  async function requestPropertyMunicipalityDownload(stateCode, city, { selectContext = false } = {}) {
    const cache = window.SurveyorPropertyLocalCache;
    const uf = normalizedCatalogState(stateCode || city?.uf || propertySearchStateCode());
    if (!city || !cache?.available?.()) return false;
    const normalizedCity = { ...city, uf };
    const scope = propertyMunicipalityScopeKey(uf, normalizedCity);
    if (selectContext) propertyContextSearchState.municipality = normalizedCity;
    const existing = await cache.getManifest?.(uf, normalizedCity).catch?.(() => null);
    if (existing?.generation) {
      updatePropertyMunicipalityScopeUi(scope, 'installed', 100);
      toast(`Os dados de ${normalizedCity.name} - ${uf} já estão baixados neste navegador.`, 'success');
      return true;
    }
    if (propertyLocalInstallJobs.has(scope)) return propertyLocalInstallJobs.get(scope);
    propertyLocalInstallProgress.set(scope, { progress: 0, stage: 'preparing' });
    updatePropertyMunicipalityScopeUi(scope, 'installing', 0);
    const ok = await installPropertyLocalData(uf, normalizedCity, { update: false });
    await refreshPropertyMunicipalityScopeUi(uf, normalizedCity);
    return ok;
  }

  function bindPropertyMunicipalityDownloadAction(action, city, stateCode, options = {}) {
    if (!action || !city) return;
    const uf = normalizedCatalogState(stateCode || city.uf || propertySearchStateCode());
    action.dataset.propertyDownloadAction = '1';
    action.dataset.propertyMunicipalityScope = propertyMunicipalityScopeKey(uf, city);
    action.type = 'button';
    action.addEventListener('mousedown', (event) => { event.preventDefault(); event.stopPropagation(); });
    action.addEventListener('click', async (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (action.dataset.localState === 'installed') return;
      await requestPropertyMunicipalityDownload(uf, city, options);
    });
    refreshPropertyMunicipalityScopeUi(uf, city).catch(() => {});
  }

  async function decoratePropertyMunicipalityInstallStates(container, stateCode) {
    const cache = window.SurveyorPropertyLocalCache;
    if (!container || !cache?.available?.() || !cache?.listStateManifests) return;
    let manifests = [];
    try { manifests = await cache.listStateManifests(stateCode); } catch { return; }
    if (!container.isConnected) return;
    const installed = new Set((manifests || []).map((item) => String(item?.scopeKey || '')));
    container.querySelectorAll('[data-property-municipality-scope]').forEach((node) => {
      const scope = String(node.dataset.propertyMunicipalityScope || '');
      const progressDetail = propertyLocalInstallProgress.get(scope) || {};
      const completed = progressDetail.stage === 'complete';
      const installing = propertyLocalInstallJobs.has(scope) && !completed;
      const state = completed || installed.has(scope) ? 'installed' : (installing ? 'installing' : 'available');
      updatePropertyMunicipalityScopeUi(scope, state, installing ? propertyMunicipalityProgressForScope(scope) : (state === 'installed' ? 100 : 0));
    });
  }

  function renderPropertyMunicipalityChoices(container, input, query) {
    if (!container) return;
    container.innerHTML = '';
    const stateCode = propertySearchStateCode();
    const descriptor = catalogStateDescriptor(stateCode);
    const items = getPropertyMunicipalitySuggestions(query, stateCode);
    if (!items.length) {
      const empty = document.createElement('div');
      empty.className = 'property-context-empty';
      empty.textContent = `Nenhum município de ${descriptor.name} encontrado.`;
      container.appendChild(empty);
      return;
    }
    items.forEach((city) => {
      const scope = propertyMunicipalityScopeKey(stateCode, city);
      const row = document.createElement('div');
      row.className = 'property-context-city';
      row.dataset.propertyMunicipalityScope = scope;
      const selectButton = document.createElement('button');
      selectButton.type = 'button';
      selectButton.className = 'property-context-city-select';
      selectButton.innerHTML = `<span class="property-context-city-copy"><strong>${escapeHtmlLocal(city.name)}</strong><small>${escapeHtmlLocal(stateCode)} · ${escapeHtmlLocal(city.state || descriptor.name)}</small></span>`;
      selectButton.addEventListener('mousedown', (event) => event.preventDefault());
      selectButton.addEventListener('click', () => {
        propertyContextSearchState.requestId += 1;
        propertyContextSearchState.municipality = city;
        input.value = `${city.name} - ${stateCode}`;
        renderPropertyContextAssistant(propertyContextSearchState.query, { focusMunicipality: false });
      });
      const downloadButton = document.createElement('button');
      downloadButton.className = 'property-municipality-download-action';
      downloadButton.innerHTML = propertyMunicipalityStatusMarkup('available');
      bindPropertyMunicipalityDownloadAction(downloadButton, city, stateCode, { selectContext: false });
      row.append(selectButton, downloadButton);
      container.appendChild(row);
    });
    decoratePropertyMunicipalityInstallStates(container, stateCode).catch(() => {});
  }

  async function runPropertyContextSearch() {
    const query = sanitizePropertyNameSearch(propertyContextSearchState.query || els.coordSearch?.value || '');
    const municipality = propertyContextSearchState.municipality;
    const stateCode = propertySearchStateCode();
    const stateDescriptor = catalogStateDescriptor(stateCode);
    if (!municipality) {
      toast(`Informe o município de ${stateDescriptor.name} para pesquisar o imóvel.`, 'info');
      renderPropertyContextAssistant(query, { focusMunicipality: true });
      return;
    }
    if (query.length < 3) {
      toast('Digite pelo menos 3 caracteres do nome do imóvel.', 'info');
      return;
    }
    const requestId = ++propertyContextSearchState.requestId;
    const municipalityId = String(municipality.id || municipality.name || '');
    setSmartSearchModeBadge('property', `IMÓVEL · ${stateCode}`);
    setCitySuggestionsStatus(`Pesquisando “${query}” em ${municipality.name} - ${stateCode}…`);
    try {
      // R26.3.59: um único resolvedor escolhe a mesma fonte da camada
      // Limites de Propriedade: CEFIR/INEMA na Bahia e SICAR nas demais UFs.
      // O fallback nacional na Bahia só ocorre quando o CEFIR não retorna nada.
      const features = await fetchRuralPropertiesByName(query, municipality, stateCode);
      // Ignora respostas antigas quando o usuário trocou município/nome ou
      // iniciou outra busca antes da anterior terminar.
      if (requestId !== propertyContextSearchState.requestId) return;
      if (String(propertyContextSearchState.municipality?.id || propertyContextSearchState.municipality?.name || '') !== municipalityId) return;
      if (sanitizePropertyNameSearch(propertyContextSearchState.query) !== query) return;
      // O resolvedor online também pode retornar imóveis de toda a UF.
      // Confere os atributos ORIGINAIS antes da lista, sem bloquear a ação
      // Localizar nem adicionar validações na recuperação da geometria.
      const scopedFeatures = features.filter((feature) => propertyFeatureMatchesMunicipality(feature, municipality));
      propertyContextSearchState.results = scopedFeatures;
      propertyContextSearchState.selectedIndex = -1;
      renderPropertyContextResults(query, municipality, scopedFeatures, { stateCode });
    } catch (error) {
      if (requestId !== propertyContextSearchState.requestId) return;
      console.warn('[Surveyor] Busca contextual de imóvel:', error);
      renderPropertyContextResults(query, municipality, [], { error: true, stateCode });
    }
  }

  function updatePropertyContextResultActiveState({ scroll = false } = {}) {
    if (!els.citySuggestBox) return;
    const activeIndex = Number(propertyContextSearchState.selectedIndex);
    els.citySuggestBox.querySelectorAll('.property-context-result').forEach((item) => {
      const index = Number(item.dataset.resultIndex);
      const active = Number.isInteger(activeIndex) && activeIndex >= 0 && index === activeIndex;
      const pending = propertyContextSearchState.pendingIndex === index;
      const feature = propertyContextSearchState.results?.[index];
      const status = propertyGeometryStatusForFeature(feature, propertySearchStateCode());
      // R185.13: um único estado controla a fila real, não uma demonstração
      // estática. A seleção só é confirmada após o mapa desenhar o polígono.
      const visibleStatus = active ? 'selected' : pending ? 'pending' : status;
      item.classList.toggle('active', active);
      for (const state of ['selected','pending','ready','queued','loading','failed']) {
        item.classList.toggle(`is-${state}`, visibleStatus === state);
      }
      item.dataset.geometryStatus = visibleStatus;
      item.setAttribute('aria-current', active ? 'true' : 'false');
      const labels = { selected: 'Selecionado', pending: 'Abrindo…', ready: 'Pronto',
        queued: 'Na fila', loading: 'Na fila', failed: 'Tentar' };
      const action = item.querySelector('.property-context-result-action');
      if (action) action.textContent = labels[visibleStatus] || 'Localizar';
      if (active && scroll) item.scrollIntoView?.({ block: 'nearest', behavior: 'smooth' });
    });
    const counter = els.citySuggestBox.querySelector('[data-property-result-counter]');
    if (counter) {
      const total = Array.isArray(propertyContextSearchState.results) ? propertyContextSearchState.results.length : 0;
      counter.textContent = activeIndex >= 0 && total ? `${activeIndex + 1} de ${total}` : `${total} resultado${total === 1 ? '' : 's'}`;
    }
    const prev = els.citySuggestBox.querySelector('[data-property-result-prev]');
    const next = els.citySuggestBox.querySelector('[data-property-result-next]');
    const total = Array.isArray(propertyContextSearchState.results) ? propertyContextSearchState.results.length : 0;
    if (prev) prev.disabled = !(activeIndex > 0 && total > 0);
    if (next) next.disabled = !(activeIndex >= 0 && activeIndex < total - 1);
  }

  async function selectPropertyContextResult(index, { scroll = true } = {}) {
    const results = Array.isArray(propertyContextSearchState.results) ? propertyContextSearchState.results : [];
    if (!results.length) return false;
    const nextIndex = Math.max(0, Math.min(results.length - 1, Number(index) || 0));
    const feature = results[nextIndex];
    if (!feature) return false;
    // Não apresentar "Visualizando" antes de confirmar que um polígono
    // realmente foi recuperado e desenhado.
    const locateStartedAt = Date.now();
    // Evita que a conclusão tardia do primeiro clique sobrescreva a seleção
    // de outro imóvel, e mantém o vermelho apenas na seleção confirmada.
    const selectionSerial = (propertyContextSearchState.selectionSerial || 0) + 1;
    propertyContextSearchState.selectionSerial = selectionSerial;
    propertyContextSearchState.pendingIndex = nextIndex;
    updatePropertyContextResultActiveState();
    // O próximo imóvel entra na fila assim que o usuário escolhe este,
    // sem esperar os segundos da consulta WFS atual.
    advancePropertyGeometryWarmup(nextIndex);
    const ok = await focusRuralPropertySearchFeature(feature, {
      query: propertyContextSearchState.query,
      municipality: propertyContextSearchState.municipality,
      stateCode: propertySearchStateCode(),
      preserveSearchResults: true,
      resultIndex: nextIndex,
      isCurrentSelection: () => selectionSerial === propertyContextSearchState.selectionSerial
    });
    console.info('[Surveyor] Localizar: geometria e enquadramento', {
      elapsedMs: Date.now() - locateStartedAt, success: !!ok
    });
    if (selectionSerial !== propertyContextSearchState.selectionSerial) return !!ok;
    propertyContextSearchState.pendingIndex = -1;
    if (ok) {
      propertyContextSearchState.selectedIndex = nextIndex;
      showSearchSuggestionBox();
    }
    updatePropertyContextResultActiveState({ scroll: !!ok && scroll });
    return ok;
  }

  function renderPropertyContextResults(query, municipality, features, options = {}) {
    if (!els.citySuggestBox) return;
    citySuggestItems = [];
    citySuggestIndex = -1;
    els.citySuggestBox.innerHTML = '';
    els.citySuggestBox.classList.add('property-context-box');

    const stateCode = normalizedCatalogState(options.stateCode || municipality?.uf || propertySearchStateCode());
    // Ao mudar de pesquisa, descarta as próximas antecipações da lista anterior.
    propertyContextSearchState.pendingIndex = -1;
    propertyContextSearchState.selectionSerial = (propertyContextSearchState.selectionSerial || 0) + 1;
    resetPropertyGeometryWarmup([], stateCode);
    const panel = document.createElement('div');
    panel.className = 'property-context-results';
    const header = document.createElement('div');
    header.className = 'property-context-results-head';
    header.innerHTML = `<div><span>IMÓVEIS RURAIS</span><strong>${escapeHtmlLocal(municipality.name)} - ${escapeHtmlLocal(stateCode)}</strong></div>`;
    const change = document.createElement('button');
    change.type = 'button';
    change.className = 'property-context-change';
    change.textContent = 'Trocar município';
    change.addEventListener('mousedown', (event) => event.preventDefault());
    change.addEventListener('click', () => {
      propertyContextSearchState.requestId += 1;
      propertyContextSearchState.municipality = null;
      propertyContextSearchState.results = [];
      propertyContextSearchState.selectedIndex = -1;
      renderPropertyContextAssistant(query, { focusMunicipality: true });
    });
    header.appendChild(change);
    panel.appendChild(header);

    if (options.error) {
      const message = document.createElement('div');
      message.className = 'property-context-message is-error';
      const sourceLabel = stateCode === 'BA' ? 'CEFIR/INEMA' : 'SICAR';
      message.innerHTML = `<strong>Não foi possível consultar ${sourceLabel} agora.</strong><small>Tente novamente em alguns instantes.</small>`;
      panel.appendChild(message);
    } else if (!features.length) {
      const message = document.createElement('div');
      message.className = 'property-context-message';
      message.innerHTML = `<strong>Nenhum imóvel encontrado.</strong><small>Não localizamos “${escapeHtmlLocal(query)}” em ${escapeHtmlLocal(municipality.name)} - ${escapeHtmlLocal(stateCode)}. Tente parte do nome ou confira o município.</small>`;
      panel.appendChild(message);
    } else {
      const summaryRow = document.createElement('div');
      summaryRow.className = 'property-context-summary-row';
      const summary = document.createElement('div');
      summary.className = 'property-context-summary';
      summary.textContent = `${features.length} resultado${features.length === 1 ? '' : 's'} encontrado${features.length === 1 ? '' : 's'} para “${query}”.`;
      summaryRow.appendChild(summary);

      const nav = document.createElement('div');
      nav.className = 'property-context-nav';
      nav.innerHTML = `<button type="button" data-property-result-prev aria-label="Imóvel anterior" title="Imóvel anterior">‹</button><span data-property-result-counter>${features.length} resultado${features.length === 1 ? '' : 's'}</span><button type="button" data-property-result-next aria-label="Próximo imóvel" title="Próximo imóvel">›</button>`;
      summaryRow.appendChild(nav);
      panel.appendChild(summaryRow);

      const list = document.createElement('div');
      list.className = 'property-context-result-list';
      features.forEach((feature, index) => {
        const name = propertyNameFromFeature(feature) || `Imóvel ${index + 1}`;
        const car = propertyCarFromFeature(feature);
        const area = propertyAreaFromFeature(feature);
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'property-context-result';
        item.dataset.resultIndex = String(index);
        const meta = [
          car ? `CAR: ${car}` : '',
          Number.isFinite(area) ? `${area.toLocaleString('pt-BR', { maximumFractionDigits: 4 })} ha` : ''
        ].filter(Boolean).join(' · ');
        item.innerHTML = `<span class="property-context-result-index">${index + 1}</span><span class="property-context-result-info"><strong>${escapeHtmlLocal(name)}</strong><small>${escapeHtmlLocal(meta || `${municipality.name} - ${stateCode}`)}</small></span><b class="property-context-result-action">Localizar</b>`;
        item.addEventListener('mousedown', (event) => event.preventDefault());
        // Pré-carregamento conservador: depois de breve passagem do cursor
        // sobre o resultado. Máximo de quatro candidatos por pesquisa, nunca
        // uma varredura dos 1000 itens nem uma nova consulta duplicada no clique.
        let warmupTimer = null;
        const cancelWarmup = () => {
          if (warmupTimer !== null) clearTimeout(warmupTimer);
          warmupTimer = null;
        };
        item.addEventListener('pointerenter', () => {
          cancelWarmup();
          warmupTimer = setTimeout(() => {
            warmupTimer = null;
            if (propertyContextSearchState.results[index] !== feature) return;
            warmupPropertyGeometry(feature, stateCode, { priority: true });
          }, 75);
        });
        item.addEventListener('pointerleave', cancelWarmup);
        item.addEventListener('click', async () => {
          if (item.dataset.busy === '1') return;
          cancelWarmup();
          item.dataset.busy = '1';
          item.setAttribute('aria-busy', 'true');
          const action = item.querySelector('.property-context-result-action');
          if (action) action.textContent = 'Abrindo…';
          try {
            await selectPropertyContextResult(index, { scroll: false });
          } finally {
            item.dataset.busy = '';
            item.removeAttribute('aria-busy');
            updatePropertyContextResultActiveState({ scroll: false });
          }
        });
        list.appendChild(item);
      });
      panel.appendChild(list);
      // Inicia em segundo plano os três primeiros resultados (ou todos, se
      // houver menos). A seleção avança a janela sem consultar os mil itens.
      resetPropertyGeometryWarmup(features, stateCode);

      nav.querySelector('[data-property-result-prev]')?.addEventListener('click', () => {
        const current = Number(propertyContextSearchState.selectedIndex);
        if (current > 0) selectPropertyContextResult(current - 1, { scroll: true });
      });
      nav.querySelector('[data-property-result-next]')?.addEventListener('click', () => {
        const current = Number(propertyContextSearchState.selectedIndex);
        if (current < 0 && features.length) selectPropertyContextResult(0, { scroll: true });
        else if (current < features.length - 1) selectPropertyContextResult(current + 1, { scroll: true });
      });
    }
    els.citySuggestBox.appendChild(panel);
    showSearchSuggestionBox();
    updatePropertyContextResultActiveState();
  }

  function renderPropertyContextAssistant(value, options = {}) {
    if (!els.citySuggestBox) return false;
    const query = sanitizePropertyNameSearch(value);
    if (!options.force && !looksLikeRuralPropertyName(query)) return false;
    if (sanitizePropertyNameSearch(propertyContextSearchState.query) !== query) propertyContextSearchState.requestId += 1;
    propertyContextSearchState.query = query;
    propertyContextSearchState.results = [];
    propertyContextSearchState.selectedIndex = -1;
    citySuggestItems = [];
    citySuggestIndex = -1;
    setSmartSearchModeBadge('property', 'IMÓVEL');
    els.citySuggestBox.innerHTML = '';
    els.citySuggestBox.classList.add('property-context-box');

    const stateCode = propertySearchStateCode();
    const stateDescriptor = catalogStateDescriptor(stateCode);
    const propertySourceLabel = stateCode === 'BA'
      ? 'CEFIR / INEMA · Limites de Propriedade'
      : 'CAR / SICAR · Limites de Propriedade';
    const panel = document.createElement('div');
    panel.className = 'property-context-assistant';
    panel.innerHTML = `
      <div class="property-context-kicker">BUSCA DE IMÓVEL RURAL</div>
      <strong class="property-context-title">Onde fica este imóvel?</strong>
      <p>Para pesquisar “${escapeHtmlLocal(query)}” com precisão, informe o município.</p>
      <label class="property-context-field"><span>Estado</span><div class="property-context-readonly"><b>${escapeHtmlLocal(stateDescriptor.name)}</b><small>${escapeHtmlLocal(stateCode)} · ${escapeHtmlLocal(propertySourceLabel)}</small></div></label>
      <label class="property-context-field"><span>Município</span><input class="property-context-city-input" type="text" autocomplete="off" placeholder="Ex.: município"></label>
      <div class="property-context-city-list"></div>
      <button type="button" class="property-context-search-btn" ${propertyContextSearchState.municipality ? '' : 'disabled'}>🔎 Procurar</button>
    `;
    els.citySuggestBox.appendChild(panel);
    showSearchSuggestionBox();

    const cityInput = panel.querySelector('.property-context-city-input');
    const cityList = panel.querySelector('.property-context-city-list');
    const searchButton = panel.querySelector('.property-context-search-btn');
    if (propertyContextSearchState.municipality) {
      const selectedCity = propertyContextSearchState.municipality;
      cityInput.value = `${selectedCity.name} - ${stateCode}`;
      const selectedRow = document.createElement('div');
      selectedRow.className = 'property-context-selected-city';
      selectedRow.dataset.propertyMunicipalityScope = propertyMunicipalityScopeKey(stateCode, selectedCity);
      const downloadButton = document.createElement('button');
      downloadButton.className = 'property-municipality-download-action';
      downloadButton.innerHTML = propertyMunicipalityStatusMarkup('available');
      bindPropertyMunicipalityDownloadAction(downloadButton, selectedCity, stateCode, { selectContext: true });
      const selectedName = document.createElement('strong');
      selectedName.textContent = `${selectedCity.name} - ${stateCode}`;
      const changeButton = document.createElement('button');
      changeButton.type = 'button';
      changeButton.className = 'property-context-change-city';
      changeButton.textContent = 'Alterar';
      selectedRow.append(downloadButton, selectedName, changeButton);
      cityList.replaceChildren(selectedRow);
      decoratePropertyMunicipalityInstallStates(cityList, stateCode).catch(() => {});
      changeButton.addEventListener('click', () => {
        propertyContextSearchState.requestId += 1;
        propertyContextSearchState.municipality = null;
        cityInput.value = '';
        renderPropertyMunicipalityChoices(cityList, cityInput, '');
        cityInput.focus();
        searchButton.disabled = true;
      });
    } else {
      renderPropertyMunicipalityChoices(cityList, cityInput, '');
    }
    cityInput.addEventListener('mousedown', (event) => event.stopPropagation());
    cityInput.addEventListener('input', () => {
      propertyContextSearchState.requestId += 1;
      propertyContextSearchState.municipality = null;
      searchButton.disabled = true;
      const typed = cityInput.value;
      renderPropertyMunicipalityChoices(cityList, cityInput, typed);
      const normalizedTyped = normalizeCityQuery(typed);
      if (normalizedTyped.length >= 3) {
        const exact = getPropertyMunicipalitySuggestions(typed, stateCode).find((city) => normalizeCityQuery(city.name) === normalizedTyped);
        if (exact) {
          propertyContextSearchState.municipality = exact;
          cityInput.value = `${exact.name} - ${stateCode}`;
          renderPropertyContextAssistant(query, { focusMunicipality: false });
        }
      }
    });
    cityInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        const first = getPropertyMunicipalitySuggestions(cityInput.value, stateCode)[0];
        if (first) {
          propertyContextSearchState.requestId += 1;
          propertyContextSearchState.municipality = first;
          renderPropertyContextAssistant(query, { focusMunicipality: false });
        }
      }
    });
    searchButton.addEventListener('click', runPropertyContextSearch);
    if (options.focusMunicipality) setTimeout(() => cityInput.focus(), 0);
    return true;
  }

  function mountSearchSuggestionOverlay() {
    const box = els.citySuggestBox;
    const input = els.coordSearch;
    if (!box || !input) return;
    if (box.parentElement !== document.body) {
      document.body.appendChild(box);
      box.classList.add('sv-map-search-overlay');
    }
    const rect = input.getBoundingClientRect();
    const viewportPadding = 8;
    const isPropertyContext = box.classList.contains('property-context-box')
      || Boolean(box.querySelector('.property-context-assistant'))
      || Boolean(box.querySelector('.property-context-results'));

    box.style.position = 'fixed';
    box.style.zIndex = '25000';

    if (isPropertyContext) {
      // V36 — o assistente de busca de imóvel fica ancorado à pesquisa do topo,
      // no lado direito do mapa. Alinhamos pela borda direita do campo para ele
      // não reaparecer no painel lateral esquerdo em nenhuma combinação de CSS.
      const maxWidth = Math.min(400, Math.max(300, window.innerWidth - viewportPadding * 2));
      const left = Math.max(
        viewportPadding,
        Math.min(rect.right - maxWidth, window.innerWidth - maxWidth - viewportPadding)
      );
      const top = Math.max(70, Math.round(rect.bottom + 8));
      box.style.setProperty('left', `${Math.round(left)}px`, 'important');
      box.style.setProperty('right', 'auto', 'important');
      box.style.setProperty('top', `${top}px`, 'important');
      box.style.setProperty('width', `${Math.round(maxWidth)}px`, 'important');
      box.style.setProperty('max-width', `calc(100vw - ${viewportPadding * 2}px)`, 'important');
      return;
    }

    const maxWidth = Math.min(Math.max(rect.width, 320), Math.max(320, window.innerWidth - viewportPadding * 2));
    const left = Math.max(viewportPadding, Math.min(rect.left, window.innerWidth - maxWidth - viewportPadding));
    box.style.left = `${Math.round(left)}px`;
    box.style.right = 'auto';
    box.style.top = `${Math.round(rect.bottom + 6)}px`;
    box.style.width = `${Math.round(maxWidth)}px`;
    box.style.maxWidth = `calc(100vw - ${viewportPadding * 2}px)`;
  }

  function showSearchSuggestionBox() {
    if (!els.citySuggestBox) return;
    mountSearchSuggestionOverlay();
    els.citySuggestBox.classList.remove('hidden');
    els.citySuggestBox.style.display = 'grid';
    els.coordSearch?.setAttribute('aria-expanded', 'true');
  }

  function setCitySuggestionsStatus(message) {
    if (!els.citySuggestBox) return;
    els.citySuggestBox.innerHTML = '';
    const div = document.createElement('div');
    div.className = 'city-suggest-status';
    div.textContent = message;
    els.citySuggestBox.appendChild(div);
    showSearchSuggestionBox();
  }

  function hideCitySuggestions() {
    if (!els.citySuggestBox) return;
    if (els.citySuggestBox.classList.contains('property-context-box')) {
      // Limpa SOMENTE os itens ainda aguardando. Polígonos já confirmados
      // continuam no cache persistente, para localização imediata depois.
      resetPropertyGeometryWarmup([], propertySearchStateCode());
      propertyContextSearchState.pendingIndex = -1;
      propertyContextSearchState.selectionSerial = (propertyContextSearchState.selectionSerial || 0) + 1;
    }
    els.citySuggestBox.classList.add('hidden');
    els.citySuggestBox.classList.remove('property-context-box');
    els.citySuggestBox.innerHTML = '';
    els.citySuggestBox.style.display = 'none';
    els.coordSearch?.setAttribute('aria-expanded', 'false');
    citySuggestItems = [];
    citySuggestIndex = -1;
  }

  function renderCitySuggestions(items) {
    if (!els.citySuggestBox) return;
    els.citySuggestBox.classList.remove('property-context-box');
    citySuggestItems = (items || []).map((city) => ({ ...city, _searchKind: 'city' }));
    citySuggestIndex = -1;
    els.citySuggestBox.innerHTML = '';
    if (!citySuggestItems.length) {
      hideCitySuggestions();
      return;
    }
    citySuggestItems.forEach((city, index) => {
      const scope = propertyMunicipalityScopeKey(city.uf || propertySearchStateCode(), city);
      const row = document.createElement('div');
      row.className = 'city-suggest-row';
      row.dataset.propertyMunicipalityScope = scope;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'city-suggest-item';
      button.setAttribute('role', 'option');
      button.setAttribute('aria-selected', 'false');
      button.dataset.index = String(index);
      const name = document.createElement('strong');
      name.textContent = `${city.name} - ${city.uf}`;
      const state = document.createElement('small');
      state.textContent = city.state || 'Brasil';
      button.append(name, state);
      button.addEventListener('mousedown', (event) => event.preventDefault());
      button.addEventListener('click', () => selectSearchSuggestion(city));
      const downloadButton = document.createElement('button');
      downloadButton.className = 'property-municipality-download-action city-suggest-download-action';
      downloadButton.innerHTML = propertyMunicipalityStatusMarkup('available');
      bindPropertyMunicipalityDownloadAction(downloadButton, city, city.uf || propertySearchStateCode(), { selectContext: false });
      row.append(button, downloadButton);
      els.citySuggestBox.appendChild(row);
    });
    showSearchSuggestionBox();
  }

  function localityResultWithinCity(item, context) {
    const lat = Number(item?.lat), lng = Number(item?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || !context?.city) return false;
    const bbox = context?.center?.bbox;
    if (Array.isArray(bbox) && bbox.length === 4 && bbox.every(Number.isFinite)) {
      if (lng >= bbox[0] && lng <= bbox[2] && lat >= bbox[1] && lat <= bbox[3]) return true;
    }
    const address = item?.address || {};
    const targetCity = normalizeCityQuery(context.city.name);
    const addressCity = normalizeCityQuery([
      address.city, address.town, address.village, address.municipality, address.county, address.city_district
    ].filter(Boolean).join(' '));
    if (targetCity && addressCity.includes(targetCity)) return true;
    try {
      const distance = L.latLng(Number(context.center?.lat), Number(context.center?.lng)).distanceTo(L.latLng(lat, lng));
      const stateText = normalizeCityQuery(`${address.state || ''} ${address['ISO3166-2-lvl4'] || ''}`);
      const uf = normalizeCityQuery(context.city.uf);
      return Number.isFinite(distance) && distance <= 60000 && (!uf || stateText.includes(uf) || stateText.includes(normalizeCityQuery(context.city.state)));
    } catch {
      return false;
    }
  }

  async function fetchLocalitySuggestions(query) {
    const context = selectedCitySearchContext;
    const clean = String(query || '').replace(/\s+/g, ' ').trim();
    if (!context?.city || clean.length < 2) return [];
    const serial = ++localitySearchSerial;
    const q = encodeURIComponent(`${clean}, ${context.city.name}, ${context.city.uf}, Brasil`);
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=10&dedupe=1&countrycodes=br&q=${q}`;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 7000);
    try {
      const response = await fetch(url, { headers: { Accept: 'application/json' }, cache: 'no-store', signal: controller.signal });
      if (!response.ok) throw new Error(`Nominatim HTTP ${response.status}`);
      const payload = await response.json();
      if (serial !== localitySearchSerial || context !== selectedCitySearchContext) return [];
      return (Array.isArray(payload) ? payload : [])
        .filter((item) => localityResultWithinCity(item, context))
        .map((item) => {
          const address = item?.address || {};
          const name = String(item?.name || item?.display_name || clean).split(',')[0].trim();
          const kind = String(item?.type || item?.addresstype || '').replaceAll('_', ' ');
          const secondary = [
            kind && kind !== name.toLowerCase() ? kind : '',
            address.suburb || address.neighbourhood || address.village || address.hamlet || address.road || '',
            `${context.city.name} - ${context.city.uf}`
          ].filter(Boolean).join(' · ');
          return {
            _searchKind: 'locality',
            name,
            displayName: String(item?.display_name || name),
            secondary,
            lat: Number(item.lat),
            lng: Number(item.lon),
            bbox: Array.isArray(item?.boundingbox) ? item.boundingbox.map(Number) : null
          };
        })
        .filter((item, index, list) => Number.isFinite(item.lat) && Number.isFinite(item.lng)
          && list.findIndex((candidate) => `${candidate.name}|${candidate.lat.toFixed(6)}|${candidate.lng.toFixed(6)}` === `${item.name}|${item.lat.toFixed(6)}|${item.lng.toFixed(6)}`) === index)
        .slice(0, 8);
    } catch (error) {
      if (error?.name !== 'AbortError') console.debug('[Surveyor] Busca de localidade:', error?.message || error);
      return [];
    } finally {
      clearTimeout(timeout);
    }
  }

  function renderLocalitySuggestions(items = [], query = '') {
    if (!els.citySuggestBox || !selectedCitySearchContext?.city) return;
    const context = selectedCitySearchContext;
    citySuggestItems = Array.isArray(items) ? items : [];
    citySuggestIndex = -1;
    els.citySuggestBox.classList.remove('property-context-box');
    els.citySuggestBox.innerHTML = '';
    const head = document.createElement('div');
    head.className = 'sv-locality-search-head';
    const copy = document.createElement('div');
    copy.innerHTML = `<strong>Dentro de ${escapeHtmlLocal(context.city.name)} - ${escapeHtmlLocal(context.city.uf)}</strong><small>Pesquise bairro, povoado, localidade, estrada ou rua.</small>`;
    const downloadButton = document.createElement('button');
    downloadButton.className = 'property-municipality-download-action sv-locality-city-download';
    downloadButton.innerHTML = propertyMunicipalityStatusMarkup('available');
    bindPropertyMunicipalityDownloadAction(downloadButton, context.city, context.city.uf, { selectContext: false });
    const change = document.createElement('button');
    change.type = 'button';
    change.textContent = 'Trocar cidade';
    change.addEventListener('mousedown', (event) => event.preventDefault());
    change.addEventListener('click', () => {
      selectedCitySearchContext = null;
      if (els.coordSearch) els.coordSearch.value = '';
      resetSmartSearchMode();
      hideCitySuggestions();
      els.coordSearch?.focus();
    });
    head.append(copy, downloadButton, change);
    els.citySuggestBox.appendChild(head);
    if (!citySuggestItems.length) {
      const empty = document.createElement('div');
      empty.className = 'city-suggest-status';
      empty.textContent = String(query || '').trim().length >= 2
        ? `Nenhuma localidade encontrada em ${context.city.name}.`
        : `Digite uma localidade dentro de ${context.city.name}.`;
      els.citySuggestBox.appendChild(empty);
      showSearchSuggestionBox();
      return;
    }
    citySuggestItems.forEach((item, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'city-suggest-item sv-locality-suggest-item';
      button.setAttribute('role', 'option');
      button.setAttribute('aria-selected', 'false');
      button.dataset.index = String(index);
      const name = document.createElement('strong');
      name.textContent = item.name;
      const state = document.createElement('small');
      state.textContent = item.secondary || `${context.city.name} - ${context.city.uf}`;
      button.append(name, state);
      button.addEventListener('mousedown', (event) => event.preventDefault());
      button.addEventListener('click', () => selectSearchSuggestion(item));
      els.citySuggestBox.appendChild(button);
    });
    showSearchSuggestionBox();
  }

  async function updateLocalitySuggestions(value) {
    if (!selectedCitySearchContext?.city) return false;
    const query = String(value || '').trim();
    setSmartSearchModeBadge('locality', `${selectedCitySearchContext.city.name} · ${selectedCitySearchContext.city.uf}`);
    if (query.length < 2) {
      renderLocalitySuggestions([], query);
      return true;
    }
    setCitySuggestionsStatus(`Buscando “${query}” em ${selectedCitySearchContext.city.name}...`);
    const results = await fetchLocalitySuggestions(query);
    if (!selectedCitySearchContext?.city) return false;
    renderLocalitySuggestions(results, query);
    return true;
  }

  async function focusLocalitySuggestion(item) {
    if (!item || !Number.isFinite(Number(item.lat)) || !Number.isFinite(Number(item.lng))) return false;
    hideCitySuggestions();
    clearPropertyNameSearchResult();
    window.SurveyorMapWorkspace?.clearCarHighlight?.({ cancelSearch: true });
    if (searchMarker) { try { map.removeLayer(searchMarker); } catch {} }
    const lat = Number(item.lat), lng = Number(item.lng);
    searchMarker = L.marker([lat, lng], { icon: markerIcon('agua'), keyboard: false, title: item.name || 'Localidade' })
      .addTo(map)
      .bindPopup(`<b>${escapeHtmlLocal(item.name || 'Localidade')}</b><br>${escapeHtmlLocal(item.displayName || '')}`)
      .openPopup();
    const rawBox = Array.isArray(item.bbox) ? item.bbox : [];
    if (rawBox.length === 4 && rawBox.every(Number.isFinite)) {
      const bounds = L.latLngBounds([rawBox[0], rawBox[2]], [rawBox[1], rawBox[3]]);
      if (bounds.isValid()) map.fitBounds(bounds.pad(.18), { maxZoom: 17, animate: true });
      else map.setView([lat, lng], 16);
    } else map.setView([lat, lng], 16);
    if (els.coordSearch) els.coordSearch.value = item.name || '';
    if (selectedCitySearchContext?.city) {
      setSmartSearchModeBadge('locality', `${selectedCitySearchContext.city.name} · ${selectedCitySearchContext.city.uf}`);
      els.coordSearch.placeholder = `Localidade em ${selectedCitySearchContext.city.name}`;
    }
    notifyMapSearchResult('locality');
    toast(`${item.name || 'Localidade'} localizada em ${selectedCitySearchContext?.city?.name || 'município selecionado'}.`, 'success');
    return true;
  }

  async function locateLocalityFromText(value) {
    if (!selectedCitySearchContext?.city) return false;
    const query = String(value || '').trim();
    if (query.length < 2) return false;
    const results = await fetchLocalitySuggestions(query);
    if (!results.length) return false;
    await focusLocalitySuggestion(results[0]);
    return true;
  }

  function selectSearchSuggestion(item) {
    if (item?._searchKind === 'locality') return focusLocalitySuggestion(item);
    return selectCitySuggestion(item);
  }

  function updateCityActiveItem(nextIndex) {
    if (!els.citySuggestBox || !citySuggestItems.length) return;
    citySuggestIndex = (nextIndex + citySuggestItems.length) % citySuggestItems.length;
    els.citySuggestBox.querySelectorAll('.city-suggest-item').forEach((button, index) => {
      const active = index === citySuggestIndex;
      button.classList.toggle('active', active);
      button.setAttribute('aria-selected', active ? 'true' : 'false');
      if (active) button.scrollIntoView({ block: 'nearest' });
    });
  }


  async function updateCitySuggestions() {
    const value = els.coordSearch?.value || '';
    const trimmed = String(value).trim();

    if (activeSearchMode === 'coordinate') {
      if (trimmed) applySelectedCoordinateFormatting();
      hideCitySuggestions();
      return;
    }

    if (activeSearchMode === 'car') {
      if (!trimmed) return hideCitySuggestions();
      renderCarSmartSuggestion(value);
      return;
    }

    if (activeSearchMode === 'property') {
      if (!trimmed) return hideCitySuggestions();
      if (selectedCitySearchContext?.city && !propertyContextSearchState.municipality) {
        propertyContextSearchState.municipality = selectedCitySearchContext.city;
      }
      selectedCitySearchContext = null;
      renderPropertyContextAssistant(value, { force: true });
      await ensureCityCache().catch(() => []);
      if (activeSearchMode === 'property' && sanitizePropertyNameSearch(els.coordSearch?.value || '') === sanitizePropertyNameSearch(value)) {
        renderPropertyContextAssistant(els.coordSearch?.value || value, { force: true });
      }
      return;
    }

    // Modo CIDADE: somente municípios/localidades passam por este fluxo.
    if (selectedCitySearchContext?.city) {
      await updateLocalitySuggestions(value);
      return;
    }
    propertyContextSearchState.requestId += 1;
    propertyContextSearchState.query = '';
    propertyContextSearchState.municipality = null;
    propertyContextSearchState.results = [];
    propertyContextSearchState.selectedIndex = -1;
    const q = normalizeCityQuery(value);
    if (q.length < 2) return hideCitySuggestions();
    const immediateItems = getCitySuggestions(value);
    if (immediateItems.length) renderCitySuggestions(immediateItems);
    else setCitySuggestionsStatus('Carregando cidades do Brasil…');
    await ensureCityCache();
    if (activeSearchMode !== 'city') return;
    renderCitySuggestions(getCitySuggestions(els.coordSearch?.value || value));
  }

  function scheduleCitySuggestions() {
    clearTimeout(citySuggestTimer);
    clearTimeout(smartSearchFormatTimer);
    clearTimeout(carAutoSearchTimer);
    const value = els.coordSearch?.value || '';
    const trimmed = String(value).trim();

    if (!trimmed) {
      hideCitySuggestions();
      updateExplicitSearchModeLayout();
      return;
    }

    if (activeSearchMode === 'coordinate') {
      applySelectedCoordinateFormatting();
      hideCitySuggestions();
      return;
    }

    if (activeSearchMode === 'car') {
      renderCarSmartSuggestion(value);
      return;
    }

    if (activeSearchMode === 'property') {
      selectedCitySearchContext = null;
      renderPropertyContextAssistant(value, { force: true });
      citySuggestTimer = setTimeout(() => {
        updateCitySuggestions().catch((error) => console.debug('[Surveyor] Busca explícita de imóvel:', error?.message || error));
      }, 80);
      return;
    }

    if (selectedCitySearchContext?.city) {
      citySuggestTimer = setTimeout(() => {
        updateLocalitySuggestions(value).catch((error) => console.debug('[Surveyor] Autocomplete de localidade:', error?.message || error));
      }, 120);
      return;
    }

    const immediateItems = getCitySuggestions(value);
    if (immediateItems.length) renderCitySuggestions(immediateItems);
    citySuggestTimer = setTimeout(() => {
      updateCitySuggestions().catch((error) => console.debug('[Surveyor] Autocomplete municipal:', error?.message || error));
    }, 120);
  }

  async function geocodeCity(city) {
    const key = `${city.id || city.name}-${city.uf}`.toLowerCase();
    const centerCache = readCityCenterCache();
    const cached = centerCache[key];
    if (cached?.lat && cached?.lng) return cached;
    if (Number.isFinite(Number(city?.lat)) && Number.isFinite(Number(city?.lng))) {
      const localCenter = { lat: Number(city.lat), lng: Number(city.lng), zoom: Number(city.zoom || 13), label: cityLabel(city), bbox: null };
      centerCache[key] = localCenter;
      writeCityCenterCache(centerCache);
      return localCenter;
    }

    const query = encodeURIComponent(`${city.name}, ${city.uf}, Brasil`);
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=1&countrycodes=br&q=${query}`;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 7000);
    let res;
    try { res = await fetch(url, { headers: { Accept: 'application/json' }, signal: controller.signal }); }
    finally { clearTimeout(timeout); }
    if (!res.ok) throw new Error('Geocodificação indisponível');
    const data = await res.json();
    const item = Array.isArray(data) ? data[0] : null;
    const lat = Number(item?.lat);
    const lng = Number(item?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) throw new Error('Cidade não encontrada');
    const rawBox = Array.isArray(item?.boundingbox) ? item.boundingbox.map(Number) : [];
    const bbox = rawBox.length === 4 && rawBox.every(Number.isFinite)
      ? [rawBox[2], rawBox[0], rawBox[3], rawBox[1]]
      : null;
    const center = { lat, lng, zoom: 13, label: cityLabel(city), bbox };
    centerCache[key] = center;
    writeCityCenterCache(centerCache);
    return center;
  }

  function notifyMapSearchResult(type = 'none') {
    window.dispatchEvent(new CustomEvent('surveyor:map-search-result', { detail: { type } }));
  }

  function clearCoordinateSearchResult({ clearInput = false } = {}) {
    if (searchMarker) {
      try { map.removeLayer(searchMarker); } catch {}
      searchMarker = null;
    }
    if (clearInput && els.coordSearch) els.coordSearch.value = '';
  }

  function clearActiveMapSearchResult({ clearInput = true } = {}) {
    clearCoordinateSearchResult({ clearInput: false });
    clearPropertyNameSearchResult();
    selectedCitySearchContext = null;
    localitySearchSerial += 1;
    window.SurveyorMapWorkspace?.clearCarHighlight?.({ cancelSearch: true });
    hideCitySuggestions();
    if (clearInput && els.coordSearch) els.coordSearch.value = '';
    if (clearInput) resetSmartSearchMode();
    try { map.closePopup(); } catch {}
    notifyMapSearchResult('none');
  }

  function focusCoordinateSearchResult(lat, lng, options = {}) {
    selectedCitySearchContext = null;
    localitySearchSerial += 1;
    const safeLat = Number(lat);
    const safeLng = Number(lng);
    if (!Number.isFinite(safeLat) || !Number.isFinite(safeLng) || Math.abs(safeLat) > 90 || Math.abs(safeLng) > 180) {
      throw new Error('Coordenada inválida.');
    }
    hideCitySuggestions();
    window.SurveyorMapWorkspace?.clearCarHighlight?.({ cancelSearch: true });
    clearPropertyNameSearchResult();
    if (searchMarker) { try { map.removeLayer(searchMarker); } catch {} }
    const formatLabel = String(options.label || 'Coordenada').replace(/[<>]/g, '');
    searchMarker = L.marker([safeLat, safeLng], {
      icon: markerIcon('agua'),
      keyboard: false,
      title: formatLabel
    }).addTo(map);
    searchMarker.bindPopup(`<b>${formatLabel}</b><br>${safeLat.toFixed(7)}, ${safeLng.toFixed(7)}`).openPopup();
    map.setView([safeLat, safeLng], Number(options.zoom || 17));
    notifyMapSearchResult('coordinate');
    if (options.toast !== false) toast(`${formatLabel} localizada no mapa.`, 'success');
    return true;
  }

  async function selectCitySuggestion(city) {
    hideCitySuggestions();
    // Cidade vira contexto para uma segunda busca: bairro, povoado, localidade,
    // estrada ou rua dentro do município selecionado.
    window.SurveyorMapWorkspace?.clearCarHighlight?.({ cancelSearch: true });
    clearPropertyNameSearchResult();
    notifyMapSearchResult('city');
    selectedCitySearchContext = null;
    els.coordSearch.value = `${city.name} - ${city.uf}`;
    els.locateBtn.disabled = true;
    const originalText = els.locateBtn.textContent;
    els.locateBtn.textContent = 'Localizando…';
    try {
      const center = await geocodeCity(city);
      if (searchMarker) map.removeLayer(searchMarker);
      searchMarker = L.marker([center.lat, center.lng], { icon: markerIcon('agua') })
        .addTo(map)
        .bindPopup(`<b>${city.name} - ${city.uf}</b><br>${center.lat.toFixed(7)}, ${center.lng.toFixed(7)}`)
        .openPopup();
      map.setView([center.lat, center.lng], center.zoom || 13);
      selectedCitySearchContext = { city: { ...city }, center };
      els.coordSearch.value = '';
      els.coordSearch.placeholder = `Localidade em ${city.name} — bairro, povoado ou rua`;
      setSmartSearchModeBadge('locality', `${city.name} · ${city.uf}`);
      renderLocalitySuggestions([], '');
      toast(`Mapa centralizado em ${city.name} - ${city.uf}. Você pode baixar o índice da cidade ou pesquisar uma localidade dentro do município.`, 'success');
    } catch (err) {
      selectedCitySearchContext = null;
      els.coordSearch.value = `${city.name} - ${city.uf}`;
      resetSmartSearchMode();
      toast('Não foi possível localizar essa cidade agora.', 'error');
    } finally {
      els.locateBtn.disabled = false;
      els.locateBtn.textContent = originalText;
    }
  }

  async function locateCityFromText(value) {
    const q = normalizeCityQuery(value);
    if (q.length < 2) return false;
    let items = getCitySuggestions(value);
    if (!items.length) {
      await ensureCityCache();
      items = getCitySuggestions(value);
    } else if (!cityCacheHydrated) {
      // Não bloqueia Amargosa/Salvador aguardando uma API externa.
      ensureCityCache().catch(() => {});
    }
    if (!items.length) return false;
    await selectCitySuggestion(items[0]);
    return true;
  }

  let cefirPropertyNameSchemaFields = null;
  let cefirPropertyMunicipalityNameSchemaFields = null;
  let cefirPropertyMunicipalityCodeSchemaFields = null;
  const RURAL_PROPERTY_PREFIX_RE = /^\s*(?:s[ií]tio|fazenda|ch[aá]cara|rancho|haras|est[aâ]ncia|granja|ro[cç]a|gleba)\b/i;
  const propertyContextSearchState = { query: '', municipality: null, results: [], requestId: 0, selectedIndex: -1 };
  const PROPERTY_NAME_STOPWORDS = new Set([
    'sitio', 'fazenda', 'chacara', 'propriedade', 'imovel', 'rural', 'gleba',
    'lote', 'terreno', 'estancia', 'rancho', 'roca', 'area', 'da', 'de', 'do',
    'das', 'dos', 'e', 'a', 'o'
  ]);

  function normalizePropertyNameSearch(value) {
    return String(value || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-zA-Z0-9\s-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  function sanitizePropertyNameSearch(value) {
    return String(value || '')
      .replace(/[\u0000-\u001f\u007f%_*?;\\]/g, ' ')
      .replace(/[^\p{L}\p{N}\s'&.\-]/gu, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 120);
  }

  function looksLikeRuralPropertyName(value) {
    const raw = String(value || '').trim();
    if (RURAL_PROPERTY_PREFIX_RE.test(raw)) return true;
    const normalized = normalizePropertyNameSearch(raw);
    const first = normalized.split(' ')[0] || '';
    if (first.length < 3) return false;
    const prefixes = ['sitio','fazenda','chacara','rancho','haras','estancia','granja','roca','gleba'];
    return prefixes.some((prefix) => prefix.startsWith(first) || first.startsWith(prefix));
  }

  function propertyNameFromFeature(feature) {
    const hit = ruralPropertyNameHit(feature?.properties || {});
    return String(hit?.value || '').trim();
  }

  function propertyMunicipalityFromFeature(feature) {
    const hit = registryProperty(feature?.properties || {}, CEFIR_PROPERTY_MUNICIPALITY_NAME_FIELDS);
    return String(hit?.value || '').trim();
  }

  function propertyMunicipalityCodeFromFeature(feature) {
    const hit = registryProperty(feature?.properties || {}, CEFIR_PROPERTY_MUNICIPALITY_CODE_FIELDS);
    return String(hit?.value || '').replace(/\D/g, '').trim();
  }

  function propertyCarFromFeature(feature) {
    const hit = registryProperty(feature?.properties || {}, [
      'cod_imovel', 'codigo_imovel', 'codigoimovel', 'num_sicar', 'numero_sicar',
      'numero_car', 'registro_car', 'car', 'cod_car'
    ]);
    return String(hit?.value || '').trim();
  }

  function propertyAreaFromFeature(feature) {
    const hit = registryProperty(feature?.properties || {}, ['area_regis', 'area_registrada', 'area', 'num_area', 'area_ha', 'areahectares', 'area_hectares']);
    const value = Number(String(hit?.value ?? '').replace(',', '.'));
    return Number.isFinite(value) ? value : null;
  }

  function propertyFeatureMatchesMunicipality(feature, municipality, { allowMissingMunicipalityAttributes = false } = {}) {
    if (!municipality) return true;
    const targetCode = String(municipality.id || '').replace(/\D/g, '');
    const featureCode = propertyMunicipalityCodeFromFeature(feature);
    if (targetCode && featureCode) return featureCode === targetCode;
    const carCode = propertyCarFromFeature(feature).toUpperCase().replace(/[^A-Z0-9]/g, '').match(/^[A-Z]{2}(\d{7})[A-Z0-9]+$/)?.[1] || '';
    if (targetCode && carCode) return carCode === targetCode;
    const targetName = normalizeCityQuery(municipality.name || '');
    const featureName = normalizeCityQuery(propertyMunicipalityFromFeature(feature));
    if (!featureCode && !featureName) return Boolean(allowMissingMunicipalityAttributes);
    return Boolean(targetName && featureName && featureName === targetName);
  }

  function propertySearchMeaningfulTokens(value) {
    return normalizePropertyNameSearch(value).split(/\s+/).map((token) => token.trim()).filter(Boolean).filter((token) => {
      return token.length >= 2 && !PROPERTY_NAME_STOPWORDS.has(token);
    }).slice(0, 8);
  }

  function canonicalPropertyNameSearch(value) {
    const normalized = normalizePropertyNameSearch(value);
    const tokens = propertySearchMeaningfulTokens(normalized);
    return tokens.length ? tokens.join(' ') : normalized;
  }

  function propertyNameSearchCql(field, query) {
    const safeQuery = sanitizePropertyNameSearch(query);
    if (!safeQuery) return '';
    const tokens = propertySearchMeaningfulTokens(safeQuery);
    // Use sempre os termos significativos quando existirem. Isso faz buscas
    // como “Sítio Raílda” consultarem o nome útil “railda”, em vez de exigir
    // que o serviço oficial também armazene o prefixo “Sítio”.
    const terms = tokens.length ? tokens : [safeQuery];
    return terms.map((term) => `${field} ILIKE '%${String(term).replace(/'/g, "''")}%'`).join(' AND ');
  }

  function propertyNameAccentTolerantCql(field, query) {
    const tokens = propertySearchMeaningfulTokens(query).filter((token) => token.length >= 4);
    if (!tokens.length) return '';
    // WFS/GeoServer nem sempre faz ILIKE sem acento. Em "Raílda" x "Railda",
    // por exemplo, a consulta integral pode falhar. O fallback usa pedaços das
    // extremidades sem o caractere central e a conferência final continua sendo
    // feita no navegador com normalização completa, evitando falso positivo.
    const clauses = tokens.map((token) => {
      const left = token.slice(0, 2).replace(/'/g, "''");
      const right = token.slice(-2).replace(/'/g, "''");
      return `(${field} ILIKE '%${left}%' AND ${field} ILIKE '%${right}%')`;
    });
    return clauses.join(' AND ');
  }

  function propertyFeatureIdentity(feature) {
    const props = feature?.properties || {};
    const code = registryProperty(props, ['cod_imovel','codigo_imovel','codigoimovel','num_sicar','numero_car','registro_car']);
    return String(feature?.id || code?.value || JSON.stringify(feature?.geometry || {})).slice(0, 800);
  }

  function propertyNameMatchScore(feature, query) {
    const candidateRaw = normalizePropertyNameSearch(propertyNameFromFeature(feature));
    const targetRaw = normalizePropertyNameSearch(query);
    if (!candidateRaw || !targetRaw) return -1;

    // "Sítio Boa Vista", "Fazenda Boa Vista" e "Boa Vista" precisam ser
    // comparados pelo nome significativo, sem deixar o tipo genérico do imóvel
    // distorcer a ordenação.
    const candidate = canonicalPropertyNameSearch(candidateRaw);
    const target = canonicalPropertyNameSearch(targetRaw);
    if (!candidate || !target) return -1;
    if (candidate === target) return 12000;
    if (candidate.startsWith(target)) return 10500 - Math.min(candidate.length, 400);
    if (candidate.includes(target)) return 9800 - Math.min(candidate.indexOf(target), 400);

    const targetTokens = target.split(' ').filter(Boolean);
    const candidateTokens = candidate.split(' ').filter(Boolean);
    const matched = targetTokens.filter((token) => candidateTokens.some((candidateToken) => candidateToken === token || candidateToken.startsWith(token) || token.startsWith(candidateToken))).length;
    // Todos os termos relevantes precisam corresponder. Um único termo como
    // "Bahia" não pode satisfazer a busca composta "Riu Bahia".
    if (matched !== targetTokens.length) return -1;
    const coverage = 1;
    const extraPenalty = Math.max(0, candidateTokens.length - targetTokens.length) * 25;
    return 3000 + coverage * 3000 - extraPenalty;
  }

  const sicarPropertySchemaCache = new Map();

  async function fetchSicarPropertySchema(stateCode = propertySearchStateCode()) {
    const uf = normalizedCatalogState(stateCode);
    if (sicarPropertySchemaCache.has(uf)) return sicarPropertySchemaCache.get(uf);
    const fallback = {
      nameFields: ['nom_imovel', 'nome_imovel', 'nm_imovel', 'nome_area', 'nomearea', 'denominacao'],
      municipalityNameFields: ['municipio', 'nom_munici', 'nome_municipio'],
      municipalityCodeFields: ['cod_municipio_ibge', 'cod_munici', 'cod_municipio']
    };
    try {
      const upstream = new URL('https://geoserver.car.gov.br/geoserver/sicar/ows');
      upstream.searchParams.set('SERVICE', 'WFS');
      upstream.searchParams.set('VERSION', '1.0.0');
      upstream.searchParams.set('REQUEST', 'DescribeFeatureType');
      upstream.searchParams.set('TYPENAME', `sicar:sicar_imoveis_${uf.toLowerCase()}`);
      let xml = '';
      let lastError = null;
      for (const url of [...geoserviceEncodedProxyUrls(upstream.toString(), 'wfs'), upstream.toString()]) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 12_000);
        try {
          const response = await fetch(url, { cache: 'no-store', credentials: 'omit', signal: controller.signal, headers: { Accept: 'application/xml,text/xml;q=0.9,*/*;q=0.1' } });
          if (!response.ok) throw new Error(`DescribeFeatureType SICAR HTTP ${response.status}`);
          xml = await response.text();
          if (xml) break;
        } catch (error) {
          lastError = error;
        } finally {
          clearTimeout(timer);
        }
      }
      if (!xml) throw lastError || new Error('DescribeFeatureType SICAR indisponível');
      const documentXml = new DOMParser().parseFromString(xml, 'application/xml');
      if (documentXml.querySelector('parsererror')) throw new Error('Schema SICAR inválido');
      const available = new Set([...documentXml.getElementsByTagNameNS('*', 'element')]
        .map((node) => String(node.getAttribute('name') || '').trim().toLowerCase()).filter(Boolean));
      const schema = {
        nameFields: CEFIR_PROPERTY_NAME_FIELDS.filter((field) => available.has(field.toLowerCase())),
        municipalityNameFields: CEFIR_PROPERTY_MUNICIPALITY_NAME_FIELDS.filter((field) => available.has(field.toLowerCase())),
        municipalityCodeFields: CEFIR_PROPERTY_MUNICIPALITY_CODE_FIELDS.filter((field) => available.has(field.toLowerCase()))
      };
      const result = {
        nameFields: schema.nameFields.length ? schema.nameFields : fallback.nameFields,
        municipalityNameFields: schema.municipalityNameFields.length ? schema.municipalityNameFields : fallback.municipalityNameFields,
        municipalityCodeFields: schema.municipalityCodeFields.length ? schema.municipalityCodeFields : fallback.municipalityCodeFields
      };
      sicarPropertySchemaCache.set(uf, result);
      return result;
    } catch (error) {
      console.debug('Schema SICAR não disponível para busca por nome:', error?.message || error);
      sicarPropertySchemaCache.set(uf, fallback);
      return fallback;
    }
  }

  function propertyMunicipalitySearchClausesForSchema(municipality, schema) {
    if (!municipality) return [];
    const clauses = [];
    const safeName = sanitizePropertyNameSearch(municipality.name || '');
    const code = String(municipality.id || '').replace(/\D/g, '');
    for (const field of schema?.municipalityCodeFields || []) {
      if (code) clauses.push(`${field} = ${Number(code)}`);
    }
    for (const field of schema?.municipalityNameFields || []) {
      if (safeName) clauses.push(`${field} ILIKE '%${safeName.replace(/'/g, "''")}%'`);
    }
    return [...new Set(clauses)];
  }

  async function fetchSicarPropertiesByName(query, municipality = null, stateCode = propertySearchStateCode()) {
    const safeQuery = sanitizePropertyNameSearch(query);
    if (safeQuery.length < 3) return [];
    const uf = normalizedCatalogState(stateCode);
    const schema = await fetchSicarPropertySchema(uf);
    const municipalityClauses = propertyMunicipalitySearchClausesForSchema(municipality, schema);
    const collected = new Map();
    let lastError = null;
    const typename = `sicar:sicar_imoveis_${uf.toLowerCase()}`;

    for (const field of schema.nameFields.slice(0, 8)) {
      const nameCql = propertyNameSearchCql(field, safeQuery);
      if (!nameCql) continue;
      const cql = municipality && municipalityClauses.length
        ? `(${nameCql}) AND (${municipalityClauses.join(' OR ')})`
        : nameCql;
      try {
        const upstream = new URL('https://geoserver.car.gov.br/geoserver/sicar/ows');
        upstream.searchParams.set('SERVICE', 'WFS');
        upstream.searchParams.set('VERSION', '1.0.0');
        upstream.searchParams.set('REQUEST', 'GetFeature');
        upstream.searchParams.set('TYPENAME', typename);
        upstream.searchParams.set('OUTPUTFORMAT', 'application/json');
        upstream.searchParams.set('SRSNAME', 'EPSG:4326');
        upstream.searchParams.set('MAXFEATURES', '80');
        upstream.searchParams.set('CQL_FILTER', cql);
        const payload = await fetchJsonCandidateUrls([
          ...geoserviceEncodedProxyUrls(upstream.toString(), 'wfs'),
          upstream.toString()
        ], 20_000);
        for (const feature of Array.isArray(payload?.features) ? payload.features : []) {
          if (!feature?.geometry) continue;
          if (municipality && !propertyFeatureMatchesMunicipality(feature, municipality, { allowMissingMunicipalityAttributes: true })) continue;
          const score = propertyNameMatchScore(feature, safeQuery);
          if (score < 0) continue;
          const identity = propertyFeatureIdentity(feature);
          const previous = collected.get(identity);
          if (!previous || score > previous.score) collected.set(identity, { feature, score });
        }
        if ([...collected.values()].some((entry) => entry.score >= 10000)) break;
      } catch (error) {
        lastError = error;
      }
    }

    const results = [...collected.values()]
      .sort((a, b) => b.score - a.score || propertyNameFromFeature(a.feature).localeCompare(propertyNameFromFeature(b.feature), 'pt-BR'))
      .slice(0, 30)
      .map((entry) => entry.feature);
    if (!results.length && lastError) console.debug('Busca SICAR por nome sem resultado:', lastError?.message || lastError);
    return results;
  }

  async function fetchCefirPropertyNameSchemaFields() {
    if (Array.isArray(cefirPropertyNameSchemaFields) && cefirPropertyNameSchemaFields.length) return cefirPropertyNameSchemaFields;
    const base = 'https://geoserver.inema.ba.gov.br/geoserver/ows';
    try {
      const upstream = new URL(base);
      upstream.searchParams.set('SERVICE', 'WFS');
      upstream.searchParams.set('VERSION', '1.0.0');
      upstream.searchParams.set('REQUEST', 'DescribeFeatureType');
      upstream.searchParams.set('TYPENAME', OFFICIAL_PROPERTY_BOUNDARY_LAYER);
      const urls = geoserviceEncodedProxyUrls(upstream.toString(), 'wfs');
      let xml = '';
      let lastError = null;
      for (const url of urls) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 20_000);
        try {
          const response = await fetch(url, { cache: 'no-store', credentials: 'omit', signal: controller.signal, headers: { Accept: 'application/xml,text/xml;q=0.9,*/*;q=0.1' } });
          if (!response.ok) throw new Error(`DescribeFeatureType HTTP ${response.status}`);
          xml = await response.text();
          if (xml) break;
        } catch (error) {
          lastError = error;
        } finally {
          clearTimeout(timer);
        }
      }
      if (!xml) throw lastError || new Error('DescribeFeatureType indisponível');
      const documentXml = new DOMParser().parseFromString(xml, 'application/xml');
      const parserError = documentXml.querySelector('parsererror');
      if (parserError) throw new Error('Schema WFS inválido');
      const available = new Set(
        [...documentXml.getElementsByTagNameNS('*', 'element')]
          .map((node) => String(node.getAttribute('name') || '').trim().toLowerCase())
          .filter(Boolean)
      );
      cefirPropertyNameSchemaFields = CEFIR_PROPERTY_NAME_FIELDS.filter((field) => available.has(field.toLowerCase()));
      cefirPropertyMunicipalityNameSchemaFields = CEFIR_PROPERTY_MUNICIPALITY_NAME_FIELDS.filter((field) => available.has(field.toLowerCase()));
      cefirPropertyMunicipalityCodeSchemaFields = CEFIR_PROPERTY_MUNICIPALITY_CODE_FIELDS.filter((field) => available.has(field.toLowerCase()));
      if (cefirPropertyNameSchemaFields.length) return cefirPropertyNameSchemaFields;
    } catch (error) {
      console.debug('Schema CEFIR não disponível para busca por nome:', error?.message || error);
    }
    // Fallback curto e ordenado pelos aliases observados nos serviços oficiais.
    cefirPropertyNameSchemaFields = ['nomearea', 'nome_area', 'nom_area', 'nom_imovel', 'nome_imovel', 'denominacao'];
    cefirPropertyMunicipalityNameSchemaFields ||= ['municipio', 'nom_munici', 'nome_municipio'];
    cefirPropertyMunicipalityCodeSchemaFields ||= ['cod_municipio_ibge', 'cod_munici', 'codmun'];
    return cefirPropertyNameSchemaFields;
  }

  function propertyMunicipalitySearchClauses(municipality) {
    if (!municipality) return [];
    const clauses = [];
    const safeName = sanitizePropertyNameSearch(municipality.name || '');
    const code = String(municipality.id || '').replace(/\D/g, '');
    for (const field of cefirPropertyMunicipalityCodeSchemaFields || []) {
      if (code) clauses.push(`${field} = ${Number(code)}`);
    }
    for (const field of cefirPropertyMunicipalityNameSchemaFields || []) {
      if (safeName) clauses.push(`${field} ILIKE '%${safeName.replace(/'/g, "''")}%'`);
    }
    return [...new Set(clauses)];
  }

  async function fetchCefirPropertiesByMunicipalityArea(query, municipality, collected = new Map()) {
    if (!municipality) return collected;
    const safeQuery = sanitizePropertyNameSearch(query);
    if (safeQuery.length < 3) return collected;
    let cityGeo = null;
    try {
      cityGeo = await geocodeCity({ ...municipality, uf: municipality.uf || 'BA' });
    } catch (error) {
      console.debug('Limite municipal indisponível para busca espacial do imóvel:', error?.message || error);
      return collected;
    }
    const bbox = Array.isArray(cityGeo?.bbox) ? cityGeo.bbox.map(Number) : [];
    if (bbox.length !== 4 || !bbox.every(Number.isFinite)) return collected;

    try {
      const upstream = new URL('https://geoserver.inema.ba.gov.br/geoserver/ows');
      upstream.searchParams.set('SERVICE', 'WFS');
      upstream.searchParams.set('VERSION', '1.0.0');
      upstream.searchParams.set('REQUEST', 'GetFeature');
      upstream.searchParams.set('TYPENAME', OFFICIAL_PROPERTY_BOUNDARY_LAYER);
      upstream.searchParams.set('OUTPUTFORMAT', 'application/json');
      upstream.searchParams.set('SRSNAME', 'EPSG:4326');
      upstream.searchParams.set('BBOX', `${bbox.join(',')},EPSG:4326`);
      upstream.searchParams.set('MAXFEATURES', '2500');
      const payload = await fetchJsonCandidateUrls(geoserviceEncodedProxyUrls(upstream.toString(), 'wfs'), 90_000);
      for (const feature of Array.isArray(payload?.features) ? payload.features : []) {
        if (!feature?.geometry) continue;
        if (!propertyFeatureMatchesMunicipality(feature, municipality, { allowMissingMunicipalityAttributes: true })) continue;
        const score = propertyNameMatchScore(feature, safeQuery);
        if (score < 0) continue;
        const identity = propertyFeatureIdentity(feature);
        const previous = collected.get(identity);
        if (!previous || score > previous.score) collected.set(identity, { feature, score });
      }
    } catch (error) {
      console.debug('Busca espacial CEFIR no município sem resultado:', error?.message || error);
    }
    return collected;
  }

  async function fetchCefirPropertiesByName(query, municipality = null) {
    const safeQuery = sanitizePropertyNameSearch(query);
    if (safeQuery.length < 3) return [];
    const base = 'https://geoserver.inema.ba.gov.br/geoserver/ows';
    const collected = new Map();
    let lastError = null;
    const fields = await fetchCefirPropertyNameSchemaFields();
    const municipalityClauses = propertyMunicipalitySearchClauses(municipality);
    for (const field of fields) {
      const nameCql = propertyNameSearchCql(field, safeQuery);
      if (!nameCql) continue;
      // Cada campo municipal é tentado isoladamente. Assim, um alias legado
      // inexistente não invalida toda a busca. Quando há município selecionado,
      // NÃO fazemos uma consulta global apenas pelo nome: isso era a principal
      // fonte de falsos positivos de imóveis homônimos em outras cidades. Se os
      // aliases municipais falharem, o fallback por BBOX municipal entra depois.
      const fuzzyNameCql = propertyNameAccentTolerantCql(field, safeQuery);
      const nameVariants = [...new Set([nameCql, fuzzyNameCql].filter(Boolean))];
      const attempts = municipality
        ? municipalityClauses.flatMap((clause) => nameVariants.map((variant) => `(${variant}) AND (${clause})`))
        : nameVariants;
      for (const cql of attempts) {
        try {
          const upstream = new URL(base);
          upstream.searchParams.set('SERVICE', 'WFS');
          upstream.searchParams.set('VERSION', '1.0.0');
          upstream.searchParams.set('REQUEST', 'GetFeature');
          upstream.searchParams.set('TYPENAME', OFFICIAL_PROPERTY_BOUNDARY_LAYER);
          upstream.searchParams.set('OUTPUTFORMAT', 'application/json');
          upstream.searchParams.set('SRSNAME', 'EPSG:4326');
          upstream.searchParams.set('MAXFEATURES', municipality ? '120' : '40');
          upstream.searchParams.set('CQL_FILTER', cql);
          const payload = await fetchJsonCandidateUrls(geoserviceEncodedProxyUrls(upstream.toString(), 'wfs'), 45_000);
          for (const feature of Array.isArray(payload?.features) ? payload.features : []) {
            if (!feature?.geometry) continue;
            // Aqui o próprio CQL já restringiu o município. Alguns schemas CEFIR
            // não devolvem o atributo municipal no GeoJSON; nesses casos aceitamos
            // atributo ausente, mas nunca um município explicitamente divergente.
            if (municipality && !propertyFeatureMatchesMunicipality(feature, municipality, { allowMissingMunicipalityAttributes: true })) continue;
            const score = propertyNameMatchScore(feature, safeQuery);
            if (score < 0) continue;
            const identity = propertyFeatureIdentity(feature);
            const previous = collected.get(identity);
            if (!previous || score > previous.score) collected.set(identity, { feature, score });
          }
          if ([...collected.values()].some((entry) => entry.score >= 10000)) break;
        } catch (error) {
          lastError = error;
        }
      }
      if ([...collected.values()].some((entry) => entry.score >= 10000)) break;
    }
    const hasStrongMatch = [...collected.values()].some((entry) => entry.score >= 9800);
    if (municipality && !hasStrongMatch) {
      await fetchCefirPropertiesByMunicipalityArea(safeQuery, municipality, collected);
    }
    const results = [...collected.values()]
      .sort((a, b) => b.score - a.score || propertyNameFromFeature(a.feature).localeCompare(propertyNameFromFeature(b.feature), 'pt-BR'))
      .slice(0, 30)
      .map((entry) => entry.feature);
    if (!results.length && lastError) console.debug('Busca CEFIR por nome sem resultado:', lastError?.message || lastError);
    return results;
  }

  function clearPropertyNameSearchResult() {
    propertyNameSearchGroup.clearLayers();
    lastSelectedRuralPropertyName = '';
    lastSelectedRuralPropertyState = '';
    updateSelectedPropertyNameInLayerCards();
  }

  // O GeoServer pode atribuir FIDs sequenciais diferentes conforme CQL,
  // página e filtragem. Nunca usar FEATUREID .1/.2 como identidade cadastral.
  function ruralCarSearchVariants(value) {
    const raw = String(value || '').trim().toUpperCase();
    const compact = raw.replace(/[^A-Z0-9]/g, '');
    if (!compact) return [];
    const variants = new Set([compact, raw]);
    const parts = compact.match(/^([A-Z]{2})(\d{7})([A-Z0-9]{32})$/);
    if (parts) {
      variants.add(`${parts[1]}-${parts[2]}-${parts[3]}`);
      variants.add(`${parts[1]}-${parts[2]}-${(parts[3].match(/.{1,4}/g) || []).join('.')}`);
    }
    return [...variants].filter(Boolean);
  }

  function sameRuralPropertyIdentity(selected, candidate) {
    if (!selected || !candidate?.geometry) return false;
    const normalize = (value) => String(value ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    const selectedCar = normalize(propertyCarFromFeature(selected));
    const candidateCar = normalize(propertyCarFromFeature(candidate));
    // Quando o índice possui CAR, exigir o MESMO CAR da geometria oficial.
    // FID sequencial semelhante não prova identidade, nem na ausência de CAR
    // no resultado do WFS. Isto evita Sítio Itachama -> Fazenda Jericó.
    if (selectedCar || candidateCar) return !!(selectedCar && candidateCar && selectedCar === candidateCar);
    // Registros sem CAR só podem usar códigos cadastrais oficiais explícitos.
    // Não comparar `feature.id`, `fid` nem `objectid`: podem ser transitórios.
    const officialKeys = ['ide_imovel','id_imovel','codigo_imo'];
    const selectedCodes = officialKeys.map((key) => normalize(selected?.properties?.[key])).filter(Boolean);
    const candidateCodes = officialKeys.map((key) => normalize(candidate?.properties?.[key])).filter(Boolean);
    return selectedCodes.length > 0 && selectedCodes.some((code) => candidateCodes.includes(code));
  }

  // RC185.11: ao receber 502/erro de uma rota, iniciar a alternativa seguinte
  // imediatamente, sem aguardar o timeout da outra rota ainda pendente.
  // Máximo de duas requisições simultâneas e três rotas por chave cadastral.
  // Uma resposta só vence se o CAR/ID do polígono corresponder ao selecionado.
  const propertyGeometryGatewayHealth = new Map();
  function rankedPropertyGeometryUrls(urls) {
    const now = Date.now();
    return [...new Set((urls || []).filter(Boolean))].sort((a, b) => {
      const score = (url) => {
        let host = url;
        try { host = new URL(url).origin; } catch {}
        const health = propertyGeometryGatewayHealth.get(host);
        if (!health) return 4000;
        if (health.cooldownUntil > now) return 100000;
        return health.successMs || 4000;
      };
      return score(a) - score(b);
    });
  }
  async function fetchVerifiedPropertyGeometry(urls, selected) {
    const candidates = rankedPropertyGeometryUrls(urls).slice(0, 3);
    if (!candidates.length) return null;
    const controllers = new Set();
    let next = 0;
    let active = 0;
    let settled = false;
    return new Promise((resolve) => {
      const finish = (feature) => {
        if (settled) return;
        settled = true;
        for (const controller of controllers) controller.abort();
        resolve(feature);
      };
      const pump = () => {
        if (settled) return;
        while (active < 2 && next < candidates.length) {
          const url = candidates[next++];
          const controller = new AbortController();
          controllers.add(controller);
          active += 1;
          const started = Date.now();
          let host = url;
          try { host = new URL(url).origin; } catch {}
          void fetchTextWithTimeout(url, {
            headers: { Accept: 'application/json,application/geo+json' },
            cache: 'no-store', signal: controller.signal
          }, 6500).then((response) => {
            const payload = JSON.parse(response.text);
            const exact = (Array.isArray(payload?.features) ? payload.features : [])
              .find((item) => sameRuralPropertyIdentity(selected, item));
            if (!exact?.geometry) return;
            const previous = propertyGeometryGatewayHealth.get(host);
            const ms = Math.max(1, Date.now() - started);
            propertyGeometryGatewayHealth.set(host, {
              successMs: previous?.successMs ? Math.round(previous.successMs * .4 + ms * .6) : ms,
              cooldownUntil: 0
            });
            finish(exact);
          }).catch((error) => {
            // Abort disparado porque outra rota venceu não é falha do gateway.
            if (settled || controller.signal.aborted) return;
            const previous = propertyGeometryGatewayHealth.get(host) || {};
            const gatewayError = /\b(?:502|503|504)\b|tempo limite|timeout/i.test(String(error?.message || ''));
            if (gatewayError) propertyGeometryGatewayHealth.set(host, {
              ...previous, cooldownUntil: Date.now() + 30000
            });
          }).finally(() => {
            controllers.delete(controller);
            active -= 1;
            if (!settled) {
              if (active === 0 && next >= candidates.length) finish(null);
              else pump();
            }
          });
        }
      };
      pump();
    });
  }

  // A consulta de geometria é distinta da busca rápida de atributos no
  // IndexedDB. Preserve os resultados do índice, mas nunca preencha o mapa
  // com uma feição cuja identidade não corresponda ao imóvel escolhido.
  async function hydrateLocalPropertyGeometry(feature, stateCode) {
    if (feature?.geometry) return feature;
    if (!feature?.properties?._surveyor_local_attributes_only) return feature;
    const uf = normalizedCatalogState(stateCode || feature?.properties?._surveyor_local_cache || propertySearchStateCode());
    const cacheKey = propertyGeometryCacheKey(feature, uf);
    const cached = propertyGeometryMemoryCache.get(cacheKey);
    if (cached?.geometry && sameRuralPropertyIdentity(feature, cached)) {
      propertyGeometryMemoryCache.delete(cacheKey);
      propertyGeometryMemoryCache.set(cacheKey, cached);
      return cached;
    }
    if (cached) propertyGeometryMemoryCache.delete(cacheKey);
    // Persistência só de geometrias que já passaram pelo CAR/ID oficial.
    // Nas próximas visitas, o polígono volta do IndexedDB, sem aguardar o WFS.
    const diskCached = await window.SurveyorPropertyLocalCache?.getVerifiedGeometry?.(cacheKey);
    if (diskCached?.geometry && sameRuralPropertyIdentity(feature, diskCached)) {
      rememberPropertyGeometry(cacheKey, diskCached);
      return diskCached;
    }
    const bahia = uf === 'BA';
    const typeName = bahia ? OFFICIAL_PROPERTY_BOUNDARY_LAYER : `sicar:sicar_imoveis_${uf.toLowerCase()}`;
    const baseUrl = bahia
      ? 'https://geoserver.inema.ba.gov.br/geoserver/ows'
      : 'https://geoserver.car.gov.br/geoserver/sicar/ows';
    const props = feature.properties || {};
    const officialCar = propertyCarFromFeature(feature);
    const variants = ruralCarSearchVariants(officialCar);
    const candidates = [];
    if (variants.length) {
      // Para a base CEFIR, cod_imovel é o campo principal. Teste de variantes
      // protege contra índices antigos que salvaram o CAR sem pontuação.
      // NUNCA usar FEATUREID sequencial para registros com CAR.
      const fields = bahia ? ['cod_imovel','numero_car','num_sicar'] : ['cod_imovel','numero_car','num_sicar'];
      const values = [...new Set(variants)];
      for (const field of fields) {
        const literals = values.map((v) => `'${v.replace(/'/g, "''")}'`).join(',');
        candidates.push(`${field} IN (${literals})`);
      }
    } else {
      // Sem CAR, usar SOMENTE chaves oficiais explícitas da feição; não FID.
      for (const field of ['ide_imovel','id_imovel','codigo_imo']) {
        const value = String(props[field] || '').trim();
        if (value) candidates.push(`${field} = '${value.replace(/'/g,"''")}'`);
      }
    }
    if (!candidates.length) return null;

    let queries = 0;
    let gatewayFailed = false;
    for (const cql of candidates.slice(0, 3)) {
      const upstream = new URL(baseUrl);
      upstream.searchParams.set('SERVICE','WFS');
      upstream.searchParams.set('VERSION','1.0.0');
      upstream.searchParams.set('REQUEST','GetFeature');
      upstream.searchParams.set('TYPENAME',typeName);
      upstream.searchParams.set('OUTPUTFORMAT','application/json');
      upstream.searchParams.set('SRSNAME','EPSG:4326');
      upstream.searchParams.set('MAXFEATURES','5');
      upstream.searchParams.set('CQL_FILTER',cql);
      queries += 1;
      try {
        // Corrida limitada entre os dois gateways, em vez de esperar até 10s
        // pelo primeiro antes de tentar o segundo. Só ganha uma resposta cujo
        // CAR/ID realmente corresponda ao imóvel selecionado.
        const urls = [...geoserviceEncodedProxyUrls(upstream.toString(),'wfs'),upstream.toString()];
        const exact = await fetchVerifiedPropertyGeometry(urls, feature);
        if (exact?.geometry) {
          rememberPropertyGeometry(cacheKey, exact);
          void window.SurveyorPropertyLocalCache?.putVerifiedGeometry?.(cacheKey, exact);
          return exact;
        }
      } catch (error) {
        gatewayFailed = true;
        console.debug('[Surveyor] Consulta de geometria por identidade:',error?.message || error);
      }
    }
    if (gatewayFailed) console.warn('[Surveyor] Geometria oficial não recuperada; índice rápido preservado.', { uf, queries });
    return null;
  }

  // O clique e a antecipação compartilham a mesma promessa de geometria;
  // os campos do imóvel e a identidade CAR continuam sendo verificados no
  // resolvedor hydrateLocalPropertyGeometry antes de alimentar o cache.
  const propertyGeometryRequestsInFlight = new Map();
  const PROPERTY_GEOMETRY_PREFETCH_WINDOW = 3;
  const PROPERTY_GEOMETRY_PREFETCH_CONCURRENCY = 2;
  let propertyGeometryWarmupRunning = 0;
  let propertyGeometryWarmupQueue = [];
  let propertyGeometryWarmupQueued = new Set();
  let propertyGeometryWarmupVersion = 0;
  let propertyGeometryWarmupFeatures = [];
  let propertyGeometryWarmupStateCode = '';
  const propertyGeometryWarmupStatuses = new Map();

  function propertyGeometryStatusForFeature(feature, stateCode) {
    if (!feature) return 'idle';
    if (feature.geometry || !feature.properties?._surveyor_local_attributes_only) return 'ready';
    const key = propertyGeometryCacheKey(feature, stateCode);
    if (propertyGeometryMemoryCache.get(key)?.geometry) return 'ready';
    if (propertyGeometryRequestsInFlight.has(key)) return 'loading';
    if (propertyGeometryWarmupQueued.has(key)) return 'queued';
    return propertyGeometryWarmupStatuses.get(key) || 'idle';
  }

  function notifyPropertyGeometryWarmupChange() {
    if (!propertyGeometryWarmupFeatures.length || typeof els === 'undefined' || !els?.citySuggestBox?.querySelector?.('.property-context-result')) return;
    if (propertyGeometryWarmupFeatures !== propertyContextSearchState.results) return;
    updatePropertyContextResultActiveState();
  }

  async function getPropertyGeometryForSelection(feature, stateCode) {
    if (feature?.geometry || !feature?.properties?._surveyor_local_attributes_only) return feature;
    const key = propertyGeometryCacheKey(feature, stateCode);
    const existing = propertyGeometryRequestsInFlight.get(key);
    if (existing) return existing;
    const promise = hydrateLocalPropertyGeometry(feature, stateCode);
    propertyGeometryRequestsInFlight.set(key, promise);
    propertyGeometryWarmupStatuses.set(key, 'loading');
    notifyPropertyGeometryWarmupChange();
    try {
      const loaded = await promise;
      propertyGeometryWarmupStatuses.set(key, loaded?.geometry ? 'ready' : 'failed');
      return loaded;
    } catch (error) {
      propertyGeometryWarmupStatuses.set(key, 'failed');
      throw error;
    } finally {
      if (propertyGeometryRequestsInFlight.get(key) === promise) propertyGeometryRequestsInFlight.delete(key);
      notifyPropertyGeometryWarmupChange();
    }
  }

  function pumpPropertyGeometryWarmup() {
    while (propertyGeometryWarmupRunning < PROPERTY_GEOMETRY_PREFETCH_CONCURRENCY
        && propertyGeometryWarmupQueue.length) {
      const job = propertyGeometryWarmupQueue.shift();
      propertyGeometryWarmupQueued.delete(job.key);
      if (job.version !== propertyGeometryWarmupVersion) continue;
      if (propertyGeometryMemoryCache.has(job.key) || propertyGeometryRequestsInFlight.has(job.key)) continue;
      propertyGeometryWarmupRunning += 1;
      void getPropertyGeometryForSelection(job.feature, job.stateCode)
        .catch(() => null)
        .finally(() => {
          propertyGeometryWarmupRunning = Math.max(0, propertyGeometryWarmupRunning - 1);
          pumpPropertyGeometryWarmup();
        });
    }
  }

  function warmupPropertyGeometry(feature, stateCode, { priority = false } = {}) {
    if (!feature?.properties?._surveyor_local_attributes_only || feature?.geometry) return;
    const key = propertyGeometryCacheKey(feature, stateCode);
    if (!key || propertyGeometryMemoryCache.has(key) || propertyGeometryRequestsInFlight.has(key)) return;
    if (propertyGeometryWarmupQueued.has(key)) {
      // O ponteiro indica a intenção do usuário: puxar a geometria para a
      // frente da fila, mas não cancelar as consultas que já foram iniciadas.
      if (priority) {
        const offset = propertyGeometryWarmupQueue.findIndex((job) => job.key === key);
        if (offset > 0) propertyGeometryWarmupQueue.unshift(propertyGeometryWarmupQueue.splice(offset, 1)[0]);
      }
      return;
    }
    // Uma resposta de gateway falha não deve provocar novas tentativas a
    // cada movimento de mouse. O clique explícito continua podendo tentar.
    if (!priority && propertyGeometryWarmupStatuses.get(key) === 'failed') return;
    const job = { key, feature, stateCode, version: propertyGeometryWarmupVersion };
    propertyGeometryWarmupQueued.add(key);
    propertyGeometryWarmupStatuses.set(key, 'queued');
    if (priority) propertyGeometryWarmupQueue.unshift(job);
    else propertyGeometryWarmupQueue.push(job);
    notifyPropertyGeometryWarmupChange();
    pumpPropertyGeometryWarmup();
  }

  function resetPropertyGeometryWarmup(features, stateCode) {
    // As operações antigas já em curso terminam sem alimentar outra lista;
    // apenas os itens ainda aguardando na fila são descartados.
    propertyGeometryWarmupVersion += 1;
    propertyGeometryWarmupQueue = [];
    propertyGeometryWarmupQueued = new Set();
    propertyGeometryWarmupStatuses.clear();
    propertyGeometryWarmupFeatures = Array.isArray(features) ? features : [];
    propertyGeometryWarmupStateCode = stateCode;
    schedulePropertyGeometryWarmupWindow(-1);
    notifyPropertyGeometryWarmupChange();
  }

  function schedulePropertyGeometryWarmupWindow(selectedIndex) {
    const list = propertyGeometryWarmupFeatures;
    if (!list.length) return;
    const start = selectedIndex < 0 ? 0 : selectedIndex + 1;
    const end = Math.min(list.length, start + PROPERTY_GEOMETRY_PREFETCH_WINDOW);
    for (let i = start; i < end; i += 1) {
      warmupPropertyGeometry(list[i], propertyGeometryWarmupStateCode);
    }
  }

  function advancePropertyGeometryWarmup(selectedIndex) {
    // Ao selecionar o 1º, mantém 2º e 3º aquecidos e prepara o 4º.
    // Em listas curtas (1, 2 ou 3), prepara todos logo no início.
    schedulePropertyGeometryWarmupWindow(selectedIndex);
  }

  function propertyFeaturePoint(feature) {
    try {
      const point = window.turf?.pointOnFeature?.(feature);
      const coordinates = point?.geometry?.coordinates;
      if (Array.isArray(coordinates) && Number.isFinite(Number(coordinates[0])) && Number.isFinite(Number(coordinates[1]))) {
        return L.latLng(Number(coordinates[1]), Number(coordinates[0]));
      }
    } catch {}
    try {
      const layer = L.geoJSON(feature);
      const bounds = layer.getBounds?.();
      if (bounds?.isValid?.()) return bounds.getCenter();
    } catch {}
    return null;
  }

  async function focusRuralPropertySearchFeature(feature, options = {}) {
    if (!feature?.geometry && feature?.properties?._surveyor_local_attributes_only) {
      const hydrated = await getPropertyGeometryForSelection(feature, options.stateCode || options.municipality?.uf || propertySearchStateCode());
      if (hydrated?.geometry) {
        // Somente depois de confirmar a identidade usar os atributos oficiais.
        // Os dados locais são auxiliares; jamais sobrescrever nome, CAR ou
        // município oficial com valores atribuídos pelo índice municipal.
        feature = {
          ...hydrated,
          properties: {
            ...(hydrated.properties || {}),
            _surveyor_local_cache: feature.properties?._surveyor_local_cache || '',
            _surveyor_local_identity: feature.properties?._surveyor_local_identity || ''
          }
        };
      }
    }
    // Se outro item foi escolhido durante o WFS, a resposta antiga jamais
    // altera o destaque vermelho nem a câmera do mapa.
    if (options.isCurrentSelection && !options.isCurrentSelection()) return false;
    if (!feature?.geometry) {
      toast('O imóvel foi encontrado nos dados locais, mas a geometria oficial não pôde ser carregada agora.', 'info');
      return false;
    }
    clearCoordinateSearchResult({ clearInput: false });
    window.SurveyorMapWorkspace?.clearCarHighlight?.({ cancelSearch: true });
    clearPropertyNameSearchResult();
    // Ao escolher um item na lista, apenas localizamos/destacamos a geometria.
    // O painel fundiário só deve abrir quando o usuário clicar no polígono vermelho.
    if (options.preserveSearchResults) closeRuralInfoPanel();

    const stateCode = normalizedCatalogState(options.stateCode || options.municipality?.uf || propertySearchStateCode());
    const sourceLayer = stateCode === 'BA'
      ? {
          name: 'Imóvel Rural - Limites de Propriedade',
          sourceName: 'CEFIR / INEMA — GeoBahia',
          serviceUrl: 'https://geoserver.inema.ba.gov.br/geoserver/wms',
          metadata: { layerName: OFFICIAL_PROPERTY_BOUNDARY_LAYER, stateCode: 'BA' },
          styleColor: '#FFD400'
        }
      : {
          name: 'Imóvel Rural - Limites de Propriedade',
          sourceName: `CAR / SICAR — ${stateCode}`,
          serviceUrl: 'https://geoserver.car.gov.br/geoserver/sicar/wms',
          metadata: { layerName: `sicar:sicar_imoveis_${stateCode.toLowerCase()}`, stateCode },
          styleColor: '#FFD400'
        };

    const halo = L.geoJSON(feature, {
      pane: 'liveDrawPane', interactive: false,
      style: { color: '#ffffff', weight: 6, opacity: .95, fillOpacity: 0 }
    }).addTo(propertyNameSearchGroup);
    const highlight = L.geoJSON(feature, {
      pane: 'liveDrawPane', interactive: true,
      style: { color: '#dc2626', weight: 3, opacity: 1, fillColor: '#ef4444', fillOpacity: .14 }
    }).addTo(propertyNameSearchGroup);
    highlight.eachLayer?.((layer) => {
      layer.on?.('click', async (event) => {
        try { L.DomEvent?.stopPropagation?.(event?.originalEvent); } catch {}
        const latlng = event?.latlng || propertyFeaturePoint(feature);
        if (!latlng) return;
        await openRuralInformationFromContext({ feature, sourceLayer, renderedLayer: highlight, latlng });
      });
    });
    const bounds = highlight.getBounds?.() || halo.getBounds?.();
    // Saltos entre regiões distantes não devem aguardar animação do Leaflet.
    // As imagens de satélite ainda dependem de rede, mas o centro/zoom do imóvel
    // é aplicado de imediato após a geometria ficar disponível.
    if (bounds?.isValid?.()) {
      const destination = bounds.pad(.22);
      const requestedZoom = Math.min(18, map.getBoundsZoom(destination));
      const alreadyCentered = map.getCenter().distanceTo(bounds.getCenter()) < 45
        && Math.abs(map.getZoom() - requestedZoom) < 0.25;
      if (!alreadyCentered) map.fitBounds(destination, { maxZoom: 18, animate: false });
    }

    const name = propertyNameFromFeature(feature) || options.query || 'Imóvel rural';
    lastSelectedRuralPropertyName = name;
    lastSelectedRuralPropertyState = stateCode;
    updateSelectedPropertyNameInLayerCards();
    if (els.coordSearch) els.coordSearch.value = name;
    if (options.preserveSearchResults) {
      showSearchSuggestionBox();
      updatePropertyContextResultActiveState({ scroll: false });
    } else {
      hideCitySuggestions();
    }
    // Não consulte/abra o painel automaticamente aqui. O clique no polígono
    // destacado é a ação explícita que abre Informações do imóvel.
    notifyMapSearchResult('property-name');
    const municipalityLabel = options.municipality?.name ? ` em ${options.municipality.name} - ${stateCode}` : '';
    toast(`Imóvel “${name}” localizado${municipalityLabel}.`, 'success');
    return true;
  }

  async function fetchLocalRuralProperties(query, municipality, stateCode) {
    const cache = window.SurveyorPropertyLocalCache;
    if (!cache?.search) return [];
    try {
      const uf = normalizedCatalogState(stateCode);
      if (!municipality) return [];
      const manifest = await cache.getManifest?.(uf, municipality);
      if (!manifest?.generation) return [];
      return await cache.search({ stateCode: uf, query, municipality, limit: 1000 });
    } catch (error) {
      console.debug('[Surveyor] Pesquisa rápida local indisponível:', error?.message || error);
      return [];
    }
  }

  async function fetchRuralPropertiesByName(query, municipality, stateCode) {
    const uf = normalizedCatalogState(stateCode);

    // Pesquisa rápida local tem prioridade quando a base da UF está instalada.
    // A consulta online oficial continua como fallback para manter atualização
    // e disponibilidade mesmo quando o usuário não instalou os dados locais.
    const localFeatures = await fetchLocalRuralProperties(query, municipality, uf);
    if (localFeatures.length) return localFeatures;
    // Uma base municipal já instalada permite responder "nenhum imóvel"
    // imediatamente. Evita disparar WFS nacional lento quando o nome não
    // existe no índice local. A consulta online continua para cidades sem base.
    if (municipality && window.SurveyorPropertyLocalCache?.getManifest) {
      try {
        const manifest = await window.SurveyorPropertyLocalCache.getManifest(uf, municipality);
        if (manifest?.status === 'installed' && manifest?.generation) return [];
      } catch (error) {
        console.debug('[Surveyor] Não foi possível verificar o índice local:', error?.message || error);
      }
    }

    // R26.3.59 — a busca deve usar a mesma fonte da camada visual de Limites
    // de Propriedade. Na Bahia essa fonte é CEFIR/INEMA (GeoBahia), que publica
    // a denominação e a geometria consultadas no mapa. O SICAR fica somente como
    // contingência quando o CEFIR realmente não retorna o imóvel.
    if (uf === 'BA') {
      const cefirFeatures = await fetchCefirPropertiesByName(query, municipality);
      if (cefirFeatures.length) return cefirFeatures;
    }

    return fetchSicarPropertiesByName(query, municipality, uf);
  }

  async function locateRuralPropertyByName(value, options = {}) {
    if (!canUseOfficialPropertySearch()) return officialPropertySearchLocked();
    const query = sanitizePropertyNameSearch(value);
    if (query.length < 3) return false;
    const municipality = options.municipality || null;
    const stateCode = normalizedCatalogState(options.stateCode || municipality?.uf || propertySearchStateCode());
    setSmartSearchModeBadge('property', municipality ? `IMÓVEL · ${stateCode}` : 'IMÓVEL');
    hideCitySuggestions();
    toast(`Pesquisando imóvel “${query}”${municipality ? ` em ${municipality.name} - ${stateCode}` : ''} nas bases oficiais…`, 'info');
    try {
      const features = await fetchRuralPropertiesByName(query, municipality, stateCode);
      if (!features.length) {
        setSmartSearchModeBadge('', '');
        return false;
      }
      if (options.returnResults === true) return features;
      await focusRuralPropertySearchFeature(features[0], { query, municipality, stateCode });
      if (features.length > 1) toast(`${features.length} imóveis compatíveis encontrados${municipality ? ` em ${municipality.name} - ${stateCode}` : ''}. Exibindo o mais compatível.`, 'success');
      return true;
    } catch (error) {
      console.warn('[Surveyor] Busca de imóvel por nome:', error);
      setSmartSearchModeBadge('', '');
      toast('Não foi possível consultar imóveis por nome nas bases oficiais agora.', 'error');
      return false;
    }
  }

  async function locate() {
    if (document.body.classList.contains('surveyor-territorial-mode')) {
      const territorialSearch = window.SurveyorTerritorialNavigator?.search;
      if (typeof territorialSearch === 'function') return territorialSearch(String(els.coordSearch?.value || ''));
    }
    closeExplicitSearchModeMenus();
    let value = String(els.coordSearch?.value || '').trim();
    if (!value) {
      toast(`Digite ${activeSearchMode === 'property' ? 'o nome do imóvel' : activeSearchMode === 'city' ? 'a cidade' : activeSearchMode === 'car' ? 'o código CAR' : 'a coordenada'}.`, 'info');
      els.coordSearch?.focus();
      return;
    }

    if (activeSearchMode === 'car') {
      if (!canUseOfficialPropertySearch()) return officialPropertySearchLocked();
      hideCitySuggestions();
      if (!isCompleteCarDraft(value)) {
        renderCarSmartSuggestion(value);
        toast('Complete o número do CAR para consultar.', 'info');
        els.coordSearch?.focus();
        return;
      }
      clearTimeout(carAutoSearchTimer);
      const searchCar = window.SurveyorMapWorkspace?.searchCar;
      if (typeof searchCar === 'function') {
        lastAutoCarValue = normalizeCarDraft(value);
        await searchCar(value);
      } else {
        toast('A consulta CAR ainda está sendo inicializada. Tente novamente.', 'info');
      }
      return;
    }

    if (activeSearchMode === 'coordinate') {
      applySelectedCoordinateFormatting({ force: true });
      value = String(els.coordSearch?.value || '').trim();
      const coordinate = parseCoordinateForSelectedMode(value);
      if (!coordinate) {
        toggleCoordinateSubtypeMenu(true);
        toast(`Complete a coordenada no formato ${coordinateFormatById()?.short || 'selecionado'}.`, 'info');
        els.coordSearch?.focus();
        return;
      }
      focusCoordinateSearchResult(coordinate.lat, coordinate.lng, { label: coordinate.format || coordinateFormatById()?.label || 'Coordenada', zoom: 17 });
      return;
    }

    if (activeSearchMode === 'property') {
      if (!canUseOfficialPropertySearch()) return officialPropertySearchLocked();
      const query = sanitizePropertyNameSearch(value);
      if (query.length < 2) {
        toast('Digite o nome do imóvel.', 'info');
        els.coordSearch?.focus();
        return;
      }
      propertyContextSearchState.query = query;
      await ensureCityCache();
      if (propertyContextSearchState.municipality) {
        await runPropertyContextSearch();
      } else {
        renderPropertyContextAssistant(query, { focusMunicipality: true, force: true });
        const descriptor = catalogStateDescriptor(propertySearchStateCode());
        toast(`Informe o município de ${descriptor.name} para pesquisar o imóvel.`, 'info');
      }
      return;
    }

    // Modo CIDADE é exclusivo para município/localidade. Nunca tenta imóvel,
    // CAR ou coordenada como fallback.
    if (selectedCitySearchContext?.city) {
      const foundLocality = await locateLocalityFromText(value);
      if (foundLocality) return;
      toast(`Não encontrei “${value}” dentro de ${selectedCitySearchContext.city.name}.`, 'info');
      return;
    }
    const foundCity = await locateCityFromText(value);
    if (!foundCity) toast('Não encontrei essa cidade. Confira o nome e tente novamente.', 'error');
  }

  els.locateBtn.onclick = () => locate().catch((error) => {
    console.warn('[Surveyor] Falha na pesquisa do mapa:', error);
    toast('A pesquisa não conseguiu concluir agora. Tente novamente.', 'error');
  });
  window.SurveyorMapSearch = {
    ...(window.SurveyorMapSearch || {}),
    search: () => locate(),
    clearActiveResult: clearActiveMapSearchResult,
    clearCoordinateResult: clearCoordinateSearchResult,
    clearPropertyNameResult: clearPropertyNameSearchResult,
    notifyResult: notifyMapSearchResult,
    refreshExplicitMode: () => updateExplicitSearchModeLayout()
  };
  function setMapSearchOpen(open, focus = false) {
    if (!els.mapSearchBar || !els.toggleMapSearch) return;
    els.mapSearchBar.classList.toggle('hidden', !open);
    els.mapSearchBar.setAttribute('aria-hidden', String(!open));
    els.toggleMapSearch.classList.toggle('active', open);
    els.toggleMapSearch.setAttribute('aria-expanded', String(open));
    els.toggleMapSearch.setAttribute('aria-label', open ? 'Fechar pesquisa de localização' : 'Abrir pesquisa de localização');
    els.toggleMapSearch.title = open ? 'Fechar pesquisa' : 'Pesquisar localização';
    if (!open) hideCitySuggestions();
    if (open && focus) setTimeout(() => els.coordSearch?.focus(), 0);
  }
  els.toggleMapSearch?.addEventListener('click', () => {
    const open = els.mapSearchBar?.classList.contains('hidden');
    setMapSearchOpen(Boolean(open), Boolean(open));
  });
  ensureSmartSearchModeBadge();
  els.coordSearch?.addEventListener('focus', () => {
    if (document.body.classList.contains('surveyor-territorial-mode')) return;
    const value = String(els.coordSearch?.value || '').trim();
    if (!value) return;
    if (activeSearchMode === 'coordinate') {
      applySelectedCoordinateFormatting();
      return;
    }
    if (activeSearchMode === 'car') {
      renderCarSmartSuggestion(value);
      return;
    }
    if (activeSearchMode === 'property') {
      ensureCityCache().then(() => renderPropertyContextAssistant(value, { force: true })).catch(() => renderPropertyContextAssistant(value, { force: true }));
      return;
    }
    if (selectedCitySearchContext?.city) {
      updateLocalitySuggestions(value).catch((error) => console.debug('[Surveyor] Autocomplete de localidade no foco:', error?.message || error));
      return;
    }
    updateCitySuggestions().catch((error) => console.debug('[Surveyor] Autocomplete municipal no foco:', error?.message || error));
  });
  els.coordSearch?.addEventListener('input', () => {
    if (document.body.classList.contains('surveyor-territorial-mode')) return;
    scheduleCitySuggestions();
  });
  els.coordSearch?.addEventListener('blur', () => {
    if (document.body.classList.contains('surveyor-territorial-mode')) return;
    if (activeSearchMode === 'coordinate') applySelectedCoordinateFormatting({ force: true });
  });
  els.coordSearch?.addEventListener('keydown', (e) => {
    if (document.body.classList.contains('surveyor-territorial-mode')) return;
    if (e.key === 'ArrowDown' && citySuggestItems.length) {
      e.preventDefault();
      updateCityActiveItem(citySuggestIndex + 1);
      return;
    }
    if (e.key === 'ArrowUp' && citySuggestItems.length) {
      e.preventDefault();
      updateCityActiveItem(citySuggestIndex - 1);
      return;
    }
    if (e.key === 'Escape') {
      const modeMenuOpen = document.getElementById('svSearchModeMenu')?.classList.contains('hidden') === false;
      const subtypeMenuOpen = document.getElementById('svCoordinateSubtypeMenu')?.classList.contains('hidden') === false;
      if (modeMenuOpen || subtypeMenuOpen) closeExplicitSearchModeMenus();
      else if (els.citySuggestBox && !els.citySuggestBox.classList.contains('hidden')) hideCitySuggestions();
      else setMapSearchOpen(false);
      return;
    }
    if (e.key === 'Enter') {
      e.preventDefault();
      if (citySuggestIndex >= 0 && citySuggestItems[citySuggestIndex]) selectSearchSuggestion(citySuggestItems[citySuggestIndex]);
      else locate();
    }
  });
  function propertySearchOverlayIsPersistent() {
    if (!els.citySuggestBox || els.citySuggestBox.classList.contains('hidden')) return false;
    return els.citySuggestBox.classList.contains('property-context-box')
      || Boolean(els.citySuggestBox.querySelector('.property-context-assistant, .property-context-results'));
  }

  document.addEventListener('pointerdown', (event) => {
    const wrap = els.coordSearch?.closest('.geo-search-input-wrap');
    if (wrap && !wrap.contains(event.target)) closeExplicitSearchModeMenus();
    if (!els.citySuggestBox || !els.coordSearch) return;
    if (event.target === els.coordSearch || els.citySuggestBox.contains(event.target) || wrap?.contains(event.target)) return;
    // Sugestões simples de cidade funcionam como autocomplete e podem fechar ao
    // clicar fora. A busca contextual de imóvel é um fluxo de trabalho: mantém
    // município, estado, status e resultados visíveis até o usuário concluir,
    // escolher um imóvel, pressionar Esc ou trocar explicitamente de busca.
    if (propertySearchOverlayIsPersistent()) return;
    hideCitySuggestions();
  });
  window.addEventListener('resize', () => {
    if (els.citySuggestBox && !els.citySuggestBox.classList.contains('hidden')) mountSearchSuggestionOverlay();
  });
  window.addEventListener('scroll', () => {
    if (els.citySuggestBox && !els.citySuggestBox.classList.contains('hidden')) mountSearchSuggestionOverlay();
  }, true);

  // Hidrata municípios em segundo plano assim que o mapa fica pronto; a caixa
  // já usa o fallback local e não precisa esperar essa requisição para abrir.
  ensureCityCache().catch(() => {});

  els.myLocationBtn.onclick = () => {
    if (!navigator.geolocation) return toast('Geolocalização não disponível.', 'error');
    els.myLocationBtn.disabled = true; els.myLocationBtn.textContent = 'Localizando…';
    navigator.geolocation.getCurrentPosition((pos) => {
      const lat = Number(pos?.coords?.latitude);
      const lng = Number(pos?.coords?.longitude);
      try {
        selectedCoordinateInputMode = 'dd';
        try { localStorage.setItem(COORDINATE_MODE_STORAGE_KEY, 'dd'); } catch {}
        selectExplicitSearchMode('coordinate', { clearInput: false, focus: false, openCoordinateFormats: false });
        els.coordSearch.value = `${lat.toFixed(7)}, ${lng.toFixed(7)}`;
        updateExplicitSearchModeLayout();
        focusCoordinateSearchResult(lat, lng, { label: 'Minha localização', zoom: 17 });
      } catch (error) {
        console.warn('[Surveyor] Minha localização:', error);
        toast('A localização foi obtida, mas não foi possível centralizar o mapa.', 'error');
      } finally {
        resetLocation();
      }
    }, (err) => {
      toast(err.code === 1 ? 'Permissão de localização negada.' : 'Não foi possível obter a localização.', 'error');
      resetLocation();
    }, { enableHighAccuracy: true, timeout: 12000, maximumAge: 15000 });
  };
  function resetLocation() { els.myLocationBtn.disabled = false; els.myLocationBtn.textContent = 'Minha localização'; }

  function referenceLayerEntries() {
    return referenceCollections.map((entry) => {
      if (entry.localLarge) return { id: entry.id, name: entry.name, visible: referenceGroup.hasLayer(entry.layer), server: false, localLarge: true, meta: entry.meta, geojson: null };
      if (!entry.server) return { id: entry.id, name: entry.name, visible: referenceGroup.hasLayer(entry.layer), server: false, geojson: entry.geojson };
      const visibleFeatures = entry.layer.toGeoJSON()?.features || [];
      const snapshot = { type: 'FeatureCollection', features: visibleFeatures.slice(0, 120) };
      return { id: entry.id, name: entry.name, visible: referenceGroup.hasLayer(entry.layer), server: true, meta: entry.meta, geojson: snapshot };
    });
  }

  function referencePopup(properties = {}) {
    const name = properties.DENOMINACA || properties.DENOMINACAO || properties.NOME || 'Imóvel cadastrado';
    const rows = [
      ['Município', properties.MUNICIPIO],
      ['Área registrada', properties.AREA_REGIS != null ? `${properties.AREA_REGIS} ha` : null],
      ['Status', properties.STATUS],
      ['CAR', properties.NUMERO_CAR],
      ['Código', properties.IDE_IMOVEL || properties.COD_IMOVEL]
    ].filter(([, value]) => value !== undefined && value !== null && value !== '');
    return `<div class="reference-popup"><b>${escapeHtmlLocal(name)}</b>${rows.map(([label, value]) => `<span><strong>${escapeHtmlLocal(label)}:</strong> ${escapeHtmlLocal(value)}</span>`).join('')}</div>`;
  }

  function escapeHtmlLocal(value) {
    return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  }

  function normalizeImportedGeoJSON(data, sourceLabel = 'arquivo importado') {
    if (!window.GeoRuralCRS?.normalizeGeoJSON) return data;
    let sourceCrs = '';
    try {
      const result = window.GeoRuralCRS.normalizeGeoJSON(data);
      if (result.changed) {
        const action = result.axisSwapped
          ? 'ordem longitude/latitude corrigida'
          : `reprojetado de ${result.sourceCrs} para EPSG:4326`;
        console.info(`[GeoRural CRS] ${sourceLabel}: ${action}.`);
        toast(`${sourceLabel}: ${action}.`, 'success');
      }
      return result.geojson;
    } catch (error) {
      if (error?.code !== 'CRS_REQUIRED') throw error;
      const suggested = error?.analysis?.likelyUtmSouth ? 'EPSG:31984' : 'EPSG:3857';
      sourceCrs = window.prompt(
        `${sourceLabel}: as coordenadas estão projetadas e o arquivo não informa o EPSG.\n\n`
        + 'Digite o CRS de origem. Para SIRGAS 2000 / UTM zona 24S use EPSG:31984.',
        suggested
      );
      if (!sourceCrs) throw new Error('Importação cancelada: informe o EPSG de origem para evitar deslocamento da geometria.');
      const result = window.GeoRuralCRS.normalizeGeoJSON(data, { sourceCrs });
      toast(`${sourceLabel}: reprojetado de ${result.sourceCrs} para EPSG:4326.`, 'success');
      return result.geojson;
    }
  }

  const referenceCanvasRenderer = L.canvas({ padding: 0.25, tolerance: 3 });

  function makeReferenceLayer() {
    return L.geoJSON(null, {
      pane: 'referencePane',
      renderer: referenceCanvasRenderer,
      style: () => referenceStyle(),
      pointToLayer: (_feature, latlng) => L.marker(latlng, { icon: referenceMarkerIcon() }),
      onEachFeature: (feature, layer) => {
        layer.bindPopup(referencePopup(feature.properties || {}));
        const label = feature.properties?.DENOMINACA || feature.properties?.DENOMINACAO || feature.properties?.NOME;
        if (label) layer.bindTooltip(String(label), { sticky: true, className: 'vertex-tooltip' });
      }
    });
  }

  function addReferenceCollection(fc, name = 'Camada de referência', fit = true) {
    const normalized = normalizeImportedGeoJSON(fc, name);
    const layer = makeReferenceLayer();
    layer.addData(normalized);
    referenceGroup.addLayer(layer);
    const entry = { id: id(), name, geojson: normalized, layer, server: false, lastReturned: normalized?.features?.length || 0 };
    referenceCollections.push(entry);
    if (fit && layer.getBounds().isValid()) map.fitBounds(layer.getBounds().pad(0.08));
    refresh();
    return entry;
  }

  function addLocalLargeReferenceLayer(meta, name = 'Camada local grande', fit = true) {
    if (!meta?.sessionId) throw new Error('A camada grande não retornou uma sessão local válida.');
    const layer = makeReferenceLayer();
    referenceGroup.addLayer(layer);
    const entry = {
      id: id(), name, geojson: null, layer, server: false, localLarge: true,
      sessionId: meta.sessionId,
      meta: { featureCount: Number(meta.featureCount || 0), estimatedBytes: Number(meta.estimatedBytes || 0), bounds: meta.bounds || null },
      lastReturned: 0, truncated: false, querySerial: 0
    };
    referenceCollections.push(entry);
    if (fit && Array.isArray(meta.bounds) && meta.bounds.length === 4) {
      const [west, south, east, north] = meta.bounds.map(Number);
      if ([west, south, east, north].every(Number.isFinite)) {
        map.fitBounds([[south, west], [north, east]], { padding: [24, 24], maxZoom: 14 });
      }
    }
    refresh();
    return entry;
  }

  function disposeLocalLargeReference(entry) {
    if (!entry?.localLarge || !entry.sessionId) return;
    try { window.GeoRuralLayerImport?.disposeLargeSession?.(entry.sessionId); } catch {}
  }

  function disposeAllLocalLargeReferences() {
    referenceCollections.filter((entry) => entry?.localLarge).forEach(disposeLocalLargeReference);
  }

  function addServerReferenceLayer(meta) {
    if (referenceCollections.some((entry) => entry.server && entry.id === meta.id)) return;
    const layer = makeReferenceLayer();
    referenceGroup.addLayer(layer);
    referenceCollections.push({ id: meta.id, name: meta.name, meta, layer, server: true, lastReturned: 0, truncated: false });
    refresh();
  }

  function collection() {
    return {
      type: 'FeatureCollection',
      properties: { propertyName: els.propertyName.value.trim(), ownerName: els.ownerName.value.trim(), ownerCpf: els.ownerCpf?.value?.trim?.() || '', ownerRg: els.ownerRg?.value?.trim?.() || '', additionalOwner: additionalOwnerFromForm(), city: els.city.value.trim(), uf: els.uf.value, description: els.projectDescription?.value?.trim?.() || '', manualDimensions: manualDimensionItems(), exportedAt: new Date().toISOString() },
      features: drawn.getLayers().map((layer) => { const f = layer.toGeoJSON(); f.properties = { ...metadata(layer) }; return f; })
    };
  }

  function loadCollection(data, fit = true) {
    const input = data.type === 'FeatureCollection' ? data : { type: 'FeatureCollection', features: [data] };
    const fc = normalizeImportedGeoJSON(input, 'Geometria do projeto');
    if (!Array.isArray(fc.features)) throw new Error('GeoJSON inválido.');
    fc.features.forEach((feature) => {
      L.geoJSON(feature, {
        style: () => styleFor(feature.properties?.category || 'outros'),
        pointToLayer: (f, latlng) => projectPointLayer(f, latlng)
      }).eachLayer((layer) => addLayer(layer, feature.properties || {}));
    });
    if (fit && drawn.getLayers().length && drawn.getBounds().isValid()) map.fitBounds(drawn.getBounds().pad(0.1));
    refresh();
  }

  function additionalOwnerFromForm() {
    const name = String(els.additionalOwnerName?.value || '').trim();
    if (!name) return null;
    return {
      name,
      cpfCnpj: String(els.additionalOwnerCpf?.value || '').trim(),
      rg: String(els.additionalOwnerRg?.value || '').trim()
    };
  }

  function loadAdditionalOwner(project) {
    const value = project?.metadata?.additionalOwner || project?.additionalOwner || {};
    const name = String(value?.name || '').trim();
    if (els.additionalOwnerName) els.additionalOwnerName.value = name;
    if (els.additionalOwnerCpf) els.additionalOwnerCpf.value = name ? String(value?.cpfCnpj || '') : '';
    if (els.additionalOwnerRg) els.additionalOwnerRg.value = name ? String(value?.rg || '') : '';
    if (els.additionalOwnerSection) els.additionalOwnerSection.open = Boolean(name);
  }
  $('removeAdditionalOwner')?.addEventListener('click', () => loadAdditionalOwner(null));

  function remoteProjectPayload() {
    migrateLegacyServitudePolygons();
    renderServitudeDerivedOverlays();
    const center = map.getCenter();
    const projectLayers = drawn.getLayers();
    const totals = projectLayers.reduce((acc, layer) => {
      const metric = metrics(layer);
      acc.areaM2 += Number(metric.areaM2 || 0);
      acc.perimeterM += Number(metric.perimeterM || 0);
      acc.vertexCount += Number(metric.vertices || 0);
      return acc;
    }, { areaM2: 0, perimeterM: 0, vertexCount: 0 });
    return {
      name: els.propertyName.value.trim(),
      propertyName: els.propertyName.value.trim() || null,
      ownerName: els.ownerName.value.trim() || null,
      registrationNumber: null,
      municipality: els.city.value.trim() || null,
      stateCode: els.uf.value || null,
      status: 'active',
      expectedUpdatedAt: currentProjectId ? currentProjectRevision : '',
      description: els.projectDescription?.value?.trim?.() || 'Projeto cartográfico criado no mapa do Surveyor.',
      centerLatitude: Number(center.lat.toFixed(7)),
      centerLongitude: Number(center.lng.toFixed(7)),
      defaultZoom: map.getZoom(),
      metadata: sanitizeForJson({
        ...currentProjectMetadata,
        source: 'georural-map',
        ownerCpf: els.ownerCpf?.value?.trim?.() || null,
        ownerRg: els.ownerRg?.value?.trim?.() || null,
        additionalOwner: additionalOwnerFromForm(),
        featureCount: projectLayers.length,
        areaHa: totals.areaM2 / 10000,
        perimeterM: totals.perimeterM,
        vertexCount: totals.vertexCount,
        referenceLayers: referenceLayerEntries().map((entry) => ({ id: entry.id, name: entry.name, server: Boolean(entry.server) })),
        glebaState: serializeGlebaProjectState(),
        savedAt: new Date().toISOString()
      })
    };
  }

  function remoteFeaturePayloads() {
    migrateLegacyServitudePolygons();
    return drawn.getLayers().filter((layer) => !isLegacyGeneratedServitudeLayer(layer)).map((layer, index) => {
      const feature = layer.toGeoJSON();
      const props = { ...metadata(layer) };
      const m = metrics(layer);
      return {
        name: props.name || `Elemento ${index + 1}`,
        category: props.category || 'outros',
        geometryType: feature.geometry.type,
        geoJson: sanitizeForJson(feature.geometry),
        areaHectares: m.areaHa || null,
        perimeterMeters: m.perimeterM || null,
        vertexCount: m.vertices,
        style: serializableDrawStyle(props.category || 'outros', props),
        properties: sanitizeForJson(props) || {},
        sortOrder: index,
        isVisible: true
      };
    });
  }

  // O mapa e o editor técnico verificam o MESMO conteúdo canônico remoto.
  // Nunca confirmar um projeto somente pela geometria: confrontantes e estilo
  // podem ter sido alterados sem mover nenhum vértice.
  async function verifyRemoteProjectPersistence(projectId, expectedFeatures = [], expectedProject = {}) {
    const verify = window.GeoRuralProjects?.verifySavedBundle;
    if (!verify) throw new Error('Verificação remota do projeto indisponível. O salvamento não foi confirmado.');
    return verify(projectId, expectedFeatures, expectedProject);
  }

  function invalidateDocumentProjectCache() {
    try { window.GeoRuralProjects?.invalidate?.(); } catch (_error) {}
  }

  async function clearRecoveryDraftAliases(previousProjectId = null, nextProjectId = currentProjectId) {
    const ids = new Set([
      String(previousProjectId || 'novo'),
      String(nextProjectId || 'novo')
    ]);
    for (const id of ids) {
      const key = recoveryDraftKey(id === 'novo' ? null : id);
      await window.GeoRuralProjects?.deleteRecoveryDraft?.(key).catch?.(() => null);
      try { sessionStorage.removeItem(key); } catch {}
    }
    setRecoveryBaseline();
  }

  async function loadRemoteProject(projectId) {
    const auth = window.GeoRuralAuth;
    if (!auth) throw new Error('Módulo de autenticação não encontrado.');
    toast('Abrindo projeto salvo na nuvem...');
    const { project, features } = await auth.getProject(projectId);
    if (!project) throw new Error('Projeto não encontrado.');

    drawn.clearLayers();
    clearProjectHistory();
    disposeAllLocalLargeReferences();
    referenceGroup.clearLayers();
    referenceCollections.length = 0;
    clearGlebaCutLines();
    clearSelection();

    els.propertyName.value = project.propertyName || project.name || '';
    els.ownerName.value = project.ownerName || '';
    if (els.ownerCpf) els.ownerCpf.value = project.ownerCpf || project.metadata?.ownerCpf || '';
    if (els.ownerRg) els.ownerRg.value = project.ownerRg || project.metadata?.ownerRg || '';
    loadAdditionalOwner(project);
    els.city.value = project.municipality || '';
    if (project.stateCode) els.uf.value = project.stateCode;
    if (els.projectDescription) els.projectDescription.value = project.description || '';

    const geojson = {
      type: 'FeatureCollection',
      features: (features || []).map((item) => ({
        type: 'Feature',
        properties: { ...(item.properties || {}), name: item.name, category: item.category, remoteFeatureId: item.id },
        geometry: item.geoJson
      })).filter((item) => item.geometry)
    };
    if (geojson.features.length) loadCollection(geojson, false);
    restoreGlebaProjectState(project.metadata?.glebaState || {});
    lastGlebaFeatureCollection = currentGlebaFeatureCollection();
    renderGlebaSummary();

    if (project.centerLatitude != null && project.centerLongitude != null) {
      map.setView([project.centerLatitude, project.centerLongitude], project.defaultZoom ?? 14);
    } else if (drawn.getLayers().length && drawn.getBounds().isValid()) {
      map.fitBounds(drawn.getBounds().pad(0.12));
    }

    currentProjectId = project.id;
    currentProjectRevision = String(project.revision || project.updatedAt || '');
    currentProjectMetadata = project.metadata || {};
    renderManualDimensions();
    history.replaceState(null, '', projectMapUrl(project.id));
    clearSelection();
    refresh();
    try { window.dispatchEvent(new CustomEvent('surveyor:project-loaded', { detail: { projectId: currentProjectId } })); } catch {}
    toast('Projeto carregado da sua nuvem.', 'success');
  }

  els.saveBtn.onclick = async () => {
    const title = els.propertyName.value.trim();
    if (!title) return toast('Informe o nome do projeto.', 'error');
    const auth = window.GeoRuralAuth;
    if (!auth?.currentUser?.()) return toast('Sua sessão expirou. Entre novamente.', 'error');

    const originalText = els.saveBtn.textContent;
    const previousProjectId = currentProjectId;
    const projectPayload = remoteProjectPayload();
    const featurePayloads = remoteFeaturePayloads();
    els.saveBtn.disabled = true;
    els.saveBtn.textContent = 'Salvando...';
    try { window.dispatchEvent(new CustomEvent('surveyor:save-start')); } catch {}
    try {
      const result = await auth.saveProjectBundle(previousProjectId, projectPayload, featurePayloads);
      const savedProjectId = result?.project?.id;
      if (!savedProjectId) throw new Error('A nuvem não retornou o identificador do projeto salvo.');
      const confirmed = await verifyRemoteProjectPersistence(savedProjectId, featurePayloads, projectPayload);
      currentProjectId = savedProjectId;
      currentProjectRevision = String(confirmed.project?.revision || confirmed.project?.updatedAt || result.project?.revision || result.project?.updatedAt || '');
      currentProjectMetadata = { ...(projectPayload.metadata || {}), ...(confirmed.project?.metadata || {}), ...(result.project?.metadata || {}) };
      history.replaceState(null, '', projectMapUrl(currentProjectId));
      await clearRecoveryDraftAliases(previousProjectId, currentProjectId);
      invalidateDocumentProjectCache();
      try { window.dispatchEvent(new CustomEvent('surveyor:save-success', { detail: { projectId: currentProjectId } })); } catch {}
      toast(`Projeto salvo e verificado na nuvem com ${featurePayloads.length} elemento(s).`, 'success');
    } catch (error) {
      console.error(error);
      try { window.dispatchEvent(new CustomEvent('surveyor:save-error', { detail: { message: error?.message || '' } })); } catch {}
      toast(error.message || 'Não foi possível confirmar o salvamento na nuvem. O rascunho local foi preservado neste navegador.', 'error');
    } finally {
      els.saveBtn.disabled = false;
      els.saveBtn.textContent = originalText;
    }
  };

  if (openedFromCarModule && els.returnToCarBtn) {
    els.returnToCarBtn.classList.remove('hidden');
    els.returnToCarBtn.addEventListener('click', async () => {
      if (!currentProjectId) {
        toast('Salve o projeto antes de voltar ao módulo CAR.', 'error');
        return;
      }
      const auth = window.GeoRuralAuth;
      if (!auth?.currentUser?.()) {
        toast('Sua sessão expirou. Entre novamente.', 'error');
        return;
      }
      const originalText = els.returnToCarBtn.textContent;
      els.returnToCarBtn.disabled = true;
      els.returnToCarBtn.textContent = 'Salvando...';
      try {
        const previousProjectId = currentProjectId;
        const projectPayload = remoteProjectPayload();
        const featurePayloads = remoteFeaturePayloads();
        const result = await auth.saveProjectBundle(previousProjectId, projectPayload, featurePayloads);
        const savedProjectId = result?.project?.id || previousProjectId;
        await verifyRemoteProjectPersistence(savedProjectId, featurePayloads, projectPayload);
        currentProjectId = savedProjectId;
        currentProjectRevision = String(result.project?.revision || result.project?.updatedAt || '');
        currentProjectMetadata = { ...(projectPayload.metadata || {}), ...(result.project?.metadata || {}) };
        await clearRecoveryDraftAliases(previousProjectId, currentProjectId);
        invalidateDocumentProjectCache();
        location.href = `/car/?project=${encodeURIComponent(currentProjectId)}`;
      } catch (error) {
        console.error(error);
        toast(error.message || 'Não foi possível salvar as alterações antes de voltar ao CAR.', 'error');
        els.returnToCarBtn.disabled = false;
        els.returnToCarBtn.textContent = originalText;
      }
    });
  }


  const PROJECT_TEMPLATE_KEY = 'surveyor-project-templates-v219292';
  async function ensureSavedProject() {
    if (currentProjectId) return currentProjectId;
    if (!els.propertyName.value.trim()) throw new Error('Salve o projeto primeiro ou informe o nome do projeto.');
    const auth = window.GeoRuralAuth;
    const projectPayload = remoteProjectPayload();
    const featurePayloads = remoteFeaturePayloads();
    const result = await auth.saveProjectBundle(null, projectPayload, featurePayloads);
    const savedProjectId = result?.project?.id;
    if (!savedProjectId) throw new Error('A nuvem não retornou o identificador do projeto salvo.');
    await verifyRemoteProjectPersistence(savedProjectId, featurePayloads, projectPayload);
    currentProjectId = savedProjectId;
    currentProjectRevision = String(result.project?.revision || result.project?.updatedAt || '');
    currentProjectMetadata = { ...(projectPayload.metadata || {}), ...(result.project?.metadata || {}) };
    history.replaceState(null, '', projectMapUrl(currentProjectId));
    await clearRecoveryDraftAliases(null, currentProjectId);
    invalidateDocumentProjectCache();
    return currentProjectId;
  }

  els.secureShareBtn?.addEventListener('click', async () => {
    try {
      const auth = window.GeoRuralAuth;
      if (!auth?.currentUser?.()) return toast('Entre novamente para compartilhar.', 'error');
      const id = await ensureSavedProject();
      const days = Number(prompt('Validade do link em dias:', '30') || '30');
      const password = prompt('Senha do link (opcional). Deixe vazio para sem senha:', '') || '';
      const maxAccessCount = Number(prompt('Limite de acessos (0 = ilimitado):', '0') || '0');
      const share = await auth.createProjectShare(id, { expiresInDays: days, password, maxAccessCount, permissionMode: 'readonly' });
      const fullUrl = new URL(share.url || share.publicUrl, location.origin).href;
      await navigator.clipboard?.writeText(fullUrl).catch(() => {});
      alert(`Link seguro criado e copiado:\n\n${fullUrl}\n\nModo: somente leitura\nValidade: ${share.expiresAt || 'não informada'}\nSenha: ${share.passwordProtected ? 'sim' : 'não'}\nLimite: ${share.maxAccessCount || 'ilimitado'}`);
      toast('Link seguro criado.', 'success');
    } catch (error) { console.error(error); toast(error.message || 'Falha ao criar link seguro.', 'error'); }
  });

  els.revokeShareBtn?.addEventListener('click', async () => {
    try {
      if (!currentProjectId) return toast('Nenhum projeto salvo para revogar.', 'error');
      if (!confirm('Revogar instantaneamente todos os links compartilhados deste projeto?')) return;
      await window.GeoRuralAuth.disableProjectShare(currentProjectId);
      toast('Links compartilhados revogados.', 'success');
    } catch (error) { console.error(error); toast(error.message || 'Falha ao revogar links.', 'error'); }
  });

  els.duplicateProjectBtn?.addEventListener('click', async () => {
    try {
      const id = await ensureSavedProject();
      const project = await window.GeoRuralAuth.duplicateProject(id);
      toast('Projeto duplicado. Abrindo cópia...', 'success');
      await loadRemoteProject(project.id);
    } catch (error) { console.error(error); toast(error.message || 'Falha ao duplicar projeto.', 'error'); }
  });

  els.projectVersionsBtn?.addEventListener('click', async () => {
    try {
      if (!currentProjectId) return toast('Salve o projeto para consultar histórico.', 'error');
      const versions = await window.GeoRuralAuth.listProjectVersions(currentProjectId);
      if (!versions.length) return alert('Ainda não há versões gravadas para este projeto. Salve ou edite para gerar histórico.');
      const text = versions.slice(0, 20).map((v, i) => `${i + 1}. ${v.label || v.id} — ${new Date(v.createdAt).toLocaleString('pt-BR')} — ${v.type || 'projeto'} — ${v.featureCount || 0} feição(ões)`).join('\n');
      const choice = prompt(`Histórico de versões:\n\n${text}\n\nDigite o número para restaurar ou deixe vazio para cancelar:`, '');
      const index = Number(choice) - 1;
      if (!choice || !versions[index]) return;
      if (!confirm('Restaurar esta versão? A versão atual será substituída.')) return;
      await window.GeoRuralAuth.restoreProjectVersion(currentProjectId, versions[index].id);
      await loadRemoteProject(currentProjectId);
      toast('Versão restaurada.', 'success');
    } catch (error) { console.error(error); toast(error.message || 'Falha ao consultar/restaurar versões.', 'error'); }
  });

  els.lockProjectBtn?.addEventListener('click', async () => {
    try {
      const id = await ensureSavedProject();
      const locked = !Boolean(currentProjectMetadata?.projectLocked);
      await window.GeoRuralAuth.setProjectLock(id, locked);
      currentProjectMetadata = { ...(currentProjectMetadata || {}), projectLocked: locked };
      toast(locked ? 'Projeto travado contra edições acidentais.' : 'Projeto destravado.', 'success');
    } catch (error) { console.error(error); toast(error.message || 'Falha ao travar/destravar projeto.', 'error'); }
  });

  function readTemplates() { try { return JSON.parse(localStorage.getItem(PROJECT_TEMPLATE_KEY) || '[]'); } catch { return []; } }
  function writeTemplates(items) { localStorage.setItem(PROJECT_TEMPLATE_KEY, JSON.stringify(items.slice(-20))); }
  els.saveTemplateBtn?.addEventListener('click', () => {
    const name = prompt('Nome do modelo de projeto:', els.propertyName.value.trim() || 'Modelo Surveyor');
    if (!name) return;
    const templates = readTemplates();
    templates.push({ id: crypto?.randomUUID?.() || String(Date.now()), name, createdAt: new Date().toISOString(), project: remoteProjectPayload(), features: remoteFeaturePayloads() });
    writeTemplates(templates);
    toast('Modelo de projeto salvo neste navegador.', 'success');
  });
  els.applyTemplateBtn?.addEventListener('click', () => {
    const templates = readTemplates();
    if (!templates.length) return alert('Nenhum modelo salvo neste navegador.');
    const list = templates.map((tpl, i) => `${i + 1}. ${tpl.name}`).join('\n');
    const index = Number(prompt(`Escolha o modelo:\n\n${list}`, '1')) - 1;
    const tpl = templates[index];
    if (!tpl) return;
    if (drawn.getLayers().length && !confirm('Aplicar este modelo vai limpar os desenhos atuais. Continuar?')) return;
    drawn.clearLayers(); clearGlebaCutLines(); clearSelection(); clearProjectHistory();
    els.propertyName.value = tpl.project?.propertyName || tpl.project?.name || '';
    els.ownerName.value = tpl.project?.ownerName || '';
    if (els.ownerCpf) els.ownerCpf.value = tpl.project?.ownerCpf || tpl.project?.metadata?.ownerCpf || '';
    if (els.ownerRg) els.ownerRg.value = tpl.project?.ownerRg || tpl.project?.metadata?.ownerRg || '';
    loadAdditionalOwner(tpl.project);
    if (els.projectDescription) els.projectDescription.value = tpl.project?.description || '';
    els.city.value = tpl.project?.municipality || '';
    if (tpl.project?.stateCode) els.uf.value = tpl.project.stateCode;
    const fc = { type: 'FeatureCollection', features: (tpl.features || []).map((f) => ({ type: 'Feature', properties: { ...(f.properties || {}), name: f.name, category: f.category }, geometry: f.geoJson })).filter((f) => f.geometry) };
    if (fc.features.length) loadCollection(fc, false);
    currentProjectId = null; currentProjectRevision = ''; currentProjectMetadata = {};
    renderManualDimensions();
    refresh();
    toast('Modelo aplicado. Salve para criar um novo projeto.', 'success');
  });

  els.exportZipBtn?.addEventListener('click', async () => {
    try {
      if (!window.JSZip) throw new Error('Biblioteca ZIP não carregada. Recarregue a página com Ctrl+F5.');
      const zip = new JSZip();
      const fc = collection();
      const name = fileBase();
      zip.file('projeto.geojson', JSON.stringify(fc, null, 2));
      zip.file('projeto.json', JSON.stringify({ project: remoteProjectPayload(), features: remoteFeaturePayloads(), exportedAt: new Date().toISOString() }, null, 2));
      zip.file('coordenadas.txt', textCoordinates());
      zip.file('README.txt', 'Exportação completa Surveyor: projeto, geometrias, coordenadas e metadados.');
      const blob = await zip.generateAsync({ type: 'blob' });
      downloadBlob(`${name}-exportacao-completa.zip`, blob);
      toast('ZIP completo gerado.', 'success');
    } catch (error) { console.error(error); toast(error.message || 'Falha ao gerar ZIP completo.', 'error'); }
  });

  els.newBtn.onclick = () => {
    if (drawn.getLayers().length && !confirm('Limpar o projeto atual?')) return;
    drawn.clearLayers(); clearGlebaCutLines(); clearSelection(); clearProjectHistory(); currentProjectId = null; currentProjectRevision = ''; currentProjectMetadata = {};
    renderManualDimensions();
    history.replaceState(null, '', 'mapa.html');
    els.propertyName.value = els.ownerName.value = els.city.value = '';
    if (els.ownerCpf) els.ownerCpf.value = '';
    if (els.ownerRg) els.ownerRg.value = '';
    loadAdditionalOwner(null);
    if (els.projectDescription) els.projectDescription.value = '';
    map.setView(DEFAULT_CENTER, 14); refresh();
    try { window.dispatchEvent(new CustomEvent('surveyor:project-new')); } catch {}
  };

  function download(name, content, type) {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = name; a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast(`${name} gerado.`, 'success');
  }
  function fileBase() { return (els.propertyName.value.trim() || 'projeto-terra').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase(); }

  els.geojsonBtn.onclick = () => download(`${fileBase()}.geojson`, JSON.stringify(collection(), null, 2), 'application/geo+json;charset=utf-8');
  els.csvBtn.onclick = () => {
    const rows = ['elemento;categoria;ordem;latitude;longitude'];
    drawn.eachLayer((layer) => metrics(layer).coords.forEach((c, i) => rows.push(`${safeCsv(metadata(layer).name)};${safeCsv(categories[metadata(layer).category].label)};${i + 1};${c.lat.toFixed(7)};${c.lng.toFixed(7)}`)));
    download(`${fileBase()}.csv`, rows.join('\n'), 'text/csv;charset=utf-8');
  };
  function safeCsv(v) { const s = String(v || ''); return /[;"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; }


  function downloadBlob(name, blob) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = name;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast(`${name} gerado.`, 'success');
  }

  async function downloadShapefileCollection(fc, baseName, mode = 'projeto') {
    if (!window.SurveyorShapefileExport) {
      toast('O exportador Shapefile não foi carregado. Atualize a página com Ctrl+F5.', 'error');
      return null;
    }
    try {
      return await window.SurveyorShapefileExport.open({
        featureCollection: fc,
        baseName: baseName || fileBase(),
        mode,
        context: {
          propertyName: els.propertyName.value.trim(),
          ownerName: els.ownerName.value.trim(),
          municipality: els.city.value.trim(),
          stateCode: els.uf.value
        },
        onStatus: (message, type) => toast(message, type === 'warning' ? 'error' : type)
      });
    } catch (error) {
      console.error('[Surveyor Shapefile]', error);
      return null;
    }
  }


  function featureCollectionFromLayer(layer) {
    if (!layer || !drawn.hasLayer(layer)) return null;
    const feature = layer.toGeoJSON();
    feature.properties = { ...metadata(layer) };
    return {
      type: 'FeatureCollection',
      properties: { propertyName: els.propertyName.value.trim(), ownerName: els.ownerName.value.trim(), ownerCpf: els.ownerCpf?.value?.trim?.() || '', ownerRg: els.ownerRg?.value?.trim?.() || '', additionalOwner: additionalOwnerFromForm(), city: els.city.value.trim(), uf: els.uf.value, exportedAt: new Date().toISOString(), exportMode: 'individual' },
      features: [feature]
    };
  }

  function escapeXml(value) {
    return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function kmlForFeatures(features) {
    const marks = (features || []).map((f) => {
      let geometry = '';
      if (f.geometry.type === 'Polygon') geometry = `<Polygon><outerBoundaryIs><LinearRing><coordinates>${f.geometry.coordinates[0].map(([x,y]) => `${x},${y},0`).join(' ')}</coordinates></LinearRing></outerBoundaryIs></Polygon>`;
      if (f.geometry.type === 'LineString') geometry = `<LineString><coordinates>${f.geometry.coordinates.map(([x,y]) => `${x},${y},0`).join(' ')}</coordinates></LineString>`;
      if (f.geometry.type === 'Point') geometry = `<Point><coordinates>${f.geometry.coordinates[0]},${f.geometry.coordinates[1]},0</coordinates></Point>`;
      return `<Placemark><name>${escapeXml(f.properties?.name)}</name>${geometry}</Placemark>`;
    }).join('');
    return `<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document>${marks}</Document></kml>`;
  }

  function coordinateRowsFromFeatures(features) {
    const rows = [];
    (features || []).forEach((feature, featureIndex) => {
      const name = feature.properties?.name || `Elemento ${featureIndex + 1}`;
      const geometry = feature.geometry || {};
      let coords = [];
      if (geometry.type === 'Polygon') coords = geometry.coordinates?.[0] || [];
      else if (geometry.type === 'LineString') coords = geometry.coordinates || [];
      else if (geometry.type === 'Point') coords = [geometry.coordinates];
      coords.forEach((coord, index) => rows.push({ name, index: index + 1, lng: Number(coord[0]), lat: Number(coord[1]) }));
    });
    return rows.filter((row) => Number.isFinite(row.lng) && Number.isFinite(row.lat));
  }

  function downloadIndividualLayer() {
    const layers = drawn.getLayers();
    if (!layers.length) return toast('Nenhum polígono ou elemento desenhado para exportar.', 'error');
    const selectedIndex = selectedLayer ? layers.indexOf(selectedLayer) : -1;
    const list = layers.map((layer, index) => {
      const p = metadata(layer);
      const label = categories[p.category]?.label || p.category || 'Elemento';
      return `${index + 1} — ${p.name || `Elemento ${index + 1}`} (${label})`;
    }).join('\n');
    const indexInput = prompt(`Digite o número do elemento que deseja baixar:\n\n${list}`, String(selectedIndex >= 0 ? selectedIndex + 1 : 1));
    if (indexInput == null) return;
    const layer = layers[Number(indexInput) - 1];
    if (!layer) return toast('Elemento individual inválido.', 'error');
    const fc = featureCollectionFromLayer(layer);
    const feature = fc.features[0];
    const cleanName = String(metadata(layer).name || 'elemento').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase() || 'elemento';
    const baseName = `${fileBase()}-${cleanName}`;
    const format = String(prompt('Formato do download individual: GeoJSON, KML, CSV, TXT ou SHP', 'GeoJSON') || 'GeoJSON').trim().toLowerCase();
    if (format === 'shp' || format === 'shape' || format === 'shapefile') return downloadShapefileCollection(fc, baseName, 'individual');
    if (format === 'kml') return download(`${baseName}.kml`, kmlForFeatures([feature]), 'application/vnd.google-earth.kml+xml;charset=utf-8');
    if (format === 'csv') {
      const rows = ['elemento;categoria;ordem;latitude;longitude'];
      coordinateRowsFromFeatures([feature]).forEach((row) => rows.push(`${safeCsv(row.name)};${safeCsv(categories[feature.properties?.category]?.label || feature.properties?.category)};${row.index};${row.lat.toFixed(7)};${row.lng.toFixed(7)}`));
      return download(`${baseName}.csv`, rows.join('\n'), 'text/csv;charset=utf-8');
    }
    if (format === 'txt') {
      const lines = [`PROJETO: ${els.propertyName.value.trim() || 'SEM NOME'}`, `ELEMENTO: ${feature.properties?.name || 'SEM NOME'}`, ''];
      coordinateRowsFromFeatures([feature]).forEach((row) => lines.push(`${row.name};V${row.index};LAT=${row.lat.toFixed(8)};LON=${row.lng.toFixed(8)}`));
      return download(`${baseName}.txt`, lines.join('\r\n'), 'text/plain;charset=utf-8');
    }
    return download(`${baseName}.geojson`, JSON.stringify(fc, null, 2), 'application/geo+json;charset=utf-8');
  }


  async function downloadLayerInFormat(layer, format = 'geojson') {
    if (!layer || !drawn.hasLayer(layer)) return toast('Selecione um elemento desenhado para baixar.', 'error');
    const fc = featureCollectionFromLayer(layer);
    const feature = fc?.features?.[0];
    if (!feature) return toast('Não foi possível preparar o elemento selecionado.', 'error');
    const cleanName = String(metadata(layer).name || 'elemento').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase() || 'elemento';
    const baseName = `${fileBase()}-${cleanName}`;
    const chosen = String(format || 'geojson').toLowerCase();
    if (chosen === 'shp' || chosen === 'shape' || chosen === 'shapefile') return downloadShapefileCollection(fc, baseName, 'individual');
    if (chosen === 'kml') return download(`${baseName}.kml`, kmlForFeatures([feature]), 'application/vnd.google-earth.kml+xml;charset=utf-8');
    if (chosen === 'csv') {
      const rows = ['elemento;categoria;ordem;latitude;longitude'];
      coordinateRowsFromFeatures([feature]).forEach((row) => rows.push(`${safeCsv(row.name)};${safeCsv(categories[feature.properties?.category]?.label || feature.properties?.category)};${row.index};${row.lat.toFixed(7)};${row.lng.toFixed(7)}`));
      return download(`${baseName}.csv`, rows.join('\n'), 'text/csv;charset=utf-8');
    }
    if (chosen === 'txt') {
      const lines = [`PROJETO: ${els.propertyName.value.trim() || 'SEM NOME'}`, `ELEMENTO: ${feature.properties?.name || 'SEM NOME'}`, ''];
      coordinateRowsFromFeatures([feature]).forEach((row) => lines.push(`${row.name};V${row.index};LAT=${row.lat.toFixed(8)};LON=${row.lng.toFixed(8)}`));
      return download(`${baseName}.txt`, lines.join('\r\n'), 'text/plain;charset=utf-8');
    }
    return download(`${baseName}.geojson`, JSON.stringify(fc, null, 2), 'application/geo+json;charset=utf-8');
  }

  document.querySelectorAll('[data-selected-download]').forEach((button) => {
    button.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      downloadLayerInFormat(selectedLayer, button.dataset.selectedDownload || 'geojson');
      button.closest('details')?.removeAttribute('open');
    });
  });

  els.shpBtn?.addEventListener('click', () => downloadShapefileCollection(collection(), fileBase(), 'projeto completo'));
  els.kmlBtn.onclick = () => download(`${fileBase()}.kml`, kmlForFeatures(collection().features), 'application/vnd.google-earth.kml+xml;charset=utf-8');


  function allCoordinateRows() {
    const rows = [];
    collection().features.forEach((feature, featureIndex) => {
      const name = feature.properties?.name || `Elemento ${featureIndex + 1}`;
      const geometry = feature.geometry || {};
      let coords = [];
      if (geometry.type === 'Polygon') coords = geometry.coordinates?.[0] || [];
      else if (geometry.type === 'LineString') coords = geometry.coordinates || [];
      else if (geometry.type === 'Point') coords = [geometry.coordinates];
      coords.forEach((coord, index) => rows.push({ name, index: index + 1, lng: Number(coord[0]), lat: Number(coord[1]) }));
    });
    return rows.filter((row) => Number.isFinite(row.lng) && Number.isFinite(row.lat));
  }

  function kmlPoints() {
    const escape = (value) => String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const marks = allCoordinateRows().map((row) => `<Placemark><name>${escape(row.name)} - V${row.index}</name><Point><coordinates>${row.lng},${row.lat},0</coordinates></Point></Placemark>`).join('');
    return `<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document>${marks}</Document></kml>`;
  }

  function textCoordinates() {
    const lines = [`PROJETO: ${els.propertyName.value.trim() || 'SEM NOME'}`, `PROPRIETÁRIO: ${[els.ownerName.value.trim(),additionalOwnerFromForm()?.name].filter(Boolean).join(' / ') || 'NÃO INFORMADO'}`, `MUNICÍPIO/UF: ${els.city.value.trim() || 'NÃO INFORMADO'}/${els.uf.value}`, ''];
    allCoordinateRows().forEach((row) => lines.push(`${row.name};V${row.index};LAT=${row.lat.toFixed(8)};LON=${row.lng.toFixed(8)}`));
    return lines.join('\r\n');
  }

  function dxfText(gridSpacing = 0) {
    return surveyorDxf(collection().features, { gridSpacing, rows: allCoordinateRows() });
  }

  els.kmlPointsBtn?.addEventListener('click', () => download(`${fileBase()}-pontos.kml`, kmlPoints(), 'application/vnd.google-earth.kml+xml'));
  els.txtBtn?.addEventListener('click', () => download(`${fileBase()}-coordenadas.txt`, textCoordinates(), 'text/plain;charset=utf-8'));
  els.dxfBtn?.addEventListener('click', () => download(`${fileBase()}.dxf`, dxfText(0), 'application/dxf'));
  els.dxf1Btn?.addEventListener('click', () => download(`${fileBase()}-planialt-1x1.dxf`, dxfText(1), 'application/dxf'));
  els.dxf5Btn?.addEventListener('click', () => download(`${fileBase()}-planialt-5x5.dxf`, dxfText(5), 'application/dxf'));
  els.dxf10Btn?.addEventListener('click', () => download(`${fileBase()}-planialt-10x10.dxf`, dxfText(10), 'application/dxf'));
  els.dxf50Btn?.addEventListener('click', () => download(`${fileBase()}-planialt-50x50.dxf`, dxfText(50), 'application/dxf'));
  els.downloadSelectedBtn?.addEventListener('click', downloadIndividualLayer);

  els.importFile.onchange = async (e) => {
    const files = [...(e.target.files || [])]; e.target.value = '';
    if (!files.length) return;
    const beforeImportSnapshot = snapshotDrawn();
    // Defensive reset: the file picker can also be opened programmatically or by
    // browser state restoration, so do not rely only on triggerProjectImport.
    resetInteractionModes();
    vertexMarkers.clearLayers();
    const first = files[0];
    const ext = first.name.split('.').pop().toLowerCase();
    const useAdvancedImporter = files.length > 1 || ['zip','shp','shx','dbf','prj','cpg','sbn','sbx'].includes(ext);
    try {
      if (useAdvancedImporter) {
        if (!window.GeoRuralLayerImport?.filesToGeoJSON) throw new Error('O importador avançado não foi carregado. Atualize a página.');
        showReferenceStatus('Importando área geoespacial', files.length > 1 ? `${files.length} arquivos selecionados` : first.name);
        const result = await window.GeoRuralLayerImport.filesToGeoJSON(files, (progress) => {
          showReferenceStatus('Importando área geoespacial', progress.message || 'Processando arquivo...', progress.percent);
        });
        if (!result?.geojson) throw new Error('A camada é grande demais para abrir como projeto editável. Importe como camada de referência.');
        loadCollection(result.geojson);
        // Imported project areas must open clean. The user can click a polygon to
        // inspect/edit it; importing itself must not leave vertex/confrontante
        // markers covering the geometry.
        clearSelection();
        vertexMarkers.clearLayers();
        setActiveMapTool(els.selectToolBtn);
        hideReferenceStatus();
        pushUndoSnapshot(beforeImportSnapshot, { label: `Camada importada — ${first.name}` });
        toast('Arquivo geoespacial importado como área do projeto.', 'success');
      } else {
        if (ext === 'json' || ext === 'geojson') loadCollection(JSON.parse(await first.text()));
        else if (ext === 'csv') loadCollection(parseCsv(await first.text()));
        else if (ext === 'rw5' || ext === 'raw') {
          if (!window.GeoRuralLayerImport?.parseRw5) throw new Error('O importador RW5 não foi carregado. Atualize a página.');
          const rw5 = window.GeoRuralLayerImport.parseRw5(await first.text());
          const normalized = normalizeImportedGeoJSON(rw5, first.name);
          const points = (normalized.features || []).filter((feature) => feature?.geometry?.type === 'Point');
          if (points.length >= 3 && window.confirm(`RW5 lido com ${points.length} ponto(s).\n\nDeseja criar um perímetro ligando os pontos na ordem do arquivo?\nOK = criar perímetro\nCancelar = importar somente os pontos`)) {
            const coords = points.map((feature) => feature.geometry.coordinates.slice(0,2));
            const firstCoord = coords[0], lastCoord = coords[coords.length - 1];
            if (firstCoord[0] !== lastCoord[0] || firstCoord[1] !== lastCoord[1]) coords.push([...firstCoord]);
            loadCollection({ type:'FeatureCollection', features:[{ type:'Feature', properties:{ name:first.name.replace(/\.(?:rw5|raw)$/i,''), category:'perimetro', sourceFormat:'RW5', rw5PointCount:points.length, rw5PointElevations:points.map((feature) => ({ name:feature.properties?.name || '', elevation:feature.properties?.elevation ?? null })) }, geometry:{ type:'Polygon', coordinates:[coords] } }] });
          } else loadCollection(normalized);
        }
        else if (ext === 'kml' || ext === 'kmz') loadCollection(parseKml(await readKmlTextFromFile(first)));
        else throw new Error('Formato não suportado. Use GeoJSON, JSON, KML, KMZ, CSV, RW5/RAW, ZIP Shapefile ou arquivos SHP/SHX/DBF.');
        clearSelection();
        vertexMarkers.clearLayers();
        setActiveMapTool(els.selectToolBtn);
        pushUndoSnapshot(beforeImportSnapshot, { label: `Camada importada — ${first.name}` });
        toast('Arquivo importado.', 'success');
      }
    } catch (err) {
      console.error(err);
      showReferenceStatus('Não foi possível importar a área', err.message || 'Falha desconhecida.');
      toast(err.message || 'Falha na importação.', 'error');
    }
  };

  function parseCsv(text) {
    const rows = text.split(/\r?\n/).map((r) => r.trim()).filter(Boolean).map((r) => r.split(/[;\t,]/).map((v) => v.trim()));
    if (rows.length < 3) throw new Error('CSV sem coordenadas suficientes.');
    const head = rows[0].map((v) => v.toLowerCase());
    let start = 0, li = head.findIndex((v) => v.includes('lat')), gi = head.findIndex((v) => v.includes('lon') || v.includes('lng'));
    if (li >= 0 && gi >= 0) start = 1; else { li = rows[0].length >= 3 ? 1 : 0; gi = rows[0].length >= 3 ? 2 : 1; }
    const coords = rows.slice(start).map((r) => [Number(String(r[gi]).replace(',', '.')), Number(String(r[li]).replace(',', '.'))]).filter(([x,y]) => Number.isFinite(x) && Number.isFinite(y));
    if (coords.length < 3) throw new Error('Menos de três coordenadas válidas.');
    const a = coords[0], b = coords.at(-1); if (a[0] !== b[0] || a[1] !== b[1]) coords.push([...a]);
    return { type: 'FeatureCollection', features: [{ type: 'Feature', properties: { name: 'Polígono importado', category: 'perimetro' }, geometry: { type: 'Polygon', coordinates: [coords] } }] };
  }

  async function readKmlTextFromFile(file) {
    const ext = String(file?.name || '').split('.').pop().toLowerCase();
    if (ext !== 'kmz') return file.text();
    if (!window.JSZip) throw new Error('O leitor KMZ não foi carregado. Atualize a página e tente novamente.');
    const zip = await window.JSZip.loadAsync(file);
    const entries = Object.values(zip.files || {}).filter((entry) => !entry.dir && /\.kml$/i.test(entry.name));
    if (!entries.length) throw new Error('O KMZ não contém arquivo KML interno.');
    const preferred = entries.find((entry) => /(^|\/)doc\.kml$/i.test(entry.name)) || entries[0];
    return preferred.async('string');
  }

  function parseKml(text) {
    const xml = new DOMParser().parseFromString(String(text || ''), 'application/xml');
    if (xml.querySelector('parsererror')) throw new Error('KML inválido. Verifique se o arquivo não está compactado como KMZ ou corrompido.');

    const localName = (node) => String(node?.localName || node?.nodeName || '').split(':').pop().toLowerCase();
    const elements = (root, name) => Array.from(root?.getElementsByTagName?.('*') || []).filter((node) => localName(node) === name.toLowerCase());
    const first = (root, name) => elements(root, name)[0] || null;
    const direct = (root, name) => Array.from(root?.children || []).filter((node) => localName(node) === name.toLowerCase());
    const textOf = (root, name) => first(root, name)?.textContent?.trim() || '';
    const closeRing = (coords) => {
      if (!coords.length) return coords;
      const a = coords[0];
      const b = coords[coords.length - 1];
      if (a[0] !== b[0] || a[1] !== b[1]) coords.push([...a]);
      return coords;
    };
    const pairs = (value) => String(value || '')
      .trim()
      .replace(/,\s+/g, ',')
      .split(/\s+/)
      .map((token) => token.split(',').slice(0, 2).map((part) => Number(String(part).trim())))
      .filter(([lng, lat]) => Number.isFinite(lng) && Number.isFinite(lat));
    const gxCoords = (track) => elements(track, 'coord')
      .map((node) => String(node.textContent || '').trim().split(/\s+/).slice(0, 2).map(Number))
      .filter(([lng, lat]) => Number.isFinite(lng) && Number.isFinite(lat));
    const propsFromPlacemark = (placemark, index) => {
      const props = { name: textOf(placemark, 'name') || `Elemento KML ${index + 1}` };
      elements(placemark, 'data').forEach((node) => {
        const key = node.getAttribute('name');
        if (key) props[key] = textOf(node, 'value');
      });
      elements(placemark, 'simpledata').forEach((node) => {
        const key = node.getAttribute('name');
        if (key) props[key] = node.textContent || '';
      });
      return props;
    };
    const polygonRings = (polygon) => {
      const outerNode = first(polygon, 'outerboundaryis') || polygon;
      const outerRingNode = first(outerNode, 'linearring') || outerNode;
      const outer = closeRing(pairs(textOf(outerRingNode, 'coordinates')));
      if (outer.length < 4) return null;
      const holes = elements(polygon, 'innerboundaryis')
        .map((innerNode) => {
          const ringNode = first(innerNode, 'linearring') || innerNode;
          const ring = closeRing(pairs(textOf(ringNode, 'coordinates')));
          return ring.length >= 4 ? ring : null;
        })
        .filter(Boolean);
      return [outer, ...holes];
    };
    const features = [];
    const addFeature = (properties, geometry, suffix = '') => {
      if (!geometry) return;
      const props = { ...properties };
      if (suffix) props.name = `${properties.name} ${suffix}`;
      features.push({ type: 'Feature', properties: props, geometry });
    };
    const parseContainer = (container, index) => {
      const baseProps = propsFromPlacemark(container, index);
      let count = 0;
      elements(container, 'polygon').forEach((polygon) => {
        const rings = polygonRings(polygon);
        if (rings) { count += 1; addFeature({ ...baseProps, category: 'perimetro' }, { type: 'Polygon', coordinates: rings }, count > 1 ? `(${count})` : ''); }
      });
      elements(container, 'linestring').forEach((line) => {
        const coords = pairs(textOf(line, 'coordinates'));
        if (coords.length >= 2) { count += 1; addFeature({ ...baseProps, category: 'estrada' }, { type: 'LineString', coordinates: coords }, count > 1 ? `(${count})` : ''); }
      });
      elements(container, 'point').forEach((point) => {
        const coord = pairs(textOf(point, 'coordinates'))[0];
        if (coord) { count += 1; addFeature({ ...baseProps, category: 'agua' }, { type: 'Point', coordinates: coord }, count > 1 ? `(${count})` : ''); }
      });
      elements(container, 'track').forEach((track) => {
        const coords = gxCoords(track);
        if (coords.length >= 2) { count += 1; addFeature({ ...baseProps, category: 'estrada' }, { type: 'LineString', coordinates: coords }, count > 1 ? `(${count})` : ''); }
        else if (coords.length === 1) { count += 1; addFeature({ ...baseProps, category: 'agua' }, { type: 'Point', coordinates: coords[0] }, count > 1 ? `(${count})` : ''); }
      });
      if (!count) {
        direct(container, 'linearring').forEach((ring) => {
          const coords = closeRing(pairs(textOf(ring, 'coordinates')));
          if (coords.length >= 4) addFeature({ ...baseProps, category: 'perimetro' }, { type: 'Polygon', coordinates: [coords] });
        });
      }
    };

    let placemarks = elements(xml, 'placemark');
    if (placemarks.length) placemarks.forEach(parseContainer);
    else parseContainer(xml, 0);

    const valid = features.filter((feature) => {
      const g = feature.geometry;
      if (g.type === 'Point') return Array.isArray(g.coordinates) && g.coordinates.length >= 2;
      if (g.type === 'LineString') return Array.isArray(g.coordinates) && g.coordinates.length >= 2;
      if (g.type === 'Polygon') return Array.isArray(g.coordinates?.[0]) && g.coordinates[0].length >= 4;
      return false;
    });
    if (!valid.length) throw new Error('Nenhuma geometria compatível foi encontrada no KML. O importador aceita Polygon, LineString, Point e gx:Track.');
    return { type: 'FeatureCollection', features: valid };
  }

  function showReferenceStatus(title, text, percent = null) {
    if (!els.referenceStatus) return;
    els.referenceStatus.classList.remove('hidden');
    els.referenceStatus.innerHTML = `<strong>${escapeHtmlLocal(title)}</strong><span>${escapeHtmlLocal(text)}</span>${percent == null ? '' : `<div class="reference-progress"><span style="width:${Math.max(0, Math.min(100, percent))}%"></span></div>`}`;
  }

  function hideReferenceStatus() {
    els.referenceStatus?.classList.add('hidden');
  }

  async function checkServer() {
    try {
      const response = await fetch(apiEndpoint('/api/health'), { cache: 'no-store' });
      serverAvailable = response.ok;
    } catch {
      serverAvailable = false;
    }
    return serverAvailable;
  }

  async function checkReferenceServer() {
    if (!await checkServer()) return false;
    try {
      const response = await fetch(apiEndpoint('/api/reference/layers'), { cache: 'no-store' });
      return response.ok;
    } catch {
      return false;
    }
  }

  async function loadServerReferenceLayers() {
    if (!await checkServer()) return;
    try {
      const response = await fetch(apiEndpoint('/api/reference/layers'), { cache: 'no-store' });
      const data = await response.json();
      (data.layers || []).forEach(addServerReferenceLayer);
      if ((data.layers || []).length) updateServerReferences(true);
    } catch (error) {
      console.error(error);
    }
  }

  function uploadReferenceZip(file) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('POST', apiEndpoint('/api/reference/upload'));
      xhr.setRequestHeader('Content-Type', 'application/zip');
      xhr.setRequestHeader('X-Filename', encodeURIComponent(file.name));
      xhr.upload.onprogress = (event) => {
        if (!event.lengthComputable) return;
        const percent = event.loaded / event.total * 100;
        showReferenceStatus('Enviando camada grande', `${(event.loaded / 1024 / 1024).toFixed(1)} de ${(event.total / 1024 / 1024).toFixed(1)} MB`, percent);
      };
      xhr.onerror = () => reject(new Error('Falha ao enviar o ZIP ao servidor de processamento.'));
      xhr.onload = () => {
        let data = {};
        try { data = JSON.parse(xhr.responseText || '{}'); } catch {}
        if (xhr.status >= 200 && xhr.status < 300) resolve(data);
        else reject(new Error(data.error || `Falha no upload (${xhr.status}).`));
      };
      xhr.send(file);
    });
  }

  async function pollReferenceJob(jobId) {
    while (true) {
      const response = await fetch(apiEndpoint(`/api/reference/status?id=${encodeURIComponent(jobId)}`), { cache: 'no-store' });
      const job = await response.json();
      if (!response.ok) throw new Error(job.error || 'Não foi possível consultar o processamento.');
      const total = Number(job.total || 0);
      const progress = Number(job.progress || 0);
      const percent = total > 0 ? progress / total * 100 : null;
      const eta = job.etaSeconds != null ? ` • aproximadamente ${Math.max(1, Math.ceil(job.etaSeconds / 60))} min restantes` : '';
      showReferenceStatus(job.phase || 'Processando camada', `${progress.toLocaleString('pt-BR')} de ${total.toLocaleString('pt-BR')}${eta}`, percent);
      if (job.state === 'ready') {
        addServerReferenceLayer(job.layer);
        showReferenceStatus('Camada pronta', `${Number(job.layer.featureCount || 0).toLocaleString('pt-BR')} imóveis indexados. Aproxime o mapa para visualizar.`, 100);
        updateServerReferences(true);
        setTimeout(hideReferenceStatus, 6000);
        return;
      }
      if (job.state === 'error') throw new Error(job.error || 'Falha ao processar o shapefile.');
      await new Promise((resolve) => setTimeout(resolve, 1800));
    }
  }

  function toleranceForZoom(zoom) {
    if (zoom <= 11) return 0.00045;
    if (zoom === 12) return 0.00025;
    if (zoom === 13) return 0.00012;
    if (zoom === 14) return 0.00006;
    if (zoom === 15) return 0.000025;
    return 0.000008;
  }

  async function updateLocalLargeReferences(force = false) {
    const entries = referenceCollections.filter((entry) => entry.localLarge && referenceGroup.hasLayer(entry.layer));
    if (!entries.length) return;
    const queryApi = window.GeoRuralLayerImport?.queryLargeSession;
    if (typeof queryApi !== 'function') return showReferenceStatus('Camada local indisponível', 'Atualize a página e importe novamente o Shapefile.');

    const zoom = map.getZoom();
    if (zoom < 10) {
      entries.forEach((entry) => { entry.layer.clearLayers(); entry.lastReturned = 0; });
      showReferenceStatus('Camada grande carregada', 'Aproxime o mapa até o zoom 10 para exibir os elementos. O arquivo permanece indexado no navegador.');
      refresh();
      return;
    }

    const serial = ++localLargeQuerySerial;
    const bounds = map.getBounds();
    const bbox = [bounds.getWest(), bounds.getSouth(), bounds.getEast(), bounds.getNorth()];
    let totalReturned = 0;
    let anyTruncated = false;
    try {
      for (const entry of entries) {
        const ownSerial = ++entry.querySerial;
        const data = await queryApi(entry.sessionId, bbox, 1800);
        if (serial !== localLargeQuerySerial || ownSerial !== entry.querySerial) return;
        entry.layer.clearLayers();
        entry.layer.addData(data);
        entry.lastReturned = Number(data.meta?.returned || data.features?.length || 0);
        entry.truncated = Boolean(data.meta?.truncated);
        totalReturned += entry.lastReturned;
        anyTruncated ||= entry.truncated;
      }
      if (anyTruncated) showReferenceStatus('Muitos elementos nesta área', `${totalReturned.toLocaleString('pt-BR')} elementos exibidos. Aproxime mais o mapa para carregar os demais.`);
      else if (force) showReferenceStatus('Camada local atualizada', `${totalReturned.toLocaleString('pt-BR')} elemento(s) visível(is). O restante continua indexado localmente.`);
      else hideReferenceStatus();
      refresh();
    } catch (error) {
      console.error(error);
      showReferenceStatus('Falha ao consultar camada local', error.message || 'Não foi possível consultar o índice local.');
    }
  }

  async function updateServerReferences(force = false) {
    const serverEntries = referenceCollections.filter((entry) => entry.server && referenceGroup.hasLayer(entry.layer));
    if (!serverEntries.length || !serverAvailable) return;
    const zoom = map.getZoom();
    if (zoom < 11) {
      serverEntries.forEach((entry) => { entry.layer.clearLayers(); entry.lastReturned = 0; });
      showReferenceStatus('Camada oficial pausada', 'Aproxime o mapa até o zoom 11 para carregar os imóveis cadastrados.');
      refresh();
      return;
    }
    if (referenceQueryController) referenceQueryController.abort();
    referenceQueryController = new AbortController();
    const bounds = map.getBounds();
    const bbox = [bounds.getWest(), bounds.getSouth(), bounds.getEast(), bounds.getNorth()].join(',');
    const tolerance = toleranceForZoom(zoom);
    try {
      let anyTruncated = false;
      let totalReturned = 0;
      for (const entry of serverEntries) {
        const url = apiEndpoint(`/api/reference/query?id=${encodeURIComponent(entry.id)}&bbox=${encodeURIComponent(bbox)}&limit=1500&tolerance=${encodeURIComponent(tolerance)}`);
        const response = await fetch(url, { signal: referenceQueryController.signal, cache: 'no-store' });
        const data = await response.json();
        if (!response.ok) throw new Error(data.error || 'Falha ao consultar a camada.');
        entry.layer.clearLayers();
        entry.layer.addData(data);
        entry.lastReturned = data.meta?.returned || data.features?.length || 0;
        entry.truncated = Boolean(data.meta?.truncated);
        totalReturned += entry.lastReturned;
        anyTruncated ||= entry.truncated;
      }
      if (anyTruncated) showReferenceStatus('Muitos imóveis nesta área', `${totalReturned.toLocaleString('pt-BR')} imóveis exibidos. Aproxime mais o mapa para carregar os demais.`);
      else if (force) showReferenceStatus('Camada atualizada', `${totalReturned.toLocaleString('pt-BR')} imóveis visíveis nesta área.`);
      else hideReferenceStatus();
      refresh();
      catalogReloadedAt = Date.now();
    } catch (error) {
      if (error.name === 'AbortError') return;
      console.error(error);
      showReferenceStatus('Falha ao consultar camada', error.message || 'Erro desconhecido.');
    }
  }

  els.importReferenceFile.onchange = async (event) => {
    const files = [...(event.target.files || [])];
    event.target.value = '';
    if (!files.length) return;
    const file = files[0];
    const ext = file.name.split('.').pop().toLowerCase();
    const useAdvancedImporter = files.length > 1 || ['zip','shp','shx','dbf','prj','cpg','sbn','sbx'].includes(ext);
    try {
      if (useAdvancedImporter) {
        if (!window.GeoRuralLayerImport?.filesToGeoJSON) throw new Error('O conversor geográfico não foi carregado. Atualize a página.');
        showReferenceStatus('Convertendo camada geoespacial', files.length > 1 ? `${files.length} arquivos selecionados` : `${(file.size / 1024 / 1024).toFixed(1)} MB • processamento no navegador`);
        const result = await window.GeoRuralLayerImport.filesToGeoJSON(files, (progress) => {
          showReferenceStatus('Convertendo camada geoespacial', progress.message || 'Processando arquivo...', progress.percent);
        });
        if (result?.geojson) {
          addReferenceCollection(result.geojson, file.name.replace(/\.[^.]+$/, ''));
          hideReferenceStatus();
          toast(`Camada de referência importada com ${Number(result.featureCount || result.geojson.features?.length || 0).toLocaleString('pt-BR')} elemento(s).`, 'success');
        } else if (result?.localLarge) {
          addLocalLargeReferenceLayer(result.localLarge, file.name.replace(/\.[^.]+$/, ''), true);
          showReferenceStatus('Camada grande pronta', `${Number(result.featureCount || 0).toLocaleString('pt-BR')} elemento(s) indexados localmente. Aproxime o mapa para visualizar.`, 100);
          await updateLocalLargeReferences(true);
          toast(`Camada grande importada localmente: ${Number(result.featureCount || 0).toLocaleString('pt-BR')} elemento(s).`, 'success');
        } else if (ext === 'zip' && await checkReferenceServer()) {
          showReferenceStatus('Preparando camada grande', 'Enviando o Shapefile para processamento seguro...', 2);
          const upload = await uploadReferenceZip(file);
          const jobId = upload.jobId || upload.id;
          if (!jobId) throw new Error('O servidor não retornou o identificador do processamento.');
          await pollReferenceJob(jobId);
        } else {
          throw new Error('O Shapefile foi convertido, mas é grande demais para abrir diretamente no navegador. Divida a camada em partes menores ou habilite o processamento de camadas grandes.');
        }
      } else if (ext === 'json' || ext === 'geojson') {
        addReferenceCollection(JSON.parse(await file.text()), file.name.replace(/\.[^.]+$/, ''));
        toast('Camada de referência adicionada em amarelo.', 'success');
      } else if (ext === 'kml' || ext === 'kmz') {
        addReferenceCollection(parseKml(await readKmlTextFromFile(file)), file.name.replace(/\.[^.]+$/, ''));
        toast('Camada de referência adicionada em amarelo.', 'success');
      } else {
        throw new Error('Use GeoJSON, KML, KMZ, ZIP do Shapefile ou selecione .SHP + .SHX + .DBF.');
      }
    } catch (error) {
      console.error(error);
      showReferenceStatus('Não foi possível importar', error.message || 'Falha desconhecida.');
      toast(error.message || 'Falha na importação.', 'error');
    }
  };


