  let surveyorLiveTool = null;

  window.addEventListener('surveyor:draw-guide-size', () => {
    if (liveDrawState?.active) liveRedraw(liveDrawState.cursor);
    if (surveyorLiveTool) renderSurveyorLiveTool(surveyorLiveTool.cursor || null);
  });

  function stopSurveyorLiveTool(options = {}) {
    const state = surveyorLiveTool;
    if (!state) {
      liveDrawGroup.clearLayers();
      document.body.classList.remove('survey-live-drawing', 'drawing-active');
      return;
    }
    state.cleanups?.forEach((cleanup) => {
      try { cleanup(); } catch (error) { console.warn('Falha ao limpar desenho ao vivo:', error); }
    });
    surveyorLiveTool = null;
    liveDrawGroup.clearLayers();
    map.dragging.enable();
    map.doubleClickZoom.enable();
    document.body.classList.remove('survey-live-drawing', 'drawing-active');
    if (!options.keepActiveTool) {
      setActiveMapTool(els.selectToolBtn);
      window.dispatchEvent(new CustomEvent('surveyor:map-tool-finished', { detail: { type: state.type || 'drawing' } }));
    }
  }

  function surveyorLiveStyle(extra = {}) {
    const style = {
      pane: 'liveDrawPane',
      renderer: liveRenderer,
      className: extra.className || 'surveyor-live-draw-shape',
      color: extra.color || '#facc15',
      fillColor: extra.fillColor || '#facc15',
      fillOpacity: Number.isFinite(Number(extra.fillOpacity)) ? Number(extra.fillOpacity) : 0.16,
      opacity: 1,
      weight: Number(extra.weight || 1.2),
      dashArray: extra.dashArray || null,
      lineCap: 'round',
      lineJoin: 'round',
      interactive: false
    };
    if (extra.fill === false) {
      style.fill = false;
      style.fillColor = 'transparent';
      style.fillOpacity = 0;
    }
    return style;
  }

  function surveyorFinalStyle(category = els.category?.value || 'perimetro', extra = {}) {
    const style = styleFor(category || 'perimetro', { styleColor: '#facc15', color: '#facc15', fillColor: '#facc15', styleOpacity: 0.20, strokeOpacity: 1, weight: 1.2 });
    const finalStyle = {
      ...style,
      pane: 'drawnPane',
      renderer: drawnRenderer,
      className: extra.className || 'surveyor-final-draw-shape',
      color: extra.color || '#facc15',
      fillColor: extra.fillColor || '#facc15',
      weight: Number(extra.weight || 1.2),
      opacity: 1,
      fillOpacity: Number.isFinite(Number(extra.fillOpacity)) ? Number(extra.fillOpacity) : 0.18,
      dashArray: extra.dashArray || null,
      lineCap: 'round',
      lineJoin: 'round',
      interactive: true
    };
    if (extra.fill === false) {
      finalStyle.fill = false;
      finalStyle.fillColor = 'transparent';
      finalStyle.fillOpacity = 0;
    }
    return finalStyle;
  }

  function surveyorLiveProps(props = {}) {
    const noShadow = Boolean(props.noShadow);
    return {
      ...props,
      liveDrawCreated: true,
      noShadow,
      styleColor: props.styleColor || '#facc15',
      color: props.color || '#facc15',
      fillColor: props.fillColor || '#facc15',
      strokeOpacity: 1,
      styleOpacity: Number.isFinite(Number(props.styleOpacity)) ? Number(props.styleOpacity) : 0.20,
      weight: Number(props.weight || 1.25)
    };
  }

  function surveyorLiveVertex(latlng, index = null, isFirst = false, isCursor = false) {
    const marker = createLiveDrawVertex(latlng, { first: isFirst, cursor: isCursor, interactive: isFirst }).addTo(liveDrawGroup);
    if (Number.isFinite(index)) {
      marker.bindTooltip(String(index + 1), {
        permanent: true,
        direction: 'top',
        className: 'surveyor-live-draw-label',
        opacity: 1
      });
    }
    if (isFirst) {
      marker.on('click', (event) => {
        L.DomEvent.stop(event.originalEvent || event);
        finishSurveyorLiveTool();
      });
    }
    return marker;
  }

  function renderSurveyorLiveTool(cursor = null) {
    const state = surveyorLiveTool;
    if (!state) return;
    if (cursor) state.cursor = cursor;
    const activeCursor = cursor || state.cursor || null;
    liveDrawGroup.clearLayers();
    const points = state.points.slice();
    const type = state.type;

    if (type === 'marker') {
      if (activeCursor) surveyorLiveVertex(activeCursor, null, false, true);
      return;
    }

    if (type === 'polyline' || type === 'servitude') {
      points.forEach((point, index) => surveyorLiveVertex(point, index));
      const draft = activeCursor ? points.concat([activeCursor]) : points;
      if (draft.length >= 2) L.polyline(draft, surveyorLiveStyle({ fill: false, fillOpacity: 0, weight: type === 'servitude' ? 2 : 1.2, color: type === 'servitude' ? '#f97316' : '#facc15', className: 'surveyor-live-draw-shape surveyor-line-draw no-shadow' })).addTo(liveDrawGroup);
      if (activeCursor) surveyorLiveVertex(activeCursor, null, false, true);
      return;
    }

    if (type === 'polygon') {
      points.forEach((point, index) => surveyorLiveVertex(point, index, index === 0 && points.length >= 3));
      const draft = activeCursor ? points.concat([activeCursor]) : points;
      if (draft.length >= 2) L.polyline(draft, surveyorLiveStyle({ fillOpacity: 0, weight: 1.2 })).addTo(liveDrawGroup);
      if (draft.length >= 3) {
        L.polygon(draft, surveyorLiveStyle({ fillOpacity: 0.16, weight: 1.2 })).addTo(liveDrawGroup);
        L.polyline([draft[draft.length - 1], draft[0]], surveyorLiveStyle({ fillOpacity: 0, weight: 1.05, dashArray: '8 8', color: '#2563eb' })).addTo(liveDrawGroup);
      }
      if (activeCursor) surveyorLiveVertex(activeCursor, null, false, true);
      return;
    }

    if (type === 'rectangle') {
      const start = state.origin;
      if (start) surveyorLiveVertex(start, 0, false);
      if (start && activeCursor) {
        L.rectangle([start, activeCursor], surveyorLiveStyle({ fillOpacity: 0.16, weight: 1.2 })).addTo(liveDrawGroup);
        surveyorLiveVertex(activeCursor, null, false, true);
      }
      return;
    }

    if (type === 'circle') {
      const start = state.origin;
      if (start) surveyorLiveVertex(start, 0, false);
      if (start && activeCursor) {
        const radius = start.distanceTo(activeCursor);
        L.circle(start, { ...surveyorLiveStyle({ fillOpacity: 0.13, weight: 1.15 }), radius }).addTo(liveDrawGroup);
        L.polyline([start, activeCursor], surveyorLiveStyle({ fillOpacity: 0, weight: 1.0, dashArray: '8 8', color: '#2563eb' })).addTo(liveDrawGroup);
        surveyorLiveVertex(activeCursor, null, false, true);
      }
    }
  }

  function finishSurveyorLiveTool(cursor = null) {
    const state = surveyorLiveTool;
    if (!state) return;
    const type = state.type;
    const points = state.points.slice();
    let layer = null;
    let props = {};

    if (type === 'polygon') {
      if (points.length < 3) return toast('Marque pelo menos 3 pontos para fechar o polígono.', 'error');
      layer = L.polygon(points, surveyorFinalStyle(els.category.value || 'perimetro'));
      props = surveyorLiveProps({ category: els.category.value || 'perimetro', name: els.areaName.value.trim() || categories[els.category.value]?.label || 'Polígono técnico' });
    } else if (type === 'polyline') {
      if (points.length < 2) return toast('Marque pelo menos 2 pontos para finalizar a linha.', 'error');
      layer = L.polyline(points, surveyorFinalStyle('outros', { className: 'surveyor-final-draw-shape surveyor-line-final no-shadow', fill: false, fillOpacity: 0 }));
      props = surveyorLiveProps({ category: 'outros', name: els.areaName.value.trim() || 'Linha técnica', noShadow: true });
    } else if (type === 'servitude') {
      if (points.length < 2) return toast('Marque pelo menos 2 pontos para finalizar a servidão.', 'error');
      layer = L.polyline(points, surveyorFinalStyle('estrada', { className: 'surveyor-final-draw-shape surveyor-line-final no-shadow', fill: false, fillOpacity: 0 }));
      props = surveyorLiveProps({
        category: 'estrada', name: els.areaName.value.trim() || 'Servidão', noShadow: true,
        servitudeDedicatedTool: true, servitudeGenerated: true, servitudeWidthMeters: 6, bufferMeters: 3,
        servitudeDetectionStatus: 'pending', servitudeCreatedAt: new Date().toISOString()
      });
    } else if (type === 'rectangle' && state.origin && cursor) {
      layer = L.rectangle([state.origin, cursor], surveyorFinalStyle(els.category.value || 'perimetro'));
      props = surveyorLiveProps({ category: els.category.value || 'perimetro', name: els.areaName.value.trim() || 'Retângulo técnico' });
    } else if (type === 'circle' && state.origin && cursor) {
      const circle = L.circle(state.origin, { ...surveyorFinalStyle('circulo'), radius: state.origin.distanceTo(cursor) });
      layer = circleToPolygon(circle);
      props = surveyorLiveProps({ category: 'circulo', name: els.areaName.value.trim() || 'Círculo técnico', radiusMeters: state.origin.distanceTo(cursor) });
    } else if (type === 'marker' && cursor) {
      layer = L.marker(cursor, { icon: markerIcon(els.category.value || 'outros'), zIndexOffset: 1200 });
      props = surveyorLiveProps({ category: els.category.value || 'outros', name: els.areaName.value.trim() || 'Ponto técnico' });
    }

    if (!layer) return;
    pushUndoSnapshot();
    stopSurveyorLiveTool({ keepActiveTool: false });
    addLayer(layer, props);
    try {
      const finalStyle = surveyorFinalStyle(props.category || els.category.value || 'perimetro', props.noShadow ? { className: 'surveyor-final-draw-shape surveyor-line-final no-shadow' } : {});
      layer.options = { ...(layer.options || {}), ...finalStyle };
      layer.setStyle?.(finalStyle);
      layer.bringToFront?.();
      drawn.bringToFront?.();
    } catch (_) {}
    if (type === 'servitude') {
      renderServitudeDerivedOverlays();
      toast('Servidão desenhada. Identificando a via automaticamente…', 'success');
      detectServitudeRoadIdentity(layer, { silent: false });
    } else {
      toast('Elemento adicionado e visível no mapa.', 'success');
    }
  }

  function startSurveyorLiveTool(type, button) {
    // Desenho técnico exige coordenadas de tela e mapa 1:1. Se a visualização
    // estava rotacionada, removemos a transformação imediatamente (sem a
    // animação de 240 ms) antes de registrar qualquer clique de desenho.
    if (window.SurveyorMapOrientation?.resetForEditing) {
      window.SurveyorMapOrientation.resetForEditing();
    } else {
      window.dispatchEvent(new CustomEvent('surveyor:map-reset-bearing', { detail: { immediate: true, reason: 'drawing' } }));
    }
    const rotationWrapper = document.querySelector('.surveyor-map-rotation-wrapper');
    if (rotationWrapper) rotationWrapper.style.transform = '';
    document.body.classList.remove('surveyor-map-view-rotated', 'surveyor-compass-dragging');
    map.invalidateSize?.(false);

    stopSurveyorLiveTool({ keepActiveTool: true });
    disableActiveHandler();
    identifyMode = false;
    coordinateMode = false;
    measureMode = false;
    els.coordinateReadout?.classList.add('hidden');
    document.querySelector('.geo-map-stage')?.classList.remove('identify-mode', 'coordinate-mode');

    surveyorLiveTool = { type, points: [], origin: null, cleanups: [] };
    document.body.classList.add('survey-live-drawing', 'drawing-active');
    setActiveMapTool(button || els.toolsMenuBtn);
    map.doubleClickZoom.disable();

    const onClick = (event) => {
      const state = surveyorLiveTool;
      if (!state) return;
      if (state.type === 'marker') {
        finishSurveyorLiveTool(event.latlng);
        return;
      }
      if (state.type === 'polygon' || state.type === 'polyline' || state.type === 'servitude') {
        const last = state.points[state.points.length - 1];
        if (!last || last.distanceTo(event.latlng) > 0.02) state.points.push(event.latlng);
        renderSurveyorLiveTool(event.latlng);
      }
    };
    const onDblClick = (event) => {
      L.DomEvent.stop(event.originalEvent || event);
      const state = surveyorLiveTool;
      if (!state) return;
      if (state.type === 'polygon' || state.type === 'polyline' || state.type === 'servitude') finishSurveyorLiveTool();
    };
    const onMove = (event) => renderSurveyorLiveTool(event.latlng);
    const onMouseDown = (event) => {
      const state = surveyorLiveTool;
      if (!state || !['rectangle', 'circle'].includes(state.type)) return;
      state.origin = event.latlng;
      state.points = [event.latlng];
      map.dragging.disable();
      renderSurveyorLiveTool(event.latlng);
    };
    const onMouseUp = (event) => {
      const state = surveyorLiveTool;
      if (!state || !['rectangle', 'circle'].includes(state.type) || !state.origin) return;
      finishSurveyorLiveTool(event.latlng);
    };
    const onKeyDown = (event) => {
      if (event.key === 'Escape') {
        stopSurveyorLiveTool();
        toast('Ferramenta cancelada.', 'success');
      }
      if (event.key === 'Enter') {
        finishSurveyorLiveTool();
      }
    };

    map.on('click', onClick);
    map.on('dblclick', onDblClick);
    map.on('mousemove', onMove);
    map.on('mousedown', onMouseDown);
    map.on('mouseup', onMouseUp);
    document.addEventListener('keydown', onKeyDown);

    surveyorLiveTool.cleanups.push(
      () => map.off('click', onClick),
      () => map.off('dblclick', onDblClick),
      () => map.off('mousemove', onMove),
      () => map.off('mousedown', onMouseDown),
      () => map.off('mouseup', onMouseUp),
      () => document.removeEventListener('keydown', onKeyDown)
    );

    const instructions = {
      polygon: 'Polígono: clique nos pontos. Finalize com duplo clique, Enter ou clicando no primeiro ponto.',
      polyline: 'Linha: clique nos pontos. Finalize com duplo clique ou Enter.',
      servitude: 'Servidão: clique ao longo do eixo da via. Finalize com duplo clique ou Enter; a via será identificada automaticamente.',
      rectangle: 'Retângulo: clique, segure e arraste até o tamanho desejado.',
      circle: 'Círculo: clique, segure e arraste para definir o raio.',
      marker: 'Ponto: clique no local desejado.'
    };
    toast(instructions[type] || 'Ferramenta ativada.', 'success');
    renderSurveyorLiveTool();
  }


  let surveyorMeasureTool = null;

  function measureLabelIcon(text, className = 'surveyor-measure-label') {
    return L.divIcon({
      className,
      html: `<div class="surveyor-measure-pill">${escapeHtmlLocal(text)}</div>`,
      iconSize: [1, 1],
      iconAnchor: [0, 0]
    });
  }

  function readableCadAngle(degrees) {
    let angle = Number(degrees) || 0;
    while (angle > 180) angle -= 360;
    while (angle <= -180) angle += 360;
    if (angle > 90) angle -= 180;
    if (angle < -90) angle += 180;
    return angle;
  }

  function cadSegmentLabelPlacement(a, b, options = {}) {
    if (!map || !a || !b) return null;
    const pointA = map.latLngToContainerPoint(a);
    const pointB = map.latLngToContainerPoint(b);
    const dx = pointB.x - pointA.x;
    const dy = pointB.y - pointA.y;
    const length = Math.hypot(dx, dy);
    if (!Number.isFinite(length) || length < 1) return null;
    const angle = readableCadAngle(Math.atan2(dy, dx) * 180 / Math.PI);
    const normal = { x: -dy / length, y: dx / length };
    const rawOffset = Number.isFinite(Number(options.offset)) ? Math.abs(Number(options.offset)) : 9;
    const mid = { x: (pointA.x + pointB.x) / 2, y: (pointA.y + pointB.y) / 2 };
    let offset = Number(options.offset) < 0 ? -rawOffset : rawOffset;
    if (options.side === 'above') {
      const plusY = mid.y + normal.y * rawOffset;
      const minusY = mid.y - normal.y * rawOffset;
      offset = plusY <= minusY ? rawOffset : -rawOffset;
    }
    return {
      angle,
      latlng: map.containerPointToLatLng([mid.x + normal.x * offset, mid.y + normal.y * offset])
    };
  }

  function cadSegmentMeasureIcon(text, angle, className = 'surveyor-cad-dimension-anchor', labelClassName = 'surveyor-cad-dimension-label') {
    const safeAngle = Math.round((Number(angle) || 0) * 100) / 100;
    const safeClass = /^[a-z0-9_-]+$/i.test(String(labelClassName || '')) ? String(labelClassName) : 'surveyor-cad-dimension-label';
    return L.divIcon({
      className,
      html: `<span class="${safeClass}" style="--surveyor-cad-angle:${safeAngle}deg">${escapeHtmlLocal(text)}</span>`,
      iconSize: [1, 1],
      iconAnchor: [0, 0]
    });
  }

  function measureSegmentMidpoint(a, b) {
    return L.latLng((a.lat + b.lat) / 2, (a.lng + b.lng) / 2);
  }

  function stopSurveyorMeasureTool(options = {}) {
    const state = surveyorMeasureTool;
    if (!state) {
      measureMode = false;
      document.body.classList.remove('drawing-active');
      return;
    }
    state.cleanups?.forEach((cleanup) => {
      try { cleanup(); } catch {}
    });
    if (!state.finished && options.clearDraft !== false) measurementGroup.clearLayers();
    surveyorMeasureTool = null;
    measureMode = false;
    document.body.classList.remove('drawing-active');
    map.doubleClickZoom.enable();
    if (!options.keepActiveTool) setActiveMapTool(els.selectToolBtn);
  }

  function startSurveyorMeasureTool() {
    resetInteractionModes();
    measurementGroup.clearLayers();
    setActiveMapTool(els.measureToolBtn);
    measureMode = true;
    document.body.classList.add('drawing-active');
    map.doubleClickZoom.disable();

    const state = { points: [], finished: false, cleanups: [] };
    surveyorMeasureTool = state;

    const totalDistance = (points) => points.slice(0, -1).reduce((sum, point, index) => sum + point.distanceTo(points[index + 1]), 0);
    const render = (cursor = null) => {
      measurementGroup.clearLayers();
      const points = cursor && state.points.length ? [...state.points, cursor] : [...state.points];
      if (!points.length) return;
      points.forEach((point, index) => {
        L.circleMarker(point, {
          pane: 'drawnPane',
          renderer: drawnRenderer,
          radius: 4,
          color: '#0f5bdc',
          weight: 2,
          fillColor: '#fff',
          fillOpacity: 1,
          interactive: false,
          className: 'no-shadow'
        }).addTo(measurementGroup);
        L.marker(point, { interactive: false, keyboard: false, icon: measureLabelIcon(String(index + 1), 'surveyor-measure-point-label') }).addTo(measurementGroup);
      });
      if (points.length < 2) return;
      L.polyline(points, {
        pane: 'drawnPane',
        renderer: drawnRenderer,
        className: 'surveyor-measure-line no-shadow',
        color: '#0f5bdc',
        weight: 3,
        dashArray: '8 6',
        opacity: 1,
        lineCap: 'round',
        lineJoin: 'round',
        interactive: false
      }).addTo(measurementGroup);
      for (let i = 0; i < points.length - 1; i += 1) {
        const dist = points[i].distanceTo(points[i + 1]);
        const placement = cadSegmentLabelPlacement(points[i], points[i + 1], { offset: 9, side: 'above' });
        if (placement) {
          L.marker(placement.latlng, {
            interactive: false,
            keyboard: false,
            zIndexOffset: 2200,
            icon: cadSegmentMeasureIcon(`${n(dist, 2)} m`, placement.angle, 'surveyor-measure-segment-anchor')
          }).addTo(measurementGroup);
        }
      }
      const last = points[points.length - 1];
      L.marker(last, {
        interactive: false,
        keyboard: false,
        zIndexOffset: 2300,
        icon: measureLabelIcon(`Total: ${n(totalDistance(points), 2)} m`, 'surveyor-measure-total-label')
      }).addTo(measurementGroup);
    };

    const finish = () => {
      if (state.points.length < 2) {
        toast('Clique pelo menos dois pontos para medir.', 'error');
        return;
      }
      state.finished = true;
      render();
      const total = totalDistance(state.points);
      stopSurveyorMeasureTool({ clearDraft: false });
      toast(`Distância medida: ${n(total, 2)} m`, 'success');
    };

    const onClick = (event) => {
      L.DomEvent.stop(event.originalEvent);
      state.points.push(event.latlng);
      render();
      toast(state.points.length === 1 ? 'Clique no próximo ponto. Dê duplo clique para finalizar.' : 'Continue clicando ou dê duplo clique para finalizar.', 'success');
    };
    const onMove = (event) => render(event.latlng);
    const onDblClick = (event) => {
      L.DomEvent.stop(event.originalEvent);
      finish();
    };
    const onContextMenu = (event) => {
      L.DomEvent.stop(event.originalEvent);
      openSurveyorMapContextMenu(event, { cancelOnly: true });
    };

    map.on('click', onClick);
    map.on('mousemove', onMove);
    map.on('dblclick', onDblClick);
    map.on('contextmenu', onContextMenu);
    state.cleanups.push(() => map.off('click', onClick), () => map.off('mousemove', onMove), () => map.off('dblclick', onDblClick), () => map.off('contextmenu', onContextMenu));
    activeLeafletHandler = { disable: () => stopSurveyorMeasureTool({ clearDraft: true, keepActiveTool: true }) };
    toast('Medição ativada: clique os pontos. Duplo clique ou botão direito finaliza.', 'success');
  }

  function closeVertexHideChoice() {
    vertexHideChoiceNode?.remove?.();
    vertexHideChoiceNode = null;
  }

  function stopVertexHideMode() {
    vertexHideMode = false;
    closeVertexHideChoice();
    document.body.classList.remove('surveyor-vertex-hide-mode', 'surveyor-vertex-restore-mode');
    els.vertexHideToolBtn?.classList.remove('is-enabled', 'active');
    els.vertexHideToolBtn?.setAttribute('aria-pressed', 'false');
    if (directEditMode) requestAnimationFrame(decorateAllDirectEditHandles);
  }

  function startVertexHideMode(operation = 'virtual') {
    resetInteractionModes({ preserveVertexHide: true });
    vertexHideOperation = operation === 'restore' ? 'restore' : operation === 'delete' ? 'delete' : 'virtual';
    vertexHideMode = true;
    closeVertexHideChoice();
    document.body.classList.toggle('surveyor-vertex-hide-mode', vertexHideOperation !== 'restore');
    document.body.classList.toggle('surveyor-vertex-restore-mode', vertexHideOperation === 'restore');
    els.vertexHideToolBtn?.classList.add('is-enabled', 'active');
    els.vertexHideToolBtn?.setAttribute('aria-pressed', 'true');
    const target = selectedLayer && drawn.hasLayer(selectedLayer) && map.hasLayer(selectedLayer) ? selectedLayer : null;
    if (target) {
      beginDirectEditMode(els.vertexHideToolBtn || els.cadToolsMenuBtn);
      requestAnimationFrame(decorateAllDirectEditHandles);
    } else {
      setActiveMapTool(els.vertexHideToolBtn || els.cadToolsMenuBtn);
    }
    toast(vertexHideOperation === 'restore'
      ? 'Restauração virtual ativada: os vértices ocultados aparecem em verde. Clique neles para recuperar o rótulo V-xx. Botão direito → Cancelar ferramenta para sair.'
      : vertexHideOperation === 'virtual'
        ? 'Remoção virtual ativada: clique nos vértices cujos rótulos V-xx não devem aparecer na geração. Botão direito → Cancelar ferramenta para sair.'
        : 'Remoção definitiva ativada: clique nos vértices que devem sair da geometria. Botão direito → Cancelar ferramenta para sair.', 'success');
  }

  function restorableVertexLayers() {
    const items = [];
    drawn.eachLayer((layer) => {
      const count = hiddenVertexCount(layer);
      if (count < 1) return;
      const feature = layer.toGeoJSON?.();
      const type = String(feature?.geometry?.type || '');
      if (!/(Polygon|LineString)/.test(type)) return;
      const p = metadata(layer);
      items.push({
        layer,
        count,
        name: String(p.name || categories[p.category]?.label || 'Elemento sem nome').trim() || 'Elemento sem nome',
        category: categories[p.category]?.label || p.category || type
      });
    });
    return items;
  }

  function openVertexRestoreTargetChoice() {
    closeVertexHideChoice();
    const candidates = restorableVertexLayers();
    if (!candidates.length) {
      toast('Nenhum polígono ou linha deste projeto possui vértices removidos virtualmente.', 'error');
      return;
    }
    if (candidates.length === 1) {
      select(candidates[0].layer, { focus: false });
      startVertexHideMode('restore');
      return;
    }
    const node = document.createElement('div');
    node.className = 'surveyor-vertex-remove-choice surveyor-vertex-restore-choice';
    node.innerHTML = `<strong>De qual desenho deseja restaurar os vértices?</strong><span class="surveyor-vertex-choice-hint">Somente elementos que possuem vértices removidos virtualmente aparecem aqui.</span><div class="surveyor-vertex-restore-list"></div>`;
    const list = node.querySelector('.surveyor-vertex-restore-list');
    candidates.forEach((item, index) => {
      const option = document.createElement('button');
      option.type = 'button';
      option.dataset.vertexRestoreTarget = String(index);
      option.innerHTML = `<b>${escapeHtmlLocal(item.name)}</b><span>${escapeHtmlLocal(String(item.category))} • ${item.count} vértice(s) para restaurar</span>`;
      list.append(option);
    });
    document.body.appendChild(node);
    node.style.left = '50%';
    node.style.top = '50%';
    node.style.transform = 'translate(-50%, -50%)';
    vertexHideChoiceNode = node;
    node.addEventListener('click', (event) => {
      const target = event.target?.closest?.('[data-vertex-restore-target]');
      if (!target) return;
      event.stopPropagation();
      const item = candidates[Number(target.dataset.vertexRestoreTarget)];
      if (!item?.layer || !drawn.hasLayer(item.layer)) return;
      select(item.layer, { focus: false });
      startVertexHideMode('restore');
    });
  }

  function openVertexHideChoice() {
    closeVertexHideChoice();
    const button = els.vertexHideToolBtn;
    if (!button) return;
    const node = document.createElement('div');
    node.className = 'surveyor-vertex-remove-choice';
    const restorableCount = restorableVertexLayers().reduce((total, item) => total + item.count, 0);
    node.innerHTML = `<strong>Vértices</strong><button type="button" data-vertex-remove-mode="restore"><b>Restaurar removidos virtualmente</b><span>${restorableCount > 0 ? `${restorableCount} vértice(s) disponível(is) para restauração no projeto.` : 'Nenhum vértice virtualmente removido foi encontrado neste projeto.'}</span></button><button type="button" data-vertex-remove-mode="virtual"><b>Remoção virtual</b><span>Mantém o ponto e a geometria, mas oculta o rótulo V-xx nas gerações.</span></button><button type="button" data-vertex-remove-mode="delete"><b>Remoção definitiva</b><span>Exclui o ponto da geometria e conecta os vértices vizinhos.</span></button>`;
    document.body.appendChild(node);
    node.style.left = '50%';
    node.style.top = '50%';
    node.style.transform = 'translate(-50%, -50%)';
    vertexHideChoiceNode = node;
    node.addEventListener('click', (event) => {
      const mode = event.target?.closest?.('[data-vertex-remove-mode]')?.dataset?.vertexRemoveMode;
      if (!mode) return;
      event.stopPropagation();
      if (mode === 'restore') {
        openVertexRestoreTargetChoice();
        return;
      }
      startVertexHideMode(mode);
    });
  }

  function resetInteractionModes(options = {}) {
    // IMPORTANT: disableActiveHandler must run before endDirectEditMode.
    // The direct-edit handler owns the Leaflet.EditToolbar.Edit instance and its
    // disable() callback is what actually removes every vertex/midpoint handle.
    // If directEditMode is cleared first, the callback returns early and leaves
    // a ghost editor attached to the FeatureGroup; newly imported polygons then
    // receive hundreds of editing handles even though the UI no longer says Edit.
    disableActiveHandler();
    endDirectEditMode({ apply: true });
    stopSurveyorMeasureTool({ clearDraft: true, keepActiveTool: true });
    stopSurveyorLiveTool();
    stopManualDimensionTool();
    stopTerrainElevationClick();
    if (!options.preserveVertexHide) stopVertexHideMode();
    identifyMode = false;
    coordinateMode = false;
    measureMode = false;
    glebaCutLineMode = false;
    document.querySelector('.geo-map-stage')?.classList.remove('identify-mode', 'coordinate-mode');
    els.coordinateReadout?.classList.add('hidden');
    document.body.classList.remove('drawing-active', 'survey-live-drawing', 'surveyor-draw-active', 'surveyor-live-draw-active', 'survey-curve-cut-drawing');
  }

  els.selectToolBtn?.addEventListener('click', () => {
    resetInteractionModes();
    setActiveMapTool(els.selectToolBtn);
    hideToolPopovers();
    toast('Modo de seleção ativado.', 'success');
  });

  els.identifyToolBtn?.addEventListener('click', () => {
    const enabling = !identifyMode;
    resetInteractionModes();
    identifyMode = enabling;
    document.querySelector('.geo-map-stage')?.classList.toggle('identify-mode', enabling);
    setActiveMapTool(enabling ? els.identifyToolBtn : els.selectToolBtn);
    toast(enabling ? 'Clique no mapa para identificar elementos.' : 'Identificação desativada.', 'success');
  });

  function toolPopoverItems() {
    return [
      { popover: els.drawToolsPopover, trigger: els.toolsMenuBtn, button: els.toolsMenuBtn, width: 305 },
      { popover: els.cadToolsPopover, trigger: els.cadToolsMenuBtn, button: els.cadToolsMenuBtn, width: 305 },
      { popover: els.sigToolsPopover, trigger: els.sigToolsMenuBtn, button: els.sigToolsMenuBtn, width: 305 },
      { popover: els.terrainToolsPopover, trigger: els.terrainToolsMenuBtn, button: els.terrainToolsMenuBtn, width: 255 }
    ];
  }

  function hideToolPopovers(except = null) {
    toolPopoverItems().forEach(({ popover }) => {
      if (popover && popover !== except) popover.classList.add('hidden');
    });
  }

  function positionToolPopover(popover, trigger, preferredWidth = 305) {
    if (!popover || !trigger) return;
    const rect = trigger.getBoundingClientRect();
    const width = Math.min(preferredWidth, window.innerWidth - 24);
    let left = rect.left;
    if (left + width > window.innerWidth - 12) left = window.innerWidth - width - 12;
    left = Math.max(12, left);
    popover.style.left = `${left}px`;
    popover.style.top = `${Math.min(window.innerHeight - 70, rect.bottom + 8)}px`;
    popover.style.width = `${width}px`;
  }

  function toggleToolPopover(popover, trigger, activeButton, preferredWidth) {
    if (!popover || !trigger) return;
    const willOpen = popover.classList.contains('hidden');
    hideToolPopovers(popover);
    if (willOpen) {
      positionToolPopover(popover, trigger, preferredWidth);
      popover.classList.remove('hidden');
      setActiveMapTool(activeButton || trigger);
    } else {
      popover.classList.add('hidden');
      if (!identifyMode && !coordinateMode && !measureMode) setActiveMapTool(els.selectToolBtn);
    }
  }

  els.toolsMenuBtn?.addEventListener('click', (event) => {
    event.stopPropagation();
    toggleToolPopover(els.drawToolsPopover, els.toolsMenuBtn, els.toolsMenuBtn, 305);
  });

  els.cadToolsMenuBtn?.addEventListener('click', (event) => {
    event.stopPropagation();
    toggleToolPopover(els.cadToolsPopover, els.cadToolsMenuBtn, els.cadToolsMenuBtn, 305);
  });

  els.sigToolsMenuBtn?.addEventListener('click', (event) => {
    event.stopPropagation();
    toggleToolPopover(els.sigToolsPopover, els.sigToolsMenuBtn, els.sigToolsMenuBtn, 305);
  });

  els.terrainToolsMenuBtn?.addEventListener('click', (event) => {
    event.stopPropagation();
    toggleToolPopover(els.terrainToolsPopover, els.terrainToolsMenuBtn, els.terrainToolsMenuBtn, 255);
  });

  window.addEventListener('resize', () => {
    toolPopoverItems().forEach(({ popover, trigger, width }) => {
      if (popover && !popover.classList.contains('hidden')) positionToolPopover(popover, trigger, width);
    });
  });

  document.addEventListener('click', (event) => {
    const insidePopover = event.target.closest('#drawToolsPopover, #cadToolsPopover, #sigToolsPopover, #terrainToolsPopover');
    const insideTrigger = event.target.closest('#toolsMenuBtn, #cadToolsMenuBtn, #sigToolsMenuBtn, #terrainToolsMenuBtn');
    if (!insidePopover && !insideTrigger) {
      hideToolPopovers();
      if (!identifyMode && !coordinateMode && !measureMode) setActiveMapTool(els.selectToolBtn);
    }
  });


















  function isGlebaSourceCandidate(layer) {
    const feature = layer?.toGeoJSON?.();
    if (!feature || !/Polygon/.test(feature.geometry?.type || '')) return false;
    const p = metadata(layer);
    // v21.9.208: glebas geradas também podem virar fonte de nova divisão.
    // Isso permite: imóvel -> Gleba 1/Gleba 2 -> subdividir a Gleba 1 e depois a Gleba 2
    // sem exportar/importar e sem apagar as subdivisões da outra gleba.
    return ['perimetro', 'gleba', 'app', 'reserva', 'vegetacao', 'outros'].includes(p.category) || p.generatedBy === 'map-glebas';
  }

  function getGlebaPolygonLayers() {
    return drawn.getLayers().filter(isGlebaSourceCandidate);
  }

  function updateGlebaSourceOptions(keepCurrent = true) {
    if (!els.glebaSourceLayer) return;
    const previous = keepCurrent ? els.glebaSourceLayer.value : '';
    const layers = getGlebaPolygonLayers();
    els.glebaSourceLayer.innerHTML = '<option value="">Selecione ou clique em uma área no mapa</option>';
    layers.forEach((layer, index) => {
      const p = metadata(layer);
      const m = metrics(layer);
      const depth = Number(p.generationDepth || p.glebaDepth || 0) || 0;
      const level = depth > 1 ? ` • subnível ${depth}` : '';
      const option = new Option(`${p.name || `Polígono ${index + 1}`}${level} • ${n(m.areaHa, 4)} ha`, p.id);
      els.glebaSourceLayer.add(option);
    });

    const optionIds = new Set([...els.glebaSourceLayer.options].map((option) => option.value).filter(Boolean));
    if (activeGlebaSourceLayerId && !optionIds.has(activeGlebaSourceLayerId)) activeGlebaSourceLayerId = '';

    if (activeGlebaSourceLayerId && optionIds.has(activeGlebaSourceLayerId)) els.glebaSourceLayer.value = activeGlebaSourceLayerId;
    else if (selectedLayer && layers.includes(selectedLayer)) {
      activeGlebaSourceLayerId = metadata(selectedLayer).id;
      els.glebaSourceLayer.value = activeGlebaSourceLayerId;
    } else if (previous && optionIds.has(previous)) {
      activeGlebaSourceLayerId = previous;
      els.glebaSourceLayer.value = previous;
    } else if (layers[0]) {
      activeGlebaSourceLayerId = metadata(layers[0]).id;
      els.glebaSourceLayer.value = activeGlebaSourceLayerId;
    }

    const activeLayer = layers.find((layer) => metadata(layer).id === els.glebaSourceLayer.value);
    if (els.glebaMapStatus) els.glebaMapStatus.textContent = activeLayer ? `fonte: ${metadata(activeLayer).name || 'polígono'}` : (layers.length ? `${layers.length} área(s)` : 'sem polígono');
  }

  function getGlebaSourceLayer() {
    const layers = getGlebaPolygonLayers();

    // v21.9.209: se há uma camada selecionada no mapa, ela vence o valor antigo
    // do combo. Isso corrige o caso do usuário clicar na Gleba Azul, mandar dividir,
    // e o sistema usar o imóvel original inteiro por causa de seleção anterior/cache.
    if (selectedLayer && layers.includes(selectedLayer)) {
      activeGlebaSourceLayerId = metadata(selectedLayer).id;
      updateGlebaSourceOptions(false);
      return selectedLayer;
    }

    updateGlebaSourceOptions(true);
    const selectedId = activeGlebaSourceLayerId || els.glebaSourceLayer?.value;
    return layers.find((layer) => metadata(layer).id === selectedId) || layers[0];
  }

  function glebaReadHeirs() {
    return [...(els.glebaHeirsList?.querySelectorAll('.map-gleba-heir-row') || [])].map((row, index) => ({
      name: row.querySelector('[data-gleba-heir-name]')?.value?.trim() || `Herdeiro ${index + 1}`,
      areaHa: Number(String(row.querySelector('[data-gleba-heir-area]')?.value || '').replace(',', '.')) || 0
    }));
  }

  function syncGlebaHeirRows(force = false) {
    if (!els.glebaHeirsList || !els.glebaMapCount) return;
    const count = Math.max(2, Math.min(80, Number(els.glebaMapCount.value || 2)));
    els.glebaMapCount.value = count;
    const current = glebaReadHeirs();
    if (!force && current.length === count) {
      els.glebaHeirsList.classList.toggle('is-custom', els.glebaMapMode?.value === 'custom');
      return;
    }
    els.glebaHeirsList.innerHTML = '';
    for (let i = 0; i < count; i++) {
      const row = document.createElement('div');
      row.className = 'map-gleba-heir-row';
      row.innerHTML = `<span>${i + 1}</span><input data-gleba-heir-name placeholder="Nome do herdeiro ${i + 1}"><input data-gleba-heir-area placeholder="Área ha">`;
      row.querySelector('[data-gleba-heir-name]').value = current[i]?.name && !/^Herdeiro\s+\d+/i.test(current[i].name) ? current[i].name : '';
      row.querySelector('[data-gleba-heir-area]').value = current[i]?.areaHa || '';
      els.glebaHeirsList.append(row);
    }
    els.glebaHeirsList.classList.toggle('is-custom', els.glebaMapMode?.value === 'custom');
  }

  function glebaTargetAreas(totalAreaM2, count) {
    if (els.glebaMapMode?.value !== 'custom') return Array(count).fill(totalAreaM2 / count);
    const heirs = glebaReadHeirs();
    const areas = heirs.slice(0, count).map((item) => Number(item.areaHa || 0) * 10000);
    if (areas.some((value) => !Number.isFinite(value) || value <= 0)) throw new Error('Informe a área em hectares para todos os herdeiros.');
    const sum = areas.reduce((a, b) => a + b, 0);
    if (sum > totalAreaM2 * 1.002) throw new Error('A soma das áreas é maior que a área do imóvel.');
    if (Math.abs(sum - totalAreaM2) > totalAreaM2 * 0.03) throw new Error('A soma das áreas personalizadas precisa ficar próxima da área total do imóvel.');
    return areas;
  }

  function resolveGlebaOrientation(projected) {
    const option = els.glebaMapOrientation?.value || 'x';
    const azimuth = Number(els.glebaMapAzimuth?.value || 0);
    const initialBox = glebaBBox(projected);
    const width = initialBox[2] - initialBox[0];
    const height = initialBox[3] - initialBox[1];
    let axis = 'x';
    let angle = 0;
    let reverse = false;
    let label = option;
    if (option === 'y' || option === 'y-reverse') axis = 'y';
    if (option === 'x-reverse' || option === 'y-reverse' || option === 'angle-reverse') reverse = true;
    if (option === 'angle' || option === 'angle-reverse') angle = -azimuth;
    if (option === 'perp') angle = -(azimuth + 90);
    if (option === 'perp-reverse') { angle = -(azimuth + 90); reverse = true; }
    if (option === 'longest') { axis = width >= height ? 'x' : 'y'; label = 'Automático pelo maior comprimento'; }
    if (option === 'shortest') { axis = width < height ? 'x' : 'y'; label = 'Automático pela menor largura'; }
    if (option === 'diagonal-ne-sw') { angle = -45; label = 'Diagonal NE/SW'; }
    if (option === 'diagonal-nw-se') { angle = 45; label = 'Diagonal NW/SE'; }
    return { axis, angle, reverse, label };
  }


  function glebaCurrentCutType() {
    const value = els.glebaCutType?.value || 'area-strips';
    return value === 'frontage-guide' ? 'frontage-guide' : 'area-strips';
  }










  function glebaManualCutCountLabel() {
    const count = glebaManualCutFeatures.length;
    if (els.glebaCutLineCount) els.glebaCutLineCount.textContent = count === 1 ? '1 linha guia' : `${count} linhas`;
    if (els.glebaCutLinesList) {
      els.glebaCutLinesList.innerHTML = count
        ? glebaManualCutFeatures.map((feature, index) => `<span><b>Corte ${index + 1}</b><small>${Math.max(0, (feature.geometry?.coordinates || []).length)} ponto(s)</small></span>`).join('')
        : '<span class="empty-cut">Nenhuma linha de corte desenhada.</span>';
    }
  }

  function addGlebaCutLineFeature(feature) {
    if (!feature?.geometry || feature.geometry.type !== 'LineString') return;
    const raw = (feature.geometry.coordinates || []).filter((coord) => Number.isFinite(coord?.[0]) && Number.isFinite(coord?.[1]));
    if (raw.length < 2) return;
    const isCurve = feature.properties?.cutType === 'curve-guide' || feature.properties?.curved === true;
    const coords = isCurve ? glebaLimitLinePoints(raw, 56) : raw;
    const clean = {
      type: 'Feature',
      properties: { ...(feature.properties || {}), id: feature.properties?.id || id(), type: 'gleba-cut-line', optimizedPointCount: coords.length, originalPointCount: raw.length },
      geometry: { type: 'LineString', coordinates: coords }
    };
    glebaManualCutFeatures.push(clean);
    L.geoJSON(clean, {
      pane: 'drawnPane',
      style: { pane: 'drawnPane', renderer: drawnRenderer, className: 'surveyor-cut-line no-shadow', color: '#2563eb', weight: 2, dashArray: '10 7', opacity: 1, lineCap: 'round', lineJoin: 'round' },
      onEachFeature: (_f, layer) => layer.bindTooltip(`Corte ${glebaManualCutFeatures.length}`, { sticky: true })
    }).addTo(glebaCutLineGroup);
    glebaManualCutCountLabel();
  }

  function clearGlebaCutLines() {
    glebaManualCutFeatures = [];
    glebaCutLineGroup.clearLayers();
    glebaManualCutCountLabel();
    scheduleGlebaRealtime();
  }






  function clearGlebaMeasureMarkers(layer) {
    (layer?._surveyGlebaMeasureMarkers || []).forEach((marker) => {
      try { map.removeLayer(marker); } catch {}
    });
    if (layer) layer._surveyGlebaMeasureMarkers = [];
  }




  function addGlebaSegmentMeasure(layer, a, b, index, color = '#111111') {
    const latA = glebaMeasureLatLng(a);
    const latB = glebaMeasureLatLng(b);
    if (!latA || !latB || !map) return;
    const meters = latA.distanceTo(latB);
    if (!Number.isFinite(meters) || meters <= 0) return;

    const pointA = map.latLngToContainerPoint(latA);
    const pointB = map.latLngToContainerPoint(latB);
    const dx = pointB.x - pointA.x;
    const dy = pointB.y - pointA.y;
    const length = Math.hypot(dx, dy);
    if (!Number.isFinite(length) || length < 1) return;

    const normalLeft = { x: -dy / length, y: dx / length };
    const normalRight = { x: dy / length, y: -dx / length };
    const centerLatLng = layer?.getBounds?.()?.getCenter?.() || L.latLng((latA.lat + latB.lat) / 2, (latA.lng + latB.lng) / 2);
    const centerPoint = map.latLngToContainerPoint(centerLatLng);
    const midPoint = { x: (pointA.x + pointB.x) / 2, y: (pointA.y + pointB.y) / 2 };
    const probe = 12;
    const distLeft = Math.hypot((midPoint.x + normalLeft.x * probe) - centerPoint.x, (midPoint.y + normalLeft.y * probe) - centerPoint.y);
    const distRight = Math.hypot((midPoint.x + normalRight.x * probe) - centerPoint.x, (midPoint.y + normalRight.y * probe) - centerPoint.y);
    const normal = distLeft >= distRight ? normalLeft : normalRight;
    const labelPoint = map.containerPointToLatLng([midPoint.x + normal.x * 11, midPoint.y + normal.y * 11]);
    const angle = readableCadAngle(Math.atan2(dy, dx) * 180 / Math.PI);

    const textMarker = L.marker(labelPoint, {
      interactive: false,
      keyboard: false,
      bubblingMouseEvents: false,
      zIndexOffset: 1800,
      icon: cadSegmentMeasureIcon(`${n(meters, 1)} m`, angle, 'gleba-measure-anchor')
    }).addTo(map);

    layer._surveyGlebaMeasureMarkers ||= [];
    layer._surveyGlebaMeasureMarkers.push(textMarker);
  }

  function clearGlebaFrontBackMarkers(layer) {
    (layer?._surveyGlebaFrontBackMarkers || []).forEach((marker) => {
      try { map.removeLayer(marker); } catch {}
    });
    if (layer) layer._surveyGlebaFrontBackMarkers = [];
  }




  function storedFrontBackForGleba(layer) {
    const p = metadata(layer);
    const frontMeters = Number(p.frontMeters ?? p.frontageMeters ?? p.frenteMeters);
    const backMeters = Number(p.backMeters ?? p.rearMeters ?? p.fundoMeters);
    let frontPoint = validGlebaLabelPoint(p.frontLabelPoint || p.frontPoint || p.frontageLabelPoint);
    let backPoint = validGlebaLabelPoint(p.backLabelPoint || p.backPoint || p.rearLabelPoint);

    if (Number.isFinite(frontMeters) && frontMeters > 0 && Number.isFinite(backMeters) && backMeters > 0 && frontPoint && backPoint) {
      // A v21.9.344/345 guardava os pontos 8% para dentro do lote. Recupera
      // a borda original uma única vez para mover as etiquetas para fora.
      if (Number(p.frontBackMeasurementVersion || 0) < 2) {
        const center = frontBackLayerCenterPoint(layer);
        frontPoint = restoreLegacyFrontBackEdge(frontPoint, center);
        backPoint = restoreLegacyFrontBackEdge(backPoint, center);
        p.frontLabelPoint = frontPoint;
        p.backLabelPoint = backPoint;
        p.frontBackMeasurementVersion = 2;
      }
      return { frontMeters, backMeters, frontPoint, backPoint };
    }

    // Compatibilidade com projetos e glebas já salvos antes desta opção. Sem
    // uma linha de frente registrada, a borda mais ao sul é usada como frente
    // visual e a oposta como fundo, sem modificar a geometria.
    try {
      const feature = layer.toGeoJSON?.();
      if (!feature?.geometry || !/Polygon/.test(feature.geometry.type || '')) return null;
      const projection = glebaProjection(feature);
      const projected = glebaTransformFeature(feature, projection.toXY);
      const measured = glebaMeasureFrontBack(projected, projected, [0, 1]);
      frontPoint = measured.frontPoint ? projection.toLngLat(measured.frontPoint) : null;
      backPoint = measured.backPoint ? projection.toLngLat(measured.backPoint) : null;
      if (!Number.isFinite(measured.frontMeters) || !Number.isFinite(measured.backMeters) || !frontPoint || !backPoint) return null;
      p.frontMeters = measured.frontMeters;
      p.backMeters = measured.backMeters;
      p.frontLabelPoint = frontPoint;
      p.backLabelPoint = backPoint;
      p.frontBackMeasurementVersion = 2;
      return { frontMeters: measured.frontMeters, backMeters: measured.backMeters, frontPoint, backPoint };
    } catch {
      return null;
    }
  }

  function frontBackLabelPosition(layer, point, occupied = []) {
    const anchor = glebaMeasureLatLng(point);
    if (!anchor || !map) return anchor;
    const anchorPoint = map.latLngToContainerPoint(anchor);
    // A etiqueta sempre sai pelo lado externo da borda medida. O centro
    // geométrico evita que uma gleba inclinada empurre "Frente" ou "Fundo"
    // para dentro de outra gleba.
    const center = glebaMeasureLatLng(frontBackLayerCenterPoint(layer)) || layer?.getBounds?.()?.getCenter?.() || anchor;
    const centerPoint = map.latLngToContainerPoint(center);
    let dx = anchorPoint.x - centerPoint.x;
    let dy = anchorPoint.y - centerPoint.y;
    let length = Math.hypot(dx, dy);
    if (!Number.isFinite(length) || length < 1) { dx = 0; dy = -1; length = 1; }
    const outward = { x: dx / length, y: dy / length };
    const tangent = { x: -outward.y, y: outward.x };
    // Mantém rótulos vizinhos legíveis. Em vez de sobrepor textos, desloca-os
    // ao longo da própria borda, preservando o lado externo do lote.
    const attempts = [0, 1, -1, 2, -2, 3, -3, 4, -4];
    let chosen = null;
    for (const step of attempts) {
      const candidate = {
        x: anchorPoint.x + outward.x * 30 + tangent.x * step * 52,
        y: anchorPoint.y + outward.y * 30 + tangent.y * step * 52
      };
      const collides = occupied.some((item) => Math.hypot(candidate.x - item.x, candidate.y - item.y) < 108);
      if (!collides) { chosen = candidate; break; }
      chosen = candidate;
    }
    occupied.push(chosen);
    return map.containerPointToLatLng([chosen.x, chosen.y]);
  }

  function addGlebaFrontBackLabel(layer, kind, meters, point, color = '#2563eb', occupied = []) {
    const latlng = frontBackLabelPosition(layer, point, occupied);
    if (!latlng || !Number.isFinite(Number(meters)) || Number(meters) <= 0) return;
    const label = kind === 'Frente' ? 'Frente' : 'Fundo';
    const marker = L.marker(latlng, {
      interactive: false,
      keyboard: false,
      bubblingMouseEvents: false,
      zIndexOffset: 2400,
      icon: L.divIcon({
        className: 'gleba-front-back-anchor',
        html: `<div class="gleba-front-back-label gleba-front-back-${label.toLowerCase()}" style="--gleba-label-color:${String(color || '#2563eb')}"><b>${label}:</b>&nbsp;${n(meters, 1)} m</div>`,
        iconSize: [1, 1],
        iconAnchor: [0, 0]
      })
    }).addTo(map);
    layer._surveyGlebaFrontBackMarkers ||= [];
    layer._surveyGlebaFrontBackMarkers.push(marker);
  }


  function frontBackTargetLayers() {
    const polygons = drawn.getLayers().filter(isFrontBackPolygonLayer);
    const glebas = polygons.filter((layer) => {
      const p = metadata(layer);
      return p.category === 'gleba' || p.generatedBy === 'map-glebas';
    });
    // Quando existem glebas, mantém uma etiqueta para cada uma delas, como no
    // croqui de divisão. Sem glebas, a etiqueta passa a ser do perímetro do
    // projeto, que é o caso mais comum ao abrir um projeto normal.
    if (glebas.length) return glebas;
    const perimeters = polygons.filter((layer) => metadata(layer).category === 'perimetro');
    return perimeters.length ? perimeters : polygons;
  }

  function updateGlebaFrontBackLabels(layer, options = {}) {
    if (!layer || !map) return;
    clearGlebaFrontBackMarkers(layer);
    const p = metadata(layer);
    if (!glebaFrontBackLabelsEnabled || !isFrontBackPolygonLayer(layer)) return;
    if (!frontBackTargetLayers().includes(layer)) return;
    const data = storedFrontBackForGleba(layer);
    if (!data) return;
    const color = p.styleColor || p.strokeColor || p.color || '#2563eb';
    const occupied = Array.isArray(options.occupied) ? options.occupied : [];
    addGlebaFrontBackLabel(layer, 'Frente', data.frontMeters, data.frontPoint, color, occupied);
    addGlebaFrontBackLabel(layer, 'Fundo', data.backMeters, data.backPoint, color, occupied);
  }

  function updateGlebaMeasureTooltip(layer) {
    if (!layer || !map) return;
    const p = metadata(layer);
    clearGlebaMeasureMarkers(layer);
    try { layer.unbindTooltip?.(); } catch {}
    if (!layer._surveyGlebaMeasureCleanupBound) {
      layer.on?.('remove', () => {
        clearGlebaMeasureMarkers(layer);
        clearGlebaFrontBackMarkers(layer);
      });
      layer.on?.('add', () => {
        updateGlebaMeasureTooltip(layer);
        updateGlebaFrontBackLabels(layer);
      });
      layer._surveyGlebaMeasureCleanupBound = true;
    }
    if (!segmentMeasuresEnabled) return;
    if (p.category === 'ponto' || layer instanceof L.Marker || layer instanceof L.Circle || layer instanceof L.CircleMarker) return;
    const segmentData = drawnSegmentCoordsFromLayer(layer);
    const coords = segmentData.coords;
    if (coords.length < 2) return;
    const color = p.styleColor || p.strokeColor || p.color || (p.category === 'gleba' ? '#2563eb' : '#0f5bdc');
    const totalSegments = segmentData.closed ? coords.length : coords.length - 1;
    for (let index = 0; index < totalSegments; index += 1) {
      const point = coords[index];
      const next = coords[(index + 1) % coords.length];
      if (!point || !next) continue;
      addGlebaSegmentMeasure(layer, point, next, index, color);
    }
  }

  function serializeGlebaProjectState() {
    return sanitizeForJson({
      controls: {
        count: Number(els.glebaMapCount?.value || 2),
        baseName: els.glebaMapBaseName?.value?.trim() || 'Gleba',
        cutType: glebaCurrentCutType(),
        replaceGenerated: Boolean(els.glebaMapReplace?.checked)
      },
      cutLines: glebaManualCutFeatures.map((feature) => ({
        type: 'Feature',
        properties: sanitizeForJson(feature.properties || {}) || {},
        geometry: sanitizeForJson(feature.geometry || {}) || null
      })).filter((feature) => feature.geometry?.type === 'LineString' && Array.isArray(feature.geometry?.coordinates) && feature.geometry.coordinates.length >= 2)
    }) || {};
  }

  function restoreGlebaProjectState(state = {}) {
    clearGlebaCutLines();
    if (state?.controls) {
      if (els.glebaMapCount && state.controls.count) els.glebaMapCount.value = String(state.controls.count);
      if (els.glebaMapBaseName && state.controls.baseName) els.glebaMapBaseName.value = state.controls.baseName;
      if (els.glebaCutType && state.controls.cutType) els.glebaCutType.value = state.controls.cutType;
      if (els.glebaMapReplace && typeof state.controls.replaceGenerated === 'boolean') els.glebaMapReplace.checked = state.controls.replaceGenerated;
    }
    (state?.cutLines || []).forEach((feature) => addGlebaCutLineFeature(feature));
  }

  function startGlebaCurveGuideDrawing() {
    glebaCutLineMode = false;
    disableActiveHandler();
    stopSurveyorLiveTool({ keepActiveTool: true });
    resetInteractionModes();
    setActiveMapTool(els.toolsMenuBtn);
    document.body.classList.add('drawing-active', 'survey-live-drawing', 'survey-curve-cut-drawing');

    const points = [];
    let finished = false;
    liveDrawGroup.clearLayers();

    const curveStyle = {
      pane: 'liveDrawPane',
      renderer: liveRenderer,
      className: 'surveyor-cut-live no-shadow',
      color: '#2563eb',
      weight: 4,
      opacity: 1,
      dashArray: '8 6',
      lineCap: 'round',
      lineJoin: 'round',
      interactive: false
    };

    const helperStyle = {
      ...curveStyle,
      className: 'surveyor-cut-helper no-shadow',
      color: '#94a3b8',
      weight: 2,
      dashArray: '4 7',
      opacity: 0.72
    };

    const almostSamePoint = (a, b) => {
      if (!a || !b) return false;
      try {
        const pa = map.latLngToContainerPoint(a);
        const pb = map.latLngToContainerPoint(b);
        return pa.distanceTo(pb) < 6;
      } catch (_) {
        return Math.abs(Number(a.lat) - Number(b.lat)) < 1e-10 && Math.abs(Number(a.lng) - Number(b.lng)) < 1e-10;
      }
    };

    const addPointMarker = (latlng, index, cursor = false) => {
      L.circleMarker(latlng, {
        pane: 'liveDrawPane',
        renderer: liveRenderer,
        radius: cursor ? 4 : 5,
        color: cursor ? '#f97316' : '#2563eb',
        weight: 2,
        fillColor: '#fff',
        fillOpacity: 1,
        interactive: false,
        className: 'surveyor-cut-live-point no-shadow'
      })
        .bindTooltip(cursor ? 'prévia' : String(index + 1), {
          permanent: !cursor,
          direction: 'top',
          className: 'surveyor-live-draw-label',
          opacity: 1
        })
        .addTo(liveDrawGroup);
    };

    const densifySegment = (a, b, pieces = 8) => {
      const out = [];
      for (let i = 0; i <= pieces; i++) {
        const t = i / pieces;
        out.push(L.latLng(a.lat + (b.lat - a.lat) * t, a.lng + (b.lng - a.lng) * t));
      }
      return out;
    };

    const catmullRomPoint = (p0, p1, p2, p3, t) => {
      const t2 = t * t;
      const t3 = t2 * t;
      const lng = 0.5 * ((2 * p1.lng) + (-p0.lng + p2.lng) * t + (2 * p0.lng - 5 * p1.lng + 4 * p2.lng - p3.lng) * t2 + (-p0.lng + 3 * p1.lng - 3 * p2.lng + p3.lng) * t3);
      const lat = 0.5 * ((2 * p1.lat) + (-p0.lat + p2.lat) * t + (2 * p0.lat - 5 * p1.lat + 4 * p2.lat - p3.lat) * t2 + (-p0.lat + 3 * p1.lat - 3 * p2.lat + p3.lat) * t3);
      return L.latLng(lat, lng);
    };

    const downsampleLatLngs = (latlngs, maxPoints = 140) => {
      if (!Array.isArray(latlngs) || latlngs.length <= maxPoints) return latlngs || [];
      const result = [];
      const last = latlngs.length - 1;
      for (let i = 0; i < maxPoints; i++) {
        const index = Math.round((i / (maxPoints - 1)) * last);
        const point = latlngs[index];
        if (!result.length || !almostSamePoint(result[result.length - 1], point)) result.push(point);
      }
      return result;
    };

    const smoothCurveFromPoints = (sourcePoints, maxPoints = 140) => {
      const pts = (sourcePoints || []).filter(Boolean);
      if (pts.length < 2) return pts;
      if (pts.length === 2) return densifySegment(pts[0], pts[1], 12);

      const samplesPerSegment = pts.length <= 8 ? 14 : pts.length <= 20 ? 9 : pts.length <= 50 ? 5 : 3;
      const curve = [];
      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i - 1] || pts[i];
        const p1 = pts[i];
        const p2 = pts[i + 1];
        const p3 = pts[i + 2] || p2;
        for (let step = 0; step < samplesPerSegment; step++) {
          if (i > 0 && step === 0) continue;
          curve.push(catmullRomPoint(p0, p1, p2, p3, step / samplesPerSegment));
        }
      }
      curve.push(pts[pts.length - 1]);
      return downsampleLatLngs(curve, maxPoints);
    };

    const previewCurve = (cursor = null) => {
      liveDrawGroup.clearLayers();
      points.forEach((point, index) => addPointMarker(point, index));

      if (points.length === 0) {
        if (cursor) addPointMarker(cursor, 0, true);
        return;
      }

      const draft = cursor && !almostSamePoint(points[points.length - 1], cursor) ? [...points, cursor] : [...points];
      if (draft.length >= 2) {
        const curve = smoothCurveFromPoints(draft, 120);
        L.polyline(curve, curveStyle).addTo(liveDrawGroup);
        if (draft.length > 2) L.polyline(draft, helperStyle).addTo(liveDrawGroup);
      }
      if (cursor) addPointMarker(cursor, points.length, true);
    };

    const cleanup = () => {
      map.off('click', onClick);
      map.off('mousemove', onMove);
      map.off('dblclick', onDoubleClick);
      document.removeEventListener('keydown', onKey);
      try { map.doubleClickZoom.enable(); } catch (_) {}
      liveDrawGroup.clearLayers();
      document.body.classList.remove('drawing-active', 'survey-live-drawing', 'survey-curve-cut-drawing');
      setActiveMapTool(els.selectToolBtn);
    };

    const finish = () => {
      if (finished) return;
      if (points.length < 3) {
        toast('Curva guia: marque pelo menos 3 pontos e finalize com duplo clique no último ponto.', 'error');
        return;
      }
      finished = true;
      const curveLatLngs = smoothCurveFromPoints(points, 140);
      const coords = curveLatLngs.map((p) => [p.lng, p.lat]);
      cleanup();
      const feature = {
        type: 'Feature',
        properties: {
          id: id(),
          type: 'gleba-cut-line',
          cutType: 'curve-guide',
          curved: true,
          method: 'multi-point-smooth-curve',
          pointCount: coords.length,
          controlPoints: points.map((p) => [p.lng, p.lat])
        },
        geometry: { type: 'LineString', coordinates: coords }
      };
      addGlebaCutLineFeature(feature);
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = 'curva pronta';
      if (els.glebaMapSummary) els.glebaMapSummary.textContent = `Curva precisa adicionada com ${points.length} ponto(s). Clique em “Gerar no mapa” para dividir por trechos ao longo da frente/acesso.`;
      toast(`Curva precisa criada com ${points.length} ponto(s). Agora clique em Gerar no mapa para dividir preservando a frente/acesso.`, 'success');
    };

    function onClick(event) {
      if (event.originalEvent?.detail > 1) return;
      L.DomEvent.stop(event.originalEvent || event);
      const last = points[points.length - 1];
      if (!almostSamePoint(last, event.latlng)) points.push(event.latlng);
      previewCurve(event.latlng);
      if (points.length === 1) toast('Curva guia: marque o próximo ponto da curva.', 'success');
      else toast(`Curva guia: ${points.length} pontos marcados. Continue marcando ou dê duplo clique no último ponto para finalizar.`, 'success');
    }

    function onMove(event) {
      previewCurve(event.latlng);
    }

    function onDoubleClick(event) {
      L.DomEvent.stop(event.originalEvent || event);
      if (event.latlng && !almostSamePoint(points[points.length - 1], event.latlng)) points.push(event.latlng);
      if (points.length >= 3) finish();
      else toast('Curva guia: marque pelo menos 3 pontos antes de finalizar.', 'error');
    }

    function onKey(event) {
      if (event.key === 'Escape') {
        cleanup();
        toast('Desenho da curva cancelado.', 'success');
      }
      if (event.key === 'Enter' && points.length >= 3) finish();
    }

    try { map.doubleClickZoom.disable(); } catch (_) {}
    map.on('click', onClick);
    map.on('mousemove', onMove);
    map.on('dblclick', onDoubleClick);
    document.addEventListener('keydown', onKey);
    toast('Curva precisa: clique acompanhando a frente/acesso. Finalize com duplo clique no último ponto ou Enter.', 'success');
  }

  function startGlebaCutLineDrawing() {
    if (els.glebaCutType) els.glebaCutType.value = 'frontage-guide';
    glebaCutLineMode = false;
    disableActiveHandler();
    stopSurveyorLiveTool({ keepActiveTool: true });
    resetInteractionModes();
    setActiveMapTool(els.toolsMenuBtn);

    const points = [];
    let finished = false;
    let lastClickAt = 0;
    let singleClickTimer = null;
    liveDrawGroup.clearLayers();
    document.body.classList.add('drawing-active', 'survey-live-drawing', 'survey-frontage-guide-drawing');

    const drawStyle = {
      pane: 'liveDrawPane',
      renderer: liveRenderer,
      className: 'surveyor-cut-live no-shadow',
      color: '#2563eb',
      weight: 2,
      opacity: 1,
      dashArray: null,
      lineCap: 'round',
      lineJoin: 'round',
      interactive: false
    };

    const addMarker = (latlng, index, cursor = false) => {
      L.circleMarker(latlng, {
        pane: 'liveDrawPane',
        renderer: liveRenderer,
        radius: cursor ? 4 : 6,
        color: cursor ? '#f97316' : '#2563eb',
        weight: 2,
        fillColor: '#fff',
        fillOpacity: 1,
        interactive: false,
        className: 'surveyor-cut-live-point no-shadow'
      }).bindTooltip(cursor ? 'prévia' : String(index + 1), {
        permanent: !cursor,
        direction: 'top',
        className: 'surveyor-live-draw-label',
        opacity: 1
      }).addTo(liveDrawGroup);
    };

    const almostSamePoint = (a, b) => {
      if (!a || !b) return false;
      try { return map.latLngToContainerPoint(a).distanceTo(map.latLngToContainerPoint(b)) < 7; }
      catch (_) { return Math.abs(Number(a.lat) - Number(b.lat)) < 1e-10 && Math.abs(Number(a.lng) - Number(b.lng)) < 1e-10; }
    };

    const redraw = (cursor = null) => {
      liveDrawGroup.clearLayers();
      points.forEach((point, index) => addMarker(point, index));
      const draft = cursor && points.length && !almostSamePoint(points[points.length - 1], cursor) ? [...points, cursor] : [...points];
      if (draft.length >= 2) L.polyline(draft, drawStyle).addTo(liveDrawGroup);
      if (cursor) addMarker(cursor, points.length, true);
    };

    const cleanup = () => {
      map.off('click', onClick);
      map.off('mousemove', onMove);
      map.off('dblclick', onDoubleClick);
      document.removeEventListener('keydown', onKey);
      try { map.doubleClickZoom.enable(); } catch (_) {}
      liveDrawGroup.clearLayers();
      document.body.classList.remove('drawing-active', 'survey-live-drawing', 'survey-frontage-guide-drawing');
      setActiveMapTool(els.selectToolBtn);
      activeLeafletHandler = null;
    };

    const finish = () => {
      if (finished) return;
      if (points.length < 2) {
        toast('Desenhe pelo menos 2 pontos para definir a direção da divisão.', 'error');
        return;
      }
      finished = true;
      const coords = points.map((p) => [p.lng, p.lat]);
      cleanup();
      addGlebaCutLineFeature({
        type: 'Feature',
        properties: { id: id(), type: 'gleba-cut-line', cutType: 'frontage-guide', method: 'custom-map-guide', pointCount: coords.length },
        geometry: { type: 'LineString', coordinates: coords }
      });
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = 'guia pronta';
      if (els.glebaMapSummary) els.glebaMapSummary.textContent = 'Linha guia adicionada. Clique em “Gerar no mapa” para dividir o polígono em áreas iguais seguindo essa direção.';
      scheduleGlebaRealtime();
      toast('Linha guia adicionada. Agora clique em Gerar no mapa para dividir em áreas iguais.', 'success');
    };

    function onClick(event) {
      const now = Date.now();
      if (event.originalEvent?.detail > 1 || now - lastClickAt < 170) return;
      lastClickAt = now;
      L.DomEvent.stop(event.originalEvent || event);
      if (!almostSamePoint(points[points.length - 1], event.latlng)) points.push(event.latlng);
      redraw(event.latlng);
      toast(points.length === 1 ? 'Clique no próximo ponto da linha guia.' : `${points.length} pontos marcados. Continue ou dê duplo clique para finalizar.`, 'success');
    }

    function onMove(event) {
      redraw(event.latlng);
    }

    function onDoubleClick(event) {
      L.DomEvent.stop(event.originalEvent || event);
      if (event.latlng && !almostSamePoint(points[points.length - 1], event.latlng)) points.push(event.latlng);
      finish();
    }

    function onKey(event) {
      if (event.key === 'Escape') { cleanup(); toast('Desenho da linha guia cancelado.', 'success'); }
      if (event.key === 'Enter') finish();
    }

    try { map.doubleClickZoom.disable(); } catch (_) {}
    map.on('click', onClick);
    map.on('mousemove', onMove);
    map.on('dblclick', onDoubleClick);
    document.addEventListener('keydown', onKey);
    activeLeafletHandler = { disable: cleanup };
    toast('Desenhe a linha guia dentro do imóvel. Dê duplo clique no último ponto ou Enter para finalizar.', 'success');
  }







  function glebaBoundaryRings(feature) {
    const geometry = feature?.geometry;
    if (!geometry) return [];
    if (geometry.type === 'Polygon') return Array.isArray(geometry.coordinates) ? geometry.coordinates.filter(Array.isArray) : [];
    if (geometry.type === 'MultiPolygon') return (geometry.coordinates || []).flatMap((polygon) => Array.isArray(polygon) ? polygon.filter(Array.isArray) : []);
    return [];
  }

  function glebaSnapToSourceBoundary(latlng, sourceFeature, options = {}) {
    if (!latlng || !sourceFeature || !map) return { latlng, snapped: false, type: 'free' };
    const vertexTolerance = Math.max(5, Number(options.vertexTolerancePx || 13));
    const edgeTolerance = Math.max(vertexTolerance, Number(options.edgeTolerancePx || 18));
    const cursor = map.latLngToContainerPoint(latlng);
    const rings = glebaBoundaryRings(sourceFeature);
    let bestVertex = null;
    let bestEdge = null;

    rings.forEach((ring, ringIndex) => {
      const coords = Array.isArray(ring) ? ring : [];
      const limit = coords.length > 1 && Number(coords[0]?.[0]) === Number(coords.at(-1)?.[0]) && Number(coords[0]?.[1]) === Number(coords.at(-1)?.[1]) ? coords.length - 1 : coords.length;
      for (let i = 0; i < limit; i += 1) {
        const coord = coords[i];
        if (!Array.isArray(coord) || !Number.isFinite(Number(coord[0])) || !Number.isFinite(Number(coord[1]))) continue;
        const vertexLatLng = L.latLng(Number(coord[1]), Number(coord[0]));
        const vertexPoint = map.latLngToContainerPoint(vertexLatLng);
        const vertexDistance = cursor.distanceTo(vertexPoint);
        if (!bestVertex || vertexDistance < bestVertex.distance) bestVertex = { latlng: vertexLatLng, distance: vertexDistance, ringIndex, vertexIndex: i };

        const nextCoord = coords[(i + 1) % limit];
        if (!Array.isArray(nextCoord) || !Number.isFinite(Number(nextCoord[0])) || !Number.isFinite(Number(nextCoord[1]))) continue;
        const a = vertexPoint;
        const bLatLng = L.latLng(Number(nextCoord[1]), Number(nextCoord[0]));
        const b = map.latLngToContainerPoint(bLatLng);
        const abx = b.x - a.x, aby = b.y - a.y;
        const denom = abx * abx + aby * aby;
        if (!(denom > 0)) continue;
        const t = Math.max(0, Math.min(1, ((cursor.x - a.x) * abx + (cursor.y - a.y) * aby) / denom));
        const projected = L.point(a.x + abx * t, a.y + aby * t);
        const distance = cursor.distanceTo(projected);
        if (!bestEdge || distance < bestEdge.distance) {
          bestEdge = { latlng: map.containerPointToLatLng(projected), distance, ringIndex, segmentIndex: i, t };
        }
      }
    });

    if (bestVertex && bestVertex.distance <= vertexTolerance) return { ...bestVertex, snapped: true, type: 'vertex' };
    if (bestEdge && bestEdge.distance <= edgeTolerance) return { ...bestEdge, snapped: true, type: 'edge' };
    return { latlng, snapped: false, type: 'free' };
  }

  // A gleba pode compartilhar vértices e trechos de borda com o perímetro.
  // booleanWithin() retorna falso nessas situações e testes apenas dos vértices
  // deixam passar polígonos que cruzam um perímetro côncavo. A verificação
  // efetiva é a diferença geométrica e a conservação da área, em finish().

  // R185.18: excluir uma gleba manual recompõe o polígono-base.
  // Não restaurar um snapshot inteiro: isso apagaria outras glebas geradas depois.
  function restoreManualGlebaToSource(glebaLayer) {
    const glebaProps = metadata(glebaLayer);
    if (glebaProps.manualGleba !== true || glebaProps.generatedBy !== 'map-glebas-manual') return false;
    const parentId = String(glebaProps.parentLayerId || glebaProps.sourceLayerId || '').trim();
    const parentLayer = drawn.getLayers().find((layer) => layer !== glebaLayer && String(metadata(layer).id || '') === parentId);
    if (!parentLayer) return false;
    // Uma gleba com subdivisões não pode ser excluída deixando filhas sem pai.
    if (drawn.getLayers().some((layer) => layer !== glebaLayer &&
        String(metadata(layer).parentLayerId || '') === String(glebaProps.id || ''))) return false;
    try {
      const parentFeature = parentLayer.toGeoJSON();
      const glebaFeature = glebaLayer.toGeoJSON();
      if (!/Polygon/.test(parentFeature?.geometry?.type || '') || !/Polygon/.test(glebaFeature?.geometry?.type || '')) return false;
      const parentArea = Number(turf.area(parentFeature) || 0);
      const glebaArea = Number(turf.area(glebaFeature) || 0);
      if (!(parentArea > 0 && glebaArea > 0)) return false;
      let reunited = null;
      try { reunited = turf.union(turf.featureCollection([parentFeature, glebaFeature])); } catch (_) {}
      if (!reunited) { try { reunited = turf.union(parentFeature, glebaFeature); } catch (_) {} }
      if (!reunited || !/Polygon/.test(reunited.geometry?.type || '')) return false;
      const restoredArea = Number(turf.area(reunited) || 0);
      const expectedArea = parentArea + glebaArea;
      if (!Number.isFinite(restoredArea) || Math.abs(restoredArea - expectedArea) > Math.max(2, expectedArea * 0.002)) return false;
      const originalProps = { ...metadata(parentLayer) };
      const restoredProps = {
        ...originalProps,
        areaHectares: restoredArea / 10000,
        areaMetrosQuadrados: restoredArea,
        perimeterMeters: Number(turf.length(turf.polygonToLine(reunited), { units: 'kilometers' }) || 0) * 1000
      };
      reunited.properties = { ...(parentFeature.properties || {}), ...restoredProps };
      // A união já foi calculada e validada; só agora altera as camadas.
      const restoredLayers = [];
      L.geoJSON(reunited, { style: () => styleFor(restoredProps.category || 'perimetro', restoredProps) })
        .eachLayer((layer) => { layer.feature = { ...reunited, properties: { ...restoredProps } }; restoredLayers.push(layer); });
      if (restoredLayers.length !== 1) return false;
      if (drawn.hasLayer(glebaLayer)) drawn.removeLayer(glebaLayer);
      drawn.removeLayer(parentLayer);
      if (selectedLayer === parentLayer || selectedLayer === glebaLayer) selectedLayer = null;
      restoredLayers.forEach((layer) => {
        attach(layer);
        drawn.addLayer(layer);
        applyStyleToDrawn(layer);
      });
      lastGlebaFeatureCollection = currentGlebaFeatureCollection();
      updateGlebaSourceOptions(true);
      renderGlebaSummary();
      scheduleRecoverySnapshot();
      refresh();
      return true;
    } catch (error) {
      console.warn('[Surveyor] Não foi possível restaurar a gleba excluída:', error);
      return false;
    }
  }

  function startManualGlebaDrawing() {
    const sourceLayer = getGlebaSourceLayer();
    if (!sourceLayer) return toast('Selecione um polígono base antes de desenhar a gleba manual.', 'error');
    const sourceFeature = sourceLayer.toGeoJSON?.();
    if (!sourceFeature?.geometry || !/Polygon/.test(sourceFeature.geometry.type || '')) return toast('O polígono base selecionado não é válido.', 'error');

    disableActiveHandler();
    stopSurveyorLiveTool({ keepActiveTool: true });
    resetInteractionModes();
    setActiveMapTool(els.toolsMenuBtn);

    const points = [];
    let finished = false;
    let singleClickTimer = null;
    let pendingManualClick = null;
    // O comando explícito evita depender de um duplo clique em um marcador pequeno.
    const finishButton = els.glebaFinishManualPolygon;
    const onFinishButton = () => finish();
    finishButton?.addEventListener('click', onFinishButton);
    if (finishButton) { finishButton.hidden = false; finishButton.disabled = true; }
    liveDrawGroup.clearLayers();
    document.body.classList.add('drawing-active', 'survey-live-drawing', 'survey-manual-gleba-drawing');

    const boundaryStyle = {
      pane: 'liveDrawPane', renderer: liveRenderer, className: 'surveyor-manual-gleba-live no-shadow',
      color: '#0f63e9', weight: 2.4, opacity: 1, fillColor: '#facc15', fillOpacity: 0.16,
      lineCap: 'round', lineJoin: 'round', interactive: false
    };

    const marker = (latlng, index, snapType = 'free', cursor = false) => {
      const color = snapType === 'vertex' ? '#16a34a' : snapType === 'edge' ? '#f59e0b' : '#0f63e9';
      const pointMarker = L.circleMarker(latlng, {
        pane: 'liveDrawPane', renderer: liveRenderer, radius: cursor ? 4.5 : 5.5,
        color, weight: 2, fillColor: '#fff', fillOpacity: 1, interactive: !cursor,
        className: 'surveyor-manual-gleba-point no-shadow'
      }).bindTooltip(cursor ? (snapType === 'vertex' ? 'encaixe no vértice' : snapType === 'edge' ? 'encaixe na linha' : 'ponto livre') : `P${index + 1}`, {
        permanent: !cursor, direction: 'top', className: 'surveyor-live-draw-label', opacity: 1
      }).addTo(liveDrawGroup);
      if (!cursor) {
        pointMarker.on('click', (event) => {
          L.DomEvent.stop(event.originalEvent || event);
        });
        pointMarker.on('dblclick', (event) => {
          L.DomEvent.stop(event.originalEvent || event);
          if (points.length < 3) {
            toast('Marque pelo menos 3 pontos antes de finalizar a gleba.', 'error');
            return;
          }
          finish();
        });
      }
      return pointMarker;
    };

    const almostSamePoint = (a, b) => {
      if (!a || !b) return false;
      try { return map.latLngToContainerPoint(a).distanceTo(map.latLngToContainerPoint(b)) < 6; } catch (_) { return false; }
    };

    const redraw = (cursorEvent = null) => {
      liveDrawGroup.clearLayers();
      points.forEach((item, index) => marker(item.latlng, index, item.snapType));
      let cursor = null;
      if (cursorEvent?.latlng) cursor = glebaSnapToSourceBoundary(cursorEvent.latlng, sourceFeature);
      const draft = cursor && points.length && !almostSamePoint(points.at(-1)?.latlng, cursor.latlng)
        ? [...points.map((item) => item.latlng), cursor.latlng]
        : points.map((item) => item.latlng);
      if (draft.length >= 3) L.polygon(draft, boundaryStyle).addTo(liveDrawGroup);
      else if (draft.length >= 2) L.polyline(draft, boundaryStyle).addTo(liveDrawGroup);
      if (cursor) marker(cursor.latlng, points.length, cursor.type, true);
    };

    const cleanup = () => {
      if (singleClickTimer) { clearTimeout(singleClickTimer); singleClickTimer = null; }
      pendingManualClick = null;
      map.off('click', onClick);
      map.off('dblclick', onDoubleClick);
      map.off('mousemove', onMove);
      document.removeEventListener('keydown', onKey);
      finishButton?.removeEventListener('click', onFinishButton);
      if (finishButton) { finishButton.hidden = true; finishButton.disabled = true; }
      try { map.doubleClickZoom.enable(); } catch (_) {}
      liveDrawGroup.clearLayers();
      document.body.classList.remove('drawing-active', 'survey-live-drawing', 'survey-manual-gleba-drawing');
      setActiveMapTool(els.selectToolBtn);
      activeLeafletHandler = null;
    };

    const finish = () => {
      if (finished) return;
      if (points.length < 3) return toast('A gleba manual precisa ter pelo menos 3 pontos.', 'error');
      const coords = points.map((item) => [item.latlng.lng, item.latlng.lat]);
      if (coords.length && (coords[0][0] !== coords.at(-1)?.[0] || coords[0][1] !== coords.at(-1)?.[1])) coords.push([...coords[0]]);
      const feature = turf.polygon([coords]);
      const areaM2 = Number(turf.area(feature) || 0);
      if (!(areaM2 > 1)) return toast('A gleba manual ficou sem área válida. Ajuste os pontos e tente novamente.', 'error');
      // Contato com a borda é permitido: validar pelo recorte e pela área
      // efetivamente retirada, sem a restrição incorreta de booleanWithin().
      // Recortar a gleba do polígono-base para não contabilizar a mesma área duas vezes.
      // Compatibilidade com as duas assinaturas de Turf utilizadas nas versões do mapa.
      let remainder = null;
      try { remainder = turf.difference(turf.featureCollection([sourceFeature, feature])); } catch (_) {}
      if (!remainder) { try { remainder = turf.difference(sourceFeature, feature); } catch (_) {} }
      const remainingAreaM2 = Number(remainder && turf.area(remainder) || 0);
      const originalAreaM2 = Number(turf.area(sourceFeature) || 0);
      // A diferença de área denuncia qualquer trecho realmente fora da base.
      // Usar tolerância do recorte (e não do imóvel inteiro), para que uma gleba
      // pequena não possa extravasar parte significativa de seu desenho.
      const toleranceM2 = Math.max(0.5, areaM2 * 0.0005);
      const outsideM2 = areaM2 - (originalAreaM2 - remainingAreaM2);
      if (!remainder || !/Polygon/.test(remainder.geometry?.type || '') || remainingAreaM2 <= 1
          || !Number.isFinite(outsideM2) || Math.abs(outsideM2) > toleranceM2) {
        return toast('O desenho ultrapassa o perímetro ou não pôde ser recortado com segurança. Encaixe os pontos na borda do imóvel.', 'error');
      }

      finished = true;
      cleanup();
      const sourceMeta = { ...metadata(sourceLayer) };
      const manualIndex = drawn.getLayers().filter((layer) => metadata(layer).category === 'gleba').length + 1;
      const baseName = els.glebaMapBaseName?.value?.trim() || 'Gleba';
      const color = glebaPalette[(manualIndex - 1) % glebaPalette.length];
      feature.properties = {
        id: id(), name: `${baseName} ${String(manualIndex).padStart(2, '0')}`, category: 'gleba',
        generatedBy: 'map-glebas-manual', manualGleba: true,
        sourceLayerId: sourceMeta.id || '', parentLayerId: sourceMeta.id || '',
        sourceLayerName: sourceMeta.name || '', parentLayerName: sourceMeta.name || '',
        rootSourceLayerId: sourceMeta.rootSourceLayerId || sourceMeta.rootLayerId || sourceMeta.id || '',
        rootSourceLayerName: sourceMeta.rootSourceLayerName || sourceMeta.rootLayerName || sourceMeta.name || '',
        generationDepth: Math.max(0, Number(sourceMeta.generationDepth || sourceMeta.glebaDepth || 0)) + 1,
        areaHectares: areaM2 / 10000,
        perimeterMeters: Number(turf.length(turf.polygonToLine(feature), { units: 'kilometers' }) || 0) * 1000,
        cutType: 'manual-polygon', cutTypeLabel: 'Desenho manual',
        styleColor: color, fillColor: color, styleOpacity: 0.32, fillOpacity: 0.32, strokeOpacity: 1, weight: 3
      };
      pushUndoSnapshot(snapshotDrawn(), { label: 'Gleba manual separada da área original' });
      // O remanescente mantém a identidade da área-base, porém com a geometria e
      // a metragem atualizadas. O snapshot acima permite desfazer a operação.
      const remainderProps = {
        ...sourceMeta,
        areaHectares: remainingAreaM2 / 10000,
        areaMetrosQuadrados: remainingAreaM2,
        perimeterMeters: Number(turf.length(turf.polygonToLine(remainder), { units: 'kilometers' }) || 0) * 1000
      };
      remainder.properties = { ...(sourceFeature.properties || {}), ...remainderProps };
      drawn.removeLayer(sourceLayer);
      if (selectedLayer === sourceLayer) selectedLayer = null;
      L.geoJSON(remainder, { style: () => styleFor(remainderProps.category || 'perimetro', remainderProps) })
        .eachLayer((layer) => addLayer(layer, remainderProps));
      let createdLayer = null;
      L.geoJSON(feature, { style: () => styleFor('gleba', feature.properties || {}) }).eachLayer((layer) => { createdLayer = layer; addLayer(layer, feature.properties || {}); });
      if (createdLayer) { selectedLayer = createdLayer; select(createdLayer, { focus: false }); }
      lastGlebaFeatureCollection = currentGlebaFeatureCollection();
      updateGlebaSourceOptions(true);
      renderGlebaSummary();
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = 'gleba manual criada';
      if (els.glebaMapSummary) els.glebaMapSummary.textContent = `Gleba: ${n(areaM2 / 10000, 4)} ha. Área restante: ${n(remainingAreaM2 / 10000, 4)} ha. Ambas independentes no mapa.`;
      scheduleRecoverySnapshot();
      refresh();
      toast(`Gleba separada: ${n(areaM2 / 10000, 4)} ha; área restante: ${n(remainingAreaM2 / 10000, 4)} ha.`, 'success');
    };

    function addManualPoint(event) {
      if (finished || !event?.latlng) return false;
      const snap = glebaSnapToSourceBoundary(event.latlng, sourceFeature, { vertexTolerancePx: 11, edgeTolerancePx: 14 });
      const inside = snap.snapped || (() => { try { return turf.booleanPointInPolygon(turf.point([snap.latlng.lng, snap.latlng.lat]), sourceFeature, { ignoreBoundary: false }); } catch (_) { return false; } })();
      if (!inside) { toast('Marque os pontos dentro do polígono base ou próximo à borda para encaixar.', 'error'); return false; }
      if (!almostSamePoint(points.at(-1)?.latlng, snap.latlng)) points.push({ latlng: snap.latlng, snapType: snap.type });
      if (finishButton) finishButton.disabled = points.length < 3;
      redraw(event);
      const snapMessage = snap.type === 'vertex' ? 'encaixado no vértice' : snap.type === 'edge' ? 'encaixado na linha do perímetro' : 'ponto livre';
      toast(`${points.length} ponto(s) • ${snapMessage}. Use Finalizar gleba, Enter ou duplo clique para concluir.`, 'success');
      return true;
    }
    function onClick(event) {
      if (event.originalEvent?.detail > 1) return;
      L.DomEvent.stop(event.originalEvent || event);
      if (singleClickTimer) clearTimeout(singleClickTimer);
      // Leaflet dispara click, click, dblclick. O primeiro click do par
      // ainda está pendente no timer quando chega o dblclick.
      pendingManualClick = event;
      singleClickTimer = setTimeout(() => {
        singleClickTimer = null;
        const pending = pendingManualClick;
        pendingManualClick = null;
        if (pending) addManualPoint(pending);
      }, 190);
    }
    function onDoubleClick(event) {
      L.DomEvent.stop(event.originalEvent || event);
      const finalClick = pendingManualClick;
      if (singleClickTimer) { clearTimeout(singleClickTimer); singleClickTimer = null; }
      pendingManualClick = null;
      if (finished) return;
      // Confirmar o vértice do primeiro click ANTES de finalizar. Na RC185.16
      // esse timer era cancelado, perdendo o quarto (ou último) vértice.
      // Um duplo clique perto de um vértice já colocado apenas fecha a área.
      if (finalClick?.latlng && !points.some((p) => almostSamePoint(p.latlng, finalClick.latlng))) {
        if (!addManualPoint(finalClick)) return; // Ponto fora da área-base: não fechar com um triângulo incorreto.
      }
      if (points.length < 3) return toast('Marque pelo menos 3 pontos antes de finalizar a gleba.', 'error');
      finish();
    }
    function onMove(event) { redraw(event); }
    function onKey(event) {
      if (event.key === 'Escape') { cleanup(); toast('Desenho da gleba manual cancelado.', 'success'); }
      if (event.key === 'Enter') finish();
      if ((event.key === 'Backspace' || event.key === 'Delete') && points.length) { event.preventDefault(); points.pop(); if (finishButton) finishButton.disabled = points.length < 3; redraw(); }
    }

    try { map.doubleClickZoom.disable(); } catch (_) {}
    map.on('click', onClick);
    map.on('mousemove', onMove);
    map.on('dblclick', onDoubleClick);
    document.addEventListener('keydown', onKey);
    activeLeafletHandler = { disable: cleanup };
    toast('Desenhe pelo menos 3 pontos. Finalize com duplo clique, Enter ou com o botão “Finalizar gleba”.', 'success');
  }

  function buildGlebaPiecesByGuideLine(projected, proj, targetAreas, widthBased = false) {
    if (!glebaManualCutFeatures.length) throw new Error('Escolha "Linha guia desenhada" e desenhe pelo menos 1 linha guia no mapa.');
    const guideFeature = glebaManualCutFeatures[glebaManualCutFeatures.length - 1];
    const lineCoords = glebaCutLineToProjectedCoords(guideFeature, proj);
    const lineAngle = glebaGuideLineAngle(lineCoords);
    if (!Number.isFinite(lineAngle)) throw new Error('A linha guia precisa ter pelo menos dois pontos diferentes.');
    const rotation = 90 - lineAngle;
    const rotated = glebaRotateFeature(projected, rotation);
    const bbox = glebaBBox(rotated);
    const extent = Math.max(bbox[2] - bbox[0], bbox[3] - bbox[1], 1000);
    const pad = extent * 2;
    const resolved = { axis: 'x', angle: rotation, reverse: false, label: `Linha guia desenhada (${n(((lineAngle % 360) + 360) % 360, 2)}°)` };
    const pieces = buildGlebaPiecesByStrips(rotated, bbox, pad, resolved, targetAreas, widthBased)
      .filter((item) => item.areaM2 > 1);
    return { pieces, resolved };
  }



  function glebaPiecesAreaQuality(pieces, targetAreas, totalArea) {
    const expected = Math.max(1, targetAreas.length);
    const accepted = (pieces || []).filter((item) => item?.feature?.geometry && (item.areaM2 || glebaGeometryArea(item.feature.geometry)) > Math.max(2, totalArea * 0.000001));
    const covered = accepted.reduce((sum, item) => sum + (item.areaM2 || glebaGeometryArea(item.feature.geometry)), 0);
    const targetSum = targetAreas.reduce((sum, value) => sum + value, 0) || totalArea || 1;
    const normalized = targetAreas.map((value) => value * ((totalArea || targetSum) / targetSum));
    const deviations = accepted.slice(0, expected).map((item, index) => {
      const target = normalized[index] || (totalArea / expected) || 1;
      const area = item.areaM2 || glebaGeometryArea(item.feature.geometry);
      return Math.abs(area - target) / Math.max(target, 1);
    });
    const maxDeviation = deviations.length ? Math.max(...deviations) : Infinity;
    return {
      count: accepted.length,
      coverage: totalArea ? covered / totalArea : 0,
      maxDeviation,
      ok: accepted.length === expected && totalArea > 0 && covered >= totalArea * 0.965 && maxDeviation <= 0.18
    };
  }

  function buildGlebaPiecesByFrontageGuide(projected, proj, targetAreas) {
    if (!glebaManualCutFeatures.length) throw new Error('Escolha "Desenhar frente/acesso" e desenhe uma linha guia dentro do imóvel.');
    const guideFeature = glebaManualCutFeatures[glebaManualCutFeatures.length - 1];
    const rawCoords = glebaCutLineToProjectedCoords(guideFeature, proj)
      .filter((coord, index, arr) => index === 0 || Math.hypot(coord[0] - arr[index - 1][0], coord[1] - arr[index - 1][1]) > 0.08);
    if (!rawCoords || rawCoords.length < 2) throw new Error('A linha guia precisa ter pelo menos dois pontos diferentes.');

    const bbox = glebaBBox(projected);
    const extent = Math.max(bbox[2] - bbox[0], bbox[3] - bbox[1], 1000);
    const totalArea = glebaGeometryArea(projected.geometry) || targetAreas.reduce((sum, value) => sum + value, 0);
    const targetSum = targetAreas.reduce((sum, value) => sum + value, 0) || totalArea;
    const normalizedTargets = targetAreas.map((value) => value * (totalArea / targetSum));
    const expected = normalizedTargets.length;

    // v21.9.96: no modo Desenhar, a linha do usuário volta a ser a geometria-guia
    // real. A versão 21.9.95 estabilizava usando apenas o ângulo da linha, mas isso
    // fazia o sistema cortar diferente do desenho. Aqui usamos a curva/linha desenhada
    // como modelo dos cortes; para 3+ glebas aplicamos suavização leve para evitar
    // quinas quebradas, sem converter o desenho em um corte reto genérico.
    const step = Math.max(24, Math.min(110, extent / 58));
    let guide = glebaLimitLinePoints(rawCoords, 56);
    if (guide.length >= 3) guide = glebaSmoothLine(guide, expected >= 4 ? 2 : 1);
    guide = glebaLimitLinePoints(glebaDensifyLine(guide, step), 96);
    if (window.turf?.simplify && guide.length >= 3) {
      try {
        const simplified = turf.simplify(turf.lineString(guide), { tolerance: Math.max(1.2, step * 0.12), highQuality: true });
        guide = glebaLimitLinePoints(simplified?.geometry?.coordinates || guide, 96);
      } catch {}
    }
    if (guide.length < 2) throw new Error('Desenhe uma linha guia maior dentro do imóvel.');

    const extendedGuide = glebaExtendCurveGuide(guide, extent * 2.8);
    const [minD, maxD] = glebaCurveDistanceRange(projected, extendedGuide, bbox, extent * 0.14);
    const extend = extent * 4;
    const cuts = [minD];
    let cumulative = 0;
    for (let i = 0; i < expected - 1; i++) {
      cumulative += normalizedTargets[i];
      cuts.push(glebaCurveCutoffForArea(projected, extendedGuide, minD, maxD, cumulative, totalArea, extend));
    }
    cuts.push(maxD);

    const rawPieces = [];
    for (let i = 0; i < cuts.length - 1; i++) {
      const part = glebaCurveBandIntersection(projected, extendedGuide, cuts[i], cuts[i + 1], extend);
      glebaCollectPiece(part, rawPieces, normalizedTargets[i] || 0, Math.max(2, totalArea * 0.000001));
    }

    let pieces = glebaMakePiecesMutuallyExclusive(projected, rawPieces, normalizedTargets, totalArea)
      .filter((item) => item?.feature?.geometry && item.areaM2 > Math.max(2, totalArea * 0.000001))
      .slice(0, expected);

    const quality = glebaPiecesAreaQuality(pieces, normalizedTargets, totalArea);
    if (!quality.ok) {
      // Não gerar mais uma divisão visualmente "limpa" porém em direção errada.
      // Se a linha desenhada não permitir uma divisão coerente, avisamos o usuário
      // para redesenhar a guia atravessando o imóvel em vez de cortar diferente.
      const msg = quality.count < expected
        ? 'A linha desenhada não atravessou o imóvel o suficiente para gerar todas as glebas. Desenhe a guia de uma borda até a outra.'
        : 'A linha desenhada gerou áreas muito diferentes. Ajuste a guia ou use Corte reto para divisão automática.';
      throw new Error(msg);
    }

    return {
      pieces,
      resolved: { axis: 'frontage-offset', angle: 0, reverse: false, label: 'Desenhar frente/acesso — seguindo a linha desenhada com áreas iguais' }
    };
  }



























  function buildGlebaPiecesByCurveGuide(projected, proj, targetAreas) {
    if (!glebaManualCutFeatures.length) throw new Error('Escolha "Curva precisa" e desenhe a frente/guia curva no mapa.');
    const guideFeature = glebaManualCutFeatures[glebaManualCutFeatures.length - 1];
    const rawCoords = glebaCutLineToProjectedCoords(guideFeature, proj);
    const bbox = glebaBBox(projected);
    const extent = Math.max(bbox[2] - bbox[0], bbox[3] - bbox[1], 1000);
    const totalArea = glebaGeometryArea(projected.geometry) || targetAreas.reduce((sum, value) => sum + value, 0);
    const targetSum = targetAreas.reduce((sum, value) => sum + value, 0) || totalArea;
    const normalizedTargets = targetAreas.map((value) => value * (totalArea / targetSum));

    // v21.9.84: curva precisa por estações.
    // A curva desenhada passa a ser a frente/eixo de acesso. As glebas são
    // separadas por intervalos ao longo dessa curva, não mais por offsets
    // paralelos que podiam deixar faixas sem frente/acesso.
    const prepared = glebaPrepareCurveGuide(rawCoords, bbox);
    const extended = glebaExtendCurveGuide(prepared, extent * 1.4);
    const curve = glebaCurveStationData(extended);
    if (!curve.length || curve.coords.length < 2) throw new Error('A curva precisa ter pelo menos dois pontos diferentes.');

    const far = extent * 3.2;
    const startStation = 0;
    const endStation = curve.length;
    const cuts = [startStation];
    let cumulative = 0;
    for (let i = 0; i < normalizedTargets.length - 1; i++) {
      cumulative += normalizedTargets[i];
      cuts.push(glebaCurveStationCutoffForArea(projected, curve, startStation, endStation, cumulative, totalArea, far));
    }
    cuts.push(endStation);

    const pieces = [];
    for (let i = 0; i < cuts.length - 1; i++) {
      const part = glebaCurveStationIntersection(projected, curve, cuts[i], cuts[i + 1], far);
      glebaCollectPiece(part, pieces, normalizedTargets[i] || 0, 2);
    }

    const covered = pieces.reduce((sum, item) => sum + item.areaM2, 0);
    if (pieces.length < 2 || covered < totalArea * 0.82) {
      throw new Error('A curva não cobriu bem o imóvel. Desenhe a curva atravessando a frente/acesso de ponta a ponta e gere novamente.');
    }

    pieces.sort((a, b) => {
      const ac = glebaFeatureCenter(a.feature);
      const bc = glebaFeatureCenter(b.feature);
      const as = glebaNearestStationOnCurve(ac, curve);
      const bs = glebaNearestStationOnCurve(bc, curve);
      return as - bs;
    });

    return {
      pieces: pieces.filter((item) => item.areaM2 > 2),
      resolved: { axis: 'curve-station', angle: 0, reverse: false, label: 'Curva precisa com frente/acesso preservado' }
    };
  }


  function buildGlebaPiecesByManualCuts(projected, bbox, pad, proj) {
    if (!glebaManualCutFeatures.length) throw new Error('Escolha o modo de corte desenhado e desenhe pelo menos 1 linha no mapa.');
    let pieces = [projected];
    glebaManualCutFeatures.forEach((cutFeature) => {
      const lineCoords = glebaCutLineToProjectedCoords(cutFeature, proj);
      pieces = pieces.flatMap((piece) => splitGlebaPieceByCutLine(piece, lineCoords, bbox, pad));
    });
    return pieces
      .map((feature) => ({ feature, areaM2: glebaGeometryArea(feature.geometry), perimeterM: glebaGeometryLength(feature.geometry), targetM2: 0 }))
      .filter((item) => item.areaM2 > 2)
      .sort((a, b) => {
        const ac = glebaFeatureCenter(a.feature);
        const bc = glebaFeatureCenter(b.feature);
        return ac[0] === bc[0] ? ac[1] - bc[1] : ac[0] - bc[0];
      });
  }

  function glebaSimplifyFeature(feature, tolerance = 0.8) {
    if (!feature?.geometry) return feature;
    let next = feature;
    if (window.turf?.simplify) {
      try {
        const simplified = turf.simplify(feature, { tolerance: Math.max(0.2, tolerance), highQuality: true, mutate: false });
        if (simplified?.geometry && glebaGeometryArea(simplified.geometry) > 0.5) next = simplified;
      } catch {}
    }
    return next;
  }

  function divideGlebaPolygonInMap(inputFeature, sourceMeta = {}) {
    const original = inputFeature?.type === 'Feature' ? inputFeature : { type: 'Feature', properties: {}, geometry: inputFeature?.geometry || inputFeature };
    const sourceId = sourceMeta?.id || original?.properties?.id || '';
    const sourceName = sourceMeta?.name || original?.properties?.name || '';
    const rootSourceLayerId = sourceMeta?.rootSourceLayerId || sourceMeta?.rootLayerId || sourceMeta?.originalSourceLayerId || sourceMeta?.sourceLayerId || sourceMeta?.parentLayerId || sourceId;
    const rootSourceLayerName = sourceMeta?.rootSourceLayerName || sourceMeta?.rootLayerName || sourceMeta?.originalSourceLayerName || sourceMeta?.sourceLayerName || sourceMeta?.parentLayerName || sourceName;
    const generationDepth = Math.max(0, Number(sourceMeta?.generationDepth || sourceMeta?.glebaDepth || 0) || 0) + 1;
    if (!original?.geometry || !/Polygon/.test(original.geometry.type || '')) throw new Error('Selecione um polígono válido.');
    const proj = glebaProjection(original);
    const baseProjected = glebaTransformFeature(original, proj.toXY);
    let projected = baseProjected;
    let resolved = resolveGlebaOrientation(projected);
    const totalArea = glebaGeometryArea(baseProjected.geometry);
    const count = Math.max(2, Math.min(80, Number(els.glebaMapCount?.value || 2)));
    const targetAreas = glebaTargetAreas(totalArea, count);
    const cutType = glebaCurrentCutType();
    let pieces = [];
    if (cutType === 'frontage-guide') {
      const guide = buildGlebaPiecesByFrontageGuide(baseProjected, proj, targetAreas);
      pieces = guide.pieces;
      resolved = guide.resolved;
    } else {
      if (resolved.angle) projected = glebaRotateFeature(projected, resolved.angle);
      const bbox = glebaBBox(projected);
      const extent = Math.max(bbox[2] - bbox[0], bbox[3] - bbox[1], 1000);
      const pad = extent * 2;
      pieces = buildGlebaPiecesByStrips(projected, bbox, pad, resolved, targetAreas, false);
    }

    const base = els.glebaMapBaseName?.value?.trim() || 'Gleba';
    const heirs = glebaReadHeirs();
    const ordered = resolved.reverse ? pieces.reverse() : pieces;
    const projectedFrontageGuide = (() => {
      if ((cutType === 'frontage-guide' || cutType === 'curve-guide') && glebaManualCutFeatures.length) {
        return glebaCutLineToProjectedCoords(glebaManualCutFeatures[glebaManualCutFeatures.length - 1], proj);
      }
      return [];
    })();
    const guideDirection = (() => {
      if (projectedFrontageGuide.length >= 2) return glebaAverageGuideVector(projectedFrontageGuide);
      if (resolved.axis === 'y') return resolved.angle ? [Math.sin(-resolved.angle), Math.cos(-resolved.angle)] : [0, 1];
      return resolved.angle ? [Math.cos(-resolved.angle), Math.sin(-resolved.angle)] : [1, 0];
    })();
    const simplifyTolerance = Math.max(0.6, Math.sqrt(totalArea) / 260);
    const features = ordered.map((item, index) => {
      let partFeature = item.feature;
      if (resolved.angle) partFeature = glebaRotateFeature(partFeature, -resolved.angle);
      partFeature = glebaSimplifyFeature(partFeature, simplifyTolerance);
      const measures = glebaMeasureFrontBack(baseProjected, partFeature, guideDirection, projectedFrontageGuide);
      const lngLat = glebaTransformFeature(partFeature, proj.toLngLat);
      const frontLabelPoint = measures.frontPoint ? proj.toLngLat(measures.frontPoint) : null;
      const backLabelPoint = measures.backPoint ? proj.toLngLat(measures.backPoint) : null;
      const color = glebaPalette[index % glebaPalette.length];
      const heir = heirs[index]?.name || `Herdeiro ${index + 1}`;
      const actualArea = item.areaM2 || glebaGeometryArea(partFeature.geometry);
      lngLat.properties = {
        ...(lngLat.properties || {}),
        id: id(),
        name: `${base} ${String(index + 1).padStart(2, '0')}`,
        category: 'gleba',
        generatedBy: 'map-glebas',
        sourceLayerId: sourceId,
        parentLayerId: sourceId,
        sourceLayerName: sourceName,
        parentLayerName: sourceName,
        rootSourceLayerId,
        rootSourceLayerName,
        generationDepth,
        glebaDepth: generationDepth,
        heir,
        owner: heir,
        areaHectares: actualArea / 10000,
        targetAreaHectares: targetAreas[index] ? targetAreas[index] / 10000 : 0,
        areaDifferencePercent: targetAreas[index] ? ((actualArea - targetAreas[index]) / targetAreas[index]) * 100 : 0,
        perimeterMeters: item.perimeterM || glebaGeometryLength(partFeature.geometry),
        segmentMeasures: true,
        frontMeters: measures.frontMeters,
        backMeters: measures.backMeters,
        frontLabelPoint,
        backLabelPoint,
        frontBackMeasurementVersion: 2,
        orientation: resolved.label,
        cutType,
        cutTypeLabel: glebaCutTypeLabel(cutType),
        styleColor: color,
        styleOpacity: 0.36,
        strokeOpacity: 1,
        weight: 3
      };
      return lngLat;
    });
    if (features.length < 2) throw new Error('Não foi possível gerar as glebas. Tente outro tipo de recorte ou outra orientação.');
    return { type: 'FeatureCollection', properties: { source: 'Surveyor - Divisão de glebas no mapa', generatedAt: new Date().toISOString(), totalAreaHectares: totalArea / 10000, cutType, cutTypeLabel: glebaCutTypeLabel(cutType) }, features };
  }

  function removeGeneratedGlebas() {
    drawn.getLayers().filter((layer) => metadata(layer).generatedBy === 'map-glebas').forEach((layer) => drawn.removeLayer(layer));
    lastGlebaFeatureCollection = null;
    refresh();
  }

  function glebaParentId(layer) {
    const p = metadata(layer);
    return String(p.parentLayerId || p.sourceLayerId || p.sourceId || '').trim();
  }

  function removeGeneratedGlebasForSource(sourceId = '') {
    const wanted = String(sourceId || '').trim();
    const generatedLayers = drawn.getLayers().filter((layer) => metadata(layer).generatedBy === 'map-glebas');
    if (!wanted) {
      generatedLayers.forEach((layer) => drawn.removeLayer(layer));
      lastGlebaFeatureCollection = null;
      refresh();
      return;
    }

    // v21.9.208: substitui somente a árvore filha da gleba selecionada.
    // Antes, glebas importadas/geradas que compartilhavam o mesmo sourceLayerId
    // podiam apagar as subdivisões de outra gleba. Agora o vínculo direto é
    // parentLayerId/sourceLayerId do polígono usado como fonte, preservando irmãos.
    const removeIds = new Set();
    let changed = true;
    while (changed) {
      changed = false;
      generatedLayers.forEach((layer) => {
        const p = metadata(layer);
        const layerId = String(p.id || '').trim();
        if (!layerId || removeIds.has(layerId)) return;
        const parentId = glebaParentId(layer);
        if (parentId === wanted || removeIds.has(parentId)) {
          removeIds.add(layerId);
          changed = true;
        }
      });
    }

    generatedLayers.forEach((layer) => {
      const layerId = String(metadata(layer).id || '').trim();
      if (removeIds.has(layerId)) drawn.removeLayer(layer);
    });
    lastGlebaFeatureCollection = null;
    refresh();
  }

  function currentGlebaFeatureCollection() {
    const features = drawn.getLayers()
      .filter((layer) => metadata(layer).category === 'gleba' || metadata(layer).generatedBy === 'map-glebas')
      .map((layer) => { const f = layer.toGeoJSON(); f.properties = { ...metadata(layer) }; return f; });
    return { type: 'FeatureCollection', properties: { exportedAt: new Date().toISOString(), source: 'Surveyor' }, features };
  }

  function addGlebaFeaturesToMap(fc, sourceLayer = null) {
    const sourceId = metadata(sourceLayer || {})?.id || fc?.properties?.sourceLayerId || fc?.features?.[0]?.properties?.sourceLayerId || '';
    if (els.glebaMapReplace?.checked) removeGeneratedGlebasForSource(sourceId);
    fc.features.forEach((feature) => {
      L.geoJSON(feature, {
        style: () => styleFor('gleba', feature.properties || {}),
        pointToLayer: (_feature, latlng) => L.marker(latlng, { icon: markerIcon('gleba') })
      }).eachLayer((layer) => addLayer(layer, feature.properties || {}));
    });
    lastGlebaFeatureCollection = currentGlebaFeatureCollection();
    const bounds = L.geoJSON(fc).getBounds();
    if (bounds?.isValid()) map.fitBounds(bounds.pad(0.08));
  }

  function renderGlebaSummary(fc = currentGlebaFeatureCollection()) {
    if (!els.glebaMapSummary) return;
    if (!fc.features.length) {
      els.glebaMapSummary.textContent = 'Nenhuma gleba gerada ainda.';
      return;
    }
    const rows = fc.features.map((feature, index) => {
      const area = Number(feature.properties?.areaHectares || (turf.area(feature) / 10000));
      const target = Number(feature.properties?.targetAreaHectares || 0);
      const diff = target ? ((area - target) / target) * 100 : Number(feature.properties?.areaDifferencePercent || 0);
      const heir = feature.properties?.heir || feature.properties?.owner || `Herdeiro ${index + 1}`;
      const diffLabel = target ? `${diff >= 0 ? '+' : ''}${n(diff, 2)}%` : '—';
      return `<tr><td>${index + 1}</td><td>${String(feature.properties?.name || `Gleba ${index + 1}`)}</td><td>${String(heir)}</td><td>${n(area, 4)} ha</td><td>${diffLabel}</td></tr>`;
    }).join('');
    els.glebaMapSummary.innerHTML = `<table><thead><tr><th>#</th><th>Gleba</th><th>Herdeiro</th><th>Área</th><th>Dif.</th></tr></thead><tbody>${rows}</tbody></table>`;
  }

  function generateGlebasOnMap(silent = false) {
    try {
      syncGlebaHeirRows(false);
      const sourceLayer = getGlebaSourceLayer();
      if (!sourceLayer) {
        if (silent) {
          if (els.glebaMapStatus) els.glebaMapStatus.textContent = 'aguardando polígono';
          if (els.glebaMapSummary) els.glebaMapSummary.textContent = 'Selecione ou desenhe um polígono para dividir em glebas.';
          return null;
        }
        throw new Error('Selecione ou desenhe um polígono antes de dividir.');
      }
      const sourceMeta = { ...metadata(sourceLayer) };
      activeGlebaSourceLayerId = sourceMeta.id || activeGlebaSourceLayerId;
      const sourceFeature = sourceLayer.toGeoJSON();
      const fc = divideGlebaPolygonInMap(sourceFeature, sourceMeta);
      fc.properties = { ...(fc.properties || {}), sourceLayerId: sourceMeta.id || '', sourceLayerName: sourceMeta.name || '', sourceAreaHectares: metrics(sourceLayer).areaHa };
      pushUndoSnapshot();
      addGlebaFeaturesToMap(fc, sourceLayer);
      renderGlebaSummary();
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = `${fc.features.length} gleba(s)`;
      if (!silent) toast('Glebas geradas no mapa.', 'success');
      return fc;
    } catch (error) {
      if (!silent) console.error(error);
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = silent ? 'aguardando ajuste' : 'erro';
      if (els.glebaMapSummary) els.glebaMapSummary.textContent = error.message || 'Não foi possível dividir a área.';
      if (!silent) toast(error.message || 'Não foi possível dividir a área.', 'error');
      return null;
    }
  }

  function scheduleGlebaRealtime() {
    if (!els.glebaMapRealtime?.checked) return;
    if (!getGlebaSourceLayer()) {
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = 'aguardando polígono';
      return;
    }
    if (glebaCurrentCutType() === 'curve-guide') {
      if (els.glebaMapStatus) els.glebaMapStatus.textContent = 'curva pronta';
      if (els.glebaMapSummary) els.glebaMapSummary.textContent = 'Modo curvo usa processamento mais pesado. Clique em “Gerar no mapa” para dividir quando terminar de desenhar.';
      return;
    }
    clearTimeout(glebaRealtimeTimer);
    glebaRealtimeTimer = setTimeout(() => generateGlebasOnMap(true), 700);
  }

  function openGlebasFromMap(layer = null) {
    const layers = getGlebaPolygonLayers();
    if (!layers.length) {
      toast('Desenhe ou importe um polígono antes de dividir em glebas.', 'error');
      setActiveMapTool(els.toolsMenuBtn);
      return;
    }
    if (layer && layers.includes(layer)) {
      selectedLayer = layer;
      activeGlebaSourceLayerId = metadata(layer).id;
    } else if (selectedLayer && layers.includes(selectedLayer)) {
      activeGlebaSourceLayerId = metadata(selectedLayer).id;
    }
    updateGlebaSourceOptions(false);
    if (activeGlebaSourceLayerId && els.glebaSourceLayer) els.glebaSourceLayer.value = activeGlebaSourceLayerId;
    syncGlebaHeirRows(false);
    document.getElementById('geoSidePanel')?.classList.remove('collapsed');
    document.querySelector('.geo-workspace')?.classList.remove('panel-collapsed');
    const tab = document.querySelector('[data-side-tab="glebas"]');
    tab?.click();
    setActiveMapTool(els.toolsMenuBtn);
    setTimeout(() => window.dispatchEvent(new Event('resize')), 80);
    toast('Divisão de glebas aberta no mapa. Ajuste herdeiros, orientação e gere em tempo real.', 'success');
  }



  function bindGlebaMapPanel() {
    syncGlebaHeirRows(true);
    [els.glebaMapMode, els.glebaMapCount, els.glebaMapBaseName, els.glebaCutType, els.glebaMapOrientation, els.glebaMapAzimuth, els.glebaSourceLayer].forEach((input) => {
      input?.addEventListener('input', () => {
        if (input === els.glebaSourceLayer) activeGlebaSourceLayerId = String(input.value || '');
        syncGlebaHeirRows(false);
        scheduleGlebaRealtime();
      });
      input?.addEventListener('change', () => {
        if (input === els.glebaSourceLayer) {
          activeGlebaSourceLayerId = String(input.value || '');
          const layer = getGlebaPolygonLayers().find((candidate) => metadata(candidate).id === activeGlebaSourceLayerId);
          if (layer) selectedLayer = layer;
        }
        syncGlebaHeirRows(false);
        if (input === els.glebaCutType && (input.value === 'manual-guide' || input.value === 'manual-lines')) {
          toast('Modo linha guia: desenhe 1 linha de referência e informe quantas glebas deseja gerar.', 'success');
        }
        if (input === els.glebaCutType && input.value === 'curve-guide') {
          toast('Modo curva precisa: desenhe a frente/guia de acesso com quantos pontos quiser e finalize com duplo clique.', 'success');
        }
        if (input === els.glebaCutType && input.value === 'manual-exact') {
          toast('Modo cortes exatos: cada linha desenhada vira um corte real no imóvel.', 'success');
        }
        scheduleGlebaRealtime();
      });
    });
    els.glebaHeirsList?.addEventListener('input', scheduleGlebaRealtime);
    els.glebaAddHeir?.addEventListener('click', () => {
      els.glebaMapCount.value = Math.min(80, Number(els.glebaMapCount.value || 2) + 1);
      syncGlebaHeirRows(true);
      scheduleGlebaRealtime();
    });
    els.glebaDrawCutLine?.addEventListener('click', startGlebaCutLineDrawing);
    els.glebaDrawManualPolygon?.addEventListener('click', startManualGlebaDrawing);
    els.glebaClearCutLines?.addEventListener('click', () => { clearGlebaCutLines(); toast('Linhas de corte removidas.', 'success'); });
    glebaManualCutCountLabel();
    els.glebaMapGenerate?.addEventListener('click', () => generateGlebasOnMap(false));
    els.glebaMapClear?.addEventListener('click', () => { pushUndoSnapshot(); removeGeneratedGlebas(); renderGlebaSummary(); toast('Glebas removidas do mapa.', 'success'); });
    els.glebaMapExportGeojson?.addEventListener('click', () => {
      const fc = currentGlebaFeatureCollection();
      if (!fc.features.length) return toast('Gere as glebas primeiro.', 'error');
      download(`${fileBase()}-glebas.geojson`, JSON.stringify(fc, null, 2), 'application/geo+json;charset=utf-8');
    });
    els.glebaMapExportKml?.addEventListener('click', () => {
      const fc = currentGlebaFeatureCollection();
      if (!fc.features.length) return toast('Gere as glebas primeiro.', 'error');
      download(`${fileBase()}-glebas.kml`, glebaKml(fc), 'application/vnd.google-earth.kml+xml;charset=utf-8');
    });
    els.glebaMapExportCsv?.addEventListener('click', () => {
      const fc = currentGlebaFeatureCollection();
      if (!fc.features.length) return toast('Gere as glebas primeiro.', 'error');
      download(`${fileBase()}-glebas-vertices.csv`, exportGlebaCsv(fc), 'text/csv;charset=utf-8');
    });
  }


  bindGlebaMapPanel();




  function geomFeatureLatLng(feature) {
    try {
      const centroid = window.turf?.centroid?.(feature);
      const c = centroid?.geometry?.coordinates;
      if (Array.isArray(c)) return L.latLng(c[1], c[0]);
    } catch (_) {}
    try {
      const box = L.geoJSON(feature).getBounds();
      if (box?.isValid?.()) return box.getCenter();
    } catch (_) {}
    const first = geomFirstCoord(feature?.geometry?.coordinates);
    return first ? L.latLng(first[1], first[0]) : map.getCenter();
  }


  function geomFeatureFromSelected(required = true) {
    if (!selectedLayer || !drawn.hasLayer(selectedLayer) || !selectedLayer.toGeoJSON) {
      if (required) toast('Selecione uma geometria no mapa antes de usar esta ferramenta.', 'error');
      return null;
    }
    const feature = selectedLayer.toGeoJSON();
    if (!feature?.geometry) {
      if (required) toast('A geometria selecionada é inválida.', 'error');
      return null;
    }
    feature.properties = { ...metadata(selectedLayer), ...(feature.properties || {}) };
    return feature;
  }

  function geomLayerFromFeature(feature) {
    let created = null;
    L.geoJSON(feature, {
      style: f => styleFor(f?.properties?.category || 'outros'),
      pointToLayer: (f, latlng) => projectPointLayer(f, latlng),
      onEachFeature: (f, leafletLayer) => {
        leafletLayer.feature = f;
        created = leafletLayer;
      }
    });
    return created;
  }

  function geomAddFeature(feature, props = {}) {
    const layer = geomLayerFromFeature({ ...feature, properties: { ...(feature.properties || {}), ...props } });
    if (!layer) throw new Error('Não foi possível criar camada a partir da geometria.');
    addLayer(layer, layer.feature?.properties || {});
    return layer;
  }

  function geomReplaceSelected(feature, successMessage) {
    const previous = selectedLayer;
    if (!previous || !drawn.hasLayer(previous)) return;
    const props = { ...metadata(previous), ...(feature.properties || {}) };
    feature.properties = props;
    pushUndoSnapshot(snapshotDrawn(), { label: String(successMessage || 'Geometria alterada').replace(/[.!]+$/, '') });
    drawn.removeLayer(previous);
    const layer = geomLayerFromFeature(feature);
    if (!layer) throw new Error('Não foi possível atualizar a geometria.');
    layer.feature = feature;
    attach(layer);
    drawn.addLayer(layer);
    applyStyleToDrawn(layer);
    if (feature.geometry?.type === 'Polygon') normalizeConfrontantes(layer);
    select(layer);
    refresh();
    toast(successMessage || 'Geometria atualizada.', 'success');
  }

  function geomTransformSelected(transformer, label) {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const origin = geomFeatureLatLng(feature);
    const updated = geomClone(feature);
    updated.geometry.coordinates = geomMapCoords(updated.geometry.coordinates, ([lng, lat, z]) => {
      const point = projectedPoint(L.latLng(lat, lng), origin);
      const next = transformer(point, origin);
      const latlng = unprojectPoint(next, origin);
      return z === undefined ? [latlng.lng, latlng.lat] : [latlng.lng, latlng.lat, z];
    });
    geomReplaceSelected(updated, label);
  }

  function geomPromptNumber(message, fallback = '') {
    const value = window.prompt(message, fallback);
    if (value === null) return null;
    const number = Number(String(value).replace(',', '.'));
    if (!Number.isFinite(number)) {
      toast('Valor numérico inválido.', 'error');
      return null;
    }
    return number;
  }




  function geomOperationOffset() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const distance = geomPromptNumber('Offset em metros. Use positivo para fora/direita e negativo para dentro/esquerda.', '5');
    if (distance === null) return;
    try {
      const type = feature.geometry?.type;
      let generated = null;
      if (/LineString/i.test(type || '') && window.turf?.lineOffset) generated = turf.lineOffset(feature, distance, { units: 'meters' });
      else if (window.turf?.buffer) generated = turf.buffer(feature, distance, { units: 'meters', steps: 16 });
      if (!generated?.geometry) throw new Error('Turf não retornou geometria.');
      pushUndoSnapshot();
      generated.properties = { ...feature.properties, id: id(), name: `${feature.properties?.name || 'Geometria'} — offset ${distance} m`, generatedBy: 'geometry-offset', offsetMeters: distance };
      geomAddFeature(generated, generated.properties);
      toast('Offset gerado como nova geometria.', 'success');
    } catch (error) {
      console.error(error);
      toast('Não foi possível gerar offset nesta geometria.', 'error');
    }
  }

  function geomOperationRotate() {
    const angle = geomPromptNumber('Ângulo de rotação em graus. Positivo gira no sentido anti-horário.', '15');
    if (angle === null) return;
    const rad = angle * Math.PI / 180;
    const cos = Math.cos(rad), sin = Math.sin(rad);
    geomTransformSelected((p) => ({ x: p.x * cos - p.y * sin, y: p.x * sin + p.y * cos }), `Geometria rotacionada em ${angle}°.`);
  }

  function geomOperationMirror() {
    const axis = String(window.prompt('Espelhar em qual eixo? Digite V para vertical ou H para horizontal.', 'V') || '').trim().toLowerCase();
    if (!axis) return;
    if (!['v', 'vertical', 'h', 'horizontal'].includes(axis)) return toast('Eixo inválido. Use V ou H.', 'error');
    const vertical = axis.startsWith('v');
    geomTransformSelected((p) => vertical ? ({ x: -p.x, y: p.y }) : ({ x: p.x, y: -p.y }), vertical ? 'Geometria espelhada no eixo vertical.' : 'Geometria espelhada no eixo horizontal.');
  }

  function geomOperationScale() {
    const factor = geomPromptNumber('Fator de escala. Ex.: 1,10 aumenta 10%; 0,90 reduz 10%.', '1.10');
    if (factor === null) return;
    if (factor <= 0) return toast('A escala precisa ser maior que zero.', 'error');
    geomTransformSelected((p) => ({ x: p.x * factor, y: p.y * factor }), `Geometria escalada por fator ${factor}.`);
  }

  function geomOperationStretchSide() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const coords = geomOuterCoords(feature);
    if (!['Polygon', 'LineString'].includes(feature.geometry?.type) || coords.length < 2) return toast('Esticar lado exige linha ou polígono.', 'error');
    const side = geomPromptNumber(`Número do lado/segmento para esticar. Use 1 a ${coords.length - (feature.geometry.type === 'LineString' ? 1 : 0)}.`, '1');
    if (side === null) return;
    const idx = Math.max(0, Math.min(coords.length - 1, Math.round(side) - 1));
    const nextIdx = feature.geometry.type === 'Polygon' ? (idx + 1) % coords.length : idx + 1;
    if (nextIdx >= coords.length) return toast('Segmento inválido para linha.', 'error');
    const distance = geomPromptNumber('Distância em metros para deslocar o lado. Use negativo para o outro sentido.', '2');
    if (distance === null) return;
    const origin = geomFeatureLatLng(feature);
    const a = projectedPoint(L.latLng(coords[idx][1], coords[idx][0]), origin);
    const b = projectedPoint(L.latLng(coords[nextIdx][1], coords[nextIdx][0]), origin);
    const dx = b.x - a.x, dy = b.y - a.y;
    const len = Math.hypot(dx, dy) || 1;
    const normal = { x: -dy / len, y: dx / len };
    const updatedCoords = coords.map((c, i) => {
      if (i !== idx && i !== nextIdx) return c;
      const p = projectedPoint(L.latLng(c[1], c[0]), origin);
      const q = { x: p.x + normal.x * distance, y: p.y + normal.y * distance };
      const ll = unprojectPoint(q, origin);
      return c[2] === undefined ? [ll.lng, ll.lat] : [ll.lng, ll.lat, c[2]];
    });
    geomReplaceSelected(geomSetOuterCoords(feature, updatedCoords), 'Lado esticado. Confira área, perímetro e confrontantes.');
  }

  function geomOperationConvert() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const type = feature.geometry?.type;
    if (type === 'LineString') {
      const coords = feature.geometry.coordinates.slice();
      if (coords.length < 3) return toast('Linha precisa ter pelo menos 3 vértices para virar polígono.', 'error');
      const first = coords[0], last = coords[coords.length - 1];
      if (first[0] !== last[0] || first[1] !== last[1]) coords.push(first.slice());
      const polygon = { ...geomClone(feature), geometry: { type: 'Polygon', coordinates: [coords] }, properties: { ...feature.properties, category: feature.properties?.category || 'perimetro' } };
      geomReplaceSelected(polygon, 'Linha convertida em polígono.');
      return;
    }
    if (type === 'Polygon') {
      const ring = (feature.geometry.coordinates?.[0] || []).slice(0, -1);
      const line = { ...geomClone(feature), geometry: { type: 'LineString', coordinates: ring }, properties: { ...feature.properties, category: feature.properties?.category || 'outros' } };
      geomReplaceSelected(line, 'Polígono convertido em linha.');
      return;
    }
    toast('Conversão disponível para LineString e Polygon.', 'error');
  }

  function geomOperationSplitLine() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    if (feature.geometry?.type !== 'LineString') return toast('Quebrar linhas funciona apenas com linhas.', 'error');
    const coords = feature.geometry.coordinates || [];
    if (coords.length < 3) return toast('A linha precisa ter pelo menos 3 vértices.', 'error');
    const index = geomPromptNumber(`Quebrar após qual vértice? Use 1 a ${coords.length - 1}.`, '2');
    if (index === null) return;
    const i = Math.round(index) - 1;
    if (i < 0 || i >= coords.length - 1) return toast('Índice de quebra inválido.', 'error');
    pushUndoSnapshot();
    const props = { ...feature.properties };
    drawn.removeLayer(selectedLayer);
    const a = { type: 'Feature', properties: { ...props, id: id(), name: `${props.name || 'Linha'} — parte 1` }, geometry: { type: 'LineString', coordinates: coords.slice(0, i + 1) } };
    const b = { type: 'Feature', properties: { ...props, id: id(), name: `${props.name || 'Linha'} — parte 2` }, geometry: { type: 'LineString', coordinates: coords.slice(i) } };
    const la = geomAddFeature(a, a.properties);
    geomAddFeature(b, b.properties);
    select(la);
    toast('Linha quebrada em duas partes.', 'success');
  }

  function geomOperationMergeLines() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    if (feature.geometry?.type !== 'LineString') return toast('Mesclar linhas exige uma linha selecionada.', 'error');
    const tolerance = geomPromptNumber('Tolerância para unir pontas, em metros.', '1');
    if (tolerance === null) return;
    const lineLayers = drawn.getLayers().filter((layer) => layer !== selectedLayer && layer.toGeoJSON?.().geometry?.type === 'LineString');
    let merged = feature.geometry.coordinates.slice();
    const consumed = [];
    let changed = true;
    while (changed) {
      changed = false;
      for (const layer of lineLayers) {
        if (consumed.includes(layer)) continue;
        const coords = layer.toGeoJSON().geometry.coordinates.slice();
        const start = merged[0], end = merged[merged.length - 1], cStart = coords[0], cEnd = coords[coords.length - 1];
        if (geomMetersBetween(end, cStart) <= tolerance) { merged = merged.concat(coords.slice(1)); consumed.push(layer); changed = true; break; }
        if (geomMetersBetween(end, cEnd) <= tolerance) { merged = merged.concat(coords.slice().reverse().slice(1)); consumed.push(layer); changed = true; break; }
        if (geomMetersBetween(start, cEnd) <= tolerance) { merged = coords.concat(merged.slice(1)); consumed.push(layer); changed = true; break; }
        if (geomMetersBetween(start, cStart) <= tolerance) { merged = coords.slice().reverse().concat(merged.slice(1)); consumed.push(layer); changed = true; break; }
      }
    }
    if (!consumed.length) return toast('Nenhuma linha conectada encontrada dentro da tolerância.', 'error');
    pushUndoSnapshot();
    consumed.forEach((layer) => drawn.removeLayer(layer));
    drawn.removeLayer(selectedLayer);
    const mergedFeature = { ...geomClone(feature), geometry: { type: 'LineString', coordinates: merged }, properties: { ...feature.properties, name: `${feature.properties?.name || 'Linha'} — mesclada` } };
    geomAddFeature(mergedFeature, mergedFeature.properties);
    toast(`${consumed.length + 1} linhas mescladas.`, 'success');
  }

  function geomOperationInsertVertex() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const coords = geomOuterCoords(feature);
    if (!['Polygon', 'LineString'].includes(feature.geometry?.type) || coords.length < 2) return toast('Inserir vértice exige linha ou polígono.', 'error');
    const segment = geomPromptNumber(`Inserir no segmento. Use 1 a ${coords.length - (feature.geometry.type === 'LineString' ? 1 : 0)}.`, '1');
    if (segment === null) return;
    const idx = Math.round(segment) - 1;
    const nextIdx = feature.geometry.type === 'Polygon' ? (idx + 1) % coords.length : idx + 1;
    if (idx < 0 || idx >= coords.length || nextIdx >= coords.length) return toast('Segmento inválido.', 'error');
    const percent = geomPromptNumber('Posição dentro do segmento, em %. Use 50 para o meio.', '50');
    if (percent === null) return;
    const t = Math.max(0, Math.min(100, percent)) / 100;
    const a = coords[idx], b = coords[nextIdx];
    const inserted = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
    const next = coords.slice();
    next.splice(idx + 1, 0, inserted);
    geomReplaceSelected(geomSetOuterCoords(feature, next), 'Vértice inserido.');
  }

  function geomOperationRemoveVertex() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const coords = geomOuterCoords(feature);
    if (!['Polygon', 'LineString'].includes(feature.geometry?.type)) return toast('Remover vértice exige linha ou polígono.', 'error');
    const min = feature.geometry.type === 'Polygon' ? 3 : 2;
    if (coords.length <= min) return toast('A geometria já está no número mínimo de vértices.', 'error');
    const index = geomPromptNumber(`Remover qual vértice? Use 1 a ${coords.length}.`, '1');
    if (index === null) return;
    const i = Math.round(index) - 1;
    if (i < 0 || i >= coords.length) return toast('Vértice inválido.', 'error');
    const next = coords.slice();
    next.splice(i, 1);
    geomReplaceSelected(geomSetOuterCoords(feature, next), 'Vértice removido.');
  }

  function geomOperationSnap() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const tolerance = geomPromptNumber('Tolerância do snap avançado em metros.', '1');
    if (tolerance === null) return;
    const targets = [];
    drawn.eachLayer((layer) => {
      if (layer === selectedLayer || !layer.toGeoJSON) return;
      const coords = geomOuterCoords(layer.toGeoJSON());
      targets.push(...coords);
    });
    if (!targets.length) return toast('Não há outros vértices para usar como alvo de snap.', 'error');
    let snapped = 0;
    const updated = geomClone(feature);
    updated.geometry.coordinates = geomMapCoords(updated.geometry.coordinates, (coord) => {
      let best = null, bestDist = Infinity;
      for (const target of targets) {
        const dist = geomMetersBetween(coord, target);
        if (dist < bestDist) { bestDist = dist; best = target; }
      }
      if (best && bestDist <= tolerance) {
        snapped += 1;
        return coord[2] === undefined ? [best[0], best[1]] : [best[0], best[1], coord[2]];
      }
      return coord;
    });
    if (!snapped) return toast('Nenhum vértice estava dentro da tolerância de snap.', 'error');
    geomReplaceSelected(updated, `${snapped} vértice(s) ajustado(s) pelo snap avançado.`);
  }

  function geomOperationFixInvalid() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    try {
      let fixed = geomClone(feature);
      if (window.turf?.cleanCoords) fixed = turf.cleanCoords(fixed, { mutate: false });
      const type = fixed.geometry?.type || '';
      const hasKinks = /Polygon/i.test(type) && window.turf?.kinks ? turf.kinks(fixed).features.length : 0;
      if (hasKinks && window.turf?.buffer) {
        const buffered = turf.buffer(fixed, 0, { units: 'meters', steps: 8 });
        if (buffered?.geometry) fixed = { ...buffered, properties: { ...feature.properties, ...(buffered.properties || {}) } };
      }
      fixed.properties = { ...feature.properties, correctedAt: new Date().toISOString(), correctedBy: 'geometry-fix' };
      geomReplaceSelected(fixed, hasKinks ? 'Geometria corrigida automaticamente. Confira o resultado.' : 'Geometria normalizada. Nenhuma autointerseção crítica detectada.');
    } catch (error) {
      console.error(error);
      toast('Não foi possível corrigir automaticamente esta geometria.', 'error');
    }
  }





  function spatialAllLayerEntries(filterFn = null) {
    const entries = [];
    drawn.eachLayer((layer) => {
      if (!layer?.toGeoJSON) return;
      try {
        const feature = layer.toGeoJSON();
        if (!feature?.geometry) return;
        feature.properties = { ...metadata(layer), ...(feature.properties || {}) };
        if (!filterFn || filterFn(feature, layer)) entries.push({ layer, feature });
      } catch (_) {}
    });
    return entries;
  }

  function spatialPolygonEntries(excludeLayer = null) {
    return spatialAllLayerEntries((feature, layer) => layer !== excludeLayer && spatialIsPolygonFeature(feature));
  }

  function spatialSelectedPolygon() {
    const feature = geomFeatureFromSelected();
    if (!feature) return null;
    if (!spatialIsPolygonFeature(feature)) {
      toast('Esta operação exige uma geometria poligonal selecionada.', 'error');
      return null;
    }
    return feature;
  }







  function spatialReplaceSelectedWith(feature, removeLayers = [], message = 'Operação espacial concluída.') {
    if (!selectedLayer || !feature?.geometry) return;
    const props = { ...metadata(selectedLayer), ...(feature.properties || {}) };
    const previous = selectedLayer;
    feature.properties = props;
    pushUndoSnapshot();
    removeLayers.forEach((layer) => { if (layer && drawn.hasLayer(layer)) drawn.removeLayer(layer); });
    if (drawn.hasLayer(previous)) drawn.removeLayer(previous);
    const layer = geomLayerFromFeature(feature);
    if (!layer) throw new Error('Não foi possível criar a camada resultante.');
    layer.feature = feature;
    attach(layer);
    drawn.addLayer(layer);
    applyStyleToDrawn(layer);
    if (feature.geometry?.type === 'Polygon' || feature.geometry?.type === 'MultiPolygon') normalizeConfrontantes(layer);
    select(layer);
    refresh();
    toast(message, 'success');
  }

  function spatialAddResultFeature(feature, baseProps = {}, message = 'Resultado espacial criado.') {
    if (!feature?.geometry) return null;
    pushUndoSnapshot();
    feature.properties = {
      ...baseProps,
      ...(feature.properties || {}),
      id: id(),
      name: baseProps.name || feature.properties?.name || 'Resultado espacial',
      generatedBy: baseProps.generatedBy || 'spatial-operation',
      generatedAt: new Date().toISOString()
    };
    const layer = geomAddFeature(feature, feature.properties);
    select(layer);
    toast(message, 'success');
    return layer;
  }

  function spatialCandidatePolygonsForSelected(feature, all = false) {
    return spatialPolygonEntries(selectedLayer).filter((entry) => all || spatialBooleanIntersects(feature, entry.feature));
  }

  function spatialPromptAllOrIntersect(message) {
    const value = window.prompt(`${message}\nDigite 1 para usar apenas polígonos que intersectam.\nDigite 2 para usar todos os polígonos do mapa.`, '1');
    if (value === null) return null;
    return String(value).trim() === '2';
  }

  function spatialOperationUnion() {
    const feature = spatialSelectedPolygon();
    if (!feature) return;
    const useAll = spatialPromptAllOrIntersect('União espacial');
    if (useAll === null) return;
    const candidates = spatialCandidatePolygonsForSelected(feature, useAll);
    if (!candidates.length) return toast('Nenhum polígono compatível encontrado para união.', 'error');
    try {
      const result = spatialUnionMany([feature, ...candidates.map((entry) => entry.feature)]);
      if (!result?.geometry) return toast('A união não gerou geometria válida.', 'error');
      result.properties = { ...feature.properties, name: `${feature.properties?.name || 'Polígono'} — união`, generatedBy: 'spatial-union' };
      spatialReplaceSelectedWith(result, candidates.map((entry) => entry.layer), `${candidates.length + 1} polígono(s) unidos.`);
    } catch (error) {
      console.error(error);
      toast('Não foi possível executar a união espacial nesta seleção.', 'error');
    }
  }

  function spatialOperationDifference() {
    const feature = spatialSelectedPolygon();
    if (!feature) return;
    const candidates = spatialCandidatePolygonsForSelected(feature, false);
    if (!candidates.length) return toast('Nenhum polígono interceptando a seleção foi encontrado para diferença.', 'error');
    try {
      let result = geomClone(feature);
      let used = 0;
      for (const entry of candidates) {
        if (!spatialBooleanIntersects(result, entry.feature)) continue;
        const next = spatialDifferenceTwo(result, entry.feature);
        used += 1;
        if (!next?.geometry) { result = null; break; }
        result = { ...next, properties: { ...(feature.properties || {}) } };
      }
      pushUndoSnapshot();
      if (drawn.hasLayer(selectedLayer)) drawn.removeLayer(selectedLayer);
      if (result?.geometry) {
        result.properties = { ...feature.properties, name: `${feature.properties?.name || 'Polígono'} — diferença`, generatedBy: 'spatial-difference' };
        const layer = geomLayerFromFeature(result);
        if (!layer) throw new Error('Resultado inválido.');
        layer.feature = result;
        attach(layer);
        drawn.addLayer(layer);
        applyStyleToDrawn(layer);
        normalizeConfrontantes(layer);
        select(layer);
        toast(`Diferença aplicada usando ${used} polígono(s).`, 'success');
      } else {
        selectedLayer = null;
        toast('A diferença removeu toda a área selecionada.', 'success');
      }
      refresh();
    } catch (error) {
      console.error(error);
      toast('Não foi possível executar diferença espacial nesta seleção.', 'error');
    }
  }

  function spatialOperationIntersection() {
    const feature = spatialSelectedPolygon();
    if (!feature) return;
    const candidates = spatialCandidatePolygonsForSelected(feature, false);
    if (!candidates.length) return toast('Nenhum polígono interceptando a seleção foi encontrado.', 'error');
    try {
      const unionTargets = spatialUnionMany(candidates.map((entry) => entry.feature));
      const result = unionTargets?.geometry ? spatialIntersectTwo(feature, unionTargets) : null;
      if (!result?.geometry) return toast('A interseção não gerou área comum.', 'error');
      result.properties = { ...feature.properties, name: `${feature.properties?.name || 'Polígono'} — interseção`, generatedBy: 'spatial-intersection' };
      spatialAddResultFeature(result, result.properties, 'Interseção criada como nova geometria.');
    } catch (error) {
      console.error(error);
      toast('Não foi possível executar interseção espacial nesta seleção.', 'error');
    }
  }

  function spatialOperationClip() {
    const mask = spatialSelectedPolygon();
    if (!mask) return;
    const targets = spatialPolygonEntries(selectedLayer).filter((entry) => spatialBooleanIntersects(mask, entry.feature));
    if (!targets.length) return toast('Nenhuma geometria poligonal encontrada para recortar pela máscara selecionada.', 'error');
    try {
      pushUndoSnapshot();
      let created = 0;
      targets.forEach((entry) => {
        const clipped = spatialIntersectTwo(entry.feature, mask);
        if (!clipped?.geometry) return;
        clipped.properties = {
          ...entry.feature.properties,
          id: id(),
          name: `${entry.feature.properties?.name || 'Geometria'} — clip`,
          generatedBy: 'spatial-clip',
          clippedBy: mask.properties?.id || mask.properties?.name || 'seleção'
        };
        geomAddFeature(clipped, clipped.properties);
        created += 1;
      });
      refresh();
      toast(`${created} geometria(s) recortada(s) pela máscara selecionada.`, created ? 'success' : 'error');
    } catch (error) {
      console.error(error);
      toast('Não foi possível executar clip nesta seleção.', 'error');
    }
  }

  function spatialOperationDissolve() {
    const entries = spatialPolygonEntries(null);
    if (entries.length < 2) return toast('Dissolver exige pelo menos 2 polígonos no mapa.', 'error');
    const propertyName = window.prompt('Dissolver por qual atributo? Use vazio para dissolver todos em uma única geometria.', 'category');
    if (propertyName === null) return;
    const key = String(propertyName || '').trim();
    const groups = new Map();
    entries.forEach((entry) => {
      const value = key ? String(entry.feature.properties?.[key] ?? 'sem_valor') : 'todos';
      if (!groups.has(value)) groups.set(value, []);
      groups.get(value).push(entry);
    });
    try {
      pushUndoSnapshot();
      let created = 0;
      groups.forEach((group, value) => {
        if (!group.length) return;
        const result = spatialUnionMany(group.map((entry) => entry.feature));
        if (!result?.geometry) return;
        result.properties = {
          ...(group[0].feature.properties || {}),
          id: id(),
          name: key ? `Dissolvido por ${key}: ${value}` : 'Dissolvido — todos os polígonos',
          [key || 'dissolve']: value,
          generatedBy: 'spatial-dissolve'
        };
        geomAddFeature(result, result.properties);
        created += 1;
      });
      refresh();
      toast(`${created} geometria(s) dissolvida(s) criada(s). Originais preservados.`, created ? 'success' : 'error');
    } catch (error) {
      console.error(error);
      toast('Não foi possível dissolver as geometrias.', 'error');
    }
  }

  function spatialOperationSimplify() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    if (!spatialIsPolygonFeature(feature) && !spatialIsLineFeature(feature)) return toast('Simplificar exige linha ou polígono selecionado.', 'error');
    const toleranceMeters = geomPromptNumber('Tolerância de simplificação em metros. Use valor pequeno, por exemplo 0,5 ou 1.', '1');
    if (toleranceMeters === null) return;
    try {
      const center = geomFeatureLatLng(feature);
      const metersPerDegreeLng = Math.max(1, 111320 * Math.cos((center.lat || 0) * Math.PI / 180));
      const toleranceDegrees = Math.max(0.00000001, toleranceMeters / Math.min(111320, metersPerDegreeLng));
      const simplified = turf.simplify(feature, { tolerance: toleranceDegrees, highQuality: true, mutate: false });
      if (!simplified?.geometry) return toast('A simplificação não gerou geometria válida.', 'error');
      simplified.properties = { ...feature.properties, simplifiedAt: new Date().toISOString(), simplifyToleranceMeters: toleranceMeters };
      geomReplaceSelected(simplified, 'Geometria simplificada. Confira o resultado antes de salvar.');
    } catch (error) {
      console.error(error);
      toast('Não foi possível simplificar esta geometria.', 'error');
    }
  }


  function spatialTopologyReportFor(feature) {
    const type = feature?.geometry?.type || 'desconhecido';
    const coords = geomOuterCoords(feature);
    const report = [];
    report.push(`Tipo: ${type}`);
    report.push(`Vértices principais: ${coords.length}`);
    if (spatialIsPolygonFeature(feature)) report.push(`Área estimada: ${n(spatialFeatureAreaHa(feature), 4)} ha`);
    if (spatialIsLineFeature(feature) && window.turf?.length) {
      try { report.push(`Comprimento estimado: ${n(turf.length(feature, { units: 'kilometers' }) * 1000, 2)} m`); } catch (_) {}
    }
    const duplicates = spatialCountConsecutiveDuplicates(coords);
    report.push(`Vértices duplicados consecutivos: ${duplicates}`);
    if (feature.geometry?.type === 'Polygon') {
      const ring = feature.geometry.coordinates?.[0] || [];
      const first = ring[0], last = ring[ring.length - 1];
      const closed = !!(first && last && first[0] === last[0] && first[1] === last[1]);
      report.push(`Anel fechado: ${closed ? 'sim' : 'não'}`);
    }
    if (spatialIsPolygonFeature(feature) && window.turf?.kinks) {
      try { report.push(`Autointerseções detectadas: ${turf.kinks(feature).features.length}`); } catch (_) { report.push('Autointerseções: não foi possível calcular'); }
    }
    if (window.turf?.booleanValid) {
      try { report.push(`Validade Turf: ${turf.booleanValid(feature) ? 'válida' : 'inválida'}`); } catch (_) {}
    }
    return report;
  }

  function spatialOperationTopologyCheck() {
    const feature = geomFeatureFromSelected();
    if (!feature) return;
    const report = spatialTopologyReportFor(feature);
    window.alert(`Verificação topológica\n\n${report.join('\n')}`);
    toast('Verificação topológica concluída.', 'success');
  }

  function spatialOperationRemoveSmallPolygons() {
    const thresholdHa = geomPromptNumber('Remover polígonos menores que quantos hectares?', '0.0100');
    if (thresholdHa === null) return;
    const threshold = Math.max(0, thresholdHa);
    const entries = spatialPolygonEntries(null);
    if (!entries.length) return toast('Nenhum polígono encontrado no mapa.', 'error');
    try {
      pushUndoSnapshot();
      let removed = 0;
      let updated = 0;
      entries.forEach(({ layer, feature }) => {
        if (feature.geometry?.type === 'Polygon') {
          if (spatialFeatureAreaHa(feature) < threshold) {
            if (drawn.hasLayer(layer)) drawn.removeLayer(layer);
            if (layer === selectedLayer) selectedLayer = null;
            removed += 1;
          }
          return;
        }
        if (feature.geometry?.type === 'MultiPolygon') {
          const kept = [];
          for (const polygon of feature.geometry.coordinates || []) {
            const part = { type: 'Feature', properties: feature.properties || {}, geometry: { type: 'Polygon', coordinates: polygon } };
            if (spatialFeatureAreaHa(part) >= threshold) kept.push(polygon); else removed += 1;
          }
          if (!kept.length) {
            if (drawn.hasLayer(layer)) drawn.removeLayer(layer);
            if (layer === selectedLayer) selectedLayer = null;
            return;
          }
          if (kept.length !== (feature.geometry.coordinates || []).length) {
            const next = geomClone(feature);
            next.geometry.coordinates = kept;
            if (drawn.hasLayer(layer)) drawn.removeLayer(layer);
            const newLayer = geomLayerFromFeature(next);
            if (newLayer) {
              newLayer.feature = next;
              attach(newLayer);
              drawn.addLayer(newLayer);
              applyStyleToDrawn(newLayer);
              updated += 1;
            }
          }
        }
      });
      refresh();
      toast(`${removed} polígono(s) pequeno(s) removido(s). ${updated} multipolígono(s) ajustado(s).`, 'success');
    } catch (error) {
      console.error(error);
      toast('Não foi possível remover pequenos polígonos automaticamente.', 'error');
    }
  }


  /* ==========================================================
     v21.9.291 — Bloco 3: Terreno / Altimetria / Topografia
     ========================================================== */
  const TERRAIN_ANALYSIS_ZOOM = 12;


  function terrainTilePixel(lng, lat, zoom = TERRAIN_ANALYSIS_ZOOM) {
    const z = Math.max(0, Math.min(TOPOGRAPHIC_MAX_NATIVE_ZOOM, Math.round(zoom || TERRAIN_ANALYSIS_ZOOM)));
    const nTiles = 2 ** z;
    const clampedLat = terrainClampLat(lat);
    const xFloat = ((Number(lng) + 180) / 360) * nTiles;
    const latRad = clampedLat * Math.PI / 180;
    const yFloat = (1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2 * nTiles;
    const x = Math.max(0, Math.min(nTiles - 1, Math.floor(xFloat)));
    const y = Math.max(0, Math.min(nTiles - 1, Math.floor(yFloat)));
    return {
      z,
      x,
      y,
      px: Math.max(0, Math.min(255, Math.floor((xFloat - x) * 256))),
      py: Math.max(0, Math.min(255, Math.floor((yFloat - y) * 256)))
    };
  }

  async function terrainElevationAt(lng, lat, zoom = TERRAIN_ANALYSIS_ZOOM) {
    const t = terrainTilePixel(lng, lat, zoom);
    const url = TOPOGRAPHIC_DEM_URL.replace('{z}', t.z).replace('{x}', t.x).replace('{y}', t.y);
    const image = await fetchDemImageData(url, 256);
    const index = ((t.py * (image.width || 256)) + t.px) * 4;
    const elevation = decodeTerrariumPixel(image.data, index);
    return Number.isFinite(elevation) ? elevation : null;
  }

  function terrainSelectedFeature(requiredType = 'any') {
    const feature = geomFeatureFromSelected();
    if (!feature) return null;
    if (requiredType === 'polygon' && !spatialIsPolygonFeature(feature)) {
      toast('Esta ferramenta exige um polígono selecionado.', 'error');
      return null;
    }
    if (requiredType === 'line-or-polygon' && !spatialIsPolygonFeature(feature) && !spatialIsLineFeature(feature)) {
      toast('Esta ferramenta exige linha ou polígono selecionado.', 'error');
      return null;
    }
    return feature;
  }





  function terrainEscapeHtml(value) {
    return String(value ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  }

  function terrainOpenReport(title, bodyHtml) {
    const win = window.open('', '_blank', 'width=960,height=720');
    if (!win) {
      window.alert(`${title}\n\nO navegador bloqueou a janela do relatório. Permita pop-ups para visualizar o gráfico.`);
      return;
    }
    win.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${terrainEscapeHtml(title)}</title><style>
      @page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#0f172a;margin:24px;background:#f8fafc}main{max-width:900px;margin:auto;background:white;border:1px solid #cbd5e1;padding:24px}h1{font-size:22px;margin:0 0 6px;text-transform:uppercase}.muted{color:#475569;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:16px;font-size:12px}th,td{border:1px solid #cbd5e1;padding:6px;text-align:right}th:first-child,td:first-child{text-align:left}th{background:#f1f5f9}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:14px 0}.card{border:1px solid #cbd5e1;padding:10px}.card b{display:block;font-size:16px}.chart{border:1px solid #cbd5e1;background:#fff;margin:16px 0;padding:8px}button{margin-top:16px;padding:8px 14px;font-weight:700}@media print{body{background:white;margin:0}main{border:0;padding:0}button{display:none}}</style></head><body><main>${bodyHtml}<button id="terrainPrintReportBtn" type="button">Imprimir / PDF</button></main></body></html>`);
    win.addEventListener('load', () => {
      win.document.getElementById('terrainPrintReportBtn')?.addEventListener('click', () => win.print());
    }, { once: true });
    win.document.close();
  }

  function terrainProfileSvg(samples, width = 820, height = 260) {
    const stats = terrainStats(samples);
    if (!stats) return '<p>Sem dados de elevação suficientes.</p>';
    const pad = { l: 46, r: 16, t: 18, b: 34 };
    const maxD = Math.max(...samples.map((s) => s.distanceMeters || 0), 1);
    const minE = stats.min;
    const maxE = stats.max;
    const span = Math.max(1, maxE - minE);
    const pts = samples.filter((s) => Number.isFinite(s.elevation)).map((s) => {
      const x = pad.l + ((s.distanceMeters || 0) / maxD) * (width - pad.l - pad.r);
      const y = pad.t + (1 - ((s.elevation - minE) / span)) * (height - pad.t - pad.b);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(' ');
    return `<svg viewBox="0 0 ${width} ${height}" width="100%" height="${height}" role="img" aria-label="Perfil de elevação">
      <rect x="0" y="0" width="${width}" height="${height}" fill="#fff"/>
      <line x1="${pad.l}" y1="${height-pad.b}" x2="${width-pad.r}" y2="${height-pad.b}" stroke="#334155" stroke-width="1"/>
      <line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${height-pad.b}" stroke="#334155" stroke-width="1"/>
      <text x="${pad.l}" y="${height-8}" font-size="11" fill="#475569">0 m</text>
      <text x="${width-pad.r-70}" y="${height-8}" font-size="11" fill="#475569">${n(maxD,0)} m</text>
      <text x="4" y="${height-pad.b}" font-size="11" fill="#475569">${n(minE,1)} m</text>
      <text x="4" y="${pad.t+6}" font-size="11" fill="#475569">${n(maxE,1)} m</text>
      <polyline points="${pts}" fill="none" stroke="#0f5bdc" stroke-width="2.5" stroke-linejoin="round"/>
    </svg>`;
  }

  async function terrainOperationProfile() {
    const feature = terrainSelectedFeature('line-or-polygon');
    if (!feature) return;
    const spacing = geomPromptNumber('Perfil de elevação: espaçamento entre amostras em metros.', '100');
    if (spacing === null) return;
    const samples = terrainDensifyLine(terrainProfileCoordinates(feature), spacing, 180);
    if (samples.length < 2) return toast('A geometria selecionada não possui comprimento suficiente para perfil.', 'error');
    toast('Calculando perfil de elevação. Aguarde...', 'success');
    for (const sample of samples) sample.elevation = await terrainElevationAt(sample.lng, sample.lat);
    const stats = terrainStats(samples);
    if (!stats) return toast('Não foi possível obter dados de elevação para esta área.', 'error');
    const rows = samples.filter((_, i) => i % Math.max(1, Math.floor(samples.length / 18)) === 0 || i === samples.length - 1)
      .map((s) => `<tr><td>${n(s.distanceMeters,1)} m</td><td>${n(s.elevation,2)} m</td><td>${n(s.lat,6)}, ${n(s.lng,6)}</td></tr>`).join('');
    terrainOpenReport('Perfil de elevação', `<h1>Perfil de elevação</h1><p class="muted">Fonte DEM: Mapzen Terrain Tiles / AWS Open Data. Resultado auxiliar para análise técnica.</p><div class="cards"><div class="card">Mínima<b>${n(stats.min,2)} m</b></div><div class="card">Média<b>${n(stats.avg,2)} m</b></div><div class="card">Máxima<b>${n(stats.max,2)} m</b></div><div class="card">Amplitude<b>${n(stats.amplitude,2)} m</b></div></div><div class="chart">${terrainProfileSvg(samples)}</div><table><thead><tr><th>Distância</th><th>Elevação</th><th>Coordenada</th></tr></thead><tbody>${rows}</tbody></table>`);
    toast('Perfil de elevação gerado.', 'success');
  }


  async function terrainOperationCutFill() {
    const feature = terrainSelectedFeature('polygon');
    if (!feature) return;
    const target = geomPromptNumber('Corte e aterro: informe a cota de projeto em metros.', '200');
    if (target === null) return;
    const spacing = geomPromptNumber('Espaçamento da malha de cálculo em metros.', '150');
    if (spacing === null) return;
    const points = terrainPointGridForPolygon(feature, spacing, 300);
    if (!points.length) return toast('Não foi possível gerar malha dentro do polígono.', 'error');
    toast('Calculando corte e aterro aproximado. Aguarde...', 'success');
    const samples = [];
    for (const pt of points) {
      const [lng, lat] = pt.geometry.coordinates;
      const elevation = await terrainElevationAt(lng, lat);
      if (Number.isFinite(elevation)) samples.push({ lng, lat, elevation });
    }
    if (!samples.length) return toast('Não foi possível obter elevação da malha.', 'error');
    const areaM2 = turf.area(feature);
    const cellArea = areaM2 / samples.length;
    let cut = 0, fill = 0;
    let min = Infinity, max = -Infinity, sum = 0;
    samples.forEach((s) => {
      min = Math.min(min, s.elevation); max = Math.max(max, s.elevation); sum += s.elevation;
      const diff = target - s.elevation;
      if (diff > 0) fill += diff * cellArea;
      if (diff < 0) cut += Math.abs(diff) * cellArea;
    });
    const avg = sum / samples.length;
    window.alert(`Corte e aterro — cálculo preliminar\n\nCota de projeto: ${n(target,2)} m\nAmostras: ${samples.length}\nÁrea: ${n(areaM2,2)} m²\nElevação média: ${n(avg,2)} m\nMínima/Máxima: ${n(min,2)} m / ${n(max,2)} m\n\nVolume de corte estimado: ${n(cut,2)} m³\nVolume de aterro estimado: ${n(fill,2)} m³\nSaldo corte - aterro: ${n(cut - fill,2)} m³\n\nResultado auxiliar. Para projeto executivo, valide com MDT/levantamento topográfico adequado.`);
    toast('Corte e aterro calculado.', 'success');
  }


  async function terrainOperationContours() {
    const feature = terrainSelectedFeature('polygon');
    if (!feature) return;
    const interval = geomPromptNumber('Curvas de nível: equidistância em metros.', '5');
    if (interval === null) return;
    const gridSizeRaw = geomPromptNumber('Densidade da malha. Use 18 a 32. Quanto maior, mais pesado.', '24');
    if (gridSizeRaw === null) return;
    const gridSize = Math.max(8, Math.min(36, Math.round(gridSizeRaw)));
    const bbox = turf.bbox(feature);
    toast('Gerando curvas de nível automáticas. Aguarde...', 'success');
    const grid = [];
    let min = Infinity, max = -Infinity;
    for (let r = 0; r <= gridSize; r += 1) {
      const row = [];
      const lat = bbox[1] + ((bbox[3] - bbox[1]) * r / gridSize);
      for (let c = 0; c <= gridSize; c += 1) {
        const lng = bbox[0] + ((bbox[2] - bbox[0]) * c / gridSize);
        let inside = false;
        try { inside = turf.booleanPointInPolygon(turf.point([lng, lat]), feature); } catch (_) {}
        const elevation = inside ? await terrainElevationAt(lng, lat) : null;
        if (Number.isFinite(elevation)) { min = Math.min(min, elevation); max = Math.max(max, elevation); }
        row.push({ lng, lat, elevation, inside });
      }
      grid.push(row);
    }
    if (!Number.isFinite(min) || !Number.isFinite(max) || max - min < interval) return toast('Variação altimétrica insuficiente para gerar curvas nessa equidistância.', 'error');
    const start = Math.ceil(min / interval) * interval;
    const end = Math.floor(max / interval) * interval;
    const levels = [];
    for (let level = start; level <= end && levels.length < 40; level += interval) levels.push(level);
    pushUndoSnapshot();
    let created = 0;
    for (const level of levels) {
      for (let r = 0; r < gridSize; r += 1) {
        for (let c = 0; c < gridSize; c += 1) {
          const corners = [grid[r][c], grid[r][c + 1], grid[r + 1][c + 1], grid[r + 1][c]];
          if (corners.some((p) => !Number.isFinite(p.elevation))) continue;
          const edges = [[0,1],[1,2],[2,3],[3,0]];
          const hits = [];
          edges.forEach(([i, j]) => {
            const a = corners[i], b = corners[j];
            if ((a.elevation <= level && b.elevation >= level) || (a.elevation >= level && b.elevation <= level)) {
              if (a.elevation !== b.elevation) hits.push(terrainInterpolatePoint(a, b, level));
            }
          });
          if (hits.length >= 2) {
            const segment = { type: 'Feature', properties: { id: id(), category: 'arco', name: `Curva de nível ${n(level,1)} m`, generatedBy: 'terrain-contour', elevation: level }, geometry: { type: 'LineString', coordinates: [hits[0], hits[1]] } };
            try { geomAddFeature(segment, segment.properties); created += 1; } catch (_) {}
            if (created >= 300) break;
          }
        }
        if (created >= 300) break;
      }
      if (created >= 300) break;
    }
    refresh();
    toast(`${created} segmento(s) de curva de nível criado(s).`, created ? 'success' : 'error');
  }

  async function terrainOperationSpotPoints() {
    const feature = terrainSelectedFeature('polygon');
    if (!feature) return;
    const spacing = geomPromptNumber('Pontos cotados: espaçamento da malha em metros.', '200');
    if (spacing === null) return;
    const points = terrainPointGridForPolygon(feature, spacing, 220);
    if (!points.length) return toast('Não foi possível gerar pontos dentro do polígono.', 'error');
    toast('Gerando pontos cotados. Aguarde...', 'success');
    pushUndoSnapshot();
    let created = 0;
    for (const pt of points) {
      const [lng, lat] = pt.geometry.coordinates;
      const elevation = await terrainElevationAt(lng, lat);
      if (!Number.isFinite(elevation)) continue;
      const marker = L.marker([lat, lng], { icon: markerIcon('benfeitoria') });
      marker.feature = { type: 'Feature', properties: { id: id(), category: 'benfeitoria', name: `Ponto cotado ${n(elevation,2)} m`, generatedBy: 'terrain-spot-point', elevation }, geometry: { type: 'Point', coordinates: [lng, lat] } };
      attach(marker);
      drawn.addLayer(marker);
      created += 1;
    }
    refresh();
    toast(`${created} ponto(s) cotado(s) criado(s).`, created ? 'success' : 'error');
  }

  function runGeometryBlockTool(tool) {
    const handlers = {
      'geom-offset': geomOperationOffset,
      'geom-rotate': geomOperationRotate,
      'geom-mirror': geomOperationMirror,
      'geom-scale': geomOperationScale,
      'geom-stretch-side': geomOperationStretchSide,
      'geom-convert': geomOperationConvert,
      'geom-split-line': geomOperationSplitLine,
      'geom-merge-lines': geomOperationMergeLines,
      'geom-insert-vertex': geomOperationInsertVertex,
      'geom-remove-vertex': geomOperationRemoveVertex,
      'geom-snap': geomOperationSnap,
      'geom-fix': geomOperationFixInvalid,
      'cad-dimension': beginManualDimensionTool,
      'cad-dimension-remove': removeLastManualDimension,
      'spatial-union': spatialOperationUnion,
      'spatial-difference': spatialOperationDifference,
      'spatial-intersection': spatialOperationIntersection,
      'spatial-clip': spatialOperationClip,
      'spatial-dissolve': spatialOperationDissolve,
      'spatial-simplify': spatialOperationSimplify,
      'spatial-topology': spatialOperationTopologyCheck,
      'sig-certified-neighbors': analyzeCertifiedNeighbors,
      'spatial-remove-small': spatialOperationRemoveSmallPolygons,
      'terrain-profile': terrainOperationProfile,
      'terrain-cut-fill': terrainOperationCutFill,
      'terrain-contours': terrainOperationContours,
      'terrain-spot-points': terrainOperationSpotPoints,
      'terrain-elevation-click': terrainOperationElevationClick
    };
    const fn = handlers[tool];
    if (!fn) return false;
    resetInteractionModes();
    const result = fn();
    if (result && typeof result.catch === 'function') {
      result.catch((error) => {
        console.error(error);
        toast('Não foi possível concluir esta operação.', 'error');
      });
    }
    return true;
  }

  function handleToolPopoverClick(event) {
    const button = event.target.closest('[data-draw-tool]');
    if (!button) return;
    const tool = button.dataset.drawTool;
    hideToolPopovers();

    if (tool === 'edit' && directEditMode) {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Edição de vértices finalizada.', 'success');
      return;
    }
    if (tool === 'polygon' && surveyorLiveTool?.type === 'polygon') {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Desenho de polígono cancelado.', 'success');
      return;
    }
    if (tool === 'polyline' && surveyorLiveTool?.type === 'polyline') {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Desenho de linha cancelado.', 'success');
      return;
    }
    if (tool === 'servitude' && surveyorLiveTool?.type === 'servitude') {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Desenho de servidão cancelado.', 'success');
      return;
    }
    if (tool === 'rectangle' && surveyorLiveTool?.type === 'rectangle') {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Desenho de retângulo cancelado.', 'success');
      return;
    }
    if (tool === 'circle' && surveyorLiveTool?.type === 'circle') {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Desenho de círculo cancelado.', 'success');
      return;
    }
    if (tool === 'marker' && surveyorLiveTool?.type === 'marker') {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Inserção de ponto cancelada.', 'success');
      return;
    }
    if (tool === 'arc' && document.body.classList.contains('drawing-active') && activeLeafletHandler) {
      resetInteractionModes();
      setActiveMapTool(els.selectToolBtn);
      toast('Desenho de arco cancelado.', 'success');
      return;
    }
    if (tool === 'cad-dimension' && manualDimensionState) {
      stopManualDimensionTool();
      setActiveMapTool(els.selectToolBtn);
      toast('Cotação CAD desativada.', 'success');
      return;
    }
    if (tool === 'terrain-elevation-click' && terrainElevationClickHandler) {
      stopTerrainElevationClick();
      setActiveMapTool(els.selectToolBtn);
      toast('Consulta de altitude desativada.', 'success');
      return;
    }

    resetInteractionModes();
    try {
      if (runGeometryBlockTool(tool)) return;
      if (tool === 'cancel') { resetInteractionModes(); setActiveMapTool(els.selectToolBtn); toast('Ferramenta cancelada.', 'success'); return; }
      if (tool === 'glebas') { openGlebasFromMap(); return; }
      if (tool === 'polygon') { startSurveyorLiveTool('polygon', button); return; }
      if (tool === 'polyline') { startSurveyorLiveTool('polyline', button); return; }
      if (tool === 'servitude') { startSurveyorLiveTool('servitude', button); return; }
      if (tool === 'rectangle') { startSurveyorLiveTool('rectangle', button); return; }
      if (tool === 'circle') { startSurveyorLiveTool('circle', button); return; }
      if (tool === 'arc') { beginArcTool(); return; }
      if (tool === 'marker') { startSurveyorLiveTool('marker', button); return; }
      if (tool === 'edit') {
        beginDirectEditMode(els.cadToolsMenuBtn || els.topEditElementsBtn);
        return;
      }
      if (tool === 'delete') {
        vertexMarkers.clearLayers();
        if (!drawn.getLayers().length) return toast('Não há desenho para excluir.', 'error');
        activateHandler(new L.EditToolbar.Delete(map, { featureGroup: drawn }));
        toast('Modo exclusão ativado. Clique no desenho que deseja excluir. Use Cancelar para sair.', 'success');
        return;
      }
      toast(`Ferramenta ${button.textContent.toLowerCase()} ativada. Use o botão Cancelar para sair.`, 'success');
    } catch (error) {
      console.error(error);
      toast('Não foi possível ativar esta ferramenta.', 'error');
    }
  }

